-- Chemistry part 2 of 2: longer explanations for CHE-1012 onwards, the gap and hard sets and past-paper questions (671 live questions).
-- Longer explanations: each question's "why" now says in two or three sentences why the key is right, and each wrong
-- option gets a sentence or two on the mistake behind it. Facts checked against the source textbook named in each
-- question's source. Stems, options and answer keys are unchanged: every UPDATE also matches on the current key, so a
-- question whose key was edited since is left alone. Safe to run twice.

UPDATE questions SET why = 'A condensation polymer forms when monomers join and lose a small molecule such as water. To get the monomers back, reverse this: break each ester or amide link and add back the water, putting –OH on the C=O carbon and –H on the O or N. This gives the dicarboxylic acid and the diol or diamine.', wrong = '{"0": "Adding HCl across C=O groups is not a real way to split ester or amide links, and it would not give back the original acid and alcohol or amine.", "1": "Turning C–C bonds back into C=C is how the monomer of an addition polymer is found, for example ethene from poly(ethene). Condensation polymers are split at their linking groups.", "2": "The monomers of polyesters and polyamides contain oxygen in their –COOH and –OH groups. Removing all oxygen would destroy the monomers rather than recover them."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1012' AND answer = 3;
UPDATE questions SET why = 'Condensation polymerisation needs two reacting groups. Lactic acid, CH₃CH(OH)COOH, has an –OH and a –COOH in the same molecule, so the –OH of one molecule can form an ester link with the –COOH of the next. Repeating this gives the polyester poly(lactic acid), PLA.', wrong = '{"0": "Lactic acid is a saturated molecule with no C=C bond, so it cannot undergo addition polymerisation.", "2": "An amino acid needs an –NH₂ group. Lactic acid has –OH and –COOH but no amino group, so it is a hydroxy acid.", "3": "Lactic acid has only one –COOH group. Its second reactive group is the –OH on carbon 2."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1013' AND answer = 1;
UPDATE questions SET why = 'An –OH group of an alcohol reacts with an acyl chloride group, –COCl, to form an ester link, –COO–. The H from –OH and the Cl from –COCl leave together as HCl. With a diol and a dioyl chloride this repeats at both ends, giving a polyester and HCl.', wrong = '{"0": "A polyamide needs an amine group (–NH₂) to form the amide link. A diol has only –OH groups, and with an acyl chloride the small molecule lost is HCl, not water.", "2": "The polymer is a polyester, but water is lost only when a carboxylic acid (–COOH) reacts with –OH. With an acyl chloride, HCl is eliminated instead.", "3": "HCl is correctly lost, but a polyamide forms only when an amine reacts with the acyl chloride. A diol gives ester links, so the product is a polyester."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1014' AND answer = 1;
UPDATE questions SET why = 'Both ethene (H₂C=CH₂) and propenoic acid (H₂C=CH–COOH) contain a C=C bond. Monomers with C=C bonds undergo addition polymerisation, and two different alkenes can add into the same chain. The product is an addition copolymer, with no small molecule lost.', wrong = '{"1": "A polyester needs –COOH and –OH groups reacting. Propenoic acid has one –COOH, but neither monomer has an –OH group to form ester links.", "2": "A polyamide needs an amine group (–NH₂) to form amide links. Neither ethene nor propenoic acid contains nitrogen.", "3": "Being different does not stop polymerisation. Two different monomers that both have C=C bonds can join in one chain to form a copolymer."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1015' AND answer = 0;
UPDATE questions SET why = 'Non-degradable plastics are not broken down by microorganisms. Over time, large plastic items crack and wear into very small fragments called microplastics. These spread through soil, water and even air, and can enter the food chain and possibly harm human health.', wrong = '{"1": "Starch-based plastics are biodegradable and are broken down by bacteria. Microplastics come from non-degradable plastics that do not decompose.", "2": "Microplastics are small pieces of the polymer itself, still made of long chains. They are not single monomer molecules released from PVC.", "3": "Natural polymers in soil, such as cellulose, are broken down by microbes. Microplastics are man-made pollutants from synthetic plastic waste."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1016' AND answer = 0;
UPDATE questions SET why = 'Photodegradable plastics contain groups, such as C=O, that absorb UV light, which weakens the bonds in the chain so it breaks down. This needs sunlight. Waste buried in landfills gets no light, so it cannot photodegrade. Such plastics also cannot be used for long and are hard to recycle well.', wrong = '{"1": "Photodegradable plastics do break down when exposed to sunlight. Their problem is that they need light, which is missing in landfills.", "2": "Carbonyl (C=O) groups are deliberately built into these polymers because they absorb UV light. This is what makes them photodegradable.", "3": "Plastics containing starch are biodegradable, broken down by soil bacteria. Photodegradable plastics rely on UV absorption, not on starch."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1017' AND answer = 0;
UPDATE questions SET why = 'Polyesters contain ester links, –COO–, which can react with water (hydrolysis) and split into carboxylic acid and alcohol units. Inside the body this happens slowly, so stitches made of a polyester hold the wound while it heals and then break down, with no need to remove them.', wrong = '{"1": "A very inert material would stay in the body unchanged. Dissolvable stitches must react slowly with water, which is the opposite of being inert.", "2": "Polyesters are condensation polymers, formed with loss of water. Addition polymers like poly(ethene) have C–C backbones that do not hydrolyse.", "3": "Polyesters are electrical insulators, and conducting electricity has nothing to do with stitches dissolving in the body."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1018' AND answer = 0;
UPDATE questions SET why = 'Artificial hip and knee joints need a surface that slides smoothly and resists wear over years of movement. Ultra-high molecular weight polyethylene (UHMWPE), made of extremely long poly(ethene) chains, is tough and low-friction, so it is used as the bearing surface in these joints.', wrong = '{"1": "PMMA, poly(methyl methacrylate), is clear and biocompatible, so it is used for artificial corneas rather than joints.", "2": "Collagen is a natural protein used as a scaffold for artificial skin. It is not strong or wear-resistant enough for joints.", "3": "PVC is not used for artificial joints. Joints use UHMWPE for its smooth, wear-resistant surface."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1019' AND answer = 0;
UPDATE questions SET why = 'The cornea is the clear front window of the eye, so a replacement must let light pass without blurring. It must also be biocompatible, meaning the body does not reject it or react against it. PMMA and hydrogels meet both needs: they are transparent and accepted by the body.', wrong = '{"1": "The cornea''s job is to let light through. It does not carry electric current, so conductivity is not needed.", "2": "Magnetism plays no part in how a cornea works. Transparency and biocompatibility are the key needs.", "3": "An artificial cornea must last a long time to restore vision. A material that broke down within days would fail."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1020' AND answer = 0;
UPDATE questions SET why = 'Carbohydrates are defined as polyhydroxy aldehydes or polyhydroxy ketones, or compounds that give these on hydrolysis. "Polyhydroxy" means they carry many –OH groups. Glucose is a polyhydroxy aldehyde (aldose) and fructose is a polyhydroxy ketone (ketose).', wrong = '{"0": "Esters of fatty acids and glycerol are lipids, that is, fats and oils (triglycerides), not carbohydrates.", "2": "Polymers of amino acids joined by peptide bonds are proteins, not carbohydrates.", "3": "Polymers of nucleotides are nucleic acids such as DNA and RNA, not carbohydrates."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1021' AND answer = 1;
UPDATE questions SET why = 'Monosaccharides are named by the number of carbon atoms they contain: a triose has 3, a tetrose 4, a pentose 5 and a hexose 6. So a five-carbon sugar, such as ribose in RNA, is a pentose.', wrong = '{"0": "\"Hex\" means six, so a hexose has six carbon atoms, for example glucose and fructose.", "1": "\"Tetra\" means four, so a tetrose has four carbon atoms, one fewer than asked.", "3": "\"Tri\" means three, so a triose has three carbon atoms, such as glyceraldehyde."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1022' AND answer = 2;
UPDATE questions SET why = 'Glucose is an aldohexose; in its ring form it closes into a six-membered ring (five C and one O) called a pyranose. Fructose is a ketohexose; its ring is five-membered (four C and one O), called a furanose. So the order is pyranose for glucose, then furanose for fructose.', wrong = '{"0": "Fructose does form a five-membered furanose ring, but glucose forms a six-membered pyranose ring, not a furanose.", "1": "This has the two rings swapped. Glucose gives the six-membered pyranose and fructose the five-membered furanose.", "2": "Glucose does form a six-membered pyranose ring, but fructose forms a five-membered furanose ring."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1023' AND answer = 3;
UPDATE questions SET why = 'Monosaccharides such as glucose and fructose carry many –OH groups. These form extensive hydrogen bonds between sugar molecules, which makes honey (rich in glucose and fructose) thick and viscous. The same –OH groups hydrogen-bond strongly with water, so the sugars dissolve easily.', wrong = '{"0": "Sugars are covalent molecules, not ionic compounds, so there are no ionic bonds between them.", "2": "Glycosidic bonds join sugar units together in di- and polysaccharides. Free monosaccharides like glucose and fructose do not contain them.", "3": "Monosaccharides are small molecules (glucose is 180 g/mol). Their properties come from hydrogen bonding, not from a high molar mass."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1024' AND answer = 1;
UPDATE questions SET why = 'Sucrose (table sugar) is a disaccharide made of one glucose and one fructose unit. They join by a condensation reaction: an –OH of one sugar and an H of the other leave as water, and a C–O–C link called a glycosidic bond forms between them.', wrong = '{"0": "Glucose and galactose together make lactose, the sugar in milk. In any case sugars are joined by a glycosidic bond, not an ester bond.", "1": "Two glucose units make maltose, not sucrose. Peptide bonds join amino acids in proteins, not sugars.", "3": "Glycerol is a three-carbon alcohol found in fats. It is not part of sucrose, which is glucose plus fructose."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1025' AND answer = 2;
UPDATE questions SET why = 'Starch is the storage carbohydrate of plants and is made of two glucose polymers. Amylose has long unbranched (straight) chains, while amylopectin has many branches, which makes it compact. So amylose is unbranched and amylopectin is highly branched.', wrong = '{"0": "The main structural material of plant cell walls is cellulose. Starch is a food store, not a structural material.", "1": "This swaps the two. Amylose is the unbranched form and amylopectin is the highly branched form.", "2": "Starch is a polymer of glucose units only. Fructose is not a building unit of starch."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1026' AND answer = 3;
UPDATE questions SET why = 'Cellulose is made of long, straight, unbranched glucose chains. These chains lie side by side and form many hydrogen bonds with each other through their –OH groups. The chains pack into strong fibres, so cellulose is rigid and water cannot pull them apart, making it insoluble.', wrong = '{"0": "Cellulose is unbranched. Glycogen is the highly branched glucose polymer, and branching would stop chains from packing tightly.", "2": "Peptide bonds are found in proteins. The glucose units in cellulose are linked by glycosidic bonds.", "3": "Cellulose is a polymer of glucose units, not fructose. Fructose is a fruit sugar and is not part of cellulose."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1027' AND answer = 1;
UPDATE questions SET why = 'Glycogen, often called animal starch, is a glucose polymer with a structure similar to amylopectin, but it is even more highly branched. Animals store it in the liver and muscles, and it is broken down to glucose when energy is needed.', wrong = '{"0": "Glycogen, like amylopectin, is built from glucose units, not fructose.", "1": "Glycogen is not unbranched. It is more branched than amylopectin; the unbranched glucose polymers are amylose and cellulose.", "3": "Plant cell walls are made of cellulose. Glycogen is a storage compound in animals, found in the liver and muscles."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1028' AND answer = 2;
UPDATE questions SET why = 'In a healthy person, the normal blood glucose level is about 70 to 110 mg/dL, with small changes during the day. The hormones insulin and glucagon keep it in this range: insulin lowers blood glucose and glucagon raises it.', wrong = '{"1": "7 to 11 mg/dL is ten times too low. Glucose at this level would be far below normal and dangerous.", "2": "700 to 1100 mg/dL is ten times too high. Such levels would mean extreme hyperglycaemia, not a normal value.", "3": "15 to 16 does not match blood glucose. The number 15.6 is the energy from glucose, about 15.6 kJ per gram."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1029' AND answer = 0;
UPDATE questions SET why = 'Insulin, a protein hormone made by the pancreas, helps glucose move from the blood into cells. Diabetes occurs when the pancreas makes too little insulin, or when the body cannot use its insulin properly. Glucose then builds up in the blood, causing hyperglycaemia (high blood sugar).', wrong = '{"0": "Glucagon raises blood glucose, but diabetes is defined by a shortage of insulin or a poor response to insulin, not by glucagon alone.", "1": "Storing glucose as glycogen in the liver lowers blood glucose. Too much storage is not the cause of diabetes.", "2": "Fructose does not replace glucose in the blood. Diabetes is about high blood glucose due to an insulin problem."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1030' AND answer = 3;
UPDATE questions SET why = 'The primary structure of a protein is the order (sequence) of amino acids in its chain, joined by peptide bonds. This sequence is the base level of structure, and it decides how the chain will later coil and fold into its higher structures.', wrong = '{"0": "The α-helix and β-pleated sheet are local coils and folds held by hydrogen bonds. They make up the secondary structure.", "2": "The overall 3D folding of a single chain is the tertiary structure.", "3": "The association of two or more polypeptide chains, as in haemoglobin, is the quaternary structure."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1031' AND answer = 1;
UPDATE questions SET why = 'In sickle cell anaemia, just one amino acid in the haemoglobin chain is changed. This small change in primary structure alters how the protein folds, so red blood cells become sickle-shaped, carry oxygen poorly and can block small vessels. It shows that sequence controls shape and function.', wrong = '{"0": "Red blood cells are packed with haemoglobin, which is a protein, so this statement is false.", "1": "Sickle cell anaemia shows the opposite: changing a single amino acid changes the protein''s shape and function.", "3": "Haemoglobin is a protein made of polypeptide chains, not a carbohydrate."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1032' AND answer = 2;
UPDATE questions SET why = 'Secondary structure arises when backbone atoms hydrogen-bond: the N–H of one peptide group bonds to the C=O of another. In an α-helix these bonds form along one coiled chain; in a β-pleated sheet they form between neighbouring strands. So both shapes are held mainly by hydrogen bonds.', wrong = '{"0": "Phosphodiester bonds link nucleotides in the sugar–phosphate backbone of DNA and RNA. They do not occur in proteins.", "1": "Disulfide bridges (–S–S–) form between cysteine side chains and help hold tertiary structure. They are not what shapes α-helices and β-sheets.", "2": "Glycosidic bonds link sugar units in carbohydrates such as starch and cellulose, not parts of a protein."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1033' AND answer = 3;
UPDATE questions SET why = 'In keratin, the protein of hair and nails, each chain coils into an α-helix held by hydrogen bonds along the same chain. In silk fibroin, neighbouring strands lie side by side and hydrogen-bond into β-pleated sheets. So keratin is the α-helix example and silk fibroin the β-sheet example.', wrong = '{"0": "This pairs the examples the wrong way round. Keratin is the α-helix example and silk fibroin is the β-pleated sheet example.", "2": "Insulin and haemoglobin are globular proteins and are not the examples used for these two secondary structures.", "3": "Cellulose and starch are carbohydrates. α-helices and β-sheets are protein structures formed by peptide backbones."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1034' AND answer = 1;
UPDATE questions SET why = 'Tertiary structure is the overall 3D folding of a single polypeptide chain. It is held by interactions between the side chains (R groups): hydrogen bonds, ionic bonds between charged groups, hydrophobic interactions and covalent disulfide bridges. This folded shape decides the protein''s function.', wrong = '{"0": "Interactions that hold separate polypeptide chains (subunits) together make up quaternary structure, not tertiary.", "1": "Peptide bonds join amino acids into the chain and so define the primary structure. Folding comes from R-group interactions.", "3": "Sugar and phosphate groups form the backbone of nucleic acids. Proteins contain no sugar–phosphate units."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1035' AND answer = 2;
UPDATE questions SET why = 'Fibrous proteins have long chains lying parallel to each other, joined by hydrogen bonds or disulfide bridges. This makes tough, thread-like fibres that are insoluble in water. They give strength and support, such as collagen in tendons and bones and keratin in hair and nails.', wrong = '{"0": "Globular proteins are the ones more sensitive to heat and pH. Fibrous proteins are tough and more stable.", "1": "Spherical, water-soluble proteins are globular proteins, such as enzymes and haemoglobin. Fibrous proteins are long and insoluble.", "2": "Most enzymes and hormones are globular proteins. Fibrous proteins mainly have structural roles."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1036' AND answer = 3;
UPDATE questions SET why = 'Lemon juice contains citric acid, which lowers the pH of milk. This disturbs the hydrogen bonds and ionic attractions that hold casein in its folded shape. The chains unfold and clump together, so the protein coagulates. This loss of shape is called denaturation.', wrong = '{"0": "Denaturation only unfolds the protein. The peptide bonds stay intact, so the primary structure is unchanged.", "2": "Lemon juice acts through its acid, not through sugar. It is the drop in pH that makes casein curdle.", "3": "Casein is the main protein of milk, not a lipid. Its curdling is a change in protein shape."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1037' AND answer = 1;
UPDATE questions SET why = 'Storage proteins hold nutrients or minerals that the organism can use later. Ferritin is a storage protein found in some bacteria and in plant and animal tissues, where it stores iron in a safe form until the body needs it.', wrong = '{"0": "Hormonal proteins carry chemical signals, such as insulin, which controls blood glucose. Ferritin stores iron instead.", "1": "Contractile proteins, such as actin and myosin, make muscles contract. Ferritin has no role in movement.", "3": "Defensive proteins, such as antibodies, help fight infection. Ferritin''s job is to store iron."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1038' AND answer = 2;
UPDATE questions SET why = 'Actin and myosin make up the thin (actin) and thick (myosin) filaments inside muscle fibres. During contraction these filaments slide over each other, shortening the muscle, so they are classed as contractile proteins.', wrong = '{"0": "Receptor proteins sit in cell membranes and bind signal molecules. Actin and myosin are found in muscle filaments.", "1": "Storage proteins, such as those in seeds or ferritin for iron, hold nutrients. Actin and myosin do mechanical work instead.", "2": "Carrier (transport) proteins in blood, such as haemoglobin, move substances around the body. Actin and myosin cause muscle movement."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1039' AND answer = 3;
UPDATE questions SET why = 'Each enzyme has an active site with a unique shape. Only a substrate of the matching shape can fit in and form an enzyme–substrate complex. Emil Fischer''s lock-and-key model (1894) describes this: the enzyme is the lock and the substrate is the key.', wrong = '{"0": "Enzymes are catalysts, so they are not used up. They come out of the reaction unchanged and can bind another substrate.", "2": "Enzymes lower the activation energy, which is why reactions go faster. Raising it would slow the reaction.", "3": "Enzymes are proteins, made of amino acids, not carbohydrates."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1040' AND answer = 1;
UPDATE questions SET why = 'Carbonic anhydrase in the blood speeds up the reaction of CO₂ with water to form carbonic acid. A single molecule of this enzyme converts about one million molecules of CO₂ and water each minute, which shows how fast enzymes can work.', wrong = '{"0": "Amylase breaks down starch into sugars. It acts on starch, not on CO₂ and water.", "1": "Pepsin is a stomach enzyme that breaks down proteins. It is not the example for CO₂ and water.", "3": "Transpeptidase helps build bacterial cell walls and is the enzyme blocked by penicillin. It does not act on CO₂."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1041' AND answer = 2;
UPDATE questions SET why = 'Enzymes are proteins whose shape is held by weak bonds such as hydrogen bonds. Well above the optimum temperature, strong vibrations break these bonds, so the protein unfolds (denatures). The active site loses its shape, the substrate no longer fits, and activity falls.', wrong = '{"0": "Once the active site is distorted, fewer enzyme–substrate complexes form, not more. That is why the rate drops.", "1": "Raising the temperature makes molecules move faster, not stop. The fall in rate is due to the enzyme being denatured.", "2": "Heating does not change a protein into a carbohydrate. The enzyme stays a protein but loses its folded shape."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1042' AND answer = 3;
UPDATE questions SET why = 'Succinate dehydrogenase normally acts on succinate (butanedioate). Malonate (propanedioate) has a very similar shape, with two –COO⁻ groups, so it fits the active site and competes with succinate. It is a competitive inhibitor, and adding more succinate can reduce its effect.', wrong = '{"0": "Permanently changing the enzyme''s shape describes irreversible or non-competitive inhibition. Malonate binds the active site reversibly.", "2": "Malonate does not react with or destroy succinate. It simply blocks the active site so succinate cannot bind.", "3": "Malonate inhibits by its shape, competing for the active site. It does not work by changing the pH."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1043' AND answer = 1;
UPDATE questions SET why = 'Bacteria need the enzyme transpeptidase to build their cell walls. Penicillin binds to this enzyme and blocks it permanently, so it is an irreversible inhibitor. Without a proper cell wall, the bacteria cannot survive.', wrong = '{"0": "Penicillin does not attack DNA. It acts on transpeptidase, the enzyme that builds the cell wall.", "1": "Insulin is a hormone that controls blood glucose in humans. It has nothing to do with how penicillin kills bacteria.", "3": "Penicillin is not used as food by the enzyme. It binds to transpeptidase and switches it off permanently."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1044' AND answer = 2;
UPDATE questions SET why = 'Polysaccharides and proteins are polymers built from repeating units (sugars and amino acids). Lipids are not; they are a mixed group of mostly non-polar molecules with no repeating monomer. Being non-polar, they do not dissolve in water but dissolve in organic solvents such as ether and chloroform.', wrong = '{"0": "Molecules made of amino acids are proteins. Lipids do not contain amino-acid chains.", "1": "Polymers of glucose are polysaccharides such as starch and cellulose, not lipids.", "2": "Lipids are largely non-polar (hydrophobic), so they are insoluble in water."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1045' AND answer = 3;
UPDATE questions SET why = 'Fats and oils are both triglycerides, esters of glycerol with three fatty acids. In fats the chains are mostly saturated and straight, so they pack closely and are solid at room temperature. In oils, C=C double bonds put kinks in the chains, which stops close packing, so they are liquid.', wrong = '{"0": "Both fats and oils are triglycerides, and both are built on glycerol. The difference lies in the fatty-acid chains.", "2": "Neither fats nor oils are polymers. Each molecule is one glycerol joined to three fatty acids.", "3": "Phosphate groups are found in phospholipids, not in ordinary fats."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1046' AND answer = 1;
UPDATE questions SET why = 'A triglyceride has three fatty acids on glycerol. In a phospholipid only two –OH groups of glycerol carry fatty acids; the third carries a phosphate group. This gives a polar (water-loving) head and two non-polar tails, which is why phospholipids form cell membranes.', wrong = '{"0": "A steroid nucleus of four fused rings is found in steroids such as cholesterol, not in phospholipids.", "1": "Three fatty acids is the triglyceride pattern, and phospholipids do contain glycerol. They have two fatty acids plus a phosphate.", "3": "Peptide bonds join amino acids in proteins. Phospholipids contain ester and phosphate links, not peptide bonds."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1047' AND answer = 2;
UPDATE questions SET why = 'All steroids share the same core of four fused rings: three six-membered cyclohexane rings and one five-membered cyclopentane ring, labelled A, B, C and D. Different groups on this core give cholesterol, bile salts, vitamin D and the sex hormones.', wrong = '{"0": "Glycerol joined to three fatty acids is a triglyceride (a fat or oil), not a steroid.", "1": "The steroid rings are saturated cyclohexane and cyclopentane rings, not benzene rings, and one of the four is five-membered.", "2": "Glucose rings are found in carbohydrates. Steroids are lipids with no sugar units in their core."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1048' AND answer = 3;
UPDATE questions SET why = 'Terpenes are hydrocarbons found in plants, built by joining five-carbon isoprene units (2-methylbuta-1,3-diene, CH₂=C(CH₃)–CH=CH₂). Limonene in lemons is a terpene. Terpenes with 40 carbon atoms (eight isoprene units) are called carotenoids.', wrong = '{"0": "Glucose units build polysaccharides such as starch. Terpenes are hydrocarbons made of isoprene units.", "2": "Amino acids build proteins. Terpenes contain no nitrogen.", "3": "Nucleotides build nucleic acids such as DNA and RNA, not terpenes."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1049' AND answer = 1;
UPDATE questions SET why = 'Fat is a more concentrated energy store than glycogen. When fat is oxidised to carbon dioxide and water it gives much more energy per gram than carbohydrate does. So animals such as polar bears store fat before hibernation, carrying a lot of energy in little mass.', wrong = '{"0": "Fat is stored mainly in adipose tissue under the skin and around organs, not only in the liver. Storage site is not the reason anyway.", "1": "Fats are non-polar and do not dissolve in blood (which is mostly water). They need carrier proteins to be transported.", "3": "Fats contain only carbon, hydrogen and oxygen. Nitrogen is found in proteins and nucleic acids."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1050' AND answer = 2;
UPDATE questions SET why = 'Vitamins A, D, E and K are fat-soluble. They dissolve in lipids, so dietary fat acts as their solvent and helps them be absorbed in the intestine and carried into the blood. That is why these vitamins are best eaten with some fat.', wrong = '{"0": "Vitamin C is water-soluble, so it does not need lipids to be absorbed.", "1": "The B vitamins and vitamin C are water-soluble and are absorbed without the help of fat.", "2": "B₁ and B₁₂ are both B vitamins, which are water-soluble, not fat-soluble."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1051' AND answer = 3;
UPDATE questions SET why = 'In DNA and RNA, the phosphate group of one nucleotide forms ester links to the 3′ carbon of one sugar and the 5′ carbon of the next. This C–O–P–O–C link is a phosphodiester bond, and a chain of them makes the strong sugar–phosphate backbone.', wrong = '{"1": "Peptide bonds join amino acids in proteins. Bases in nucleic acids are not linked to each other by peptide bonds.", "2": "Glycosidic bonds link each base to its sugar. The link between nucleotides is through phosphate, a phosphodiester bond.", "3": "Hydrogen bonds hold the bases of the two DNA strands together. The sugars in one strand are joined by covalent phosphodiester links."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1052' AND answer = 0;
UPDATE questions SET why = 'In the DNA double helix, adenine always pairs with thymine and guanine with cytosine. The A–T pair is held by two hydrogen bonds and the G–C pair by three. This is why DNA rich in G–C pairs is harder to separate.', wrong = '{"1": "This swaps the numbers. A–T has two hydrogen bonds and G–C has three.", "2": "A–T pairs do have two hydrogen bonds, but G–C pairs have three, not two.", "3": "G–C pairs do have three hydrogen bonds, but A–T pairs have only two."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1053' AND answer = 0;
UPDATE questions SET why = 'In 1953 James Watson and Francis Crick proposed that DNA consists of two polynucleotide chains wound around each other in a right-handed double helix. The strands are held together by hydrogen bonds between complementary base pairs.', wrong = '{"1": "Emil Fischer proposed the lock-and-key model of enzyme action in 1894, not the structure of DNA.", "2": "Woodward and Eschenmoser are known for the total synthesis of vitamin B₁₂, not the DNA double helix.", "3": "Ziegler and Natta developed catalysts for polymerising alkenes, such as making poly(propene). They did not work on DNA."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1054' AND answer = 0;
UPDATE questions SET why = 'The genetic code is read in groups of three bases. Each group of three, called a codon, codes for one amino acid. The levels run genome, chromosome, gene, DNA, codon, from largest to smallest.', wrong = '{"1": "A section of DNA on a chromosome that codes for one protein is a gene. A gene contains many codons.", "2": "A pair of chromosomes is a much larger unit; humans have 23 pairs. A codon is just three bases.", "3": "The sugar–phosphate backbone holds the bases in place, but the code is carried by the base sequence, read three at a time."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1055' AND answer = 0;
UPDATE questions SET why = 'During translation, transfer RNA (tRNA) molecules each carry a specific amino acid. Each tRNA recognises a matching codon on the mRNA, so the amino acids are lined up in the order set by the code. In this way tRNA turns the base sequence into an amino-acid sequence.', wrong = '{"1": "Messenger RNA (mRNA) carries the code copied from DNA to the ribosome. It does not carry amino acids itself.", "2": "Ribosomal RNA (rRNA) forms part of the ribosome, where proteins are built. It does not bring amino acids.", "3": "DNA stores the genetic code in the nucleus and is not used directly in translation. It does not carry amino acids."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1056' AND answer = 0;
UPDATE questions SET why = 'Gene expression has two steps. First, in the nucleus, the base sequence of a gene in DNA is copied into a strand of messenger RNA (mRNA); this step is transcription. The mRNA then travels to a ribosome, where translation turns its code into a protein.', wrong = '{"1": "Translation is the second step. It happens at the ribosome, where the mRNA code is read to join amino acids into a protein.", "2": "Replication copies a whole DNA molecule into new DNA before cell division. It does not make mRNA.", "3": "Denaturation is the loss of a protein''s folded shape, caused by heat or pH. It has nothing to do with copying genes."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1057' AND answer = 0;
UPDATE questions SET why = 'Calcium, found in milk, dairy foods and green vegetables, helps form bones and teeth. It is also needed for normal blood clotting, muscle contraction and relaxation, heart function and nerve function. So calcium fits both roles in the stem.', wrong = '{"1": "Iron is needed to make haemoglobin and myoglobin, which carry and store oxygen. It is not the mineral for clotting and bones.", "2": "Zinc is part of many enzyme systems and is found in insulin. It is not the key mineral for bones and clotting.", "3": "Sodium mainly helps with fluid balance and nerve signals. It is not a building material of bones or a clotting factor."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1058' AND answer = 0;
UPDATE questions SET why = 'Zinc, obtained from meat, seafood and whole grains, is a component of many enzyme systems involved in growth and immune function. It is also found in the hormone insulin, which controls blood glucose.', wrong = '{"1": "Calcium is needed for bones and teeth, blood clotting, muscle action and nerve function, not for insulin.", "2": "Phosphorus is part of bones, ATP and phospholipids. It is not the mineral found in insulin.", "3": "Iron is part of haemoglobin and myoglobin, which carry oxygen. It is not the mineral linked to insulin."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1059' AND answer = 0;
UPDATE questions SET why = 'Phosphorus helps build bones and teeth and controls the release and use of energy through ATP (adenosine triphosphate). It is part of phospholipids, which help carry fat in the body, and it helps keep the acid–base balance normal.', wrong = '{"1": "Haemoglobin synthesis needs iron, which binds the oxygen carried by red blood cells.", "2": "The mineral found in the hormone insulin is zinc, not phosphorus.", "3": "Blood clotting is a role of calcium. Phosphorus has several other roles, so \"clotting only\" is wrong on both counts."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1060' AND answer = 0;
UPDATE questions SET why = 'Chromatography uses two phases: a stationary phase that stays in place and a mobile phase that moves over it. Each component of a mixture is attracted to the two phases to a different degree (different affinity), so the components move at different speeds and separate.', wrong = '{"1": "Colour only makes spots easy to see. Colourless substances can also be separated and then shown with a locating agent.", "2": "Separation by density is used in methods such as centrifuging, not chromatography.", "3": "Melting point is used to test purity, not to separate components by chromatography."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1061' AND answer = 0;
UPDATE questions SET why = 'Adsorption means gas or dissolved particles stick to the surface of a solid. Activated charcoal is very porous and has a huge surface area, so large amounts of gases and impurities collect on its surface. This makes it useful in gas masks and filters.', wrong = '{"0": "Charcoal holds gases by a surface effect, adsorption. It does not react chemically with every gas.", "2": "Adsorbed gas stays on the surface of the charcoal. It is not dissolved evenly through the solid.", "3": "Taking a substance into the interior is absorption. Charcoal works by adsorption, which happens at the surface."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1062' AND answer = 1;
UPDATE questions SET why = 'Filter paper is made of cellulose, which holds water. In paper chromatography this trapped water is the stationary phase, and the solvent that rises up the paper is the mobile phase. Components separate by how well they dissolve in each phase, which is called partition.', wrong = '{"0": "An inert gas such as helium is the mobile phase in gas chromatography. It plays no part in paper chromatography.", "1": "The organic solvent moves up the paper, so it is the mobile phase, not the stationary phase.", "2": "A layer of silica or alumina on glass is the stationary phase in thin-layer chromatography (TLC), not paper chromatography."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1063' AND answer = 3;
UPDATE questions SET why = 'Rf (retardation factor) = distance moved by the substance ÷ distance moved by the solvent front, both measured from the baseline. Since it is a ratio of two lengths it has no unit, and because a spot cannot move further than the solvent, Rf is never more than 1.', wrong = '{"0": "This is the ratio turned upside down. It would give values greater than 1, which is impossible for an Rf.", "1": "The time a substance takes to pass through a column is the retention time used in gas chromatography.", "3": "Peak area is measured in gas chromatography to find how much of each component is present."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1064' AND answer = 2;
UPDATE questions SET why = 'Rf = distance moved by the spot ÷ distance moved by the solvent front. Here Rf = 4.8 cm ÷ 12.0 cm = 0.40. The units cancel, and 0.40 is less than 1 as an Rf must be.', wrong = '{"0": "2.5 is 12.0 ÷ 4.8, the ratio upside down. An Rf can never be greater than 1.", "2": "0.25 would mean the spot moved only 3.0 cm, a quarter of 12.0 cm. It is a division slip.", "3": "7.2 is 12.0 − 4.8, a difference in centimetres. Rf is a ratio of distances, not a subtraction."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1065' AND answer = 1;
UPDATE questions SET why = 'Rearranging Rf = distance moved by spot ÷ distance moved by solvent gives distance of spot = Rf × solvent distance. So the spot moved 0.65 × 8.0 cm = 5.2 cm, which is less than 8.0 cm as expected.', wrong = '{"1": "12.3 cm is 8.0 ÷ 0.65. A spot cannot travel further than the solvent front, so this is impossible.", "2": "0.65 is the Rf itself, which is a unitless ratio, not a distance in cm.", "3": "7.35 cm is 8.0 − 0.65. Rf must be multiplied by the solvent distance, not subtracted from it."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1066' AND answer = 0;
UPDATE questions SET why = 'The Rf value of a substance depends on the conditions, mainly the solvent used and the temperature. If these stay the same, a substance always gives the same Rf, so an unknown can be identified by comparing its Rf with known standard values.', wrong = '{"1": "A larger spot may look bigger or smear, but it does not change the Rf; the conditions set it.", "2": "Rf is a ratio of two distances, so a longer paper changes both distances equally and leaves Rf unchanged.", "3": "The solvent front must be marked to calculate Rf. If the solvent runs off the top, its distance cannot be measured."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1067' AND answer = 0;
UPDATE questions SET why = 'Colourless spots cannot be seen on the chromatogram. Spraying it with a locating agent reacts with these substances and gives them colour. For example, ninhydrin turns colourless amino-acid spots purple.', wrong = '{"0": "Longer paper may spread the spots further, but it does not make a colourless spot coloured.", "1": "Heating the solvent only changes how the solvent runs. It does not give colour to a colourless spot.", "2": "Adding more sample makes the spot more concentrated, but a colourless substance stays colourless."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1068' AND answer = 3;
UPDATE questions SET why = 'In thin-layer chromatography, alumina (Al₂O₃) or silica (SiO₂) is mixed with water to form a slurry. This is spread evenly on a glass slide and dried in an oven, leaving a thin white solid layer. That layer is the stationary phase.', wrong = '{"0": "Filter paper holding water is the stationary phase in paper chromatography, not TLC.", "1": "A non-volatile liquid coated on particles in a column is the stationary phase of gas chromatography.", "3": "Helium is used as the carrier gas (mobile phase) in gas chromatography, not as a stationary phase."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1069' AND answer = 2;
UPDATE questions SET why = 'Alumina is a polar solid, and polar substances are adsorbed onto it more strongly. Butanone, which is polar, sticks more to the alumina and moves only a short way. Pentane is non-polar, stays dissolved in the non-polar solvent and travels further, so the two separate.', wrong = '{"0": "Butanone and pentane differ in polarity, so they are held to different extents and travel different distances.", "2": "This is reversed. Non-polar pentane is attracted only weakly to polar alumina, so it moves further, not less.", "3": "Alumina holds butanone by adsorption, a physical attraction. No chemical reaction takes place."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1070' AND answer = 1;
UPDATE questions SET why = 'Colourless spots on a TLC plate must be made visible before Rf values can be measured. Some colourless substances glow when the plate is placed under ultraviolet light, and others turn brown when exposed to iodine vapour. Ninhydrin spray is also used for amino acids.', wrong = '{"0": "Litmus paper shows whether a solution is acidic or basic. It is not used to locate spots on a TLC plate.", "1": "Fehling''s solution is a test for aldehydes in a test tube, not a way to reveal spots on a plate.", "2": "A flame test identifies metal ions by the colour they give to a flame. It cannot show spot positions."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1071' AND answer = 3;
UPDATE questions SET why = 'Small samples taken from a reaction mixture can be spotted on a TLC plate at intervals. If the reactant spot fades and the product spot appears, the reaction is going ahead. TLC is also used to check purity, test foods and drugs, and in forensic work.', wrong = '{"0": "TLC uses only tiny amounts of sample, so it is not suitable for separating or purifying on a large scale.", "1": "TLC compares Rf values to identify substances. It does not give an exact molar mass.", "3": "TLC uses a liquid solvent moving over a solid layer. No gas stream is involved, and it does not sort proteins by size."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1072' AND answer = 2;
UPDATE questions SET why = 'TLC separates substances by how far they move. If two compounds have very similar Rf values, their spots overlap and are not cleanly separated, so resolution is poor. Other limits are that TLC is mainly qualitative and is sensitive to humidity and temperature.', wrong = '{"0": "Needing volatile compounds is a limitation of gas chromatography. TLC works with substances in solution.", "2": "The mobile phase in TLC is a liquid solvent. A gas mobile phase is used in gas chromatography.", "3": "TLC needs only very small samples. In fact, it cannot handle large amounts."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1073' AND answer = 1;
UPDATE questions SET why = 'In gas chromatography the sample is vaporised and pushed through a long column by an inert carrier gas such as helium or nitrogen. This gas is the mobile phase. The stationary phase is a non-volatile liquid coated on tiny solid particles inside the column.', wrong = '{"0": "Silica or alumina particles in the column support the stationary liquid. They do not move, so they are not the mobile phase.", "1": "Water held in cellulose is the stationary phase in paper chromatography, not part of GC.", "2": "A liquid solvent is the mobile phase in paper chromatography and TLC. In GC the mobile phase is a gas."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1074' AND answer = 3;
UPDATE questions SET why = 'Like attracts like: non-polar substances interact more strongly with a non-polar stationary liquid. Because they spend more time held by the stationary phase, they are carried through the column more slowly. So non-polar components come out later and have longer retention times.', wrong = '{"0": "Stronger interaction with the stationary liquid slows a component down. The non-polar ones therefore pass through slowest, not fastest.", "1": "Every component eventually leaves the column and reaches the detector. Non-polar ones are simply recorded later.", "3": "The carrier gas (helium or nitrogen) is chosen because it is inert, so it does not react with the components."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1075' AND answer = 2;
UPDATE questions SET why = 'In gas chromatography, retention time is the time a substance takes to travel through the column, from injection until it reaches the detector. Each component under fixed conditions has its own retention time, which helps identify it.', wrong = '{"0": "Peak area shows how much of a component is present, not how long it took to pass through.", "2": "The distance a spot travels is measured in paper chromatography and TLC to find the Rf value.", "3": "The sample is vaporised almost at once in the injector. Retention time is the time spent passing through the column."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1076' AND answer = 1;
UPDATE questions SET why = 'In GC, the percentage of a component equals its peak area ÷ the total of all peak areas × 100. Total area = 30 + 50 + 20 = 100 units. So % of A = 30 ÷ 100 × 100 = 30%.', wrong = '{"0": "20% is C''s share, 20 ÷ 100 × 100. The question asks for A.", "1": "50% is the share of B, 50 ÷ 100 × 100, not of A. The largest peak belongs to B.", "3": "60% comes from 30 ÷ 50 × 100, comparing A with B only. The total must include all three peaks."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1077' AND answer = 2;
UPDATE questions SET why = 'A GC peak is close to a triangle, so its area = ½ × base × height. Here area = ½ × 0.8 cm × 5.0 cm = 2.0 cm². Peak areas found this way give the proportion of each component.', wrong = '{"1": "4.0 cm² is base × height, 0.8 × 5.0, with the ½ left out. That would be the area of a rectangle.", "2": "5.8 is 0.8 + 5.0. Adding two lengths gives a length, not an area.", "3": "6.25 is 5.0 ÷ 0.8, height divided by base. Area needs ½ × base × height."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1078' AND answer = 0;
UPDATE questions SET why = 'Gas chromatography needs samples that can be vaporised and stay stable when heated. Proteins are very large molecules that do not vaporise; on strong heating they break down instead. So proteins cannot be analysed by GC.', wrong = '{"0": "Ethanol is volatile, so GC is widely used to measure alcohol in blood.", "1": "Gases are already in the vapour state, so a mixture of gases is easily separated by GC.", "2": "Volatile esters vaporise easily, so they are well suited to GC."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1079' AND answer = 3;
UPDATE questions SET why = 'Forensic laboratories use gas chromatography to provide evidence in legal cases. A common example is the blood alcohol content (BAC) test, since ethanol is volatile. GC also detects illegal drugs, poisons and performance-enhancing substances in body samples.', wrong = '{"1": "DNA sequencing reads the order of bases in DNA. It is not done by gas chromatography, as DNA does not vaporise.", "2": "Fingerprint dusting uses powder to show prints on surfaces. It is not a chromatographic method.", "3": "Blood pressure is a physical measurement made with a cuff. It is not a chemical analysis of a mixture."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1080' AND answer = 0;
UPDATE questions SET why = 'Paper chromatography relies on a solvent slowly soaking up through paper, so it is slow. TLC uses a thin solid layer on glass and is faster than paper. GC pushes vapours through a column with a carrier gas and is very fast. So the order is paper < TLC < GC.', wrong = '{"0": "TLC is faster than paper chromatography, so TLC cannot come before paper in a slowest-to-fastest list.", "2": "This lists them from fastest to slowest, the reverse of what is asked.", "3": "GC is the fastest of the three, so it must come last, after TLC."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1081' AND answer = 1;
UPDATE questions SET why = 'In gas chromatography the stationary phase is a non-volatile, high-boiling liquid (a long-chain hydrocarbon) coated on tiny particles of silica or alumina packed in the column. Components separate by how strongly they dissolve in this liquid compared with the moving gas.', wrong = '{"0": "A dry solid layer of silica (or alumina) is the stationary phase in TLC. In GC the silica only supports the stationary liquid.", "1": "Water held in the cellulose of paper is the stationary phase of paper chromatography.", "3": "Helium is an inert carrier gas, so it is the mobile phase in GC, not the stationary phase."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1082' AND answer = 2;
UPDATE questions SET why = 'Energy of a photon is directly proportional to its frequency: E = hν, where h is Planck''s constant. Since the speed of light c = λν, frequency ν = c/λ, so E = hc/λ. Higher frequency or shorter wavelength means more energy.', wrong = '{"0": "E = h/ν would make energy fall as frequency rises. In fact E increases with ν, so E = hν.", "2": "E = hλ/c would make energy rise with wavelength. Energy is inversely proportional to λ, so E = hc/λ.", "3": "E = c/hλ puts h in the denominator, which is wrong. The correct form is E = hc/λ."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1083' AND answer = 1;
UPDATE questions SET why = 'Photon energy is E = hc/λ, so the shorter the wavelength, the higher the energy. Gamma rays have the shortest wavelength (and highest frequency) in the electromagnetic spectrum, so each gamma-ray photon carries the most energy.', wrong = '{"0": "Infrared has longer wavelengths than visible light, so its photons carry less energy than visible, UV or gamma photons.", "1": "Ultraviolet photons are energetic, but X-rays and gamma rays have even shorter wavelengths and more energy.", "3": "Radio waves have the longest wavelengths of all, so their photons have the lowest energy."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1084' AND answer = 2;
UPDATE questions SET why = 'IHD (index of hydrogen deficiency) is the number of H₂ pairs a compound lacks compared with the saturated alkane, CₙH₂ₙ₊₂. For six carbons that is C₆H₁₄. Both compounds are C₆H₁₂, short by 2 H, one pair, so IHD = 1: a C=C in hex-1-ene and a ring in cyclohexane.', wrong = '{"0": "6 is the number of carbon atoms. IHD counts the missing pairs of hydrogen atoms, which here is only one.", "1": "IHD = 0 means a fully saturated, open-chain compound, C₆H₁₄. These molecules have two fewer H.", "2": "IHD = 2 would need four fewer H, giving C₆H₁₀. C₆H₁₂ is short by only one pair."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1085' AND answer = 3;
UPDATE questions SET why = 'Saturated C₆ is C₆H₁₄. Benzene, C₆H₆, has 8 fewer H atoms, which is 8 ÷ 2 = 4 pairs, so IHD = 4. This matches its structure: one ring plus three C=C double bonds.', wrong = '{"1": "3 counts only the three C=C bonds and forgets that the ring itself also counts as one.", "2": "6 is the number of carbon atoms (or hydrogen atoms) in benzene, not its IHD.", "3": "IHD = 1 fits C₆H₁₂, such as cyclohexane. Benzene is much more unsaturated."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1086' AND answer = 0;
UPDATE questions SET why = 'A saturated hydrocarbon with 30 carbons is C₃₀H₆₂ (CₙH₂ₙ₊₂). The hopane C₃₀H₅₂ has 62 − 52 = 10 fewer H atoms, which is 10 ÷ 2 = 5 pairs. So its IHD is 5; hopanes contain five rings and no double bonds.', wrong = '{"1": "IHD = 0 would need the fully saturated open-chain formula C₃₀H₆₂.", "2": "4 comes from using CₙH₂ₙ (60 H) instead of CₙH₂ₙ₊₂ (62 H) as the saturated formula: (60 − 52) ÷ 2 = 4.", "3": "10 is the number of missing H atoms. IHD counts pairs, so it is 10 ÷ 2 = 5."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1087' AND answer = 0;
UPDATE questions SET why = 'Each ring and each C=C counts 1 towards IHD, and a C≡C counts 2. One ring plus two C=C bonds adds up to 1 + 2 = 3, so it cannot be a structure with IHD = 2.', wrong = '{"0": "One ring (1) plus one C=C (1) gives IHD = 2, so this is possible.", "1": "A triple bond counts as two degrees of unsaturation, so one C≡C alone gives IHD = 2.", "2": "Each ring counts 1, so two rings give IHD = 2. This is possible."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1088' AND answer = 3;
UPDATE questions SET why = 'When atoms are heated or given energy, electrons jump to higher energy levels. As they fall back to lower levels they give out photons with definite energies and so definite wavelengths. These appear as separate bright coloured lines on a dark background, called an emission spectrum.', wrong = '{"0": "Dark lines on a coloured (continuous) background form an absorption spectrum, when a cool gas absorbs certain wavelengths.", "2": "A continuous rainbow comes from white light or a hot solid. Atoms give separate lines because their energy levels are fixed.", "3": "Atomic spectra are sharp line spectra, not one broad band. Each line matches one electron jump."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1089' AND answer = 1;
UPDATE questions SET why = 'When white light passes through a cool gas at low pressure, the atoms absorb only photons whose energy exactly matches a jump between their energy levels. These wavelengths go missing, so dark lines appear across the continuous spectrum, at the same positions as that element''s emission lines.', wrong = '{"0": "Passing electrons through a magnet bends their path. It does not produce an absorption spectrum.", "1": "Heating a gas until it glows makes its electrons fall back and emit light, which gives an emission spectrum.", "3": "Burning an element gives out light, which is emission. Absorption needs light passing through a cool gas."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1090' AND answer = 2;
UPDATE questions SET why = 'When sodium is heated in a flame, its excited electrons fall back and emit strong lines at about 589 nm. This wavelength lies in the yellow part of the visible spectrum, so sodium gives a bright yellow flame, as also seen in sodium street lamps.', wrong = '{"1": "656 nm is the strong red line of hydrogen, not sodium.", "2": "410 nm is a violet line in the hydrogen spectrum, not the yellow sodium line.", "3": "217 nm is in the ultraviolet, where buta-1,3-diene absorbs (its λmax). It is not visible light."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1091' AND answer = 0;
UPDATE questions SET why = 'Each element has its own fixed set of electron energy levels, so it emits its own unique pattern of spectral lines. No two elements give the same set, so the lines act like a fingerprint. This even lets astronomers find which elements are present in stars.', wrong = '{"0": "Non-metals also give line spectra. Hydrogen, a non-metal, has a well-known spectrum with a red line at 656 nm.", "1": "If all elements gave the same lines, spectra could not tell them apart. Each element''s pattern is different.", "2": "Temperature affects how bright the lines are, but their positions are set by the element''s energy levels."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1092' AND answer = 3;
UPDATE questions SET why = 'Transmittance T is the fraction of light that passes through the sample. Absorbance is defined as A = −log T (= log 1/T). If T = 0.1, only 10% passes and A = 1; less light passing means a larger absorbance.', wrong = '{"0": "Since T is at most 1, log T is zero or negative. Without the minus sign absorbance would come out negative.", "2": "A = 1/T is not the definition. Absorbance uses a logarithm: A = −log T.", "3": "100 − T gives the percentage not transmitted, which is not the same as absorbance. Absorbance is logarithmic."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1093' AND answer = 1;
UPDATE questions SET why = 'The filled bonding orbitals are lowest in energy, σ below π. Non-bonding (n) orbitals, holding lone pairs, lie above them. The empty antibonding orbitals are highest, with π* below σ*. So the order is σ < π < n < π* < σ*.', wrong = '{"0": "σ bonding orbitals are the lowest of all, not π. Also, σ* lies above π*.", "1": "Non-bonding n orbitals lie above the bonding σ and π orbitals, not below them.", "3": "π bonding lies below n, and π* lies below σ*. Both pairs are in the wrong order here."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1094' AND answer = 2;
UPDATE questions SET why = 'Buta-1,3-diene has C=C π bonds but no lone pairs, so n transitions are impossible. Its absorption at 217 nm comes from π → π* jumps. Since 217 nm is in the UV, below the visible range of about 400 to 800 nm, no visible light is absorbed and the compound is colourless.', wrong = '{"0": "d–d transitions happen in transition-metal ions with partly filled d orbitals. Butadiene has no d electrons.", "1": "n → π* needs non-bonding (lone-pair) electrons, which butadiene lacks, and absorbing at 217 nm gives no colour.", "2": "217 nm is in the UV, not the visible region. σ → σ* jumps need even more energy, at shorter wavelengths."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1095' AND answer = 3;
UPDATE questions SET why = 'As more C=C bonds are conjugated, the gap between the highest filled π orbital and the lowest empty π* orbital becomes smaller. A smaller energy gap means lower-energy, longer-wavelength light is absorbed (E = hc/λ). So λmax rises: 217, then 257, then 290 nm.', wrong = '{"0": "A larger gap would mean shorter wavelengths absorbed, but λmax increases. So the gap must be getting smaller.", "2": "λmax clearly increases with each extra C=C, from 217 to 257 to 290 nm.", "3": "Conjugation shifts absorption to longer wavelengths, towards the visible region, not to X-rays."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1096' AND answer = 1;
UPDATE questions SET why = 'Chlorophyll (in green tomatoes) and lycopene (in red tomatoes) are both highly conjugated pigments. Each absorbs light most strongly at a different visible wavelength, its λmax. The colour seen is made of the light that is not absorbed, so the tomatoes look different.', wrong = '{"0": "A compound that absorbs only in the UV absorbs no visible light and looks colourless. These pigments are coloured.", "1": "Infrared absorption is linked to bond vibrations and does not give a visible colour.", "3": "Both pigments have long conjugated systems. That is exactly why they absorb in the visible region."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1097' AND answer = 2;
UPDATE questions SET why = 'A bond absorbs IR radiation only if its vibration changes the molecule''s dipole moment. Symmetrical non-polar molecules such as H₂ and O₂ have no dipole and their stretching does not create one, so they are IR inactive. Polar bonds such as O–H and C=O absorb strongly.', wrong = '{"0": "Unpaired electrons are not needed. Most organic molecules have all electrons paired and still absorb IR.", "1": "Organic compounds with no metal at all, such as alcohols and ketones, give strong IR spectra.", "2": "Symmetrical non-polar molecules such as H₂ and O₂ are exactly the ones that do not absorb IR."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1098' AND answer = 3;
UPDATE questions SET why = 'A bond behaves like a spring. Stronger, shorter bonds, such as multiple bonds like C≡C and polar bonds like O–H, are stiffer and vibrate at higher frequencies. They need more energy to vibrate, so they absorb at higher wavenumbers.', wrong = '{"0": "Longer, weaker bonds vibrate more slowly and absorb at lower wavenumbers, not higher.", "2": "O–H and C≡C are covalent bonds, not ionic. Their high wavenumbers come from bond strength.", "3": "O–H is a strongly polar bond. Being non-polar is not the reason for absorbing at high wavenumbers."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1099' AND answer = 1;
UPDATE questions SET why = 'An IR spectrum has two parts. Above 1500 cm⁻¹ is the functional-group region, where bonds like O–H and C=O give clear peaks. Below 1500 cm⁻¹ is the fingerprint region, a complex pattern unique to each molecule, like a fingerprint.', wrong = '{"0": "2200 to 2250 cm⁻¹ is where the C≡N of nitriles absorbs, in the functional-group region.", "1": "Above 3000 cm⁻¹ lies in the functional-group region, where O–H, N–H and C–H peaks appear.", "3": "The fingerprint region is part of the infrared spectrum, not the ultraviolet."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1100' AND answer = 2;
UPDATE questions SET why = 'A strong, sharp peak near 1710 cm⁻¹ shows a C=O bond. Since there is no broad band at 3200 to 3600 cm⁻¹, there is no O–H group. A carbonyl with no O–H fits a ketone such as propanone.', wrong = '{"0": "A nitrile shows its C≡N peak at 2200 to 2250 cm⁻¹, not at 1710 cm⁻¹.", "1": "An alcohol such as propan-2-ol shows a broad O–H band at 3200 to 3600 cm⁻¹ and has no C=O peak.", "2": "An alkane has only C–C and C–H bonds, so it shows no C=O peak near 1710 cm⁻¹."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1101' AND answer = 3;
UPDATE questions SET why = 'A carboxylic acid, –COOH, has both C=O and O–H. Its C=O gives a strong peak near 1700 cm⁻¹. Its O–H, heavily hydrogen-bonded, gives a very broad band from about 2500 to 3300 cm⁻¹ that overlaps the C–H peaks. Both features together identify the acid.', wrong = '{"0": "A sharp peak near 2200 cm⁻¹ belongs to a C≡N (nitrile) group, not a carboxylic acid.", "2": "Peaks at 3300 to 3500 cm⁻¹ come from N–H bonds in amines and amides. Acids show a broad O–H band.", "3": "Acids have strong peaks above 1500 cm⁻¹, from C=O near 1700 cm⁻¹ and O–H at 2500 to 3300 cm⁻¹."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1102' AND answer = 1;
UPDATE questions SET why = 'The triple bond in a nitrile, C≡N, is very strong and stiff, so it vibrates at a high frequency. It gives a characteristic absorption at about 2200 to 2250 cm⁻¹, a region where few other bonds absorb.', wrong = '{"1": "1710 to 1750 cm⁻¹ is the C=O stretch of esters, not C≡N.", "2": "3200 to 3600 cm⁻¹ is the broad O–H band of alcohols.", "3": "2850 to 2950 cm⁻¹ is the C–H stretch of alkanes, a single bond that absorbs at lower energy."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1103' AND answer = 0;
UPDATE questions SET why = 'A modern roadside breathalyser passes infrared radiation through the breath sample. The C–H and O–H bonds of ethanol absorb certain IR wavelengths. The more radiation absorbed, the more ethanol is present in the person''s breath.', wrong = '{"0": "Mass spectrometry is a laboratory method. Roadside breathalysers measure ethanol by its infrared absorption.", "1": "Ethanol has no conjugated π system, so it does not absorb UV light usefully.", "3": "Paper chromatography separates mixtures slowly on paper. It is not used for quick breath testing."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1104' AND answer = 2;
UPDATE questions SET why = 'Relative atomic mass is the weighted average of isotope masses: Ar = (% × mass + % × mass) ÷ 100. For boron, Ar = (19.9 × 10 + 80.1 × 11) ÷ 100 = (199 + 881.1) ÷ 100 = 10.80. It lies closer to 11 because ¹¹B is more abundant.', wrong = '{"1": "10.50 is the simple average of 10 and 11, which ignores that ¹¹B is four times more common.", "2": "10.20 comes from swapping the abundances: (80.1 × 10 + 19.9 × 11) ÷ 100 = 10.20.", "3": "11.00 is the mass of ¹¹B alone. It ignores the 19.9% of lighter ¹⁰B."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1105' AND answer = 0;
UPDATE questions SET why = 'Relative atomic mass is the weighted average of the isotope masses. For chlorine, Ar = (75 × 35 + 25 × 37) ÷ 100 = (2625 + 925) ÷ 100 = 35.5. It lies nearer 35 because ³⁵Cl is three times as common as ³⁷Cl.', wrong = '{"1": "36.0 is the simple average of 35 and 37, which ignores their different abundances.", "2": "35.0 is the mass of ³⁵Cl alone. It ignores the 25% of heavier ³⁷Cl.", "3": "36.5 comes from swapping the abundances: (25 × 35 + 75 × 37) ÷ 100 = 36.5."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1106' AND answer = 0;
UPDATE questions SET why = 'In a mass spectrometer, fast electrons knock one electron out of the molecule, M + e⁻ → M⁺ + 2e⁻. The ion formed is the whole molecule with a single positive charge, called the molecular ion. Its m/e value equals the relative molecular mass, Mr.', wrong = '{"0": "The tallest peak (base peak) is often a stable fragment ion, not M⁺. The molecular ion can be small if it breaks up easily.", "1": "Fragments are pieces formed when M⁺ breaks apart. The molecular ion is the heaviest ion, not the smallest.", "2": "M⁺ forms by losing an electron, not by gaining a proton. A protonated molecule would have m/e one unit higher."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1107' AND answer = 3;
UPDATE questions SET why = 'The molecular ion peak gives Mr. Butanal is C₄H₈O, so Mr = 4(12) + 8(1) + 16 = 48 + 8 + 16 = 72. This matches the M⁺ peak at m/e = 72, so the compound could be butanal.', wrong = '{"0": "Propanal is C₃H₆O: 36 + 6 + 16 = 58, so its M⁺ peak is at 58.", "2": "Ethanal is C₂H₄O: 24 + 4 + 16 = 44, so its M⁺ peak is at 44.", "3": "Pentanal is C₅H₁₀O: 60 + 10 + 16 = 86, so its M⁺ peak is at 86."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1108' AND answer = 1;
UPDATE questions SET why = 'Hexane (Mr = 86) breaks into alkyl cation fragments. A peak at 43 fits three carbons and seven hydrogens: C₃H₇⁺ = 3(12) + 7(1) = 43, which is CH₃CH₂CH₂⁺. Other hexane fragments appear at 71, 57, 29 and 15.', wrong = '{"0": "CH₃⁺ has mass 12 + 3 = 15, so it gives the peak at m/e = 15.", "1": "CH₃CH₂⁺ (C₂H₅⁺) has mass 24 + 5 = 29, so it gives the peak at 29.", "3": "C₄H₉⁺ has mass 48 + 9 = 57, so it gives the peak at 57."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1109' AND answer = 2;
UPDATE questions SET why = 'Each carbon has a 1.1% chance of being ¹³C, so the [M+1] peak grows with the number of carbons: n = (100 × abundance of [M+1]) ÷ (1.1 × abundance of M⁺). Here n = (100 × 2.2) ÷ (1.1 × 40) = 220 ÷ 44 = 5 carbon atoms.', wrong = '{"1": "With 4 carbons the [M+1] peak would be 4 × 1.1% of 40, about 1.8, not 2.2.", "2": "2 comes from 2.2 ÷ 1.1, which treats the M⁺ peak as if it were 100 instead of 40.", "3": "With 11 carbons the [M+1] peak would be 11 × 1.1% of 40, about 4.8, far more than 2.2."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1110' AND answer = 0;
UPDATE questions SET why = 'Natural carbon is about 98.9% ¹²C and 1.1% ¹³C. Molecules that contain one ¹³C atom are one mass unit heavier, so they give a small peak at M+1. The more carbon atoms a molecule has, the larger this [M+1] peak is.', wrong = '{"0": "Chlorine''s isotopes ³⁵Cl and ³⁷Cl differ by 2 mass units, so they give [M+2] peaks, not [M+1].", "1": "The molecular ion forms by losing an electron. It does not pick up an extra hydrogen atom.", "2": "Deuterium (²H) is very rare in nature, far less common than ¹³C, so it is not the main cause."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1111' AND answer = 3;
UPDATE questions SET why = 'Bromine has two isotopes, ⁷⁹Br and ⁸¹Br, in almost equal amounts (about 50% each). A molecule with one Br atom therefore has two molecular ions two units apart, M and M+2, with nearly equal heights, a ratio of about 1 : 1.', wrong = '{"1": "3 : 1 is the pattern for one chlorine atom, since ³⁵Cl is three times as common as ³⁷Cl.", "2": "9 : 6 : 1 (M, M+2, M+4) is the pattern for two chlorine atoms.", "3": "1 : 2 : 1 (M, M+2, M+4) is the pattern for two bromine atoms."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1112' AND answer = 0;
UPDATE questions SET why = 'Chlorine is 75% ³⁵Cl and 25% ³⁷Cl, a ratio of 3 : 1. With two Cl atoms the possible pairs are ³⁵Cl³⁵Cl (3 × 3 = 9), ³⁵Cl³⁷Cl in two ways (2 × 3 × 1 = 6) and ³⁷Cl³⁷Cl (1 × 1 = 1). This gives M : M+2 : M+4 = 9 : 6 : 1.', wrong = '{"0": "One Cl atom gives only two peaks, M and M+2, in the ratio 3 : 1. There is no M+4 peak.", "2": "Two Br atoms (⁷⁹Br and ⁸¹Br about 1 : 1) give M : M+2 : M+4 in the ratio 1 : 2 : 1.", "3": "One Br atom gives just two peaks of nearly equal height, M and M+2 in a 1 : 1 ratio."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1113' AND answer = 1;
UPDATE questions SET why = 'Bromine exists as ⁷⁹Br and ⁸¹Br in nearly equal amounts. CH₃⁷⁹Br has mass 15 + 79 = 94, and CH₃⁸¹Br has mass 15 + 81 = 96. So bromomethane shows two molecular ion peaks, at 94 and 96, of about equal height.', wrong = '{"0": "Carbon is about 98.9% ¹²C and only 1.1% ¹³C, not equal amounts. ¹³C would also give M+1, not M+2.", "1": "Fragments are lighter than the molecule, so they appear below 94. Both 94 and 96 are whole-molecule ions.", "3": "Losing a hydrogen would lower the mass to 93 or 95, not create a peak at 96."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1114' AND answer = 2;
UPDATE questions SET why = 'A ¹H nucleus spins and acts like a tiny magnet. In a strong external magnetic field it can line up with the field (lower energy) or against it (higher energy). The small energy gap between these two spin states is what NMR measures.', wrong = '{"1": "Nuclei do not all take one state. Two orientations are possible, with and against the field, and they differ in energy.", "2": "The spin does not disappear in a field. It is the spin that makes the nucleus magnetic in the first place.", "3": "Nuclei in NMR absorb and re-emit low-energy radio waves, not X-rays."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1115' AND answer = 0;
UPDATE questions SET why = 'The energy gap between the two nuclear spin states in a magnetic field is very small. Radio waves have low enough energy to match this gap exactly, so absorbing radio-frequency radiation flips nuclei from the lower to the higher spin state.', wrong = '{"0": "UV light carries much more energy and excites electrons between orbitals, as in UV-Vis spectroscopy.", "2": "X-rays are far too energetic for spin flipping; they can knock out inner electrons.", "3": "Infrared radiation makes bonds vibrate, as in IR spectroscopy. It does not flip nuclear spins."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1116' AND answer = 1;
UPDATE questions SET why = 'A nucleus shows NMR only if it has a net spin. ¹²C has 6 protons and 6 neutrons, both even numbers, so their spins pair up and cancel, leaving no magnetic moment. ¹³C, with 7 neutrons, has a net spin and does give an NMR signal.', wrong = '{"0": "Carbon atoms do have electrons (six of them). NMR depends on the spin of the nucleus, not on having electrons.", "1": "The mass number of ¹²C is 12, which is even. Nuclei with an odd mass number, like ¹H and ¹³C, are the NMR-active ones.", "2": "¹²C is a stable, non-radioactive isotope. Radioactivity has nothing to do with NMR signals."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1117' AND answer = 3;
UPDATE questions SET why = 'Deuterium (²H, D) has a different nucleus from ordinary hydrogen, so it flips its spin at a very different radio frequency. In a ¹H NMR spectrum the D atoms of CDCl₃ give no signal, so the solvent does not hide the sample''s peaks.', wrong = '{"0": "Deuterium has one proton and one neutron. It is ordinary hydrogen (¹H) that has no neutron.", "1": "CDCl₃, deuterated chloroform, is a liquid at room temperature, used to dissolve the sample.", "3": "Deuterium is an isotope of hydrogen and is not more electronegative than chlorine. Its frequency is the reason."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1118' AND answer = 2;
UPDATE questions SET why = 'Chemical shifts are measured relative to a standard. Tetramethylsilane, Si(CH₃)₄ or TMS, is added to the sample and its signal is set at δ = 0.0 ppm. All other peaks are given as their distance from the TMS peak, in ppm.', wrong = '{"0": "Benzene protons appear at about 6.5 to 9.0 ppm, far from zero, so benzene is not the reference.", "2": "CDCl₃ is the solvent used to dissolve the sample. It is chosen because it gives no ¹H signal.", "3": "Water is not the standard. Its O–H signal varies and it is not added as a reference."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1119' AND answer = 1;
UPDATE questions SET why = 'TMS is chosen as the standard because it is chemically inert, so it does not react with the sample. Being acidic and reactive would make it useless, so this is the statement that is not a reason.', wrong = '{"0": "This is a real reason. TMS is unreactive, and it is volatile (low boiling), so it can be removed easily afterwards.", "1": "This is a real reason. All 12 H atoms in Si(CH₃)₄ are equivalent, giving one strong, sharp peak.", "2": "This is a real reason. Silicon has low electronegativity, so the TMS protons are well shielded and appear far right, away from most signals."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1120' AND answer = 3;
UPDATE questions SET why = 'A proton near an electronegative atom has less electron density around it, so it is less shielded and appears at higher δ. In methanol the O–H proton is bonded directly to oxygen, so it appears at 4.80 ppm. The CH₃ protons are on carbon, one step further from oxygen, at 3.35 ppm.', wrong = '{"0": "The CH₃ protons have more electron density than the O–H proton, which is why they appear at the lower δ value.", "1": "In methanol, CH₃–O–H, the hydroxyl proton is bonded to oxygen, not to carbon.", "3": "TMS is only the zero reference. It does not move the position of any signal in the sample."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1121' AND answer = 2;
UPDATE questions SET why = 'Each set of chemically equivalent protons gives one peak. In propanone, CH₃COCH₃, the two CH₃ groups are attached to the same C=O and are identical. All six H atoms are in the same environment, so there is only one peak.', wrong = '{"0": "1-Chloropropane, CH₃CH₂CH₂Cl, has three different proton environments, so it gives three peaks.", "2": "Ethanol, CH₃CH₂OH, has three proton environments (CH₃, CH₂ and OH), so it gives three peaks.", "3": "Methanol, CH₃OH, has two environments (CH₃ and OH), so it gives two peaks."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1122' AND answer = 1;
UPDATE questions SET why = 'An aldehyde proton, in R–CHO, is attached to the carbon of a C=O group. The electronegative oxygen and the C=O bond leave it very deshielded, so it appears far downfield at about 9.0 to 10.0 ppm. A signal at 9.5 ppm fits this.', wrong = '{"0": "Vinylic protons (on C=C) appear at about 4.5 to 6.0 ppm, well below 9.5 ppm.", "1": "Alkyl protons such as CH₃ are highly shielded and appear at about 0.5 to 1.5 ppm.", "2": "Alkyl protons next to a C=O appear at about 2.0 to 2.6 ppm, not 9.5 ppm."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1123' AND answer = 3;
UPDATE questions SET why = 'Protons attached directly to a benzene ring (Ar–H) are strongly deshielded by the ring''s delocalised π electrons. They appear at about 6.5 to 9.0 ppm, a range that marks an aromatic compound.', wrong = '{"0": "2.0 to 2.6 ppm is where alkyl protons next to a C=O group appear.", "1": "0.5 to 1.5 ppm is where ordinary alkyl protons, such as CH₃ in alkanes, appear.", "3": "3.0 to 4.5 ppm is where alkyl protons next to an electronegative atom such as O or Cl appear."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1124' AND answer = 2;
UPDATE questions SET why = 'Ethanol, CH₃CH₂OH, has three proton environments: OH (1 H), CH₂ (2 H) and CH₃ (3 H). A low-resolution spectrum shows one peak per environment, and the area under each peak is proportional to the number of protons. So there are three peaks in the area ratio 1 : 2 : 3.', wrong = '{"1": "Ethanol has three environments, not two, and its CH₂ and OH groups do not each have 3 H.", "2": "One peak would need all six protons to be equivalent, as in propanone. Ethanol has three different environments.", "3": "Equivalent protons share one peak. The six H atoms fall into only three environments, giving three peaks."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1125' AND answer = 0;
UPDATE questions SET why = 'The closer a proton is to electronegative oxygen, the higher its δ. The CH₃ protons are furthest from oxygen, so they appear lowest, at 1.2 ppm. The CH₂ is bonded to the O, so it appears at 3.7 ppm. The O–H proton sits on the oxygen itself and appears at 5.4 ppm here.', wrong = '{"0": "The CH₃ group is furthest from oxygen, so it gives the lowest δ (1.2 ppm), not the CH₂.", "2": "This order is reversed. The O–H proton is at the highest δ here, and CH₃ at the lowest.", "3": "TMS gives its peak at 0.0 ppm, not 1.2 ppm, and it is the reference, not part of ethanol."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1126' AND answer = 1;
UPDATE questions SET why = 'By the n + 1 rule, a signal is split into (n + 1) peaks, where n is the number of protons on the neighbouring carbon(s). A quartet has 4 peaks, so n + 1 = 4 and n = 3. The neighbour is usually a CH₃ group.', wrong = '{"0": "Two neighbouring protons give 2 + 1 = 3 peaks, a triplet, not a quartet.", "1": "4 is the number of peaks (n + 1). The number of neighbouring protons is one less, 3.", "3": "One neighbouring proton gives 1 + 1 = 2 peaks, a doublet."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1127' AND answer = 2;
UPDATE questions SET why = 'Using the n + 1 rule: the CH₃ protons have 2 neighbours on the CH₂, giving 3 peaks, a triplet. The CH₂ protons have 3 neighbours on the CH₃, giving a quartet. The OH proton exchanges rapidly and is normally not split, so it is a singlet.', wrong = '{"0": "A doublet needs one neighbouring proton. The CH₃ is next to a CH₂ with two protons, so it is a triplet.", "1": "The CH₃ is next to a CH₂ (two H), so it is a triplet, not a quartet, and the OH is a singlet, not a doublet.", "2": "The CH₃ and CH₂ protons split each other, so only the OH appears as a singlet."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1128' AND answer = 3;
UPDATE questions SET why = 'In ethane, CH₃–CH₃, all six protons are in identical environments. Equivalent protons do not split each other''s signals, even though each CH₃ is next to another CH₃. So ethane gives one unsplit peak, a singlet.', wrong = '{"1": "Each carbon in ethane does have an adjacent carbon. The singlet arises because the protons are all equivalent.", "2": "Ethane contains ordinary hydrogen, not deuterium. Its protons do give a signal, just not a split one.", "3": "TMS is a reference at 0.0 ppm. It does not hide or remove splitting in other signals."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1129' AND answer = 0;
UPDATE questions SET why = 'Chloroethane has two proton environments. The CH₃ (3 H) has 2 neighbours on CH₂, so it gives a triplet at low δ, 0.5 to 1.5 ppm. The CH₂ (2 H) is next to Cl and has 3 neighbours on CH₃, so it gives a quartet at higher δ, 3.0 to 4.5 ppm. Areas are 3 : 2.', wrong = '{"0": "The CH₃ and CH₂ protons are on neighbouring carbons, so they split each other. They are not singlets.", "2": "The patterns are swapped. CH₃ next to CH₂ gives a triplet, and CH₂ next to CH₃ gives a quartet.", "3": "CH₃ and CH₂ are different environments, so there must be two signals, not one."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1130' AND answer = 1;
UPDATE questions SET why = 'Ethyl ethanoate is CH₃COOCH₂CH₃. The CH₃ on the C=O has no H neighbours, so it is a singlet at 2.2 ppm. The CH₂ is bonded to O (high δ, 3.9 ppm) and split by the CH₃ into a quartet. The end CH₃ is split by CH₂ into a triplet at 1.3 ppm.', wrong = '{"0": "Propyl methanoate, HCOOCH₂CH₂CH₃, has an HCOO proton near 8 ppm and four environments. It has no 3H singlet.", "1": "In methyl propanoate the quartet CH₂ is next to C=O (about 2.0 to 2.6 ppm) and the 3H singlet is OCH₃ (about 3.7 ppm), the reverse.", "2": "Methyl ethanoate, CH₃COOCH₃, has two CH₃ groups with no neighbours, so it shows only two singlets."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1131' AND answer = 3;
UPDATE questions SET why = 'The O–H proton of ethanol is easily swapped for deuterium: CH₃CH₂OH + D₂O ⇌ CH₃CH₂OD + HOD. Deuterium does not give a signal in a ¹H NMR spectrum, so after shaking with D₂O the O–H peak disappears. This is a simple test to identify the O–H peak.', wrong = '{"0": "The CH₃ protons are bonded to carbon and do not exchange with D₂O, so their peak stays.", "1": "The CH₂ protons are also C–H protons, which do not exchange with D₂O. Their peak is unchanged.", "3": "TMS has only C–H protons bonded to carbon and silicon. It does not exchange, and its peak stays at 0.0 ppm."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1132' AND answer = 2;
UPDATE questions SET why = 'Hydrogen atoms bonded to highly electronegative O or N are slightly acidic and constantly swap between molecules. When D₂O is added, these H atoms are quickly replaced by D. Hydrogens bonded to carbon are not exchangeable, so they stay.', wrong = '{"0": "O–H and N–H protons are near electronegative atoms, so they are deshielded, not the most shielded.", "2": "O–H and N–H protons are bonded to oxygen and nitrogen. Protons bonded to carbon do not exchange with D₂O.", "3": "The exchange happens because these H atoms are labile (easily released). It is not about having no neighbouring protons."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1133' AND answer = 1;
UPDATE questions SET why = '¹³C chemical shifts spread over a much wider range than ¹H shifts. Carbon signals appear from about 0 to 220 ppm, with alkyl carbons near the low end and C=O carbons near 190 to 220 ppm. ¹H signals cover only about 0 to 12 ppm.', wrong = '{"0": "200 to 800 nm is the wavelength range used in UV-Vis spectroscopy. NMR shifts are given in ppm.", "1": "0 to 12 ppm is roughly the range of ¹H NMR. ¹³C shifts extend much further, up to about 220 ppm.", "3": "4000 to 500 cm⁻¹ is the wavenumber range of an IR spectrum, not an NMR range."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1134' AND answer = 2;
UPDATE questions SET why = 'In ¹³C NMR each different carbon environment gives one peak. In 2-methylpropane, (CH₃)₃CH, the three CH₃ carbons are all bonded to the same central carbon, so they are equivalent. The central CH carbon is different. Two environments give two peaks.', wrong = '{"1": "4 counts every carbon atom separately. Equivalent carbons give only one peak, so the three CH₃ groups share one.", "2": "One peak would need all carbons to be equivalent. The central CH carbon differs from the methyl carbons.", "3": "Three peaks would need three environments. The molecule has only two: the CH₃ carbons and the central CH."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1135' AND answer = 0;
UPDATE questions SET why = 'Ethanol, CH₃CH₂OH, has two carbon environments. The CH₂ carbon is bonded directly to electronegative oxygen, so it is deshielded and appears in the 50 to 70 ppm range, near 57 ppm. The CH₃ carbon, further from oxygen, appears at about 18 ppm.', wrong = '{"0": "Ethanol has no C=O group. A carbonyl carbon would appear much further downfield, around 190 to 220 ppm.", "1": "The CH₃ carbon is not bonded to oxygen, so it is more shielded and appears at about 18 ppm.", "2": "TMS is the reference and appears at 0 ppm, not 57 ppm."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1136' AND answer = 3;
UPDATE questions SET why = 'Carbon atoms in C=O groups are strongly deshielded by the oxygen and the double bond. Aldehyde and ketone carbonyl carbons (R–CHO, R–CO–R) appear at about 190 to 220 ppm, so a peak at 205 ppm indicates such a carbon.', wrong = '{"1": "Alkyl (sp³) carbons are well shielded and appear at about 0 to 50 ppm.", "2": "A carbon bonded to a halogen appears at about 30 to 60 ppm, much lower than 205.", "3": "Nitrile carbons (R–C≡N) appear at about 100 to 125 ppm."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1137' AND answer = 0;
UPDATE questions SET why = '¹³C atoms are rare (about 1.1%), so two ¹³C atoms are almost never next to each other and carbon peaks are not split by neighbouring carbons. Each environment shows as a single line. Peak areas also do not reliably match the number of carbons, unlike in ¹H NMR.', wrong = '{"0": "In ¹³C NMR, peak areas are not proportional to the number of carbons. Only in ¹H NMR do areas count the protons.", "2": "¹³C peaks appear as single lines, not split into quartets or other patterns.", "3": "0 to 12 ppm is the ¹H range. ¹³C shifts cover about 0 to 220 ppm."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1138' AND answer = 1;
UPDATE questions SET why = 'Count carbon environments. Butan-1-ol, CH₃CH₂CH₂CH₂OH, and butan-2-ol, CH₃CH(OH)CH₂CH₃, each have four different carbons, giving four peaks. 2-Methoxypropane, CH₃–O–CH(CH₃)₂, has the OCH₃ carbon, the CH carbon and two equivalent CH₃ carbons: three environments, three peaks.', wrong = '{"0": "In butan-2-ol all four carbons are different (the two end CH₃ groups are not equivalent), so it gives four peaks.", "1": "Butan-1-ol is a straight chain with all four carbons in different environments, so it gives four peaks.", "3": "Each butanol gives four ¹³C peaks, so neither fits a spectrum with three peaks."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1139' AND answer = 2;
UPDATE questions SET why = '2,2-Dimethylpropane, C(CH₃)₄, has a central carbon bonded to four identical CH₃ groups. The four CH₃ carbons are equivalent and give one peak, and the central quaternary carbon gives another. So there are two peaks.', wrong = '{"1": "5 counts every carbon separately. The four equivalent CH₃ carbons give only one peak.", "2": "One peak would need all carbons to be equivalent, but the central carbon differs from the CH₃ carbons.", "3": "There are only two carbon environments, so three peaks is not possible."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1140' AND answer = 0;
UPDATE questions SET why = 'Gold and platinum are very unreactive metals. They rarely combine with oxygen, sulfur or other elements, so they are found in nature as the free metal, called the native state. More reactive metals such as Na, Al and Fe exist only in compounds within ores.', wrong = '{"1": "Reactive metals form compounds easily, so they are found combined in ores, not free.", "2": "Gold and platinum occur as the free metal. Metals such as zinc are found as sulfide ores.", "3": "Both gold and platinum are solids at room temperature. Mercury is the only liquid metal."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1141' AND answer = 0;
UPDATE questions SET why = 'An ore is not a pure compound. It is a mixture of the useful metal compound with impurities and earthy materials such as sand and rock. These unwanted earthy impurities are called gangue, and they are removed during the extraction of the metal.', wrong = '{"0": "A flux is a substance added during smelting to combine with and remove the gangue. It is not the impurity itself.", "2": "Slag is the product formed when the flux reacts with the gangue in a furnace.", "3": "An alloy is a mixture of a metal with other metals or non-metals, made on purpose to improve its properties."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1142' AND answer = 1;
UPDATE questions SET why = 'Both methods turn an ore into a metal oxide. Roasting heats a sulfide ore in excess air, for example 2ZnS + 3O₂ → 2ZnO + 2SO₂. Calcination heats a carbonate ore with limited or no air, for example ZnCO₃ → ZnO + CO₂.', wrong = '{"0": "Adding carbon to remove oxygen from the oxide is the reduction step that comes after roasting or calcination.", "1": "Heating a carbonate ore with little or no air is calcination, not roasting.", "2": "Using electricity to reduce a molten compound is the electrolytic method, used for very reactive metals."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1143' AND answer = 3;
UPDATE questions SET why = 'In the furnace, carbon first burns to carbon monoxide, C + ½O₂ → CO. The CO is the reducing agent: it takes oxygen from haematite, Fe₂O₃ + 3CO → 2Fe + 3CO₂. So it is CO that removes oxygen from Fe₂O₃.', wrong = '{"0": "Carbon dioxide is a product of the reduction. It is already fully oxidised and cannot take oxygen from Fe₂O₃.", "1": "Oxygen is what is being removed from the iron oxide, so it cannot be the reducing agent.", "3": "Zinc is not used in the extraction of iron. Carbon monoxide, from coke, is the reducing agent."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1144' AND answer = 2;
UPDATE questions SET why = 'Very reactive metals such as Na, K and Al cannot be reduced by carbon, so their molten compounds are electrolysed. The positive metal ions move to the negative electrode, the cathode, where they gain electrons and become metal atoms, for example Na⁺ + e⁻ → Na.', wrong = '{"0": "Gangue is the earthy impurity removed from the ore before reduction. The metal does not form in it.", "2": "Positive ions are attracted to the negative cathode, not the anode, and they gain electrons rather than lose them.", "3": "Metals are deposited as the element at the cathode. A gas such as chlorine or oxygen forms at the anode."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1145' AND answer = 1;
UPDATE questions SET why = 'Copper is used for wiring because it conducts electricity very well. Even tiny amounts of impurity lower its conductivity, so copper for electrical wiring is refined, usually by electrolysis, to about 99.99% purity.', wrong = '{"0": "50% copper would be half impurity and would conduct poorly. Wiring copper must be almost pure.", "1": "90% purity still leaves 10% impurity, which would greatly reduce conductivity. About 99.99% is needed.", "3": "75% copper is far too impure. A quarter impurity would make it a poor conductor."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1146' AND answer = 2;
UPDATE questions SET why = 'Brass is an alloy of copper (about 60 to 90%) and zinc (about 10 to 40%). It is strong and resists corrosion, so it is used in electrical fittings, taps and decorative items.', wrong = '{"0": "Aluminium and magnesium, with copper and manganese, make duralumin, an alloy used for aircraft bodies.", "1": "Copper and tin make bronze, a hard alloy used for medals and statues.", "2": "Iron and carbon make steel, used in buildings and tools."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1147' AND answer = 3;
UPDATE questions SET why = 'Duralumin is mostly aluminium (about 93 to 95%) with small amounts of copper, magnesium and manganese. The aluminium keeps it light, the added metals make it much stronger, and it resists corrosion. These properties suit aircraft bodies.', wrong = '{"1": "Duralumin is based on aluminium, a light metal, and it is tough rather than brittle.", "2": "Duralumin is a metal alloy, so it conducts electricity. It is not an insulator.", "3": "Duralumin is a solid at room temperature, which is why it can form an aircraft body."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1148' AND answer = 0;
UPDATE questions SET why = 'Alloying means mixing a metal with other metals, or with a non-metal such as carbon, to form a uniform mixture. This changes the microstructure of the metal and improves properties such as strength, hardness, corrosion resistance, and electrical or magnetic behaviour.', wrong = '{"0": "An alloy is still metallic. Ceramics are a different class of materials, mainly silicates and oxides.", "2": "Alloying adds other elements to a metal, so it makes the metal less pure, not more.", "3": "Alloys like brass and steel are still far denser than water. Lowering density below water is not the aim."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1149' AND answer = 1;
UPDATE questions SET why = 'Ceramics are mainly made of silicates and oxides of alkali metals, alkaline earth metals and aluminium, such as Na₂O, K₂O, CaO and Al₂O₃. Strong bonds in fixed structures make them hard, heat-resistant and good insulators, but brittle.', wrong = '{"0": "Ionic halides such as NaCl are salts, not ceramics. Ceramics are built from silicates and metal oxides.", "1": "Pure metals are malleable and conduct electricity well, the opposite of brittle, insulating ceramics.", "2": "Long-chain hydrocarbons are found in polymers and fuels, not in ceramics."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1150' AND answer = 3;
UPDATE questions SET why = 'Ceramics are extremely hard and very hard to scratch or wear away. Silicon carbide is a ceramic with this hardness, so it is used as the abrasive on sandpaper and in cutting tools to grind down softer materials.', wrong = '{"0": "Most ceramics are electrical insulators, which is why porcelain is used on power lines. Conductivity is not needed for sandpaper.", "1": "Ceramics are hard and brittle, not flexible. Hardness, not flexibility, makes them good abrasives.", "3": "Ceramics are chemically inert and do not dissolve in water."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1151' AND answer = 2;
UPDATE questions SET why = 'A composite has two parts. The matrix, such as a polymer, surrounds and holds everything together. The reinforcement agent, such as glass or carbon fibres, is held inside the matrix and gives the material its high strength. Fibreglass is an example.', wrong = '{"0": "Composites are valued for being strong yet light, a good strength-to-weight ratio. Adding weight is not the reinforcement''s role.", "2": "Holding the parts together is the job of the matrix. The reinforcement provides strength.", "3": "Conducting electricity is not the purpose of the reinforcement; glass fibres, for example, are insulators."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1152' AND answer = 1;
UPDATE questions SET why = 'Semiconductors conduct only under certain conditions, so the current through them can be controlled. Silicon is the most common semiconductor because it works well and is very abundant in sand. It is used in microchips, SIM cards and solar panels.', wrong = '{"0": "Aluminium is a metal and a good conductor at all times, so it is not a semiconductor.", "1": "Copper is a metallic conductor used in wires and connectors, not a semiconductor.", "2": "Gallium nitride is a semiconductor, but it is used for fast charging in electric cars. Silicon is the most common one."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1153' AND answer = 3;
UPDATE questions SET why = 'Gallium arsenide (GaAs) is a major semiconductor besides silicon. It is used in wireless communication, for example in 5G internet devices. A related compound, gallium nitride (GaN), is used for fast charging in electric cars.', wrong = '{"0": "Aircraft bodies are made of duralumin, a light, strong aluminium alloy, not GaAs.", "1": "Sandpaper uses silicon carbide, a very hard ceramic, as its abrasive.", "3": "Fertilizers supply nutrients such as nitrogen and phosphorus. GaAs is an electronic material, not a fertilizer."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1154' AND answer = 2;
UPDATE questions SET why = 'Lead, mercury and cadmium are toxic heavy metals used in electronics, batteries and fluorescent lights. When these items are dumped, the metals can leach out into groundwater and then enter plants, animals and humans, causing serious harm.', wrong = '{"0": "Gold, silver and platinum are precious, unreactive metals. They are not the toxic metals that leach from such waste.", "2": "Sodium, potassium and calcium are light, reactive metals needed by the body. They are not toxic heavy metals.", "3": "Aluminium and magnesium are light metals and silicon is a metalloid. They are not the toxic heavy metals named."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1155' AND answer = 1;
UPDATE questions SET why = 'Many plastics contain added chemicals such as phthalates (which make plastic soft) and bisphenol A (BPA). These additives can leach out and interfere with the body''s hormones, which can affect growth and health.', wrong = '{"0": "These additives do not make plastics dissolve in water. Their danger is their effect on hormones.", "1": "Phthalates and BPA are not radioactive. They are ordinary organic compounds.", "2": "Phthalates and BPA are organic compounds made of carbon, hydrogen and oxygen, not heavy metals."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1156' AND answer = 3;
UPDATE questions SET why = 'Extracting aluminium from its ore (bauxite) needs huge amounts of electrical energy for electrolysis. Recycling only needs scrap aluminium to be melted and cleaned, so it uses about 95% less energy than extracting the metal from raw ore.', wrong = '{"0": "5% less is far too small a saving. Recycling aluminium avoids the energy-hungry electrolysis step and saves about 95%.", "1": "50% less underestimates the saving. Melting scrap needs only about one-twentieth of the energy, a 95% saving.", "3": "Recycling saves a great deal of energy, because melting scrap needs far less energy than electrolysing the ore."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1157' AND answer = 2;
UPDATE questions SET why = 'Chemical recycling, also called depolymerisation, uses heat, solvents or catalysts to break polymer chains back into their original monomers or other simple chemicals. These can be purified and used again, giving purer starting materials than simple remelting.', wrong = '{"0": "Removing ink with chemicals such as NaOH is the deinking step in paper recycling.", "2": "Sorting, cleaning, melting and reshaping plastic is mechanical recycling. It keeps the chains intact rather than breaking them down.", "3": "Crushing and melting cullet is how glass is recycled, not plastics."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1158' AND answer = 1;
UPDATE questions SET why = 'In glass recycling, scrap glass is cleaned and crushed into small pieces called cullet. The cullet is melted to make new glass. This is chemically simple because glass is a non-crystalline solid that can be remelted again and again.', wrong = '{"0": "Slag is the waste formed when a flux reacts with gangue in a metal furnace.", "1": "Pulp is the mixture of wood or paper fibres in water used in paper making and recycling.", "2": "Gangue is the earthy impurity found with a metal compound in an ore."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1159' AND answer = 3;
UPDATE questions SET why = 'X-rays have very short wavelengths, similar to the spacing between atoms in a crystal. When an X-ray beam hits the regular layers of atoms, it is diffracted into a pattern of spots. Analysing this pattern reveals atomic positions, bond lengths, bond angles and electron density.', wrong = '{"0": "X-rays are scattered by the electrons of all atoms, not only hydrogen. Hydrogen, with one electron, scatters X-rays weakly.", "1": "X-rays are not radio waves. They have extremely short wavelengths, while radio waves have very long ones.", "3": "The method depends on the diffraction pattern of X-rays, not on the crystal giving off visible light."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1160' AND answer = 2;
UPDATE questions SET why = 'X-ray diffraction patterns of DNA fibres provided the key evidence that DNA is a double helix. The method is still widely used to find the 3D structures of proteins and enzymes and to see how drug molecules bind to their targets.', wrong = '{"0": "Amino acids are separated by chromatography or electrophoresis, not by X-ray diffraction.", "2": "Blood alcohol is measured by gas chromatography or by IR breathalysers.", "3": "Ammonia is made by the Haber process from nitrogen and hydrogen. X-ray diffraction finds structures, it does not make chemicals."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1161' AND answer = 1;
UPDATE questions SET why = 'Natural gas is mainly methane, CH₄. As a chemical feedstock (raw material), methane is used mostly to make ammonia, which goes into fertilizers, and methanol, which is used as a solvent and fuel.', wrong = '{"0": "TNT (trinitrotoluene) is made by nitrating toluene, an aromatic compound, not from methane.", "1": "Benzene and toluene are aromatic compounds obtained from coal and from reforming oil fractions.", "2": "Polystyrene is made from styrene (phenylethene), which comes from benzene, not from methane."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1162' AND answer = 3;
UPDATE questions SET why = 'Crude oil vapour enters a column that is hot at the bottom and cooler towards the top. Hydrocarbons with high boiling points (large molecules) condense as soon as they reach a level cooler than their boiling point, which is near the bottom. Low-boiling fractions rise higher before condensing.', wrong = '{"0": "Only the light, low-boiling fractions such as refinery gases and petrol reach the top of the column.", "1": "Fractional distillation is a physical separation by boiling point. Cracking is a separate chemical process.", "3": "High-boiling hydrocarbons condense into liquids low in the column. Only the lightest fractions stay as gases."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1163' AND answer = 2;
UPDATE questions SET why = 'TNT is trinitrotoluene. It is made by nitrating toluene (methylbenzene), which adds three –NO₂ groups to the ring. So toluene is the petrochemical starting material for this explosive.', wrong = '{"0": "Butadiene is used to make synthetic rubber, such as styrene-butadiene rubber for tyres.", "2": "Ethene is the monomer of poly(ethene), used for bags, bottles and packaging.", "3": "Xylene is used to make polyester fibres for textiles, not TNT."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1164' AND answer = 1;
UPDATE questions SET why = 'Thermal cracking uses no catalyst, so it needs very high temperatures (450 to 750 °C) and high pressure. Catalytic cracking uses a catalyst such as a zeolite (an aluminosilicate), which lowers the activation energy. It runs at about 500 °C, saving energy and giving better control over the products.', wrong = '{"0": "Turning straight-chain alkanes into aromatic rings is reforming, not catalytic cracking.", "1": "Using no catalyst at 450 to 750 °C describes thermal cracking, the method catalytic cracking is being compared with.", "2": "Cracking breaks large molecules into smaller ones. Joining small molecules into large ones is polymerisation."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1165' AND answer = 3;
UPDATE questions SET why = 'In cracking, a long alkane breaks into a shorter alkane and an alkene, and atoms must balance. C₁₀H₂₂ → C₈H₁₈ + C₂H₄. Carbon: 10 = 8 + 2. Hydrogen: 22 = 18 + 4. The second product is ethene.', wrong = '{"0": "C₈H₁₈ + C₂H₆ contains 24 H atoms, but decane has only 22. The equation would not balance.", "1": "C₈H₁₈ + CH₄ has only 9 carbon atoms, one short of decane''s 10.", "3": "C₈H₁₈ + H₂ has only 8 carbon atoms, leaving two carbons of decane unaccounted for."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1166' AND answer = 2;
UPDATE questions SET why = 'Straight-chain alkanes burn unevenly in engines, causing knocking. Reforming rearranges them into branched or cyclic (aromatic) hydrocarbons with higher octane numbers, which burn more smoothly. It also supplies benzene, toluene and xylene for industry.', wrong = '{"0": "Removing sulfur from fuel is a separate purification step, not the purpose of reforming.", "2": "Breaking large molecules into smaller alkenes is cracking. Reforming rearranges molecules without making them smaller.", "3": "Making polymers is polymerisation, a separate process that uses monomers such as ethene."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1167' AND answer = 1;
UPDATE questions SET why = 'Hexane is C₆H₁₄ and benzene is C₆H₆. Balancing hydrogen: 14 H = 6 H in benzene + 8 H left over, and 8 H make 4 H₂. So C₆H₁₄ → C₆H₆ + 4H₂, and four molecules of hydrogen are released per hexane.', wrong = '{"0": "1 H₂ is released when hexane forms cyclohexane, C₆H₁₄ → C₆H₁₂ + H₂, not benzene.", "1": "3 H₂ is released when cyclohexane forms benzene, C₆H₁₂ → C₆H₆ + 3H₂. Starting from hexane needs one more.", "3": "7 H₂ would use all 14 H atoms of hexane, leaving none for benzene''s 6 H atoms."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1168' AND answer = 2;
UPDATE questions SET why = 'Energy density is the energy stored per unit volume, so it is measured in megajoules per litre (MJ/L). Specific energy is the energy stored per unit mass, measured in megajoules per kilogram (MJ/kg). So the order is MJ/L, then MJ/kg.', wrong = '{"1": "The units are swapped. Energy density is per litre (volume) and specific energy is per kilogram (mass).", "2": "kJ/mol is used for enthalpy changes and J/K for entropy or heat capacity, not for fuel energy.", "3": "The watt (W) is a unit of power and the joule (J) of energy. Neither is per volume or per mass."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1169' AND answer = 0;
UPDATE questions SET why = 'Hydrogen has a very high specific energy, about 120 MJ/kg, so a small mass of it releases a lot of energy. Weight matters most in aircraft and spacecraft, so this makes hydrogen attractive there, even though it is a light gas with low energy per litre.', wrong = '{"1": "Hydrogen''s energy density per litre is low, because the gas is so light and spread out.", "2": "Hydrogen burns to release a great deal of energy, giving one of the highest energies per kilogram of any fuel.", "3": "Hydrogen is the lightest element and far less dense than diesel."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1170' AND answer = 0;
UPDATE questions SET why = 'Energy density is the energy stored per unit volume. CNG has a lower energy density than petrol, so each litre of tank space holds less energy. To travel the same distance, a CNG car must carry a larger volume of fuel, so it needs a bigger tank.', wrong = '{"1": "Specific energy is per kilogram. A higher specific energy would not explain needing more storage volume.", "2": "CNG is mainly methane, CH₄, which does contain carbon.", "3": "Boiling point does not set the tank size. The reason is the lower energy stored per litre."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1171' AND answer = 0;
UPDATE questions SET why = 'Each fission of U-235 is started by one neutron but releases three new neutrons. These neutrons can strike more U-235 nuclei and split them too, releasing even more neutrons. This self-sustaining series of fissions is a chain reaction.', wrong = '{"1": "The neutrons do not go only into barium. They fly out and can trigger fission in other U-235 nuclei.", "2": "The neutrons do not turn into protons at once. They remain free and can cause further fission.", "3": "Releasing extra neutrons keeps the reaction going rather than stopping it. Control rods are used to absorb some."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1172' AND answer = 0;
UPDATE questions SET why = 'Nuclear fusion is the joining of light nuclei, such as hydrogen isotopes, to form a heavier nucleus. It is the opposite of fission, where a heavy nucleus splits. Both release far more energy than chemical reactions; fusion powers the Sun.', wrong = '{"1": "Splitting heavy nuclei such as U-235 into lighter ones is nuclear fission, not fusion.", "2": "Breaking bonds between atoms in molecules is a chemical change. Nuclear reactions change the nuclei themselves.", "3": "Removing electrons from atoms is ionisation. Fusion involves nuclei, not electrons."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1173' AND answer = 0;
UPDATE questions SET why = 'Solar panels, made of silicon, turn sunlight into direct current (DC). Homes, offices and industry run on alternating current (AC), so an inverter converts the DC from the panels into AC. Batteries in the system store energy for the night.', wrong = '{"1": "Storing electricity for the night or cloudy days is the job of the batteries, not the inverter.", "2": "The inverter works the other way. It converts DC from the panels into AC; AC to DC is done by a rectifier.", "3": "The inverter does not handle light at all. It works on the electrical output of the panels."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1174' AND answer = 0;
UPDATE questions SET why = 'Below the minimum effective concentration (MEC) a drug does not work, and above the minimum toxic concentration (MTC) it causes harm. The therapeutic window is the range in between, where the drug is effective but still safe.', wrong = '{"1": "Below the minimum effective concentration the drug level is too low to have a useful effect.", "2": "Above the minimum toxic concentration the drug causes harmful side effects, which is outside the window.", "3": "A dose that kills half of those taking it relates to lethal dose (LD₅₀), not to the therapeutic window."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1175' AND answer = 0;
UPDATE questions SET why = 'A narrow therapeutic window means the effective concentration and the toxic concentration are close together. A small change in dose can push the level from safe to harmful, so such drugs need careful dosing and often regular blood tests to check their levels.', wrong = '{"0": "Every drug becomes toxic at a high enough dose. With a narrow window, the toxic level is close to the effective one.", "1": "Being safe even at double the dose describes a drug with a wide window and high therapeutic index, like penicillin.", "3": "Such drugs, like warfarin and digoxin, are widely used. They just need careful dosing and monitoring."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1176' AND answer = 2;
UPDATE questions SET why = 'The therapeutic index compares the toxic dose with the effective dose: TI = TD₅₀ ÷ ED₅₀. For drug X, TI = 80 mg ÷ 20 mg = 4. The toxic dose is four times the effective dose; the higher the TI, the safer the drug.', wrong = '{"0": "0.25 is ED₅₀ ÷ TD₅₀ = 20 ÷ 80, the ratio upside down.", "2": "60 is TD₅₀ − ED₅₀ = 80 − 20. The therapeutic index is a ratio, not a difference.", "3": "100 is TD₅₀ + ED₅₀ = 80 + 20. Adding the doses has no meaning here."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1177' AND answer = 1;
UPDATE questions SET why = 'Warfarin, a blood thinner, and digoxin, a heart medicine, have a low therapeutic index: the toxic dose is close to the effective dose. Patients taking them need regular blood tests, called therapeutic drug monitoring, to keep the dose safe.', wrong = '{"0": "Codeine and caffeine are not the examples used for a low therapeutic index needing blood monitoring.", "1": "Penicillin and paracetamol are given as examples of a high TI. An accidental double dose is not life-threatening.", "2": "Aspirin and vitamin C are not the examples given for drugs needing blood-level monitoring."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1178' AND answer = 3;
UPDATE questions SET why = 'The stomach is strongly acidic, with a pH of about 1.5 to 3.5. This acid can react with some drugs and break them down before they are absorbed. A protective coating that dissolves only in the less acidic small intestine lets the drug pass safely through the stomach.', wrong = '{"1": "The stomach is strongly acidic, not alkaline. Its low pH is what damages some drugs.", "2": "The small intestine is less acidic than the stomach. That is why the coating is designed to dissolve there.", "3": "The coating protects the drug from stomach acid. It does not make the drug toxic."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1179' AND answer = 0;
UPDATE questions SET why = 'The stomach lining is covered by a thick layer of mucus that contains bicarbonate ions (HCO₃⁻). The bicarbonate neutralises acid at the surface of the stomach cells, so the strong acid pumped in by the parietal cells does not damage the lining.', wrong = '{"0": "Chlorophyll is the green pigment in plants. It is not found in the human stomach.", "1": "A layer of fat is not what protects the stomach. Mucus and bicarbonate do this job.", "3": "Cellulose is found in plant cell walls. Humans cannot even digest it, and it does not line the stomach."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1180' AND answer = 2;
UPDATE questions SET why = 'Penicillin has two core rings fused together: a four-membered β-lactam ring and a five-membered thiazolidine ring, which contains sulfur and nitrogen. The strained β-lactam ring is the part that reacts with and blocks the bacterial enzyme.', wrong = '{"0": "Penicillin has no seven-membered ring. Its fused rings are four- and five-membered.", "1": "A benzene ring may appear in some side chains, but the ring fused to the β-lactam is the five-membered thiazolidine.", "2": "A three-membered epoxide ring is not part of penicillin''s structure."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1181' AND answer = 3;
UPDATE questions SET why = 'The four-membered β-lactam ring is essential for penicillin''s antibacterial action. Some bacteria make enzymes called β-lactamases that attack this ring and break it open. Once the ring is opened, penicillin can no longer block the cell-wall enzyme, so the bacteria become resistant.', wrong = '{"0": "β-lactamases do not repair the cell wall. They destroy penicillin by opening its β-lactam ring.", "2": "β-lactamases act on penicillin, not on DNA. DNA thickness has nothing to do with this resistance.", "3": "Neutralising stomach acid is the job of antacids or bicarbonate, not bacterial enzymes."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1182' AND answer = 1;
UPDATE questions SET why = 'Penicillin works by blocking transpeptidase, the enzyme bacteria use to build their cell walls. Without a proper wall, the bacteria burst and die. Human cells have no cell wall at all, so penicillin has nothing to attack in them.', wrong = '{"0": "Penicillin does enter the blood and is carried around the body to reach infections. That is not why it is safe.", "1": "Human cells do not contain β-lactam rings. The safety comes from human cells lacking a cell wall.", "3": "Penicillin is produced by the Penicillium mould, not by human cells."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1183' AND answer = 2;
UPDATE questions SET why = 'In 1928 Alexander Fleming noticed that a mould growing on a contaminated dish had killed the bacteria around it. The mould, later identified as Penicillium, released a substance that stopped bacterial growth. This chance discovery led to penicillin, the first antibiotic.', wrong = '{"0": "Fritz Haber is known for developing the synthesis of ammonia from nitrogen and hydrogen (the Haber process).", "1": "Emil Fischer proposed the lock-and-key model of enzyme action in 1894.", "2": "R. B. Woodward is known for the total synthesis of complex molecules such as vitamin B₁₂, not for discovering penicillin."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1184' AND answer = 3;
UPDATE questions SET why = 'Mu (μ) opioid receptors, found in the brain and spinal cord, are the primary target of most opioids, including morphine. Activating them gives strong pain relief, but it also causes respiratory depression (slowed breathing) and intense euphoria.', wrong = '{"0": "Kappa (κ) receptors are involved in spinal pain relief and sedation, and are less linked with euphoria.", "2": "Delta (δ) receptors mainly play a role in emotional response and mood regulation.", "3": "The COX enzyme is the target of aspirin, which reduces pain and inflammation in a different way."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1185' AND answer = 1;
UPDATE questions SET why = 'When an opiate binds its receptor, calcium channels close and potassium channels open. K⁺ leaving the cell makes the inside more negative (hyperpolarised), so it becomes much harder for the neuron to fire and pass on a pain signal.', wrong = '{"0": "Opiates do not destroy neurons. They only make it harder for the neuron to send signals.", "1": "Opening sodium channels would excite the neuron and make it more likely to fire, the opposite of pain relief.", "3": "Opiates actually increase dopamine release in the brain''s reward centre, which gives a feeling of well-being."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1186' AND answer = 2;
UPDATE questions SET why = 'The brain makes its own painkillers called endorphins. They bind to opioid receptors in the central nervous system and reduce pain. Opiate drugs such as morphine work by binding to the same receptors, hijacking this natural system.', wrong = '{"0": "β-lactamases are bacterial enzymes that destroy penicillin. They are not painkillers.", "1": "Interferons are proteins that boost the immune response against viruses, not natural painkillers.", "2": "COX is an enzyme that helps produce pain and inflammation signals; aspirin works by blocking it."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1187' AND answer = 3;
UPDATE questions SET why = 'Viruses are not independent cells. They get inside our cells and use our own DNA/RNA machinery to make copies of themselves, so a drug that stops the virus may also harm our cells. Viruses also mutate quickly, so a drug or vaccine can stop working when the virus changes.', wrong = '{"0": "Viruses have no cell walls. Cell walls are found in bacteria and are the target of penicillin.", "2": "Antibiotics act on bacteria and do not kill viruses. That is exactly why antiviral drugs are needed.", "3": "Viruses are much smaller than bacteria, and size is not the main reason antivirals are hard to design."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1188' AND answer = 1;
UPDATE questions SET why = 'Many antivirals work by enzyme inhibition. A virus makes its proteins as one long strand that a viral enzyme, protease, must cut into working pieces. Protease inhibitors block this enzyme, so the virus cannot form working proteins. They are used against HIV and hepatitis C.', wrong = '{"0": "Boosting the immune system is how interferons work. Protease inhibitors block a viral enzyme instead.", "1": "Breaking bacterial cell walls is how penicillin works, and viruses have no cell walls.", "3": "Neutralising stomach acid is done by antacids. It has nothing to do with treating viral infections."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1189' AND answer = 2;
UPDATE questions SET why = 'Plants need nitrogen, phosphorus and potassium in such large amounts that they are called the primary macronutrients. Fertilizer bags are labelled with an N–P–K ratio, which shows how much of each of these three elements the fertilizer contains.', wrong = '{"0": "Iron, zinc and copper are micronutrients, needed by plants only in small amounts.", "1": "Carbon, hydrogen and oxygen are macronutrients, but plants get them from air and water, not from fertilizer.", "2": "Calcium, magnesium and sulfur are needed in moderate amounts. They are not the primary three on the label."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1190' AND answer = 3;
UPDATE questions SET why = 'Phosphorus is a structural part of ATP (adenosine triphosphate), the molecule that stores and releases energy in cells. It is usually given to crops as superphosphates or ammonium phosphates, and it is one of the three primary macronutrients.', wrong = '{"0": "Acting as an osmoregulator, controlling water balance, is the role of potassium.", "2": "The metal at the centre of chlorophyll is magnesium. Phosphorus is not part of chlorophyll.", "3": "Phosphorus is a primary macronutrient needed in large amounts, not a micronutrient."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1191' AND answer = 1;
UPDATE questions SET why = 'Nitrogen and phosphorus become part of plant molecules such as proteins and ATP. Potassium does not become part of the plant''s structure. Instead it works as an osmoregulator, controlling water balance, and it activates more than sixty enzymes in plant metabolism.', wrong = '{"0": "Being part of ATP is the role of phosphorus, not potassium.", "1": "Every amino acid contains nitrogen. Potassium is not part of amino acids.", "3": "Potassium is a primary macronutrient, the K in N–P–K, so it is needed in large amounts."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1192' AND answer = 2;
UPDATE questions SET why = 'When too much fertilizer is used, the excess nitrates and phosphates are washed by rain into rivers and lakes. These nutrients make algae grow rapidly. The overgrowth of algae harms fish and other aquatic life, for example by using up oxygen when the algae die and decay.', wrong = '{"0": "Acid rain forms from sulfur and nitrogen oxides in the air, not from fertilizer washing into lakes.", "1": "Fertilizer nutrients feed algae, so they grow more, not die.", "2": "Fertilizers do not make water radioactive. The harm comes from the extra nutrients."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1193' AND answer = 3;
UPDATE questions SET why = 'Many modern insecticides, such as organophosphates and neonicotinoids, are neurotoxins. They attack the insect''s nervous system, so nerve signals are disrupted, leading to paralysis and death of the insect.', wrong = '{"0": "Blocking photosynthesis is how some herbicides kill weeds. Insects do not photosynthesise.", "2": "Destroying fungal cell membranes, by blocking ergosterol synthesis, is how fungicides work.", "3": "These chemicals do not dissolve the exoskeleton. They kill by damaging the nervous system."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1194' AND answer = 1;
UPDATE questions SET why = 'Ergosterol is a key part of fungal cell membranes. Many fungicides block its synthesis, so the membrane cannot be built properly. Without a stable membrane, the fungal cell leaks and dies. Triazoles are a common example.', wrong = '{"0": "Inhibiting photosynthesis is how some herbicides kill weeds. Fungi do not photosynthesise.", "1": "Acting as neurotoxins is how insecticides such as organophosphates work. Fungi have no nervous system.", "3": "Adding nitrogen is what fertilizers do. It would help growth, not kill fungi."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1195' AND answer = 2;
UPDATE questions SET why = 'Neonicotinoids are insecticides that also harm non-target insects such as bees. They have been linked to colony collapse disorder, in which honeybee colonies suddenly lose their worker bees. Because bees pollinate many crops, this threatens food production worldwide.', wrong = '{"0": "Golden rice is a genetically modified crop with beta-carotene. It is not linked to neonicotinoids.", "1": "Acid rain is caused by sulfur oxides and nitrogen oxides in the air, not by insecticides.", "2": "Ozone depletion is caused mainly by CFCs, not by neonicotinoids."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1196' AND answer = 3;
UPDATE questions SET why = 'Even clean rain is slightly acidic, because carbon dioxide dissolves in it to form weak carbonic acid, giving a pH of about 5.6. Rain is called acid rain when its pH falls below 5.6, due to sulfuric and nitric acids from SOₓ and NOₓ pollution.', wrong = '{"0": "Normal rain is already below pH 7 because of dissolved CO₂, so pH 7 cannot be the acid-rain limit.", "2": "Acid rain can reach about pH 3, but any rain below 5.6 counts as acid rain.", "3": "pH 8.5 is alkaline. Acid rain must have a pH below 7, and in fact below 5.6."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1197' AND answer = 1;
UPDATE questions SET why = 'Soil particles hold nutrient ions such as K⁺, Ca²⁺ and Mg²⁺. H⁺ ions from acid rain take their place, for example K⁺–soil + H⁺ → H⁺–soil + K⁺, and the freed nutrients are washed away. The acid also releases toxic Al³⁺ ions, which damage plant roots.', wrong = '{"1": "Acid rain removes K⁺ and Ca²⁺ from the soil by leaching. It does not add them.", "2": "Adding H⁺ ions makes soil more acidic, which lowers its pH rather than raising it.", "3": "H⁺ ions do not combine with nitrogen to make ammonia in the soil. They swap places with nutrient ions."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1198' AND answer = 0;
UPDATE questions SET why = 'Acid rain draining through soil releases aluminium ions, Al³⁺, which run into lakes. The Al³⁺ clogs the gills of fish, so they cannot absorb enough oxygen from the water. The fish suffocate and die.', wrong = '{"0": "In acidified lakes the water becomes more acidic, not alkaline.", "1": "Freezing has nothing to do with acidification. The harm comes from Al³⁺ damaging the gills.", "3": "Fish do not die from loss of CO₂. They die because Al³⁺ blocks oxygen uptake through their gills."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1199' AND answer = 2;
UPDATE questions SET why = 'Climate change brings more floods in some areas. To help crops cope, scientists developed flood-tolerant varieties such as Sub1 rice, which can survive being completely underwater for about two weeks and then recover.', wrong = '{"0": "Sub1 rice is bred for flood tolerance, not for growing without nitrogen.", "1": "Producing beta-carotene is the trait of golden rice, which helps prevent vitamin A deficiency.", "2": "Making its own insecticide is the trait of Bt cotton."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1200' AND answer = 3;
UPDATE questions SET why = 'Golden rice is genetically engineered to make beta-carotene, which the body converts into vitamin A. Lack of vitamin A can cause blindness, especially in developing countries where rice is the main food. The beta-carotene gives the rice its golden colour.', wrong = '{"0": "Producing a bacterial insecticide is the trait of Bt cotton, not golden rice.", "2": "Golden rice is made to improve nutrition, not just to resist herbicides.", "3": "Golden rice is not engineered for extra starch. Its added trait is beta-carotene."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1201' AND answer = 1;
UPDATE questions SET why = 'One concern about GM crops is that herbicide-resistant genes may pass to wild weeds through cross-pollination. The weeds then become superweeds that cannot be killed by the herbicide. Other concerns are resistant insects and unknown long-term effects on health and biodiversity.', wrong = '{"0": "GM crops are often designed to increase yields, for example by resisting pests and disease.", "1": "GM crops such as golden rice are grown to be eaten. Being inedible is not a stated concern.", "3": "Bt crops make their own pesticide, which reduces the need for chemical sprays."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1202' AND answer = 2;
UPDATE questions SET why = 'Pakistan has large reserves of natural gas, which is mostly methane, CH₄. Methane supplies the hydrogen needed to make ammonia, which is then converted into urea, NH₂CONH₂. Because the raw material is local, fertilizer production costs stay lower.', wrong = '{"0": "Stainless steel uses chromite, found at Muslim Bagh, together with iron.", "1": "Cement is made mainly from limestone (CaCO₃) and clay, with some gypsum.", "2": "Soda ash (Na₂CO₃) is made from brine (from rock salt) and limestone by the Solvay process."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1203' AND answer = 3;
UPDATE questions SET why = 'Chromite, an ore of chromium, is found at Muslim Bagh in Balochistan. Chromium is used to make stainless steel and pigments. Other Pakistani deposits are known for different minerals, such as rock salt at Khewra.', wrong = '{"0": "Khewra is famous for one of the world''s largest rock-salt deposits, not for chromite.", "2": "Thar, in Sindh, is known for its large coal reserves, not chromite.", "3": "Kalabagh is not the site named for chromite. Chromite is mined at Muslim Bagh."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1204' AND answer = 1;
UPDATE questions SET why = 'In the Contact process, sulfur dioxide is oxidised to sulfur trioxide, 2SO₂ + O₂ → 2SO₃, over a catalyst of vanadium(V) oxide, V₂O₅, or platinum. The SO₃ is then turned into oleum and finally into very pure, concentrated sulfuric acid.', wrong = '{"0": "Iron is the catalyst in the Haber process for making ammonia, not the Contact process.", "2": "Zeolites are catalysts used in the catalytic cracking of petroleum fractions.", "3": "Nickel is used as a catalyst for hydrogenation, such as turning vegetable oils into margarine."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1205' AND answer = 1;
UPDATE questions SET why = 'In the Solvay process, ammonia and CO₂ are passed into brine to precipitate sodium hydrogencarbonate, which is heated to give sodium carbonate. The ammonia is recovered by reacting it with lime made from limestone. This step leaves calcium chloride, CaCl₂, as the by-product.', wrong = '{"1": "Chlorine gas is made by the chlor-alkali process, the electrolysis of brine, not by the Solvay process.", "2": "Sulfur trioxide is made in the Contact process, on the way to sulfuric acid.", "3": "Urea is a fertilizer made from ammonia and CO₂. It is not a by-product of the Solvay process."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1206' AND answer = 0;
UPDATE questions SET why = 'The chlor-alkali process passes an electric current through brine, a concentrated solution of NaCl, usually in membrane cells. Chlorine gas forms at the anode, hydrogen gas at the cathode, and sodium hydroxide (caustic soda) is left in solution. So the products are Cl₂, NaOH and H₂.', wrong = '{"1": "Sodium carbonate with calcium chloride as by-product comes from the Solvay process, which uses brine and limestone, not electrolysis.", "2": "Ammonia is made by the Haber process, and urea is then made from ammonia and CO₂.", "3": "Sulfuric acid is made by the Contact process from sulfur dioxide."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1207' AND answer = 0;
UPDATE questions SET why = 'To make cement, a close mixture of limestone and clay is heated to about 1500 °C in a rotary kiln. The hard product, called clinker, is then ground with a little gypsum, which controls how quickly the cement sets.', wrong = '{"1": "150 °C is far too low to make clinker from limestone and clay, and the clinker is ground with gypsum, not salt.", "2": "Heating to about 500 °C over a zeolite catalyst describes catalytic cracking of petroleum, not cement making.", "3": "37 °C with enzymes describes biological processes at body temperature, not a cement kiln."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1208' AND answer = 0;
UPDATE questions SET why = 'Edible oils contain unsaturated fatty acid chains with C=C bonds, which keep them liquid. In hydrogenation, hydrogen is added across these C=C bonds with a nickel catalyst. The chains become more saturated, the melting point rises, and the oil turns into a solid fat such as margarine.', wrong = '{"1": "Sodium benzoate is a preservative that stops microbes growing in food. It is not made by hydrogenation.", "2": "Adding iodine to salt is fortification, done to prevent iodine deficiency.", "3": "Bread rises because of leavening agents such as baking soda or yeast, which release CO₂."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1209' AND answer = 0;
UPDATE questions SET why = 'When water is added, cement undergoes hydration reactions. These reactions are exothermic, meaning they release heat to the surroundings. That is why freshly mixed cement feels warm.', wrong = '{"1": "If cement absorbed heat from the air it would feel cool, not warm. Its reaction with water gives out heat.", "2": "Cement is not radioactive. The warmth comes from an ordinary chemical reaction.", "3": "Fission is the splitting of heavy nuclei in a reactor. Setting cement is a chemical, not a nuclear, process."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1210' AND answer = 0;
UPDATE questions SET why = 'Hazardous chemicals must be clearly labelled so workers know what they are handling. Flammable, toxic and corrosive substances are kept in suitable containers and in separate storage areas. This prevents leaks, contamination and dangerous reactions between incompatible chemicals.', wrong = '{"1": "Storing different hazardous chemicals together risks dangerous reactions, such as an oxidiser setting fire to a flammable liquid.", "2": "Unlabelled bottles are unsafe because nobody can tell what is inside or how to handle it.", "3": "Pouring chemicals down drains pollutes water and can cause reactions in pipes. It is never safe disposal."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1211' AND answer = 0;
UPDATE questions SET why = 'Water molecules are polar, with a partial negative charge (δ−) on oxygen and partial positive charges (δ+) on hydrogen. The δ− ends surround positive ions and the δ+ ends surround negative ions such as NO₃⁻ and PO₄³⁻. This stabilises the ions, so ionic substances dissolve.', wrong = '{"1": "Water is polar, not non-polar. Its polarity is exactly what lets it dissolve ionic substances.", "2": "Water has an unusually high boiling point for its size because of hydrogen bonding. Boiling point does not explain dissolving.", "3": "Water is not a strong acid. It ionises only very slightly and can act as both a weak acid and a weak base."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1212' AND answer = 0;
UPDATE questions SET why = 'Amphoteric means able to act as both an acid and a base. Water can donate a proton (acid) or accept one (base); it even does both with itself: 2H₂O ⇌ H₃O⁺ + OH⁻. This self-ionisation, Kw = 1.0 × 10⁻¹⁴ at 25 °C, is the basis of the pH scale.', wrong = '{"0": "Existing as both a solid and a liquid describes physical states, not acid–base behaviour.", "2": "Dissolving acids and bases is about solvent ability. Amphoteric means the substance itself can behave as an acid or a base.", "3": "Containing both H and O is just water''s composition. Many compounds contain H and O without being amphoteric."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1213' AND answer = 1;
UPDATE questions SET why = 'Acid rain raises the concentration of H₃O⁺ in lakes. These ions react with insoluble metal compounds in the sediment, such as aluminium hydroxide and lead salts, by protonating them or displacing them from minerals. This makes them more soluble, so toxic metal ions enter the water.', wrong = '{"0": "Adding acid does not increase dissolved oxygen in the water.", "1": "Extra H₃O⁺ releases metal ions into the water; it does not remove them.", "3": "Adding H₃O⁺ makes the water more acidic, which lowers the pH."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1214' AND answer = 2;
UPDATE questions SET why = 'Biochemical oxygen demand is the amount of oxygen microorganisms use to break down the organic matter in a water sample. In the standard test, the sample is kept in the dark for five days at 20 °C, and the drop in dissolved oxygen is measured.', wrong = '{"0": "At 100 °C the microorganisms would be killed, so no biological oxygen use could be measured.", "1": "Thirty days at 0 °C is not the standard. Microbes work very slowly near freezing.", "2": "One day at 37 °C is body temperature conditions, not the standard BOD test."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1215' AND answer = 3;
UPDATE questions SET why = 'COD is the oxygen needed to oxidise both organic and inorganic matter chemically, using strong oxidising agents such as K₂Cr₂O₇ or KMnO₄. Because it does not depend on microbes, it measures the total oxidisable pollution, while BOD measures only what bacteria break down.', wrong = '{"0": "Measuring the oxygen actually present in the water is dissolved oxygen (DO), not COD.", "2": "Oxygen used only by bacteria to break down organic matter is BOD.", "3": "COD is usually higher than BOD, because chemical oxidants oxidise more substances than microbes can."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1216' AND answer = 1;
UPDATE questions SET why = 'Drinking water should be clean, with plenty of dissolved oxygen and very little organic matter. Typical values are DO above 6 mg/L and BOD below 2 mg/L. High DO with low BOD shows that microbes are not using up oxygen to break down pollution.', wrong = '{"0": "DO of 0 to 2 mg/L and BOD over 500 mg/L describes industrial waste, which is heavily polluted.", "1": "DO below 1 mg/L and BOD above 100 mg/L describes raw sewage.", "3": "DO of 2 to 4 mg/L and BOD of 10 to 30 mg/L describes treated sewage, not drinking water."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1217' AND answer = 2;
UPDATE questions SET why = 'Dissolved oxygen is the oxygen available in water for aquatic organisms to breathe. When there is little organic pollution, microbes use up little oxygen, so DO stays high. High DO therefore generally means clean, healthy water.', wrong = '{"0": "Heavy organic pollution lowers DO, because microbes use up oxygen while breaking down the organic matter.", "1": "A dead zone has very little oxygen, so fish and other animals cannot survive there.", "2": "Raw sewage has DO below 1 mg/L, which is very low, not high."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1218' AND answer = 3;
UPDATE questions SET why = 'In well-oxygenated water, elements exist in oxidised forms such as SO₄²⁻ and CO₂. When oxygen is used up in stagnant water, conditions become reducing. Sulfur is then reduced to hydrogen sulfide, H₂S, and nitrogen to ammonia, NH₃, both of which are toxic.', wrong = '{"0": "O₃ (ozone) and H₂O₂ are oxidising agents, used as disinfectants. They do not form in oxygen-depleted water.", "2": "SO₄²⁻ and CO₂ are the oxidised forms found in well-oxygenated water, the opposite condition.", "3": "NO₃⁻ and O₂ are oxidised species. Oxygen-depleted water would not contain O₂."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1219' AND answer = 1;
UPDATE questions SET why = 'Point-source pollution enters water from one single, identifiable place. A factory pipe discharging mercury salts into a river is one such point. The pollution is most concentrated right at the outlet, forming a plume that spreads downstream.', wrong = '{"0": "Acid rain falls over a whole region from many distant sources, so it is non-point (diffuse) pollution.", "1": "Rain washing fertilizer off many farms collects pollution over a wide area, which is non-point pollution.", "3": "Stormwater runoff from many roads gathers oil and zinc over a wide area, so it is non-point pollution."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1220' AND answer = 2;
UPDATE questions SET why = 'Non-point source pollution comes from rain or snowmelt flowing over large areas such as farms and roads. The water picks up many different pollutants along the way. The result is a mixture of pollutants at fairly low concentrations, spread over a wide area, mainly after storms.', wrong = '{"0": "One pollutant at very high concentration at one spot is typical of a point source, such as a factory pipe.", "1": "Non-point pollution carries fertilizers, pesticides, oil and salts. It is not limited to radioactive waste.", "2": "Rain is what drives non-point pollution, because runoff carries pollutants into rivers and lakes."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1221' AND answer = 3;
UPDATE questions SET why = 'Cholera is caused by bacteria that spread through water contaminated with sewage. Other water-borne diseases from microbiological pollution include typhoid, dysentery and hepatitis A. They are caused by pathogens, not by chemical pollutants.', wrong = '{"0": "Itai-itai disease is caused by cadmium, a heavy metal, which makes bones brittle.", "2": "Minamata disease is caused by methylmercury poisoning, a chemical pollutant.", "3": "Blue baby syndrome is caused by high nitrate levels in drinking water, not by microbes."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1222' AND answer = 1;
UPDATE questions SET why = 'Boiling water at 100 °C breaks down the structure of most bacteria, viruses and protozoa, so it makes water safe from microbes. It does not remove chemical pollutants such as salts, heavy metals or pesticides, which stay in the water.', wrong = '{"0": "Dissolved salts stay behind when water is boiled. As some water evaporates, they actually become more concentrated.", "1": "Heavy metal ions such as Pb²⁺ do not evaporate and are not destroyed by boiling.", "3": "Boiling does not reliably remove or destroy pesticides dissolved in water."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1223' AND answer = 2;
UPDATE questions SET why = 'In aquatic sediments, bacteria convert inorganic mercury into methylmercury, [CH₃Hg]⁺. This form is far more dangerous: it is fat-soluble, crosses cell membranes and the blood–brain barrier, builds up along food chains (biomagnification) and is a powerful neurotoxin.', wrong = '{"0": "The bacterial product is not a harmless oxide. Methylmercury is more toxic than inorganic mercury.", "1": "Calcium mercurate is not what forms. Bacteria attach a methyl group to mercury.", "2": "The conversion produces dissolved methylmercury, not only mercury vapour."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1224' AND answer = 3;
UPDATE questions SET why = 'In the 1950s a factory in Minamata, Japan, released methylmercury into the bay. It built up in fish eaten by local people, causing mercury poisoning with neurological damage, birth defects and deaths. The condition is now called Minamata disease.', wrong = '{"0": "Nitrates in well water cause blue baby syndrome in infants, not the Minamata disaster.", "2": "Cadmium in rice fields caused itai-itai disease, a different poisoning case in Japan.", "3": "An oil spill harms marine life by coating the water, but it was not the cause of Minamata disease."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1225' AND answer = 1;
UPDATE questions SET why = 'Lead interferes with the body''s production of haemoglobin, the protein that carries oxygen in red blood cells. With less haemoglobin, the blood carries less oxygen, which is anaemia. In children lead is also a cumulative poison that causes lasting brain damage.', wrong = '{"0": "Killing bacteria has nothing to do with anaemia. Lead harms the body by blocking haemoglobin production.", "1": "Replacing calcium in bones is the effect of cadmium, which causes itai-itai disease.", "3": "Lead does not cause anaemia by reducing nitrates. Its effect is on haemoglobin production."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1226' AND answer = 2;
UPDATE questions SET why = 'Cd²⁺ and Ca²⁺ have the same 2+ charge and similar sizes, but Cd²⁺ is slightly smaller, so it has a higher charge density (charge per size). This lets Cd²⁺ take the place of Ca²⁺ in bones, making them weak and brittle, as in itai-itai disease.', wrong = '{"0": "Both ions carry the same charge, 2+. The difference is in how concentrated that charge is.", "1": "Cadmium (about 112) is much heavier than calcium (about 40). Mass is not the reason it replaces calcium.", "2": "Cd²⁺ is a positive ion (cation), like Ca²⁺. An anion could not take the place of Ca²⁺."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1227' AND answer = 3;
UPDATE questions SET why = 'The WHO limits in drinking water are: cadmium 0.003 mg/L, mercury 0.006, lead and arsenic 0.01, chromium 0.05 and copper 2.0 mg/L. The smallest number is cadmium''s, 0.003 mg/L, so it has the lowest allowed level.', wrong = '{"0": "Chromium''s limit, 0.05 mg/L, is more than ten times higher than cadmium''s 0.003 mg/L.", "2": "Copper''s limit, 2.0 mg/L, is the highest of all the metals listed.", "3": "Lead''s limit, 0.01 mg/L, is higher than cadmium''s 0.003 mg/L."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1228' AND answer = 1;
UPDATE questions SET why = 'DDT is a non-polar organochlorine compound, so it does not dissolve in water but dissolves well in the fatty tissue of animals. It is also persistent, breaking down very slowly. So it builds up in fish and birds and becomes more concentrated up the food chain.', wrong = '{"0": "DDT is a persistent organic pollutant that breaks down very slowly, not rapidly.", "1": "DDT is insoluble in water and is not quickly excreted, which is why it accumulates.", "3": "DDT is an organic compound containing chlorine, not a heavy metal."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1229' AND answer = 2;
UPDATE questions SET why = 'PCBs (polychlorinated biphenyls) were widely used as coolants in electrical transformers. They leak into water mainly from hazardous waste sites where old equipment was dumped. PCBs are probable human carcinogens, weaken the immune system and cause skin problems such as chloracne.', wrong = '{"0": "Fertilizer runoff carries nitrogen and phosphorus compounds, not PCBs.", "1": "Natural gas is mainly methane and is not a source of PCBs.", "2": "Boiling water does not create PCBs; they are man-made industrial chemicals."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1230' AND answer = 3;
UPDATE questions SET why = 'Excess nitrogen and phosphorus from runoff make algae grow very fast, forming algal blooms that block sunlight. When the algae die, bacteria decompose them and use up large amounts of dissolved oxygen. The water becomes hypoxic, forming dead zones where fish cannot survive.', wrong = '{"0": "Algae do not produce mercury. Dead zones are caused by oxygen being used up.", "2": "The main harm is not direct nitrogen poisoning of fish. It is the loss of oxygen when algae decay.", "3": "Algal blooms block sunlight from reaching underwater plants. They do not increase it."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1231' AND answer = 1;
UPDATE questions SET why = 'High nitrate levels in drinking water reduce the blood''s ability to carry oxygen. Infants are most at risk: their skin can turn bluish from lack of oxygen, a condition called blue baby syndrome or methaemoglobinaemia.', wrong = '{"0": "Chloracne is a skin condition caused by PCBs, not by nitrates.", "1": "Itai-itai disease is caused by cadmium replacing calcium in bones.", "3": "Minamata disease is caused by methylmercury poisoning, which damages the nervous system."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1232' AND answer = 2;
UPDATE questions SET why = 'Oil does not mix with water and is less dense, so it spreads as a thin layer over the sea surface. This layer blocks sunlight and reduces oxygen exchange between air and water, harming fish, birds and mammals. Animals also swallow oil when they clean their fur or feathers.', wrong = '{"0": "Raising the pH of seawater is not how oil causes harm. Its main effect is the surface layer.", "1": "Oil is non-polar and does not dissolve in water. It floats as a film on top.", "2": "Oil is not a nutrient for fish. Its hydrocarbons are toxic to marine life."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1233' AND answer = 3;
UPDATE questions SET why = 'Persistent toxins such as mercury and some pesticides are not broken down or excreted. Each animal eats many organisms from the level below, so the toxin builds up and becomes more concentrated at each step of the food chain. Top predators, including humans, get the highest doses.', wrong = '{"0": "The toxins are not diluted. They become more concentrated going up the food chain.", "2": "Persistent toxins resist breakdown, so top predators store them rather than destroying them.", "3": "Animals, including fish, birds and humans, are badly affected, not only plants."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1234' AND answer = 1;
UPDATE questions SET why = 'Sewage, farm runoff and industrial waste feed the growth of algae and other organisms. When these die and decay in oxygen-poor (anaerobic) water, the decomposition releases methane, CH₄. Methane is a powerful greenhouse gas, so it adds to global warming.', wrong = '{"0": "Producing ozone is not the link given between water pollution and global warming.", "1": "Absorbing CO₂ would reduce greenhouse gases, not add to warming. The link is methane release.", "3": "Water pollution lowers dissolved oxygen, it does not raise it."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1235' AND answer = 2;
UPDATE questions SET why = 'The first stage of treatment removes large, physical debris. Water passes through metal screens that trap large particles. It is then held in large tanks so that suspended solids sink to the bottom under gravity, which is sedimentation.', wrong = '{"0": "Ion exchange swaps Ca²⁺ and Mg²⁺ for Na⁺ or H⁺ to soften water. It is used later for high-purity water.", "1": "Reverse osmosis is used at the end to make high-purity water, not to remove large particles.", "2": "Chlorination is the disinfection step that kills microbes, done after solids have been removed."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1236' AND answer = 3;
UPDATE questions SET why = 'In filtration, water first passes through layers of graded sand and gravel that trap fine particles. For more advanced purification, activated carbon is used. Its huge porous surface adsorbs remaining impurities, such as dissolved organic compounds that cause taste and odour.', wrong = '{"1": "Aluminium sulfate (alum) is a coagulant that makes small particles clump into flocs. It is not a filter material.", "2": "Sodium chloride is common salt. It is not used as a filtering or adsorbing material.", "3": "Calcium carbonate is not the material used to adsorb impurities in advanced filtration."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1237' AND answer = 0;
UPDATE questions SET why = 'Chlorine gas or sodium hypochlorite reacts with water to form hypochlorous acid, HOCl, for example Cl₂ + H₂O → HOCl + HCl. HOCl penetrates the cell walls of bacteria and viruses and disrupts their cell functions, killing them.', wrong = '{"1": "HCl also forms when chlorine reacts with water, but it is not the species that kills microbes.", "2": "Chloride ions, Cl⁻, are harmless and present in ordinary salt. They do not disinfect water.", "3": "Sodium ions from NaOCl are just spectator ions and have no disinfecting effect."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1238' AND answer = 0;
UPDATE questions SET why = 'In reverse osmosis, pressure forces water through a semi-permeable membrane. Water molecules pass through, but dissolved salts, bacteria and other impurities are held back. This gives high-purity water for laboratories and for areas where water is very salty.', wrong = '{"1": "Adding chlorine disinfects water by killing microbes, but it does not remove dissolved salts.", "2": "Boiling water and condensing the steam is distillation, a different purification method.", "3": "Adding alum is coagulation, which clumps fine particles together so they settle."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1239' AND answer = 0;
UPDATE questions SET why = 'Drip irrigation delivers water slowly and directly to the roots of each plant through pipes and small emitters. Very little water is lost to evaporation or runoff, so it saves a lot of water while also improving crop yields. Sprinkler irrigation is another efficient method.', wrong = '{"1": "Flood irrigation covers whole fields with water, and much of it evaporates or soaks away, so it wastes water.", "2": "Open-channel flooding sends water across fields in channels, losing a lot to evaporation and seepage.", "3": "Using hosepipes for watering lets water run freely and wastes it; it is even fined for lawns and car-washing."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1240' AND answer = 0;
UPDATE questions SET why = 'Greywater is lightly used household water from laundry, dishwashing and bathing. It does not contain toilet waste, so it can be reused for toilet flushing, gardening and industrial cooling. This saves fresh water and reduces the load on sewage treatment.', wrong = '{"1": "Sewage from toilets contains human waste and harmful microbes, so it is not greywater.", "2": "Industrial effluent may contain toxic chemicals and is not classed as household greywater.", "3": "Rainwater is collected separately by rainwater harvesting. It has not been used, so it is not greywater."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1241' AND answer = 0;
UPDATE questions SET why = 'Under the Punjab Water Act, 2019, it is illegal to discharge pollutants into water or block its flow. The penalty is up to 3 months'' imprisonment and/or a fine of Rs 500,000.', wrong = '{"1": "The Punjab Environmental Protection Act, 1997 covers pollution prevention, with fines up to Rs 5 million plus daily fines.", "2": "The Punjab Irrigation, Drainage and Rivers Act, 2023 sets water and drainage fees and discharge permits; no such penalty is given for it.", "3": "The Punjab Water and Sanitation Authority Act, 2025 sets up water authorities in major cities. It does not carry this penalty."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1242' AND answer = 0;
UPDATE questions SET why = 'By VSEPR theory, electron pairs around a central atom spread out as far apart as possible. Six bond pairs and no lone pairs point to the six corners of an octahedron. So SF₆ is octahedral, and every F–S–F angle between neighbouring bonds is 90°.', wrong = '{"0": "Trigonal bipyramidal, with 90° and 120° angles, is the shape for five electron pairs, as in PCl₅.", "1": "Six pairs in one flat ring would be only 60° apart and repel strongly. Pairs spread out in 3D instead.", "3": "Tetrahedral, with 109.5° angles, is the shape for four electron pairs, as in CH₄."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1243' AND answer = 2;
UPDATE questions SET why = 'Oxygen in water has four electron pairs arranged roughly tetrahedrally: two bond pairs and two lone pairs. Lone pairs repel more strongly than bond pairs, so they push the two O–H bonds closer together. The angle shrinks from 109.5° to 104.5°, giving a bent (V-shaped) molecule.', wrong = '{"1": "An sp² arrangement would give angles near 120°, which does not match 104.5°.", "2": "Repulsion between the hydrogen atoms would push them apart and widen the angle, not narrow it.", "3": "Water really is bent (V-shaped), not linear. Its bent shape is why it has a dipole moment."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1244' AND answer = 0;
UPDATE questions SET why = 'In H₃O⁺, oxygen has three bond pairs (to H atoms) and one lone pair. These four pairs are arranged tetrahedrally, but only the atoms are counted when naming the shape. Three H atoms below one lone pair give a pyramidal ion, like NH₃.', wrong = '{"0": "Trigonal planar needs three bond pairs and no lone pair on the central atom. H₃O⁺ has one lone pair.", "2": "A tetrahedral shape needs four bond pairs and no lone pairs, as in CH₄. H₃O⁺ has only three bonds.", "3": "A V-shape needs two lone pairs. When water gains H⁺, one of its two lone pairs becomes a bond pair."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1245' AND answer = 1;
UPDATE questions SET why = 'In molecular orbital theory, electrons in bonding orbitals hold the atoms together and electrons in antibonding orbitals weaken the bond. So bond order = ½ (bonding electrons − antibonding electrons). It gives the number of bonds; for example, N₂ has (6 − 0)/2 = 3 from its 2p electrons.', wrong = '{"0": "Counting only bonding electrons ignores antibonding electrons, which cancel part of the bonding.", "1": "Antibonding electrons lower the bond order. They are subtracted from the bonding electrons, not doubled.", "2": "Unpaired electrons decide whether a molecule is paramagnetic. They do not give the bond order."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1246' AND answer = 3;
UPDATE questions SET why = 'A π orbital forms when two parallel p orbitals overlap side by side. The electron density lies in two lobes, above and below the line joining the nuclei. The internuclear axis itself lies in a nodal plane, where the electron density is zero.', wrong = '{"0": "Maximum electron density along the axis belongs to σ orbitals, which form by head-on overlap.", "1": "Being symmetrical around the internuclear axis is a feature of σ orbitals, not π orbitals.", "2": "Bonding molecular orbitals are lower in energy than the atomic orbitals that form them. Antibonding ones are higher."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1247' AND answer = 3;
UPDATE questions SET why = 'The number of molecular orbitals formed always equals the number of atomic orbitals that combine. Two 1s orbitals give two MOs: a lower-energy bonding orbital, σ1s, and a higher-energy antibonding orbital, σ*1s. Both electrons of H₂ go into σ1s.', wrong = '{"0": "Two atomic orbitals must give two molecular orbitals, so one bonding orbital alone is too few.", "1": "In-phase overlap gives a bonding MO and out-of-phase overlap gives an antibonding MO, so one of each forms.", "2": "Four molecular orbitals would need four atomic orbitals to combine, not two."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1248' AND answer = 3;
UPDATE questions SET why = 'The six 2p electrons of N₂ fill the two π2p bonding orbitals and the σ2p bonding orbital, with none in the 2p antibonding orbitals. Bond order = (6 − 0)/2 = 3. A triple bond is made of one σ bond and two π bonds, N≡N.', wrong = '{"0": "Bond order 2, with one σ and one π bond, describes O₂, which has two electrons in antibonding orbitals.", "1": "Only one σ bond can form between two atoms. The second and third bonds must be π bonds.", "2": "A bond order of 1 means a single bond, as in F₂. N₂ is triple bonded."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1249' AND answer = 3;
UPDATE questions SET why = 'Bond order = ½ (bonding electrons − antibonding electrons). For the 2p electrons of O₂, bond order = (6 − 2)/2 = 4/2 = 2. So the two oxygen atoms are joined by a double bond, one σ and one π.', wrong = '{"0": "A bond order of 1 would need four antibonding electrons, as in F₂: (6 − 4)/2 = 1. O₂ has only two.", "1": "1.5 is the bond order of the superoxide ion O₂⁻, which has one extra antibonding electron: (6 − 3)/2.", "2": "2.5 is the bond order of O₂⁺, which has one fewer antibonding electron: (6 − 1)/2."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1250' AND answer = 3;
UPDATE questions SET why = 'After the bonding orbitals of O₂ are filled, two electrons remain for the antibonding π*2p_y and π*2p_z orbitals, which have equal energy. By Hund''s rule they enter these orbitals singly with parallel spins. These two unpaired electrons make oxygen paramagnetic.', wrong = '{"1": "Two electrons in one orbital must have opposite spins, so they would be paired, not unpaired.", "2": "The π2p_y and π2p_z bonding orbitals are completely filled in O₂, so their electrons are paired.", "3": "The σ1s and σ*1s orbitals are filled inner orbitals, each holding a pair of electrons."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1251' AND answer = 0;
UPDATE questions SET why = 'For N₂ the energy order of the 2p-derived orbitals is π2p_y = π2p_z < σ2pₓ, so the π orbitals are filled before σ2pₓ. For O₂ the order switches to σ2pₓ < π2p_y = π2p_z. So in N₂ the π orbitals lie below σ2pₓ, while in O₂ σ2pₓ lies below them.', wrong = '{"1": "This swaps the two molecules. It is in O₂ that σ2pₓ lies below the π orbitals.", "2": "The order is not the same. σ2pₓ and the π2p orbitals change places between N₂ and O₂.", "3": "Antibonding orbitals are always higher in energy than the matching bonding orbitals."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1252' AND answer = 0;
UPDATE questions SET why = 'From the equation, 1 mol CH₄ needs 2 mol O₂. So 0.25 mol CH₄ needs 2 × 0.25 = 0.50 mol O₂. Number of O₂ molecules = 0.50 mol × 6.02 × 10²³ mol⁻¹ = 3.01 × 10²³.', wrong = '{"0": "1.505 × 10²³ is 0.25 × 6.02 × 10²³, the number of methane molecules. It forgets the 1 : 2 mole ratio.", "1": "6.02 × 10²³ is 1 mol of O₂, which would burn 0.50 mol of methane, twice the amount given.", "3": "12.04 × 10²³ is 2 mol of O₂, enough to burn a whole mole of methane."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1253' AND answer = 2;
UPDATE questions SET why = 'The limiting reactant is the one that runs out first. Using the balanced equation, work out how much product each reactant could make from the moles present. The reactant that gives the smallest amount of product is limiting; the other is in excess.', wrong = '{"0": "A larger mass does not mean more moles, and the mole ratio in the equation must also be considered.", "2": "A larger molar mass does not decide which reactant runs out. The moles present and the mole ratio do.", "3": "The order in which reactants are written in an equation has no effect on which one is used up first."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1254' AND answer = 1;
UPDATE questions SET why = 'Al could make 0.40 mol AlCl₃ (ratio 2 : 2). Cl₂ could make 0.45 × 2/3 = 0.30 mol AlCl₃. Cl₂ gives less, so it is limiting and 0.30 mol AlCl₃ forms. This uses 0.30 mol Al, leaving 0.40 − 0.30 = 0.10 mol Al in excess.', wrong = '{"0": "Making 0.40 mol AlCl₃ would need 0.60 mol Cl₂, but only 0.45 mol is present.", "1": "This takes Cl₂ : AlCl₃ as 1 : 1. The equation gives 3 : 2, so 0.45 mol Cl₂ makes only 0.30 mol AlCl₃.", "3": "Cl₂ is the limiting reactant, so it is all used up. The leftover reactant is aluminium."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1255' AND answer = 2;
UPDATE questions SET why = 'Stoichiometry means calculating amounts of substances from balanced equations. In medicine it is used to prepare antibiotics, measure cholesterol and glucose in blood, test athletes'' urine for steroids and stimulants, set vaccine antigen levels and work out drug doses.', wrong = '{"1": "Counting red blood cells is done by looking under a microscope. It does not use calculations from a chemical equation.", "2": "Measuring body temperature with a thermometer is a physical measurement, not a stoichiometric calculation.", "3": "An ECG records the electrical activity of the heart. No chemical amounts are calculated."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1256' AND answer = 0;
UPDATE questions SET why = 'A medicine works only within a certain dose range. Too small a dose of paracetamol has no useful effect on pain or fever, while an overdose can be toxic and cause severe liver damage. So the dose must be calculated accurately, often from the patient''s body mass.', wrong = '{"0": "Large doses do not simply lower fever more. Beyond the safe limit, paracetamol becomes toxic to the liver.", "2": "Giving more than the body needs is exactly what accurate dosing tries to avoid, because excess is harmful.", "3": "Paracetamol is absorbed into the blood, which is how it relieves pain and reduces fever."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1257' AND answer = 1;
UPDATE questions SET why = 'Boyle''s law states that for a fixed amount of gas at constant temperature, volume is inversely proportional to pressure: V ∝ 1/P, or P₁V₁ = P₂V₂. If the pressure is doubled, the volume becomes half.', wrong = '{"0": "Volume doubles when pressure is halved, not doubled. The two change in opposite directions.", "1": "At constant temperature and amount, volume stays the same only if the pressure does not change.", "3": "One-quarter of the volume would need the pressure to rise four times, since PV is constant."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1258' AND answer = 2;
UPDATE questions SET why = 'From the ideal gas equation PV = nRT, for a fixed amount of gas V ∝ T/P. Doubling the absolute temperature doubles V, and doubling the pressure halves it. The two effects cancel: V × 2 ÷ 2 = V, so the volume does not change.', wrong = '{"0": "Doubling T alone would double V, but doubling P at the same time halves it again.", "1": "Four times the volume would need T doubled and P halved, not both doubled.", "2": "Half the volume would result from doubling P at constant T. Here T is doubled too."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1259' AND answer = 3;
UPDATE questions SET why = 'Avogadro''s law states that at constant temperature and pressure, the volume of a gas is directly proportional to the number of moles: V ∝ n. So equal volumes of gases at the same T and P contain equal numbers of molecules.', wrong = '{"1": "V ∝ 1/P at constant n and T is Boyle''s law, which links volume and pressure.", "2": "V ∝ T at constant n and P is Charles''s law, which links volume and temperature.", "3": "At constant V and T, adding more gas raises the pressure, so P ∝ n, not 1/n."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1260' AND answer = 0;
UPDATE questions SET why = 'Viscosity is a liquid''s resistance to flow. Honey contains sugars with many –OH groups, which form strong hydrogen bonds between molecules. These strong attractions stop molecules sliding past each other easily, so honey is more viscous and pours more slowly than water.', wrong = '{"1": "Lower viscosity would make honey flow faster than water. Stronger intermolecular forces actually raise viscosity.", "2": "Vapour pressure describes how easily a liquid evaporates, not how fast it flows.", "3": "Surface tension concerns the liquid''s surface. It is not what controls how quickly a liquid pours."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1261' AND answer = 0;
UPDATE questions SET why = 'Viscosity depends on how strongly molecules attract each other. Stronger intermolecular forces hold molecules together more tightly, so they move past each other less freely. The liquid resists flow more, so it becomes more viscous.', wrong = '{"0": "Raising the temperature gives molecules more energy to overcome attractions, so viscosity falls.", "2": "Higher kinetic energy helps molecules break free of their neighbours, which lowers viscosity.", "3": "Smaller molecules usually have weaker forces and less tangling, so they flow more easily."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1262' AND answer = 1;
UPDATE questions SET why = 'Some substances do not melt directly to a clear liquid. On heating, the crystalline solid first melts to a cloudy liquid, the liquid-crystal phase, in which molecules keep some order. On further heating this changes into a normal clear liquid.', wrong = '{"0": "This is the sequence written backwards, as on cooling. Heating starts from the crystalline solid.", "1": "The cloudy liquid-crystal phase comes before the clear liquid on heating, not after it.", "3": "Liquid crystals form between a crystalline solid and a clear liquid. An amorphous solid is not part of the sequence."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1263' AND answer = 2;
UPDATE questions SET why = 'In a liquid crystal, the rod-like molecules stay roughly parallel, like logs in a stack. They can slide through the fluid and spin around their long axis, but they cannot turn end over end. This keeps their orderly parallel arrangement.', wrong = '{"0": "Turning end over end would destroy the parallel arrangement that makes the phase a liquid crystal.", "2": "Only vibrating about fixed positions describes particles in a solid. Liquid-crystal molecules can also move through the fluid.", "3": "Random motion in all directions describes gas molecules. Liquid-crystal molecules keep a parallel order."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1264' AND answer = 1;
UPDATE questions SET why = 'Liquid crystals behave partly like liquids and partly like solids. They flow and are viscous like liquids, but their ordered, parallel molecules give them crystal-like optical properties. Like crystals, they are anisotropic, meaning their properties differ with direction.', wrong = '{"0": "Being able to flow is a property of liquids, not crystalline solids.", "1": "Viscosity, resistance to flow, is a property of liquids, not of crystalline solids.", "2": "Molecules moving through the fluid is liquid-like behaviour. In a crystalline solid particles stay in fixed positions."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1265' AND answer = 3;
UPDATE questions SET why = 'A tumour is usually warmer than the healthy tissue around it. Cholesteric liquid crystals change colour (their optical behaviour) with small changes in temperature. Applied to the skin over the breast, they show the warmer area, helping to detect a tumour early.', wrong = '{"1": "The liquid crystal is placed on the skin surface and responds to temperature. It is not taken up by the tumour.", "2": "Liquid crystals change how they reflect light. They do not give off X-rays.", "3": "The tumour is warmer, not colder, than the surrounding tissue, and the liquid crystal does not freeze."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1266' AND answer = 0;
UPDATE questions SET why = 'An intermediate is a short-lived species, often an ion or free radical, that is formed in one elementary step and used up in a later step. Because it is made and then consumed, it does not appear in the overall balanced equation.', wrong = '{"0": "Intermediates are used up before the reaction ends, so they do not appear as products in the overall equation.", "1": "A substance used in an early step and given back unchanged at the end is a catalyst, not an intermediate.", "3": "The slowest step is the rate-determining step. It is a step in the mechanism, not a chemical species."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1267' AND answer = 2;
UPDATE questions SET why = 'Doubling [H₂] doubles the rate, so the reaction is first order in H₂. Tripling [NO] makes the rate 9 = 3² times larger, so it is second order in NO. Rate = k[NO]²[H₂], third order overall. Orders come from experiment, not from equation coefficients.', wrong = '{"0": "If the reaction were first order in NO, tripling [NO] would only triple the rate, not multiply it by nine.", "1": "This copies the coefficients of the equation. Second order in H₂ would make the rate four times larger when [H₂] doubles.", "2": "This swaps the orders. Doubling [H₂] would then quadruple the rate, and tripling [NO] would only triple it."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1268' AND answer = 3;
UPDATE questions SET why = 'The overall rate is set by the slowest step, the rate-determining step. Steps that come after it are fast and only take up what the slow step produces. A species that takes part only in such a later fast step does not appear in the rate equation, so its concentration does not affect the rate.', wrong = '{"1": "Only species involved in the rate-determining step, or in steps before it, appear in the rate equation.", "2": "There is no dependence on this species at all, so the rate cannot depend on the square of its concentration.", "3": "Its order is zero, but the whole reaction is not zero order. Other species in the slow step still affect the rate."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1269' AND answer = 0;
UPDATE questions SET why = 'Na⁺ comes from the strong base NaOH and Cl⁻ from the strong acid HCl. Conjugates of strong acids and bases are extremely weak, so neither ion reacts with water (no hydrolysis). The H₃O⁺ and OH⁻ concentrations stay equal, so the solution is neutral, pH 7 at 25 °C.', wrong = '{"1": "Neither ion reacts significantly with water, so neither produces extra H₃O⁺ or OH⁻.", "2": "NaCl is a strong electrolyte and dissociates completely into Na⁺ and Cl⁻ in water.", "3": "Cl⁻ is an extremely weak base. It does not remove H₃O⁺ ions from water."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1270' AND answer = 0;
UPDATE questions SET why = 'An indicator is chosen so that it changes colour at the right moment. The pH at the end of the titration should be close to the indicator''s own neutral point (colour-change pH), and the indicator should give a sharp colour change near the equivalence point.', wrong = '{"0": "Indicators are weak organic acids or bases, not strong acids, and they must show two different colours.", "2": "Indicators change colour over a narrow range of about 2 pH units, and many are coloured in base.", "3": "An indicator that reacted with the titrant before the equivalence point would give a false end point."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1271' AND answer = 1;
UPDATE questions SET why = 'In the oxidation number method, the first step is to find which atoms change oxidation number and by how much. Next, multiply the species by suitable numbers so that the total increase in oxidation number equals the total decrease, since electrons lost must equal electrons gained. Other atoms are then balanced by inspection.', wrong = '{"0": "Adding H⁺ is part of balancing in acidic solution by the ion-electron method, not the next step here.", "2": "Writing separate half-equations is the ion-electron (half-reaction) method, a different technique.", "3": "Cancelling spectator ions is used when writing ionic equations. It is not a step of the oxidation number method."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1272' AND answer = 1;
UPDATE questions SET why = 'Each Cr goes from +6 to +3, so 2 Cr gain 6 electrons. This needs 6 Cl⁻ to lose 6 electrons, forming 3Cl₂. Another 8 Cl stay as chloride in 2KCl and 2CrCl₃. Total HCl = 6 + 8 = 14: K₂Cr₂O₇ + 14HCl → 2KCl + 2CrCl₃ + 3Cl₂ + 7H₂O.', wrong = '{"0": "6 counts only the chlorine oxidised to Cl₂. It leaves out the 8 Cl that end up in KCl and CrCl₃.", "1": "8 counts only the chlorine that stays as chloride in KCl and CrCl₃, leaving out the 6 Cl oxidised to Cl₂.", "2": "12 HCl gives only 12 H, but 7 H₂O need 14 H, and the chlorine does not balance either."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1273' AND answer = 3;
UPDATE questions SET why = 'In MnO₄⁻, Mn is +7; in Mn²⁺ it is +2, so each MnO₄⁻ gains 5 electrons. Each Fe²⁺ → Fe³⁺ loses 1 electron. To balance electrons, 5 Fe²⁺ react with each MnO₄⁻: MnO₄⁻ + 5Fe²⁺ + 8H⁺ → Mn²⁺ + 5Fe³⁺ + 4H₂O.', wrong = '{"0": "One Fe²⁺ gives only one electron, but MnO₄⁻ needs five to be reduced to Mn²⁺.", "1": "Two Fe²⁺ would supply only two electrons, not the five MnO₄⁻ needs.", "2": "Three electrons match a change such as Cr(VI) to Cr(III). Mn(VII) to Mn(II) needs five."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1274' AND answer = 3;
UPDATE questions SET why = 'An electrolytic cell uses electrical energy to force a non-spontaneous reaction, so it converts electrical energy into chemical energy. It needs a direct current (DC) supply so that each electrode keeps the same charge. The anode is positive and the cathode negative.', wrong = '{"0": "Converting chemical energy into electrical energy is what a galvanic (voltaic) cell does.", "1": "Alternating current keeps reversing, so the electrodes would swap roles. Electrolysis needs direct current.", "3": "In an electrolytic cell the anode is connected to the positive terminal, so it is positive."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1275' AND answer = 2;
UPDATE questions SET why = 'In molten CuBr₂, the Cu²⁺ ions move to the negative cathode and gain electrons: Cu²⁺ + 2e⁻ → Cu. Gaining electrons is reduction, which always happens at the cathode. Bromide ions lose electrons at the anode to form bromine.', wrong = '{"0": "Bromine forms at the anode, not the cathode, where Br⁻ ions are oxidised.", "2": "Copper does form at the cathode, but by gaining electrons, which is reduction, not oxidation.", "3": "Bromine forms at the anode by oxidation (2Br⁻ → Br₂ + 2e⁻), not at the cathode by reduction."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1276' AND answer = 1;
UPDATE questions SET why = 'For Cu²⁺ + 2e⁻ → Cu, z = 2. E = 0.34 + (0.059/2) log(0.01) = 0.34 + 0.0295 × (−2) = 0.34 − 0.059 ≈ +0.28 V. A lower Cu²⁺ concentration makes the electrode potential less positive.', wrong = '{"0": "+0.40 V comes from adding 0.059 instead of subtracting it, ignoring that log(0.01) is negative.", "1": "+0.34 V is the standard potential, which applies only when [Cu²⁺] is 1 mol dm⁻³.", "3": "+0.22 V comes from using z = 1, which doubles the correction to 0.118 V."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1277' AND answer = 2;
UPDATE questions SET why = 'Metals at the top of the activity series, such as K, Na and Ca, have the most negative standard reduction potentials. This means they lose electrons (are oxidised) most easily. So they are the most reactive metals and the strongest reducing agents.', wrong = '{"0": "The most positive reduction potentials belong to unreactive metals at the bottom, such as Ag and Au.", "1": "Metals that lose electrons easily are reducing agents. Oxidising agents gain electrons.", "2": "Top metals react vigorously, many even with cold water and certainly with acids."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1278' AND answer = 3;
UPDATE questions SET why = 'In the activity series, metals from about Cd to Pb, including tin (E° = −0.14 V), do not react with water. Because they lie above hydrogen (negative E°), they can still replace hydrogen from dilute acids such as HCl. So tin fits.', wrong = '{"0": "Sodium is near the top of the series and reacts vigorously even with cold water.", "2": "Copper (E° = +0.34 V) lies below hydrogen, so it does not release H₂ from dilute HCl.", "3": "Silver (E° = +0.80 V) lies below hydrogen and does not react with water or dilute acids."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1279' AND answer = 1;
UPDATE questions SET why = 'Cu²⁺ is reduced and Fe is oxidised. E°cell = E°(reduction half, Cu²⁺/Cu) − E°(oxidation half, Fe²⁺/Fe) = 0.34 − (−0.44) = +0.78 V. A positive E°cell means the reaction is feasible, so iron displaces copper from solution.', wrong = '{"1": "−0.78 V is E°cell for the reverse reaction, copper reducing Fe²⁺, which is not feasible.", "2": "−0.10 V comes from adding the two potentials, −0.44 + 0.34, instead of subtracting.", "3": "+0.10 V comes from 0.44 − 0.34, which drops the negative sign of the iron potential."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1280' AND answer = 0;
UPDATE questions SET why = 'The longest chain containing the C=C has four carbons, so the parent is butene. Number from the end nearer the double bond: C=C starts at C1 and the methyl group is on C3. The name is 3-methylbut-1-ene.', wrong = '{"0": "This numbers from the wrong end. The double bond must get the lowest possible number, which is 1.", "2": "In 2-methylbut-1-ene the methyl group sits on a double-bonded carbon, CH₂=C(CH₃)CH₂CH₃, a different compound.", "3": "The compound has a C=C double bond, so its name must end in -ene, not -ane."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1281' AND answer = 1;
UPDATE questions SET why = 'The longest chain containing the C=C has four carbons, so the parent is butene. The double bond is at C2 from either end, so the methyl group decides the numbering: it must get the lower number, C2. The name is 2-methylbut-2-ene.', wrong = '{"1": "Numbering from the other end keeps the double bond at 2 but gives the methyl a higher number, 3. The lower number, 2, must be used.", "2": "In this molecule the double bond lies between C2 and C3, not between C1 and C2.", "3": "The longest chain has only four carbons. The fifth carbon is a methyl branch, so the parent is butene, not pentene."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1282' AND answer = 0;
UPDATE questions SET why = 'Physical state depends on molecular size. The smallest alkenes, ethene, propene and butene, are gases at room temperature. Alkenes with 5 to 15 carbons are liquids, and larger ones are solids. Pent-1-ene has five carbons, so it is a liquid.', wrong = '{"0": "Ethene, C₂H₄, is the smallest alkene and is a gas at room temperature.", "1": "Propene, C₃H₆, has only three carbons and is a gas at room temperature.", "3": "Butene, C₄H₈, is the last of the gaseous alkenes. Liquids start at five carbons."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1283' AND answer = 2;
UPDATE questions SET why = 'Alkenes are hydrocarbons, so they do not dissolve in water but do dissolve in alcohol and other organic solvents. They have a characteristic smell and burn with a luminous (bright, sooty) flame. Their sp² carbons make them slightly polar, unlike alkanes.', wrong = '{"0": "Alkenes are hydrocarbons that cannot hydrogen-bond with water, so they are insoluble in it.", "2": "Alkenes are slightly polar because of their sp² hybridised carbons. Alkanes are the non-polar ones.", "3": "Small alkenes are gases and those with 5 to 15 carbons are liquids. Only larger ones are solids."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1284' AND answer = 1;
UPDATE questions SET why = 'In organic chemistry, reduction means adding hydrogen or removing oxygen. Nitrobenzene, C₆H₅NO₂, is reduced to phenylamine, C₆H₅NH₂, for example with tin and concentrated HCl. Both oxygen atoms are removed and two hydrogens are added, so it is a reduction.', wrong = '{"0": "Ethanol to ethanoic acid gains oxygen and loses hydrogen, which is oxidation.", "1": "Turning ethene into epoxyethane adds an oxygen atom, which is oxidation.", "2": "Combustion is burning in oxygen to give CO₂ and H₂O, which is oxidation."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1285' AND answer = 3;
UPDATE questions SET why = 'Sulfur has six valence electrons (3s² 3p⁴). Its oxidation states range from −2 (as in H₂S) to +6. The common positive states are +4, as in SO₂, and +6, as in SO₃ and H₂SO₄.', wrong = '{"0": "+1 and +3 are not the common oxidation states of sulfur.", "1": "+5 is typical of nitrogen and phosphorus (Group 15), not sulfur. Sulfur''s common states are even numbers here.", "3": "+7 would need seven electrons, but sulfur has only six valence electrons, so its highest state is +6."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1286' AND answer = 2;
UPDATE questions SET why = 'Sulfur has atomic number 16 and is in Group 16, period 3. After the neon core (10 electrons), the remaining 6 go into 3s and 3p: [Ne] 3s² 3p⁴. This gives six valence electrons.', wrong = '{"1": "[Ne] 3s² 3p⁶ has 18 electrons, which is argon, a noble gas.", "2": "[Ar] 4s² 4p⁴ would be a period 4 element. Sulfur is in period 3, and selenium also has 3d¹⁰ electrons.", "3": "[Ne] 3s² 3p³ has 15 electrons, which is phosphorus."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1287' AND answer = 0;
UPDATE questions SET why = 'Down Group 17, the molecules Cl₂, Br₂ and I₂ become larger and heavier, with more electrons. More electrons give stronger London dispersion forces between molecules. More energy is needed to separate them, so volatility falls: Cl₂ is a gas, Br₂ a liquid and I₂ a solid.', wrong = '{"0": "Electronegativity decreases down the group, and it does not decide how easily a non-polar molecule evaporates.", "1": "The molecules get larger, not smaller, down the group.", "2": "Halogen molecules have no H atoms bonded to F, O or N, so they cannot hydrogen bond with each other."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1288' AND answer = 3;
UPDATE questions SET why = 'Group 2 oxides are white solids that are basic, because the metals are electropositive. Going down the group, the metals become more metallic and their oxides more ionic, so basic character increases. BeO is amphoteric and BaO is the most basic.', wrong = '{"0": "This is the reverse of the actual trend. Basic character rises down the group.", "2": "The trend is not constant. Metallic character, and with it basic character, increases down the group.", "3": "Only BeO at the top is amphoteric. None of the oxides becomes acidic; they become more basic going down."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1289' AND answer = 1;
UPDATE questions SET why = 'Beryllium is covered by a thin but tough layer of beryllium oxide. This layer protects the metal, so beryllium does not react with water or steam, even when heated. The other Group 2 metals react, and reactivity increases down the group.', wrong = '{"1": "Magnesium reacts very slowly with cold water and much faster with steam, forming MgO and H₂.", "2": "Calcium reacts readily with cold water to form Ca(OH)₂ and hydrogen.", "3": "Barium is low in the group and reacts vigorously with cold water."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1290' AND answer = 0;
UPDATE questions SET why = 'Mn goes from +7 to +2, so each MnO₄⁻ gains 5 electrons. In C₂O₄²⁻ each C goes from +3 to +4 in CO₂, so each ion loses 2 electrons. Equal electrons: 2 × 5 = 5 × 2 = 10. So 2MnO₄⁻ + 5C₂O₄²⁻ + 16H⁺ → 2Mn²⁺ + 10CO₂ + 8H₂O, a 2 : 5 ratio.', wrong = '{"0": "In a 1 : 1 ratio, MnO₄⁻ would gain 5 electrons while oxalate lost only 2, so electrons would not balance.", "2": "5 : 2 reverses the ratio. Oxalate, which loses fewer electrons each, must be the larger number.", "3": "1 : 2 gives 5 electrons gained but only 4 lost, so it does not balance."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1291' AND answer = 1;
UPDATE questions SET why = 'Lower alcohols, carboxylic acids, glucose and sucrose all carry polar functional groups such as –OH and –COOH. These groups form hydrogen bonds with water molecules, so the compounds dissolve in polar solvents like water.', wrong = '{"0": "These compounds contain oxygen, so they are not hydrocarbons. Hydrocarbons are insoluble in water.", "2": "They do have functional groups, and it is these polar groups that make them dissolve.", "3": "C=C bonds are non-polar and do not help a compound dissolve in water. Most of these compounds have none."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1292' AND answer = 1;
UPDATE questions SET why = 'In IUPAC names the primary suffix (-an-, -en-, -yn-) shows whether the parent chain is saturated or has a double or triple bond. Here "-en-" means a C=C bond. The secondary suffix names the functional group family; "-ol" means an alcohol, with –OH on C1.', wrong = '{"0": "This swaps the roles. \"-en-\" shows a double bond and \"-ol\" shows an alcohol.", "1": "A triple bond is shown by \"-yn-\", and aldehydes end in \"-al\", not \"-ol\".", "3": "The number of carbons in the main chain is shown by the stem, here \"but-\" for four carbons."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1293' AND answer = 2;
UPDATE questions SET why = '–CN is an electron-withdrawing group: it pulls electron density out of the benzene ring. This makes the ring less reactive than benzene (deactivated), and incoming electrophiles go mainly to the meta position. –NO₂ and C=O groups behave the same way.', wrong = '{"0": "–OH donates electrons into the ring, so it activates it and directs to ortho and para positions.", "1": "Alkyl groups such as –CH₃ donate electrons, activate the ring and direct ortho/para.", "3": "–OR donates electrons through its oxygen lone pair, so it is an activating ortho/para director."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1294' AND answer = 2;
UPDATE questions SET why = 'Groups such as –R, –OH, –OR, –NR₂ and –SR donate electrons into the benzene ring. The ring becomes richer in electrons and so more reactive towards electrophiles than benzene. Substitution then occurs mainly at the ortho and para positions, with para usually favoured.', wrong = '{"0": "Groups that withdraw electrons and make the ring less reactive are meta directors, such as –NO₂ and –CN.", "2": "These groups make electrophilic substitution easier, not impossible.", "3": "With ortho/para directors, the meta product forms only in very small amounts."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1295' AND answer = 1;
UPDATE questions SET why = 'Aromatic compounds such as benzene have a high ratio of carbon to hydrogen. When burned in air, not all the carbon is oxidised to CO₂, so unburnt carbon forms soot and the flame is smoky. This smoky flame is used as a simple test for aromatic compounds.', wrong = '{"0": "Alkanes have a lower carbon content and burn with a clean, non-smoky flame.", "1": "Alcohols such as ethanol burn with a clean blue flame, not a smoky one.", "3": "A smoky flame is the test described for aromatic compounds, not for carboxylic acids."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1296' AND answer = 2;
UPDATE questions SET why = 'Oxidising a secondary alcohol with acidified K₂Cr₂O₇ gives a ketone. Propan-2-ol, CH₃CH(OH)CH₃, is a secondary alcohol, and its oxidation gives propanone, CH₃COCH₃. The orange dichromate turns green as it is reduced.', wrong = '{"0": "Propan-1-ol is a primary alcohol, so it is oxidised to propanal and then to propanoic acid, not propanone.", "1": "Ethanol is a primary alcohol and gives ethanal and then ethanoic acid. It has only two carbons anyway.", "2": "2-Methylpropan-2-ol is a tertiary alcohol, which is not oxidised by acidified dichromate."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1297' AND answer = 3;
UPDATE questions SET why = 'Hydrolysis of an ester breaks the ester link with water, giving back the carboxylic acid and the alcohol it was made from. C₆H₅COOC₂H₅ + H₂O → C₆H₅COOH + C₂H₅OH. So ethyl benzoate gives benzoic acid and ethanol.', wrong = '{"1": "Phenol and ethanoic acid would come from hydrolysing phenyl ethanoate, a different ester.", "2": "Hydrolysis does not remove the carboxyl carbon from the ring or create a new ester.", "3": "Hydrolysis is not a reduction, so it cannot produce an aldehyde such as benzaldehyde."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1298' AND answer = 0;
UPDATE questions SET why = 'Globular proteins are folded into a spherical or oval shape. Most working proteins, such as enzymes and hormones, are globular. Their shape is held by weak bonds, so they are more sensitive to heat and pH; this is why egg white hardens on heating.', wrong = '{"0": "Long, rod-like structural proteins such as keratin are fibrous proteins, not globular ones.", "1": "Being insoluble and stable describes fibrous proteins. Globular proteins are usually soluble and denature easily.", "3": "A globular protein''s compact shape comes from its tertiary structure, so it certainly has one."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1299' AND answer = 2;
UPDATE questions SET why = 'A peptide bond forms when the –COOH group of one amino acid reacts with the –NH₂ group of the next, with loss of water. The link formed, –CO–NH–, is an amide bond. Many such bonds join amino acids into a polypeptide chain.', wrong = '{"0": "An ester bond forms between a –COOH group and an –OH group, as in fats, not between amino acids.", "1": "A glycosidic bond joins two sugar units, as in sucrose, not amino acids.", "2": "Hydrogen bonds between C=O and N–H hold the secondary structure, but they do not join amino acids into the chain."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1300' AND answer = 3;
UPDATE questions SET why = 'Defensive proteins help the body fight infection and prevent injury. Antibodies are defensive proteins: each one recognises and binds tightly to a specific antigen, such as a protein on the surface of a virus or bacterium, marking it for destruction.', wrong = '{"0": "Storage proteins hold nutrients for later use, such as ferritin storing iron.", "1": "Contractile proteins, such as actin and myosin, make muscles contract.", "3": "Structural proteins, such as keratin and collagen, give shape and support to the body."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1301' AND answer = 2;
UPDATE questions SET why = 'Hormonal proteins act as chemical messengers that control body processes such as growth and metabolism. Insulin, made by the pancreas, is a hormonal protein: it signals cells to take up glucose from the blood, lowering blood glucose.', wrong = '{"1": "Transport proteins carry substances around the body, such as haemoglobin carrying oxygen.", "2": "Contractile proteins, actin and myosin, produce muscle movement.", "3": "Storage proteins, such as ferritin, store nutrients like iron."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-1302' AND answer = 0;
UPDATE questions SET why = 'In 1886 Eugen Goldstein used a discharge tube with holes in its cathode. He saw glowing rays passing through the holes in the direction opposite to the cathode rays and called them canal rays. They were later shown to be positively charged, so they are also called positive rays.', wrong = '{"0": "J. J. Thomson measured the e/m of cathode rays and later studied positive rays, but he did not first observe them.", "2": "Rutherford proposed the nuclear model of the atom from his gold-foil experiment. He did not discover canal rays.", "3": "James Chadwick discovered the neutron in 1932, long after canal rays were observed."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6001' AND answer = 1;
UPDATE questions SET why = 'Fast cathode-ray electrons collide with gas atoms or molecules in the tube and knock electrons out of them. This leaves positive ions, which are attracted towards the negative cathode. Some pass through the holes in the cathode and appear as positive rays.', wrong = '{"1": "The positive ions come from the gas in the tube, not from the anode.", "2": "The cathode metal does not release protons. The positive particles come from the gas, so they change with the gas used.", "3": "No nuclear decay happens in a discharge tube. The ions form by collisions that remove electrons."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6002' AND answer = 0;
UPDATE questions SET why = 'For positive rays, e/m depends on the mass of the ion formed from the gas. Hydrogen gives the lightest positive ion, H⁺, which has the largest e/m of all. This particle, with the highest e/m among positive rays, was identified as the proton.', wrong = '{"0": "He⁺ is about four times heavier than H⁺ with the same charge, so its e/m is smaller.", "1": "Ne⁺ is about twenty times heavier than H⁺, so its e/m is much smaller.", "2": "Oxygen ions are much heavier than H⁺, so their e/m is far smaller."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6003' AND answer = 3;
UPDATE questions SET why = 'Cathode rays are always electrons, so their e/m is the same whatever gas is in the tube. Positive rays are ions formed from the gas itself, and different gases give ions of different masses. So the e/m of positive rays depends on the gas used.', wrong = '{"0": "Both cathode rays and positive rays travel in straight lines, so this is a shared property.", "1": "Both are deflected by electric and magnetic fields, though in opposite directions because their charges differ.", "3": "Both consist of material particles with mass: electrons in cathode rays and ions in positive rays."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6004' AND answer = 2;
UPDATE questions SET why = 'Positive rays carry positive charge, so in an electric field they bend towards the negative plate, the opposite way to cathode rays. Their particles are positive ions, at least 1836 times heavier than electrons, so for the same field they are deflected by a much smaller amount.', wrong = '{"0": "Bending towards the positive plate is what negatively charged cathode rays do, and the heavy ions bend less, not more.", "2": "The direction is right, but the ions are far heavier than electrons, so they bend much less, not the same amount.", "3": "Positive rays are made of charged ions, so they are deflected. Only neutral particles pass straight through."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6005' AND answer = 1;
UPDATE questions SET why = 'A proton has a mass of about 1.6726 × 10⁻²⁷ kg and an electron about 9.11 × 10⁻³¹ kg. Dividing, (1.6726 × 10⁻²⁷) ÷ (9.11 × 10⁻³¹) ≈ 1836. So a proton is about 1836 times heavier than an electron.', wrong = '{"1": "1/1836 is the ratio turned upside down. That is the electron''s mass relative to the proton.", "2": "18.36 is a hundred times too small. The powers of ten have been handled wrongly.", "3": "183.6 is still ten times too small. The correct ratio is about 1836."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6006' AND answer = 0;
UPDATE questions SET why = 'Each series in the hydrogen spectrum is named after the level the electron falls to. Lines in the visible region, the Balmer series, come from electrons falling from higher orbits to n = 2. Falls to n = 1 give the ultraviolet Lyman series, and to n = 3 the infrared Paschen series.', wrong = '{"0": "Falls to n = 1 release more energy and give the Lyman series in the ultraviolet region.", "1": "Falls to n = 3 release less energy and give the Paschen series in the infrared region.", "2": "Falls to n = 4 give the Brackett series, which lies further into the infrared."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6007' AND answer = 3;
UPDATE questions SET why = 'Using Eₙ = −13.6/n² eV with n = 2: E₂ = −13.6/2² = −13.6/4 = −3.4 eV. The energy is less negative than in the first orbit, because the electron is further from the nucleus and less tightly bound.', wrong = '{"0": "−13.6 eV is the energy of the first orbit, where n = 1.", "1": "−6.8 eV comes from dividing by n (2) instead of n² (4).", "3": "−1.51 eV is the energy of the third orbit, −13.6/3² = −13.6/9."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6008' AND answer = 2;
UPDATE questions SET why = 'The radius of the n-th Bohr orbit is rₙ = 0.529 n² Å. For the third orbit, r₃ = 0.529 × 3² = 0.529 × 9 = 4.761 ≈ 4.76 Å. The radius grows with the square of n, so orbits spread out quickly.', wrong = '{"0": "1.59 Å comes from multiplying by n (3) instead of n² (9).", "2": "2.12 Å is the radius of the second orbit, 0.529 × 2² = 0.529 × 4.", "3": "0.176 Å comes from dividing 0.529 by 3 instead of multiplying by 3²."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6009' AND answer = 1;
UPDATE questions SET why = 'An electron in an atom can have only certain fixed (quantised) energies. When it falls from one allowed level to a lower one, it emits a photon whose energy equals the exact gap, ΔE = hν. Each jump gives one definite frequency, so the spectrum is a set of sharp lines.', wrong = '{"1": "Atoms with many electrons also give line spectra. The cause is quantised energy levels, not having one electron.", "2": "Hydrogen is colourless and does not absorb all visible light. The lines are emitted light.", "3": "An electron spiralling into the nucleus, as in the classical picture, would give a continuous spectrum, which is not seen."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6010' AND answer = 0;
UPDATE questions SET why = 'Kinetic molecular theory assumes that ideal gas molecules have no attractive or repulsive forces between them. So "gas molecules attract each other strongly" is not a postulate. Real gases do attract weakly, which is one reason they deviate from ideal behaviour.', wrong = '{"0": "This is a postulate: gas molecules move constantly and randomly in straight lines between collisions.", "1": "This is a postulate: collisions are perfectly elastic, so no kinetic energy is lost overall.", "2": "This is a postulate: the molecules'' own volume is tiny compared with the container''s volume."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6011' AND answer = 3;
UPDATE questions SET why = 'Kinetic theory shows that the average kinetic energy of gas molecules is (3/2)kT, where T is the absolute (Kelvin) temperature. So average kinetic energy is directly proportional to absolute temperature: doubling T in kelvin doubles it.', wrong = '{"0": "At 0 °C molecules still move; doubling a Celsius temperature does not double kinetic energy. Only the Kelvin scale works.", "1": "At the same temperature all gases have the same average kinetic energy, whatever their molar mass.", "3": "Changing the volume at constant temperature does not change the average kinetic energy."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6012' AND answer = 2;
UPDATE questions SET why = 'Gas molecules move rapidly and keep striking the walls of the container. Each collision changes a molecule''s momentum and pushes on the wall. The total force of countless collisions per unit area of wall is the pressure of the gas.', wrong = '{"0": "Attractions between molecules slightly reduce the pressure of a real gas. They are not its cause.", "2": "The weight of gas molecules is negligible, and gas pressure acts equally on all walls, not just downwards.", "3": "Kinetic theory treats the molecules'' own volume as negligible, so it is not the source of pressure."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6013' AND answer = 1;
UPDATE questions SET why = 'Average kinetic energy depends only on temperature, so H₂ and O₂ at the same temperature have the same average kinetic energy. Since KE = ½mv² is equal, the lighter H₂ molecules (2 g/mol) must move faster than the heavier O₂ molecules (32 g/mol).', wrong = '{"1": "Average kinetic energy depends only on temperature, not on molar mass, so O₂ does not have more.", "2": "With equal kinetic energies but different masses, the speeds cannot be equal. Lighter H₂ moves faster.", "3": "H₂ does move faster, but its average kinetic energy is the same as O₂''s at the same temperature."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6014' AND answer = 0;
UPDATE questions SET why = 'Boyle''s law at constant temperature: P₁V₁ = P₂V₂. So P₂ = P₁V₁ ÷ V₂ = (1.0 atm × 2.0 dm³) ÷ 0.50 dm³ = 4.0 atm. The volume falls to a quarter, so the pressure rises four times.', wrong = '{"0": "0.25 atm comes from P₁ × V₂ ÷ V₁, using the volume ratio upside down. Compressing a gas raises its pressure.", "1": "2.0 atm would match halving the volume. Here the volume falls to one quarter, so the pressure rises fourfold.", "2": "At constant temperature, pressure must change when volume changes, so it cannot stay at 1.0 atm."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6015' AND answer = 3;
UPDATE questions SET why = 'By Boyle''s law, P = k/V, so P is directly proportional to 1/V. A graph of P against 1/V is therefore a straight line through the origin, with slope k.', wrong = '{"0": "P against V is a curve (a hyperbola), since P falls as V rises.", "1": "PV is constant, so PV against P is a horizontal straight line, not a line through the origin.", "3": "V against T at constant pressure is Charles''s law, not a Boyle''s law graph."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6016' AND answer = 2;
UPDATE questions SET why = 'For a fixed amount of gas, PV = nRT, so the constant k in Boyle''s law equals nRT. It depends only on temperature: raising the temperature increases k. On a graph, this gives a new P–V curve (isotherm) further from the axes.', wrong = '{"0": "Raising the pressure at constant temperature just lowers V. The product PV stays the same.", "2": "Lowering the volume raises P at constant temperature, but PV stays the same.", "3": "Slow compression keeps the temperature constant, so PV, and therefore k, stays the same."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6017' AND answer = 1;
UPDATE questions SET why = 'Charles''s law, V₁/T₁ = V₂/T₂, needs Kelvin temperatures. T₁ = 27 + 273 = 300 K and T₂ = 127 + 273 = 400 K. V₂ = 300 cm³ × 400/300 = 400 cm³. The volume grows by one-third because the absolute temperature does.', wrong = '{"1": "1411 cm³ comes from using Celsius values, 300 × 127/27. Gas law calculations must use kelvin.", "2": "225 cm³ comes from the inverted ratio, 300 × 300/400. Heating a gas at constant pressure expands it.", "3": "600 cm³ would need the absolute temperature to double, to 600 K. It only rises from 300 K to 400 K."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6018' AND answer = 0;
UPDATE questions SET why = 'At constant pressure, a gas expands by 1/273 of its volume at 0 °C for every 1 °C rise. 273 cm³ gains 1 cm³ per degree, so 10 °C adds 10 cm³: 283 cm³. In kelvin, V₂ = 273 × 283/273 = 283 cm³.', wrong = '{"0": "263 cm³ is a decrease, but heating a gas at constant pressure makes it expand.", "1": "At constant pressure the volume changes with temperature, so it cannot stay at 273 cm³.", "2": "2730 cm³ multiplies the volume by 10, as if V were proportional to the Celsius temperature."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6019' AND answer = 3;
UPDATE questions SET why = 'Absolute zero is the zero of the Kelvin scale: 0 K = −273.15 °C, often rounded to −273 °C. A kelvin and a Celsius degree are the same size, so T(K) = t(°C) + 273.15.', wrong = '{"0": "−100 °C has no special meaning; it is 173 K, well above absolute zero.", "1": "0 °C is the freezing point of water, which is 273.15 K, not absolute zero.", "3": "−373.15 °C is 100 degrees below absolute zero, which is impossible."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6020' AND answer = 2;
UPDATE questions SET why = 'Extending the volume–temperature line of a gas meets V = 0 at −273.15 °C, absolute zero. At this temperature molecular motion would be at its minimum. It is the lowest possible temperature; it can be approached very closely but has never actually been reached.', wrong = '{"0": "At absolute zero molecular motion is at its minimum, not its fastest.", "2": "The graph predicts that an ideal gas''s volume would become zero, not double.", "3": "Liquid nitrogen boils at about −196 °C (77 K), far above absolute zero."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6021' AND answer = 1;
UPDATE questions SET why = 'The Kelvin and Celsius scales have degrees of the same size, but 0 K is 273 degrees below 0 °C. So to convert, add 273: T(K) = t(°C) + 273. Here −23 °C = −23 + 273 = 250 K.', wrong = '{"1": "−296 K comes from subtracting 273. Kelvin temperatures are never negative.", "2": "23 K drops the minus sign and forgets to add 273. It would be far colder than −23 °C.", "3": "296 K comes from adding +23 instead of −23 to 273."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6022' AND answer = 0;
UPDATE questions SET why = 'Charles''s law treats a gas as ideal, with molecules that take up no space and do not attract each other. Real molecules do occupy space and attract one another, so every real gas turns into a liquid or solid before reaching absolute zero. It never shrinks to zero volume.', wrong = '{"0": "On cooling at constant pressure, gases contract, not expand.", "1": "Real gas molecules do have mass. The reason is that they condense before reaching 0 K.", "2": "Charles''s law works at constant pressure, so the pressure does not become infinite."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6023' AND answer = 3;
UPDATE questions SET why = 'R has different values in different units: 8.314 J K⁻¹ mol⁻¹, 0.0821 dm³ atm K⁻¹ mol⁻¹, 1.987 cal K⁻¹ mol⁻¹ and 62.4 dm³ mmHg K⁻¹ mol⁻¹. The number 62.4 belongs with mmHg (torr), not atm, so 62.4 dm³ atm K⁻¹ mol⁻¹ is wrong.', wrong = '{"0": "8.314 J K⁻¹ mol⁻¹ is the SI value of R, so it is correct.", "1": "0.0821 dm³ atm K⁻¹ mol⁻¹ is the correct value of R when pressure is in atm.", "3": "1.987 cal K⁻¹ mol⁻¹ is correct: 8.314 J ÷ 4.184 J per cal ≈ 1.987 cal."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6024' AND answer = 2;
UPDATE questions SET why = 'Helium is monatomic with molar mass 4 g/mol, so 4.0 g is 4.0 ÷ 4 = 1 mol. By Avogadro''s law, 1 mol of any ideal gas occupies 22.4 dm³ at STP. So 4.0 g of helium occupies 22.4 dm³.', wrong = '{"0": "5.6 dm³ is the volume of 0.25 mol, which would be only 1.0 g of helium.", "2": "11.2 dm³ treats helium as diatomic, He₂ (8 g/mol), giving 0.5 mol. Helium exists as single atoms.", "3": "89.6 dm³ is 22.4 × 4, multiplying by the mass in grams instead of using 1 mol."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6025' AND answer = 1;
UPDATE questions SET why = 'From PV = nRT, n = PV/RT = (2.0 atm × 24.63 dm³) ÷ (0.0821 × 300 K) = 49.26 ÷ 24.63 = 2.0 mol. Note that RT = 24.63, the same number as the volume, which makes the arithmetic easy.', wrong = '{"1": "0.50 mol comes from dividing by the pressure instead of multiplying: 24.63 ÷ (24.63 × 2.0).", "2": "1.0 mol ignores the 2.0 atm pressure, as if P were 1 atm.", "3": "4.0 mol is twice the correct answer, as if the pressure were 4.0 atm."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6026' AND answer = 0;
UPDATE questions SET why = 'Kinetic theory assumes negligible molecular volume and no attractions. At low pressure the molecules are far apart, so their own volume hardly matters. At high temperature they move fast enough that attractions have little effect. So real gases behave most ideally at low pressure and high temperature.', wrong = '{"0": "High pressure and low temperature cause the largest deviations; these are the conditions used to liquefy gases.", "1": "High pressure crowds the molecules together, so their own volume becomes important.", "2": "At low temperature molecules move slowly, so attractions between them have a bigger effect."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6027' AND answer = 3;
UPDATE questions SET why = 'Van der Waals pointed out two faulty assumptions. First, real molecules do have volume, which matters at high pressure. Second, real molecules do attract each other, which matters at low temperature. He corrected both in his equation for real gases.', wrong = '{"0": "Random motion and elastic collisions still hold reasonably well for real gases. They are not the faulty assumptions.", "1": "Kinetic theory does not assume equal speeds; molecules have a range of speeds.", "3": "Obeying Newton''s laws and having kinetic energy are true of real molecules too."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6028' AND answer = 2;
UPDATE questions SET why = 'Helium atoms are very small, non-polar and have only two electrons, so London forces between them are extremely weak. With almost no attraction and tiny size, helium behaves very nearly ideally. Polar gases such as NH₃, SO₂ and H₂O attract each other strongly.', wrong = '{"0": "NH₃ is polar and forms hydrogen bonds, so it deviates strongly from ideal behaviour and liquefies easily.", "2": "SO₂ is polar with strong dipole attractions, so it is easily liquefied and far from ideal.", "3": "Water molecules form strong hydrogen bonds, so water vapour deviates greatly from ideal behaviour."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6029' AND answer = 1;
UPDATE questions SET why = 'When water is cooled, it contracts like most liquids until about 4 °C. Below 4 °C, hydrogen bonds start to hold the molecules in a more open arrangement, so the water expands again. Its volume is smallest, and its density greatest, at about 4 °C.', wrong = '{"1": "At 0 °C liquid water has already begun to expand, so it is less dense than at 4 °C. Ice is less dense still.", "2": "At 25 °C the molecules move more and spread out, so water is less dense than at 4 °C.", "3": "Near 100 °C water has expanded the most of all liquid water, so it is at its least dense."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6030' AND answer = 0;
UPDATE questions SET why = 'In ice, each water molecule is hydrogen bonded to four others in a tetrahedral pattern. This builds an open, cage-like hexagonal lattice with empty spaces. The molecules are further apart than in liquid water, so ice is about 9% less dense and floats.', wrong = '{"0": "Even clear, bubble-free ice floats, so trapped air is not the reason.", "1": "Ice and liquid water are both made of identical H₂O molecules of the same mass.", "2": "Water molecules attract each other through hydrogen bonds. They do not repel strongly."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6031' AND answer = 3;
UPDATE questions SET why = 'Water is densest at about 4 °C, so water at this temperature sinks to the bottom of the lake. Colder water stays on top and freezes first. The ice layer is a poor conductor of heat, so it insulates the water below, which stays liquid at about 4 °C and lets fish survive.', wrong = '{"0": "Ice is a poor conductor of heat. That is why it acts as an insulating blanket over the water.", "1": "The water under the ice is near 4 °C, nowhere near its boiling point.", "3": "Fish are cold-blooded and give out very little heat, far too little to melt a sheet of ice."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6032' AND answer = 2;
UPDATE questions SET why = 'In an ionic crystal, the number of anions that can pack around a cation (its coordination number) depends mainly on their relative sizes, the radius ratio r₊/r₋. A larger ratio lets more anions touch the cation. This, with the ion charges, fixes the crystal''s shape.', wrong = '{"0": "The colour of ions does not affect how they pack together in a crystal.", "2": "The melting point is a result of the crystal structure and bonding, not what decides the structure.", "3": "The number of neutrons is in the nucleus and does not change the size of an ion."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6033' AND answer = 1;
UPDATE questions SET why = 'Cs⁺ (radius about 167 pm) is much larger than Na⁺ (about 102 pm), while Cl⁻ is the same in both. The larger cation gives a higher radius ratio, r₊/r₋, so eight Cl⁻ ions can fit around each Cs⁺. This gives 8 : 8 coordination in CsCl instead of 6 : 6 in NaCl.', wrong = '{"1": "Both Na⁺ and Cs⁺ carry the same +1 charge, so charge is not the difference.", "2": "The chloride ion is essentially the same size in both crystals.", "3": "CsCl is an ionic crystal made of Cs⁺ and Cl⁻ ions, not separate molecules."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6034' AND answer = 0;
UPDATE questions SET why = 'A molecular solid is made of separate molecules held together by weak intermolecular forces. Solid iodine consists of I₂ molecules held by weak London forces, so it is soft, sublimes easily on gentle warming and does not conduct electricity.', wrong = '{"0": "Sodium chloride is an ionic solid, made of Na⁺ and Cl⁻ ions held by strong ionic bonds.", "1": "Diamond is a covalent network solid in which every carbon is bonded to four others.", "2": "Copper is a metallic solid, with positive ions in a sea of delocalised electrons."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6035' AND answer = 3;
UPDATE questions SET why = 'In a molecular solid, the atoms within each molecule are held by strong covalent bonds, but the molecules are held to each other only by weak intermolecular forces. Melting overcomes just these weak forces, which needs little energy. Ionic solids need strong attractions between ions to be broken.', wrong = '{"0": "Free (delocalised) electrons are a feature of metals, not molecular solids.", "1": "Molecules are neutral. Large charges on particles are found in ionic solids, which melt at high temperatures.", "3": "Molecular solids such as ice and iodine are crystalline and do have definite shapes."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6036' AND answer = 2;
UPDATE questions SET why = 'A crystal lattice is a regular three-dimensional pattern of points that represent the particles. The unit cell is the smallest repeating block of this pattern. Stacking unit cells side by side in all three directions builds the entire lattice.', wrong = '{"0": "A lattice point is a single position occupied by a particle, not a repeating block.", "2": "A crystal face is a flat outer surface of the crystal, not its repeating unit.", "3": "Isomorphs are different substances that have the same crystal form, such as NaNO₃ and CaCO₃."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6037' AND answer = 1;
UPDATE questions SET why = 'In a crystalline solid the particles are arranged in a regular, repeating pattern, so all the forces holding them are similar. They all break at the same temperature, giving a sharp, definite melting point. Amorphous solids such as glass have no regular order and soften over a range.', wrong = '{"1": "Hardness does not prove a regular structure. Glass is hard but amorphous.", "2": "Both crystalline and amorphous solids, such as quartz and glass, can be transparent.", "3": "Gradual softening over a temperature range is typical of amorphous solids, not crystalline ones."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6038' AND answer = 0;
UPDATE questions SET why = 'By Le Chatelier''s principle, a system responds to a change by opposing it. Raising the pressure favours the side with fewer moles of gas. Here 1 + 3 = 4 mol of gas on the left give 2 mol on the right, so the equilibrium shifts to the right and more NH₃ forms.', wrong = '{"0": "The left side has more gas moles (4), so higher pressure works against it, not towards it.", "1": "The two sides have different numbers of gas moles (4 and 2), so a pressure change does shift the equilibrium.", "2": "Kc changes only with temperature. Pressure shifts the position, not the value of Kc."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6039' AND answer = 3;
UPDATE questions SET why = 'A catalyst provides a pathway with lower activation energy for both the forward and the reverse reaction. Both rates increase by the same factor, so equilibrium is reached faster. The composition at equilibrium, and the value of K, stay the same.', wrong = '{"0": "The catalyst speeds up the forward and reverse reactions equally, so there is no shift towards products.", "1": "K depends only on temperature, so a catalyst does not change it.", "3": "Since both directions speed up equally, there is no shift towards reactants either."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6040' AND answer = 2;
UPDATE questions SET why = 'Pressure affects an equilibrium only when the two sides have different numbers of gas moles. In H₂(g) + I₂(g) ⇌ 2HI(g) there are 2 mol of gas on each side. Neither direction changes the total moles, so pressure has no effect on the position.', wrong = '{"0": "1 mol of N₂O₄ gives 2 mol of NO₂, so higher pressure shifts it to the left.", "2": "3 mol of gas (2SO₂ + O₂) give 2 mol of SO₃, so higher pressure shifts it to the right.", "3": "1 mol of PCl₅ gives 2 mol of gas, so higher pressure shifts it to the left."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6041' AND answer = 1;
UPDATE questions SET why = 'In an exothermic reaction, heat is given out, so it acts like a product. Raising the temperature adds heat, and the system opposes this by favouring the endothermic reverse reaction. The equilibrium shifts to the left, less product forms, and K becomes smaller.', wrong = '{"1": "Shifting right with a larger K is what happens when an endothermic reaction is heated.", "2": "K does change with temperature; temperature is the only factor that changes it.", "3": "A shift to the right would mean more product, which would increase K, not decrease it."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6042' AND answer = 0;
UPDATE questions SET why = 'Adding N₂ raises a reactant concentration. By Le Chatelier''s principle the system uses up some of the added N₂ by reacting it with H₂ to form more NH₃, so the position shifts right. Because the temperature is unchanged, Kc keeps the same value.', wrong = '{"0": "The shift to the right is correct, but changing a concentration does not change Kc. Only temperature does.", "1": "Adding a reactant favours the forward reaction, so the shift is to the right, not the left.", "2": "N₂ is part of this equilibrium, so adding more of it does disturb the system and cause a shift."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6043' AND answer = 3;
UPDATE questions SET why = 'The first law of thermodynamics is the law of conservation of energy. Energy cannot be created or destroyed, only changed from one form to another. For a system, ΔE = q + w, where q is heat absorbed by the system and w is work done on it.', wrong = '{"0": "Heat flowing on its own from a hot body to a cold body is a statement of the second law.", "1": "The entropy of the universe increasing in spontaneous changes is the second law.", "3": "Not all spontaneous reactions are exothermic; dissolving NH₄NO₃ is spontaneous but endothermic."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6044' AND answer = 2;
UPDATE questions SET why = 'Use ΔE = q + w. Heat absorbed by the system is positive, q = +50 kJ. Work done by the system on its surroundings is negative, w = −20 kJ. So ΔE = 50 − 20 = +30 kJ; the system gains 30 kJ of internal energy.', wrong = '{"0": "+70 kJ adds the work as if it were done on the system. Work done by the system must be subtracted.", "2": "−30 kJ has the sign reversed. The system gains more heat (50 kJ) than it loses as work (20 kJ), so ΔE is positive.", "3": "−70 kJ gets both signs wrong. Heat absorbed is positive and only the work is negative."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6045' AND answer = 1;
UPDATE questions SET why = 'Internal energy (E or U) is the total energy of all the particles in a system. It includes their kinetic energy (translational, rotational and vibrational motion) and their potential energy (in bonds and intermolecular attractions). Its absolute value cannot be measured, only changes, ΔE.', wrong = '{"1": "Kinetic energy is only part of it. The potential energy stored in bonds and attractions is also included.", "2": "Heat given out in a reaction is one way internal energy changes. It is not the internal energy itself.", "3": "Work done on the system is another way of changing internal energy, not the energy itself."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6046' AND answer = 0;
UPDATE questions SET why = 'Internal energy (E or U) is the total kinetic and potential energy of the particles in a system. Like every form of energy, its SI unit is the joule (J). For chemical changes, values are usually quoted per mole in kJ mol⁻¹.', wrong = '{"0": "The watt is the unit of power, the rate of energy transfer (1 W = 1 J s⁻¹). It is not a unit of energy itself.", "1": "The kelvin is the SI unit of temperature. Temperature affects internal energy but is not measured in the same unit.", "2": "J K⁻¹ is the unit of heat capacity (and of entropy). It tells how much energy is needed per kelvin of temperature rise."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6047' AND answer = 3;
UPDATE questions SET why = 'By the first law, ΔE = q + w, and the only work in most reactions is expansion work, w = −PΔV. In a sealed bomb calorimeter the volume cannot change, so ΔV = 0 and w = 0. The heat exchanged at constant volume therefore equals ΔE, written qᵥ = ΔE.', wrong = '{"0": "ΔH equals the heat exchanged at constant pressure (qₚ = ΔH), as in an open beaker. A bomb calorimeter works at constant volume instead.", "1": "Heat is still absorbed or released by the reaction. It is only the expansion work that becomes zero at constant volume.", "3": "PΔV is the expansion work term. At constant volume ΔV = 0, so PΔV is zero and cannot equal the heat change."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6048' AND answer = 2;
UPDATE questions SET why = 'ΔH and ΔE differ by ΔnRT, where Δn is moles of gaseous products minus moles of gaseous reactants. In H₂(g) + Cl₂(g) → 2HCl(g) there are 2 mol of gas on each side, so Δn = 2 − 2 = 0. Then ΔnRT = 0 and ΔH = ΔE.', wrong = '{"0": "Here Δn = 2 − (1 + 3) = −2. The gas volume shrinks, so ΔH is less than ΔE.", "2": "One mole of CO₂ gas is formed from solids only, so Δn = +1 and ΔH = ΔE + RT.", "3": "Water is a liquid here, so Δn = 0 − 3 = −3. Only gases count in Δn, so ΔH and ΔE differ."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6049' AND answer = 1;
UPDATE questions SET why = 'A state function depends only on the initial and final states of a system, not on how the change was carried out. The amount of work done depends on the path taken between the two states, so work is not a state function. Heat is also a path function for the same reason.', wrong = '{"1": "Internal energy is a state function. ΔE between two states is the same whatever route is followed.", "2": "Enthalpy is a state function. This is why Hess''s law works: ΔH is the same by any route.", "3": "Pressure describes the present condition of a system, like temperature and volume, so it is a state function."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6050' AND answer = 0;
UPDATE questions SET why = 'Mn has an oxidation number of +7 in MnO₄⁻ and +2 in Mn²⁺, so each Mn gains 7 − 2 = 5 electrons. The balanced half-equation is MnO₄⁻ + 8H⁺ + 5e⁻ → Mn²⁺ + 4H₂O. Charge check: −1 + 8 − 5 = +2 on the left, matching Mn²⁺ on the right.', wrong = '{"0": "Three electrons are gained when MnO₄⁻ (+7) is reduced to MnO₂ (+4), which happens in neutral or weakly alkaline solution, not in acid.", "1": "Two is the charge on the Mn²⁺ ion, not the number of electrons gained by Mn.", "2": "Seven is the oxidation number of Mn in MnO₄⁻. The electrons gained equal the change, 7 − 2 = 5."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6051' AND answer = 3;
UPDATE questions SET why = 'Seven O atoms on the left end up in 7 H₂O on the right, and 7 H₂O contain 14 H atoms, so 14 H⁺ are needed. Charge check: left side −2 + 14 − 6 = +6, right side 2 × (+3) = +6. So x = 14.', wrong = '{"0": "Seven H⁺ supply only 7 H atoms, but 7 H₂O need 14. Charge would also not balance (−2 + 7 − 6 = −1).", "1": "Six is the number of electrons in the half-equation, not the number of H⁺ ions.", "3": "Twelve H⁺ give only 12 H atoms for 14 needed, and the charge on the left would be +4, not +6."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6052' AND answer = 2;
UPDATE questions SET why = 'In the redox reaction, electrons lost must equal electrons gained. MnO₄⁻ gains 5 electrons (Mn +7 → +2), while each Fe²⁺ loses only 1 (Fe²⁺ → Fe³⁺ + e⁻). So 5 Fe²⁺ are needed per MnO₄⁻: MnO₄⁻ + 5Fe²⁺ + 8H⁺ → Mn²⁺ + 5Fe³⁺ + 4H₂O.', wrong = '{"0": "A 1 : 1 ratio would be right only if both species transferred the same number of electrons. Here it is 5 against 1.", "2": "Two Fe²⁺ would give only 2 electrons, but MnO₄⁻ needs 5. The electrons would not balance.", "3": "Eight is the number of H⁺ ions in the balanced equation, not the number of Fe²⁺ ions."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6053' AND answer = 1;
UPDATE questions SET why = 'The ionic character of a bond grows with the electronegativity difference between the two atoms. Fluorine is the most electronegative element (about 4.0 against 2.1 for H), so H–F has the largest difference, about 1.9. H–F is therefore the most polar of these bonds.', wrong = '{"1": "Iodine is the least electronegative halogen (about 2.5), so the H–I difference is only about 0.4. It is the least ionic of the four.", "2": "Bromine is about 2.8, so the H–Br difference is only about 0.7. This is much less than H–F.", "3": "Chlorine is about 3.0, so the H–Cl difference is about 0.9. That is polar, but less than half the H–F difference."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6054' AND answer = 0;
UPDATE questions SET why = 'When two different atoms share a pair of electrons, the more electronegative atom pulls the pair closer to itself. It gains a partial negative charge (δ−) and the other atom a partial positive charge (δ+). These partial charges give the covalent bond some ionic character.', wrong = '{"0": "Complete transfer of electrons forms ions and a purely ionic bond, not a covalent bond with partial ionic character.", "1": "Atoms with the same electronegativity share the pair equally, giving a non-polar bond with no ionic character.", "2": "A coordinate bond is about where the shared pair came from. It does not explain the partial charges, which come from electronegativity difference."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6055' AND answer = 3;
UPDATE questions SET why = 'Ionic character rises as the electronegativity difference grows. A difference of about 1.7 is taken as the point where a bond is roughly 50% ionic. Above this the bond is treated as mainly ionic, and below it as mainly covalent.', wrong = '{"0": "A difference below about 0.4 gives an almost non-polar covalent bond, with very little ionic character.", "1": "A difference of 1.0 gives a polar covalent bond, only about 20% ionic.", "3": "3.3 is larger than the biggest difference between any two elements (Cs and F differ by about 3.2), so it is not the 50% point."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6056' AND answer = 2;
UPDATE questions SET why = 'The chain has four carbons, so the parent is butene. The double bond lies between C2 and C3, and its locant is the lower number, 2. The IUPAC name is but-2-ene (also written 2-butene).', wrong = '{"0": "But-1-ene is CH₂=CH–CH₂–CH₃, with the double bond at the end of the chain between C1 and C2.", "2": "Butane, CH₃CH₂CH₂CH₃, is a saturated alkane with no double bond.", "3": "The ending \"-yne\" means a triple bond. This molecule has a C=C double bond, so it is an alkene."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6057' AND answer = 1;
UPDATE questions SET why = 'The longest chain that includes the double bond has three carbons, so the parent is propene. Numbering from the CH₂= end puts the double bond at C1 and the methyl group on C2. The name is 2-methylprop-1-ene (often shortened to 2-methylpropene).', wrong = '{"1": "But-1-ene is the straight-chain isomer, CH₂=CH–CH₂–CH₃. This molecule is branched.", "2": "The methyl group sits on C2, not C1. A methyl on C1 would simply lengthen the chain.", "3": "But-2-ene is the straight chain CH₃CH=CHCH₃, a different isomer of C₄H₈."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6058' AND answer = 0;
UPDATE questions SET why = 'The chain is numbered from the end nearer the double bond: C1=C2–C3–C4(CH₃)–C5. The double bond then starts at C1 and the methyl group is on C4. The name is 4-methylpent-1-ene.', wrong = '{"0": "This numbers from the wrong end. The double bond must get the lowest possible locant, which is 1, not 4.", "1": "The double bond is at the end of the chain, between C1 and C2, not between C2 and C3.", "2": "Pentene with five carbons can have the double bond at C1 or C2, so its position must be given in the name."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6059' AND answer = 3;
UPDATE questions SET why = 'Each carbon in ethene is sp² hybridised, giving three bonds in a flat triangle about 120° apart. The leftover p orbitals on the two carbons overlap sideways, above and below this plane, to form the π bond. This overlap locks both CH₂ groups in one plane, so all six atoms are coplanar.', wrong = '{"0": "A tetrahedral shape with 109.5° angles belongs to sp³ carbon, as in ethane.", "1": "A linear shape with 180° angles belongs to sp carbon, as in ethyne.", "3": "If the CH₂ planes were at right angles, the p orbitals could not overlap and the π bond would break."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6060' AND answer = 2;
UPDATE questions SET why = 'The π bond forms only while the two p orbitals stay parallel and overlap sideways. Twisting one carbon relative to the other would separate them and break the π bond, which costs a lot of energy. This lack of free rotation is why alkenes can show cis-trans (geometric) isomerism.', wrong = '{"0": "The σ bond is symmetric around the bond axis, so rotation does not break it. That is why ethane rotates freely.", "2": "Rotation alone does not change the hybridisation of the carbons. The problem is the loss of π overlap.", "3": "Rotation would break the π bond, so it is false that all bonds would stay intact."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6061' AND answer = 1;
UPDATE questions SET why = 'A double bond is one σ bond plus one π bond. The extra bond pulls the carbons closer (134 pm against 154 pm) and makes the bond stronger. But a π bond, formed by weaker sideways overlap, is weaker than a σ bond, so 614 kJ mol⁻¹ is less than 2 × 348 = 696 kJ mol⁻¹.', wrong = '{"1": "The data show the opposite: C=C is shorter (134 pm) and stronger (614 kJ mol⁻¹) than C–C.", "2": "Twice 348 is 696 kJ mol⁻¹, and 614 is less than that, so the double bond is not exactly twice as strong.", "3": "The bonds are not the same length: 154 − 134 = 20 pm, so C=C is clearly shorter."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6062' AND answer = 0;
UPDATE questions SET why = 'Sulphonation puts an –SO₃H group on the benzene ring: C₆H₆ + H₂SO₄ → C₆H₅SO₃H + H₂O. Fuming sulphuric acid (oleum), which contains dissolved SO₃, does this readily on warming. Plain concentrated H₂SO₄ also works but needs long heating.', wrong = '{"0": "A mixture of concentrated HNO₃ and H₂SO₄ is the nitrating mixture. It gives nitrobenzene, not benzenesulphonic acid.", "1": "Dilute H₂SO₄ does not sulphonate benzene. Heating a sulphonic acid with dilute acid actually removes the –SO₃H group.", "2": "SO₂ with water forms sulphurous acid, which is not a strong enough electrophile to substitute into benzene."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6063' AND answer = 3;
UPDATE questions SET why = 'In SO₃ the sulphur is bonded to three electronegative oxygens, so it carries a large partial positive charge. This electron-poor sulphur is attacked by the π electrons of the ring, making SO₃ the electrophile. In strongly acidic solution it may act in the protonated form HSO₃⁺.', wrong = '{"0": "NO₂⁺ (the nitronium ion) is the electrophile in nitration, not sulphonation.", "1": "HSO₄⁻ is a negative ion. It is formed in the reaction mixture but is not electron-seeking, so it cannot be the electrophile.", "3": "H₃O⁺ only carries protons. It does not deliver the –SO₃H group that substitutes into the ring."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6064' AND answer = 2;
UPDATE questions SET why = 'Sulphonation is reversible. Heating benzenesulphonic acid with steam or dilute acid removes the –SO₃H group and gives back benzene (desulphonation). Chemists use this to put –SO₃H on a position temporarily as a blocking group and remove it later.', wrong = '{"0": "A Lewis acid such as FeCl₃ or AlCl₃ is needed for halogenation and Friedel-Crafts reactions. Sulphonation needs only fuming or concentrated H₂SO₄.", "2": "Sulphonation is an electrophilic substitution. The aromatic ring is kept, just like in nitration and halogenation.", "3": "Cyclohexane comes from hydrogenating benzene with H₂ and a nickel catalyst, not from sulphonation."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6065' AND answer = 1;
UPDATE questions SET why = 'The methyl group pushes electrons into the ring, so it activates the ring and directs new groups to the ortho (2-) and para (4-) positions. Sulphonation of toluene therefore gives mainly o- and p-toluenesulphonic acids. At higher temperatures the para isomer is favoured.', wrong = '{"1": "Meta substitution is directed by electron-withdrawing groups such as –NO₂ or –COOH, not by an activating –CH₃ group.", "2": "Benzoic acid forms when the side chain of toluene is oxidised, for example by hot KMnO₄. Sulphonation does not oxidise the methyl group.", "3": "The methyl group stays on the ring. Sulphonation replaces a ring hydrogen, not the CH₃ group."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6066' AND answer = 0;
UPDATE questions SET why = 'AlCl₃ has an incomplete octet, so it is a Lewis acid (an electron-pair acceptor). It pulls Cl⁻ from CH₃Cl: CH₃Cl + AlCl₃ → CH₃⁺ + AlCl₄⁻. The CH₃⁺ electrophile attacks the ring, then AlCl₄⁻ takes the H⁺ away, giving toluene and HCl and regenerating AlCl₃.', wrong = '{"0": "AlCl₃ does not give electrons to anything, so it is not a reducing agent. It accepts an electron pair.", "1": "In Friedel-Crafts alkylation a methyl group, not chlorine, is added to the ring. Cl ends up in HCl.", "2": "No water is formed in this reaction. AlCl₃ must be anhydrous because water would react with it and destroy the catalyst."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6067' AND answer = 3;
UPDATE questions SET why = 'This is Friedel-Crafts acylation. AlCl₃ removes Cl⁻ from CH₃COCl to form the acylium ion CH₃CO⁺, which substitutes into the ring. The product is the ketone C₆H₅COCH₃, called phenylethanone (acetophenone), along with HCl.', wrong = '{"0": "Toluene (methylbenzene) is made by Friedel-Crafts methylation with CH₃Cl, not by acylation.", "1": "Benzoic acid, C₆H₅COOH, is made by oxidising a side chain such as in toluene. Acylation gives a ketone, not an acid.", "3": "Ethylbenzene comes from alkylation with chloroethane (C₂H₅Cl). An acyl chloride adds a C=O group to the ring."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6068' AND answer = 2;
UPDATE questions SET why = 'An alkyl group donates electrons to the ring, so the alkylated product is more reactive than benzene and reacts again, giving polyalkylation. An acyl group has a C=O that withdraws electrons, so the ketone product is less reactive than benzene. Further substitution is slow, and acylation stops after one group.', wrong = '{"0": "Acyl chlorides react readily with AlCl₃ to give acylium ions. Low reactivity is not why acylation stops.", "2": "AlCl₃ is regenerated at the end of each alkylation step, so it is not used up.", "3": "Both alkylation and acylation are electrophilic substitution reactions. The ring stays aromatic in each."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6069' AND answer = 1;
UPDATE questions SET why = 'The chain has four carbons with a C≡C triple bond between C2 and C3, so the parent is butyne with locant 2. In current IUPAC style the number goes just before the suffix: but-2-yne (also written 2-butyne).', wrong = '{"1": "But-1-yne is HC≡C–CH₂–CH₃, with the triple bond at the end of the chain.", "2": "The ending \"-ene\" means a double bond. This molecule has a triple bond, so it is an alkyne.", "3": "Writing the locant after the whole name (butyne-2) is not the IUPAC form. It is placed before the suffix: but-2-yne."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6070' AND answer = 0;
UPDATE questions SET why = 'The chain is numbered from the end nearer the triple bond: C1≡C2–C3(CH₃)–C4. The triple bond starts at C1 and the methyl group is on C3. The IUPAC name is 3-methylbut-1-yne.', wrong = '{"0": "This numbers from the wrong end. The triple bond must get the lowest locant, 1, not 3.", "1": "The triple bond is between C1 and C2, not starting at C2. The locant format is also not IUPAC style.", "2": "Isopentyne is an old common-style name, not an IUPAC name."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6071' AND answer = 3;
UPDATE questions SET why = 'An alkane has the formula CₙH₂ₙ₊₂. Each π bond removes two hydrogens, and a C≡C triple bond contains two π bonds, so an open-chain alkyne has four fewer hydrogens: CₙH₂ₙ₋₂. Examples are ethyne C₂H₂ and propyne C₃H₄.', wrong = '{"0": "CₙH₂ₙ₊₂ is the general formula of alkanes, which contain only single bonds.", "1": "CₙH₂ₙ fits alkenes, with one C=C bond, and cycloalkanes, which have two hydrogens fewer than alkanes, not four.", "3": "CₙHₙ happens to fit ethyne (C₂H₂) and benzene (C₆H₆), but not propyne (C₃H₄) or other alkynes."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6072' AND answer = 2;
UPDATE questions SET why = 'A strong base in alcohol removes HBr from neighbouring carbons (dehydrohalogenation). Doing this twice turns 1,2-dibromoethane into ethyne: BrCH₂CH₂Br → CH₂=CHBr → HC≡CH. The second elimination is harder, so excess alcoholic KOH with strong heating, or NaNH₂, is used.', wrong = '{"0": "In aqueous KOH, OH⁻ mainly replaces the Br atoms (substitution), giving ethane-1,2-diol rather than an alkyne.", "2": "Zinc dust removes both Br atoms from neighbouring carbons as ZnBr₂, giving ethene, not ethyne.", "3": "H₂ with nickel adds hydrogen to multiple bonds. It does not remove HBr to create a triple bond."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6073' AND answer = 1;
UPDATE questions SET why = 'A triple bond forms when two molecules of HBr are removed from a dihalide with Br on neighbouring carbons (vicinal) or on the same carbon (geminal). 1,2-Dibromopropane loses 2HBr: CH₃CHBrCH₂Br → CH₃C≡CH, which is propyne.', wrong = '{"1": "1-Bromopropane has only one Br, so it can lose only one HBr, giving propene, not propyne.", "2": "2-Bromopropane also has a single Br. One elimination gives propene, with a double bond only.", "3": "Propan-1-ol has no halogen to eliminate. With hot concentrated acid it dehydrates to propene, not propyne."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6074' AND answer = 0;
UPDATE questions SET why = 'Calcium carbide contains the carbide ion C₂²⁻, which takes two protons from water to become ethyne: CaC₂ + 2H₂O → C₂H₂ + Ca(OH)₂. The reaction is quick at room temperature, so it is a convenient lab and industrial source of ethyne.', wrong = '{"0": "Calcium carbonate does not give a hydrocarbon. With acid it releases CO₂.", "1": "Calcium oxide reacts with water only to form calcium hydroxide (slaking). No gas is produced.", "2": "Aluminium carbide, Al₄C₃, contains C⁴⁻ and reacts with water to give methane, CH₄, not ethyne."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6075' AND answer = 3;
UPDATE questions SET why = 'An sp orbital is 50% s character, more than sp² (33%) or sp³ (25%). Electrons in s-rich orbitals stay closer to the nucleus, so the sp carbon is relatively electronegative. When ≡C–H loses H⁺, the lone pair in the sp orbital is held tightly, so the acetylide ion is stable enough for the H to be weakly acidic.', wrong = '{"0": "The ≡C–H bond is actually the shortest C–H bond, because of the high s character. Bond length is not the reason.", "1": "Ethyne contains only carbon and hydrogen. There is no –OH group.", "3": "If the triple bond pushed electrons onto hydrogen, H⁺ would be harder to lose, making it less acidic, not more."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6076' AND answer = 2;
UPDATE questions SET why = 'Only a hydrogen attached to a triply bonded carbon (≡C–H) is acidic enough to be removed by NaNH₂. Propyne is a terminal alkyne: CH₃C≡CH + NaNH₂ → CH₃C≡C⁻Na⁺ + NH₃. The product is a sodium acetylide salt.', wrong = '{"0": "But-2-yne, CH₃C≡CCH₃, has its triple bond in the middle of the chain, so no hydrogen is on a triply bonded carbon.", "2": "Ethene''s hydrogens are on sp² carbons, which are far less acidic. NaNH₂ cannot remove them.", "3": "Ethane''s hydrogens are on sp³ carbons, the least acidic of all. It does not react with NaNH₂."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6077' AND answer = 1;
UPDATE questions SET why = 'Ammoniacal silver nitrate reacts only with terminal alkynes, which have an acidic ≡C–H. But-1-yne gives a white precipitate of silver butynide, while but-2-yne, with no hydrogen on its triply bonded carbons, gives no precipitate. So this reagent tells them apart.', wrong = '{"1": "Both compounds have a triple bond, so both add bromine and decolourise bromine water. No difference is seen.", "2": "Both are hydrogenated by H₂ and Ni to the same product, butane, so this cannot distinguish them.", "3": "Both have π bonds that are oxidised by alkaline KMnO₄, so both decolourise it."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6078' AND answer = 0;
UPDATE questions SET why = 'The acidity of a C–H bond depends on the s character of the carbon''s orbital. More s character holds the electron pair closer, stabilising the anion left after H⁺ is lost. sp (50%) > sp² (33%) > sp³ (25%), so ethyne > ethene > ethane.', wrong = '{"0": "This is exactly the reverse order. Ethane, with sp³ carbon, is the least acidic.", "1": "Ethyne, with sp carbon and 50% s character, is the most acidic, not ethene.", "2": "Their acidities differ very widely, by many powers of ten, because of the different hybridisation of carbon."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6079' AND answer = 3;
UPDATE questions SET why = 'Lindlar''s catalyst is palladium that has been partly poisoned, so it adds only one molecule of H₂ and stops at the alkene. Both H atoms are delivered from the catalyst surface to the same side of the triple bond (syn addition). But-2-yne therefore gives cis-but-2-ene.', wrong = '{"0": "Butane would form with a fully active catalyst such as Ni or Pt and excess H₂, which reduces the alkyne all the way.", "1": "The trans alkene is obtained by reducing the alkyne with sodium in liquid ammonia, not with Lindlar''s catalyst.", "3": "Hydrogenation does not move the multiple bond. The C=C stays between C2 and C3."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6080' AND answer = 2;
UPDATE questions SET why = 'With an active nickel catalyst and excess hydrogen, the triple bond takes up two molecules of H₂ in turn. Ethene forms first but is hydrogenated again straight away: HC≡CH + 2H₂ → CH₃CH₃. The final product is ethane.', wrong = '{"0": "Ethene is only an intermediate here. Stopping at the alkene needs a poisoned catalyst such as Lindlar''s catalyst.", "2": "Benzene forms when ethyne is passed through a red-hot iron tube, joining three molecules (trimerisation), not with H₂.", "3": "Ethanol contains oxygen, and no source of oxygen is present in this reaction."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6081' AND answer = 1;
UPDATE questions SET why = 'Markovnikov''s rule: H adds to the carbon that already has more hydrogens. The first HBr gives 2-bromopropene, CH₃CBr=CH₂. The second HBr again puts Br on C2, giving CH₃CBr₂CH₃, 2,2-dibromopropane (a geminal dihalide, both Br on one carbon).', wrong = '{"1": "Putting both Br atoms on C1 would be anti-Markovnikov addition, which needs special conditions such as peroxides.", "2": "1,2-Dibromopropane is made by adding Br₂ to propene, not by adding two HBr to propyne.", "3": "C3 is a CH₃ group not involved in the triple bond, so addition cannot place Br there."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6082' AND answer = 0;
UPDATE questions SET why = 'Water adds across the triple bond with Hg²⁺ and dilute acid as catalyst, giving the enol CH₂=CHOH, called vinyl alcohol (ethenol). An enol, with –OH on a double-bonded carbon, is unstable and quickly rearranges (tautomerises) to the aldehyde CH₃CHO, ethanal.', wrong = '{"0": "Ethanol, CH₃CH₂OH, is saturated. Hydration of ethyne adds only one water molecule and leaves a C=C, so ethanol does not form.", "1": "Ethylene glycol (ethane-1,2-diol) is made by oxidising ethene, for example with cold dilute KMnO₄.", "2": "Acetic acid would form only if the ethanal were oxidised further. It is not the first product."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6083' AND answer = 3;
UPDATE questions SET why = 'Alkynes do undergo electrophilic addition, but usually a little more slowly than alkenes. The sp carbons hold their π electrons more tightly, and the vinyl-type carbocation formed is less stable. Benzene usually substitutes instead of adding, because addition would destroy its stable delocalised ring.', wrong = '{"0": "Alkanes have no π bonds. They react with bromine only by slow free-radical substitution in UV light, so they are less reactive.", "1": "Benzene does not decolourise bromine water, while ethene does so quickly. The order stated is reversed.", "3": "Alkynes readily add H₂, halogens, hydrogen halides and water across the triple bond."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6084' AND answer = 2;
UPDATE questions SET why = 'The longest chain has four carbons (butane). Numbering from the end nearer the bromine puts Br on C2 rather than C3, because the lowest locant is used. The IUPAC name is 2-bromobutane.', wrong = '{"0": "In 1-bromobutane the Br is on an end carbon, CH₃CH₂CH₂CH₂Br. Here it is on the second carbon.", "2": "3-Bromobutane numbers from the wrong end. The same compound must be called 2-bromobutane to give the lowest locant.", "3": "Sec-butyl bromide is a correct common name for this compound, but it is not the IUPAC name asked for."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6085' AND answer = 1;
UPDATE questions SET why = 'The longest chain through the C–Cl carbon has three carbons (propane), with both Cl and a CH₃ on C2: 2-chloro-2-methylpropane. The carbon carrying Cl is bonded to three other carbons, so it is a tertiary (3°) alkyl halide.', wrong = '{"1": "1-Chlorobutane is CH₃CH₂CH₂CH₂Cl, a straight chain. (CH₃)₃CCl has no straight four-carbon chain.", "2": "2-Chlorobutane is CH₃CHClCH₂CH₃, where the C–Cl carbon is bonded to two carbons, making it secondary.", "3": "1-Chloro-2-methylpropane is (CH₃)₂CHCH₂Cl, a primary isomer. Here Cl sits on the central carbon."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6086' AND answer = 0;
UPDATE questions SET why = 'Number the chain to give the lowest set of locants. From the Br end the substituents are at {1,3}, which beats {2,4} from the other end. Prefixes are then written in alphabetical order, bromo before chloro: 1-bromo-3-chlorobutane.', wrong = '{"0": "The locant set {2,4} comes from numbering the wrong way. The lower set {1,3} must be used.", "1": "The locants are right, but the prefixes must be listed alphabetically, so bromo comes before chloro.", "2": "This swaps the positions. Br is on C1 and Cl is on C3, not the other way round."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6087' AND answer = 3;
UPDATE questions SET why = 'The molecule has four carbons with the C=O group in the middle of the chain, so it is a ketone. Ketones end in "-one", and the C=O is on C2. The name is butan-2-one (butanone), also called methyl ethyl ketone.', wrong = '{"0": "Butanal is an aldehyde, CH₃CH₂CH₂CHO, with the C=O at the end of the chain bonded to an H.", "1": "Propanone, CH₃COCH₃, has only three carbons. This molecule has four.", "3": "The ending \"-ol\" means an alcohol with an –OH group. This molecule has a C=O group instead."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6088' AND answer = 2;
UPDATE questions SET why = 'In an aldehyde the CHO carbon is always C1. The chain through it has three carbons (propanal), and a methyl group branches from C2. The name is 2-methylpropanal.', wrong = '{"0": "Butanal, CH₃CH₂CH₂CHO, is the straight-chain isomer. This compound is branched.", "2": "A ketone needs carbon on both sides of the C=O. Here the C=O is at the chain end with an H, so it is an aldehyde.", "3": "Isobutanol is the name of an alcohol, (CH₃)₂CHCH₂OH, with –OH, not –CHO."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6089' AND answer = 1;
UPDATE questions SET why = 'In a carboxylic acid the COOH carbon is C1. The chain here has three carbons (propanoic acid), and Cl is on the next carbon, C2. The name is 2-chloropropanoic acid.', wrong = '{"1": "In 3-chloropropanoic acid, Cl is on the far CH₂ group: ClCH₂CH₂COOH. Here Cl is on C2.", "2": "Ethanoic acid has two carbons. This molecule has three, counting the COOH carbon.", "3": "This is not an IUPAC name. \"Butyric\" also implies four carbons, but the chain here has three."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6090' AND answer = 0;
UPDATE questions SET why = 'Acid hydrolysis turns a –C≡N group into –COOH: CH₃CN + 2H₂O + H⁺ → CH₃COOH + NH₄⁺. The nitrile carbon becomes the COOH carbon, so the acid keeps the same number of carbons. Two-carbon ethanenitrile gives two-carbon ethanoic acid.', wrong = '{"0": "HCN has only one carbon, so its hydrolysis gives methanoic acid, HCOOH.", "1": "Propanenitrile, C₂H₅CN, has three carbons, so it gives propanoic acid, C₂H₅COOH.", "2": "Reducing an amide gives an amine, not a carboxylic acid. Amides give acids by hydrolysis."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6091' AND answer = 3;
UPDATE questions SET why = 'The CH₃ group of the Grignard reagent attacks the carbon of CO₂, forming CH₃COOMgBr. Acid hydrolysis then gives CH₃COOH, ethanoic acid. The method adds one carbon (from CO₂) to the alkyl group.', wrong = '{"0": "Methanol would come from methanal reacting with a Grignard reagent or from reduction, not from CO₂.", "1": "Methanoic acid has only one carbon. Here CO₂ supplies a carbon that joins the CH₃, giving two carbons.", "3": "Propanone has three carbons and is a ketone. Grignard reagents with CO₂ give carboxylic acids."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6092' AND answer = 2;
UPDATE questions SET why = 'The body can build some amino acids from others, but essential amino acids cannot be made in the body at all. About nine, such as lysine, leucine and valine, must therefore come from proteins in food.', wrong = '{"0": "Essential amino acids are found in both plant and animal proteins. Animal proteins usually contain all of them.", "2": "Adults need essential amino acids too, for repairing tissues and making enzymes and hormones.", "3": "Only a few amino acids, such as cysteine and methionine, contain sulphur. That is not what \"essential\" means."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6093' AND answer = 1;
UPDATE questions SET why = 'Kwashiorkor is caused by a severe lack of protein in the diet, even when some energy is supplied. It often appears after weaning onto starchy food. Low blood protein lets fluid collect in tissues, which causes the swollen belly and limbs.', wrong = '{"1": "A lack of vitamin C causes scurvy, with bleeding gums and poor wound healing.", "2": "A lack of iodine causes goitre, a swelling of the thyroid gland in the neck.", "3": "A lack of iron causes anaemia, because too little haemoglobin is made."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6094' AND answer = 0;
UPDATE questions SET why = 'Collagen is a fibrous protein made of long chains wound into strong triple-helix fibres. It gives strength and support to skin, tendons, cartilage and bone. This makes it the main structural protein of the body.', wrong = '{"0": "Haemoglobin is a transport protein. It carries oxygen in red blood cells.", "1": "Insulin is a hormone. It controls blood glucose levels.", "2": "Amylase is an enzyme. It catalyses the breakdown of starch."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6095' AND answer = 3;
UPDATE questions SET why = 'A synthetic adhesive is a man-made polymer. Epoxy resins are made industrially and harden by chemical reaction into a strong network. Starch paste, animal glue and casein glue all come from natural materials.', wrong = '{"0": "Starch paste is made from starch, a natural polymer from plants, so it is a natural adhesive.", "1": "Animal glue is made from gelatin (collagen) in bones and hides, a natural protein.", "3": "Casein glue is made from casein, a natural protein in milk."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6096' AND answer = 2;
UPDATE questions SET why = 'Superglue is based on alkyl 2-cyanoacrylates. These small molecules polymerise very rapidly when they meet traces of water on most surfaces. The polymer chains form in seconds and make a strong bond.', wrong = '{"0": "Polyvinyl acetate (white glue) sets slowly, over minutes or hours, as its water evaporates or soaks in.", "2": "Urea-formaldehyde resins are thermosetting wood adhesives that need time, and often heat, to cure.", "3": "Natural rubber adhesives set as their solvent evaporates. They do not set in seconds with moisture."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6097' AND answer = 1;
UPDATE questions SET why = 'The hardener, often an amine, reacts with the epoxide groups of the resin. Each molecule links to several others, building a three-dimensional cross-linked network. This thermosetting polymer is rigid and cannot be softened again by heating.', wrong = '{"1": "Epoxy adhesives usually contain no solvent. They harden by chemical reaction, not by evaporation.", "2": "Hardening comes from new covalent bonds forming, not from cooling and crystallising.", "3": "Curing happens between the two parts themselves. It does not need oxygen from the air."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6098' AND answer = 0;
UPDATE questions SET why = 'White glue is polyvinyl acetate (PVA) dispersed in water. When it is spread on wood or paper, the water soaks in or evaporates. The PVA particles join into a flexible polymer film that holds the surfaces together.', wrong = '{"0": "Polystyrene is used for packaging, insulation and disposable cups, not as a water-based glue.", "1": "PVC (polyvinyl chloride) is used for pipes, flooring and cable insulation.", "2": "Teflon (PTFE) is a slippery non-stick polymer. Very little sticks to it, so it is not an adhesive."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6099' AND answer = 3;
UPDATE questions SET why = 'A dye dissolves in the medium it is applied from, usually water, and then becomes attached to the material, such as a fibre. A pigment does not dissolve. Its fine particles are held on the surface by a binder, as in paints and inks.', wrong = '{"0": "Both dyes and pigments can be natural or synthetic. Indigo, for example, is a dye that can be natural or man-made.", "1": "Most dyes are organic compounds. Many pigments, on the other hand, are inorganic.", "3": "Pigments are used mainly in paints, inks and plastics, not only in food."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6100' AND answer = 2;
UPDATE questions SET why = 'A vat dye is insoluble in water. It is reduced in a vat to a soluble, usually colourless "leuco" form that soaks into the fibre. Air then oxidises it back to the insoluble coloured dye, which stays trapped in the fibre. Indigo, used for denim, is the classic vat dye.', wrong = '{"0": "Direct dyes are already soluble in water and dye cotton straight from solution, with no reduction or oxidation step.", "2": "Mordant dyes need a metal salt to fix them to the fibre. Indigo is fixed by oxidation, not by a metal salt.", "3": "Disperse dyes are applied as fine suspensions of insoluble dye, mainly to synthetic fibres such as polyester."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6101' AND answer = 1;
UPDATE questions SET why = 'A mordant is a metal salt, for example of aluminium or chromium. Its metal ion forms a complex, called a lake, that binds both to the dye and to the fibre. This fixes a dye that would otherwise wash out, and different metals give different shades of the same dye.', wrong = '{"1": "A mordant fixes the dye to the fibre. Simply dissolving the dye would not stop it from washing out.", "2": "A reducing agent is used in vat dyeing to make an insoluble dye soluble, not in mordant dyeing.", "3": "A detergent only cleans the fibre before dyeing. It does not bind the dye."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6102' AND answer = 0;
UPDATE questions SET why = 'The colour of a dye comes from its chromophore, such as the –N=N– group in azo dyes. Auxochromes such as –OH and –NH₂ are attached to it. They deepen or shift the colour and help the dye bind to the fibre.', wrong = '{"0": "Auxochromes such as –OH, –NH₂ and –SO₃H usually make a dye more soluble and better at binding, not insoluble.", "1": "Auxochromes intensify the colour. They do not remove it.", "2": "The main colour-bearing group is the chromophore. Auxochromes only modify its colour."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6103' AND answer = 3;
UPDATE questions SET why = 'Some dyes bind more strongly to certain parts of cells, so they are used as biological stains. They make cell structures and bacteria visible under the microscope. Crystal violet is used in the Gram stain, and methylene blue is a common stain for nuclei and bacteria.', wrong = '{"0": "Dyes are not burned for energy. They are valued for colour, not as fuels.", "1": "Dyes do not supply the nutrients, such as N, P and K, that plants need, so they are not fertilisers.", "3": "Refrigerants are volatile liquids that absorb heat when they evaporate. Dyes are not used for this."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6104' AND answer = 2;
UPDATE questions SET why = 'Planck''s quantum theory says light is emitted and absorbed in small separate packets of energy called quanta. A quantum of light is called a photon. Its energy is E = hν, where h is Planck''s constant and ν is the frequency.', wrong = '{"0": "The smallest unit of charge is the charge on one electron or proton. A photon carries no charge.", "1": "A photon has zero rest mass, while an electron has a rest mass of about 9.1 × 10⁻³¹ kg.", "2": "Every photon carries energy equal to hν, so light certainly carries energy."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6105' AND answer = 3;
UPDATE questions SET why = 'Photon energy is E = hc/λ, with λ in metres: 600 nm = 6.0 × 10⁻⁷ m. E = (6.63 × 10⁻³⁴ × 3.0 × 10⁸) ÷ (6.0 × 10⁻⁷) = (1.99 × 10⁻²⁵) ÷ (6.0 × 10⁻⁷) = 3.3 × 10⁻¹⁹ J.', wrong = '{"0": "This comes from dividing hc by 600 without converting nanometres to metres: 1.99 × 10⁻²⁵ ÷ 600 = 3.3 × 10⁻²⁸.", "1": "This is h ÷ λ = 6.63 × 10⁻³⁴ ÷ 6.0 × 10⁻⁷, which is the photon''s momentum, not its energy. The factor c is missing.", "2": "This is just hc = 1.99 × 10⁻²⁵, which has not yet been divided by the wavelength."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6106' AND answer = 3;
UPDATE questions SET why = 'Photon energy is E = hc/λ, so energy is inversely proportional to wavelength. X has half the wavelength of Y, so it has twice the energy. E(X) : E(Y) = (1/400) : (1/800) = 800 : 400 = 2 : 1.', wrong = '{"1": "Photons of different wavelengths carry different energies. Equal energies would need equal wavelengths.", "2": "4 : 1 would follow if energy depended on 1/λ². In fact it depends on 1/λ, so the ratio is 2 : 1.", "3": "1 : 2 treats energy as directly proportional to wavelength. The relationship is inverse, so the ratio flips."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6107' AND answer = 0;
UPDATE questions SET why = 'Reacting particles that collide with at least the activation energy pass through a short-lived arrangement at the top of the energy barrier. In this activated complex (transition state), old bonds are partly broken and new bonds are partly formed. It then breaks up to give products or falls back to reactants.', wrong = '{"0": "The activated complex sits at an energy maximum and lasts only an instant, so it cannot be isolated or stored.", "1": "A catalyst lowers the activation energy, not ΔH. An activated complex also forms in uncatalysed reactions.", "3": "Products are formed after the activated complex breaks up. The complex is not itself a product."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6108' AND answer = 2;
UPDATE questions SET why = 'Activation energy is the height of the barrier measured from the starting point. The reverse reaction starts from the products at 20 kJ mol⁻¹, so Ea(reverse) = 170 − 20 = 150 kJ mol⁻¹. For comparison, Ea(forward) = 170 − 50 = 120 kJ mol⁻¹ and ΔH(forward) = 20 − 50 = −30 kJ mol⁻¹.', wrong = '{"0": "30 kJ mol⁻¹ is the size of ΔH (50 − 20), the gap between reactants and products, not a barrier height.", "1": "120 kJ mol⁻¹ (170 − 50) is the activation energy of the forward reaction, measured from the reactants.", "3": "170 kJ mol⁻¹ is the energy level of the activated complex itself, not its height above the products."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6109' AND answer = 2;
UPDATE questions SET why = 'Only collisions with energy at least equal to the activation energy can form the activated complex. At the same temperature, many more molecules have 40 kJ mol⁻¹ than 90 kJ mol⁻¹. So a much larger fraction of P''s collisions are effective, and P reacts faster.', wrong = '{"0": "Rate depends on how many collisions are effective, not just on how many happen. The two barriers differ, so the rates differ.", "2": "The activation energy says nothing about ΔH. A low barrier does not mean the reaction is more exothermic.", "3": "A higher barrier means fewer collisions have enough energy, so Q is slower, not faster."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6110' AND answer = 1;
UPDATE questions SET why = 'A two-step reaction profile has two peaks with a trough between them. Each peak is an activated complex, which exists only for an instant and cannot be isolated. The trough holds the intermediate, a real species with a short lifetime that is formed in step one and used up in step two.', wrong = '{"0": "This reverses the two. Activated complexes sit at the peaks and the intermediate sits in the trough.", "2": "They are different species: one is a passing arrangement at a peak, the other a real substance in a trough.", "3": "The intermediate lies in a trough, not at a peak, and it does not appear in the overall rate equation."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6111' AND answer = 1;
UPDATE questions SET why = 'Resonance energy is the extra stability of the real molecule compared with its most stable single structure. Benzene''s heat of hydrogenation is about 150 kJ mol⁻¹ less than expected for the imaginary Kekulé structure, cyclohexatriene. This difference is benzene''s resonance (delocalisation) energy.', wrong = '{"1": "The two Kekulé structures are identical in energy, so the difference between them is zero.", "2": "Making benzene from cyclohexane is a dehydrogenation. Its enthalpy change is not the resonance energy.", "3": "The energy to break all C–C bonds is a kind of atomisation energy, not the extra stability from delocalisation."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6112' AND answer = 0;
UPDATE questions SET why = 'Benzene''s six π electrons are delocalised around the ring, giving a large resonance energy. An addition reaction would destroy this delocalised system and lose that stability. So benzene usually undergoes electrophilic substitution, which keeps the aromatic ring in the product.', wrong = '{"1": "Benzene does not mix with water because it is non-polar and cannot hydrogen bond, not because of resonance energy.", "2": "Benzene burns with a sooty flame because of its high carbon-to-hydrogen ratio, which leaves unburnt carbon.", "3": "Boiling points depend on intermolecular forces and molar mass. Methylbenzene is heavier, so it boils higher."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6113' AND answer = 0;
UPDATE questions SET why = 'Each carbon in ethene is sp² hybridised and keeps one 2p orbital unhybridised, at right angles to the plane of the molecule. The two parallel 2p orbitals overlap sideways (laterally), above and below the plane. This lateral overlap is the π bond.', wrong = '{"0": "The carbons in ethene are sp² hybridised, not sp³. sp³ carbons have no free p orbital to form a π bond.", "2": "Head-on (linear) overlap of two sp² orbitals along the C–C axis forms the σ bond, not the π bond.", "3": "Hydrogen 1s orbitals overlap with carbon sp² orbitals to form the C–H σ bonds, not the π bond."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6114' AND answer = 1;
UPDATE questions SET why = 'The π bond exists only while the two p orbitals stay parallel and overlap sideways. Turning one CH₂ group through 90° would pull them apart and break the π bond, which needs about 250 kJ mol⁻¹. Room temperature does not supply this, so the groups cannot rotate, and alkenes can show cis-trans isomerism.', wrong = '{"0": "Rotation about a σ bond alone is free, whatever its length, as in ethane. The π bond is what blocks rotation.", "1": "The hydrogens on the two carbons repel only slightly. This small repulsion is not what stops rotation.", "2": "The carbons in ethene are sp² hybridised and trigonal planar, not sp³ and tetrahedral."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6115' AND answer = 3;
UPDATE questions SET why = 'In addition polymerisation the C=C bonds open and the monomers join end to end, with no atoms lost. So the polymer''s molar mass is n × monomer mass = 1000 × 28 = 28 000 g mol⁻¹.', wrong = '{"0": "14 000 = 1000 × 14 treats CH₂ (14 g mol⁻¹) as the monomer instead of C₂H₄ (28 g mol⁻¹).", "1": "26 000 = 1000 × 26 removes 2 g mol⁻¹ (two H atoms) per monomer. No hydrogen is lost in addition polymerisation.", "2": "27 982 = 28 000 − 18 subtracts a water molecule. Losing water happens only in condensation polymerisation."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6116' AND answer = 3;
UPDATE questions SET why = 'Excess strong base removes two molecules of HBr in two elimination steps: BrCH₂CH₂Br → CH₂=CHBr → HC≡CH. The second step is harder, but excess NaNH₂ or hot alcoholic KOH drives it. The main product is ethyne.', wrong = '{"0": "Ethane-1,2-diol comes from substitution by OH⁻ in aqueous base. A strong base in alcohol or NaNH₂ favours elimination.", "1": "Bromoethene forms after the first elimination, but excess strong base removes the second HBr as well.", "3": "Ethene would form if Br₂ were removed, for example with zinc dust. Removing two HBr leaves a triple bond."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6117' AND answer = 2;
UPDATE questions SET why = 'Moles of CaC₂ = 6.4 ÷ 64 = 0.10 mol. The equation gives 1 mol C₂H₂ per mol CaC₂, so 0.10 mol C₂H₂ forms. At STP one mole of gas occupies 22.4 dm³, so the volume is 0.10 × 22.4 = 2.24 dm³.', wrong = '{"0": "1.12 dm³ is 0.05 mol, half the correct amount, as if two CaC₂ gave one C₂H₂.", "2": "4.48 dm³ is 0.20 mol, double the correct amount, as if each water molecule produced an ethyne.", "3": "22.4 dm³ is the volume of a whole mole of gas. Only 0.10 mol is formed here."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6118' AND answer = 1;
UPDATE questions SET why = 'Ethene adds bromine fastest. Ethyne also adds bromine, but more slowly, because its sp carbons hold the π electrons more tightly and the vinyl-type carbocation formed is less stable. Benzene does not add bromine in the dark without a catalyst, because addition would destroy its aromatic stability.', wrong = '{"1": "Ethane is saturated, with no π bond, so it cannot undergo addition at all. It cannot be the most reactive.", "2": "Benzene is the least reactive of the three towards addition, not the most.", "3": "Ethyne has two π bonds, but its electrons are held more tightly, so it reacts more slowly than ethene."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6119' AND answer = 0;
UPDATE questions SET why = 'Burning magnesium is reactive enough to combine with nitrogen in the air as well as oxygen: 3Mg + N₂ → Mg₃N₂. When water is added, the nitride is hydrolysed: Mg₃N₂ + 6H₂O → 3Mg(OH)₂ + 2NH₃. The ammonia gives the smell.', wrong = '{"0": "Magnesium nitrate is not formed when magnesium burns. Burning gives the oxide and the nitride.", "1": "Burning magnesium does not form a hydride, and water contains no nitrogen to make ammonia.", "3": "MgO contains no nitrogen. With water it forms only Mg(OH)₂, so it cannot release ammonia."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6120' AND answer = 2;
UPDATE questions SET why = 'Calcium forms Ca²⁺ ions and nitrogen forms nitride ions, N³⁻. The total charges must cancel: 3 × (+2) = +6 and 2 × (−3) = −6. The formula is Ca₃N₂, made by 3Ca + N₂ → Ca₃N₂.', wrong = '{"0": "Ca(N₃)₂ is calcium azide, which contains the azide ion N₃⁻, not the nitride ion N³⁻.", "1": "CaN would need Ca³⁺ with N³⁻, or Ca²⁺ with N²⁻. Calcium forms only Ca²⁺.", "2": "Ca₂N₃ swaps the numbers. Its charges are 2 × (+2) = +4 and 3 × (−3) = −9, which do not balance."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6121' AND answer = 3;
UPDATE questions SET why = 'Lithium is the only alkali metal that combines directly with nitrogen: 6Li + N₂ → 2Li₃N. The very small Li⁺ ion forms a strong lattice with the small N³⁻ ion. This is one way lithium resembles magnesium, its diagonal neighbour, which also forms a nitride.', wrong = '{"0": "Potassium''s large K⁺ ion cannot form a stable lattice with N³⁻, so potassium does not react directly with nitrogen.", "2": "Caesium is the most reactive alkali metal with water, but its very large ion does not form a nitride directly.", "3": "Sodium does not react with nitrogen under ordinary conditions. Only lithium does in Group 1."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6122' AND answer = 1;
UPDATE questions SET why = 'In excess oxygen the alkali metals give different main products. Lithium forms mainly the normal oxide Li₂O, sodium mainly the peroxide Na₂O₂, and potassium, rubidium and caesium the superoxides such as KO₂. Larger cations are better at stabilising the larger peroxide and superoxide ions.', wrong = '{"0": "Potassium in excess oxygen does not stop at the normal oxide K₂O. It goes on to form the superoxide KO₂.", "1": "Sodium in excess oxygen forms mainly the peroxide Na₂O₂, not the superoxide.", "3": "Lithium forms mainly the normal oxide Li₂O. Its small ion cannot stabilise the peroxide well."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6123' AND answer = 2;
UPDATE questions SET why = 'The equation is 2Na + Cl₂ → 2NaCl, so 1 mol Na gives 1 mol NaCl. Moles of Na = 4.6 ÷ 23 = 0.20 mol, giving 0.20 mol NaCl. Mass = 0.20 × 58.5 = 11.7 g.', wrong = '{"0": "5.85 g is the mass of 0.10 mol NaCl. It comes from thinking that two Na atoms make only one NaCl.", "1": "8.15 g = 4.6 + 3.55 adds 0.10 mol of Cl atoms. Each of the 0.20 mol Na needs a Cl, which is 7.1 g.", "3": "23.4 g is the mass of 0.40 mol NaCl. It doubles the correct number of moles."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6124' AND answer = 2;
UPDATE questions SET why = 'Going down Group 1 the outer s electron is further from the nucleus and better shielded by inner electrons. Less energy is needed to remove it, so the first ionisation energy falls from Li to Cs. The metal loses its electron more easily and reacts with water more vigorously.', wrong = '{"1": "Melting points of the alkali metals actually decrease down the group. A higher melting point would not speed up the reaction anyway.", "2": "Hydration energy becomes less negative down the group, because the ions get larger. It does not explain the trend.", "3": "All Group 1 hydroxides are soluble in water, and their solubility is not the reason for the reactivity trend."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6125' AND answer = 0;
UPDATE questions SET why = 'Aluminium (E° = −1.66 V) should react with water, but its surface is covered by a thin, tough layer of Al₂O₃. This layer sticks firmly, does not let water reach the metal, and is itself unreactive. If the layer is removed, for example with mercury salts, aluminium does react with water.', wrong = '{"0": "Aluminium hydroxide, Al(OH)₃, is insoluble in water. It is the protective oxide layer that matters.", "1": "Aluminium is a metal. It conducts electricity, is malleable and forms positive ions.", "2": "Aluminium is well above hydrogen in the electrochemical series (E° = −1.66 V). It should react, but the oxide layer stops it."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6126' AND answer = 3;
UPDATE questions SET why = 'The Al atom in AlCl₃ has only six outer electrons, so it is electron-deficient. A chlorine of a second AlCl₃ molecule donates a lone pair to it, forming a coordinate bond, and the same happens the other way. The two Cl bridges give each Al an octet, so the vapour contains Al₂Cl₆ dimers.', wrong = '{"0": "The two Al atoms are joined through bridging Cl atoms (Al–Cl–Al). There is no direct Al–Al bond.", "2": "Aluminium chloride is largely covalent. It sublimes as separate molecules rather than keeping an ionic lattice in the vapour.", "3": "There are no Cl–Cl bonds in Al₂Cl₆. The bridging chlorines bond to aluminium atoms."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6127' AND answer = 1;
UPDATE questions SET why = 'Water breaks the C–O–C link between the two acyl groups of the anhydride. Each half picks up H or OH from the water: (CH₃CO)₂O + H₂O → 2CH₃COOH. The products are two molecules of ethanoic acid.', wrong = '{"1": "Ethyl ethanoate (an ester) forms when the anhydride reacts with ethanol, not with water.", "2": "The anhydride has no ethyl group, so no ethanol can be formed by adding water.", "3": "Ethanal would need a reduction step. Hydrolysis only adds water, so no aldehyde forms."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6128' AND answer = 0;
UPDATE questions SET why = 'In nucleophilic acyl substitution a group attached to the C=O leaves. The more easily that group leaves, the more reactive the derivative. Cl⁻ leaves best, then RCOO⁻, then RO⁻, and NH₂⁻ worst, so acyl chloride > anhydride > ester > amide. Acyl chlorides fume in moist air, while amides need long boiling with acid or alkali.', wrong = '{"1": "This puts anhydrides above acyl chlorides and amides above esters. Both pairs are the wrong way round.", "2": "This is the exact reverse order. Amides are the least reactive, not the most.", "3": "Acyl chlorides, with the best leaving group Cl⁻, are the most reactive, not esters."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6129' AND answer = 0;
UPDATE questions SET why = 'NH₃ attacks the carbonyl carbon of the acyl chloride and Cl is replaced by –NH₂, giving ethanamide. The HCl released reacts with a second NH₃ molecule: CH₃COCl + 2NH₃ → CH₃CONH₂ + NH₄Cl. So the products are ethanamide and ammonium chloride.', wrong = '{"0": "Ethanoic acid forms when ethanoyl chloride reacts with water, not with ammonia.", "1": "The C=O group is kept, so an amide forms, not an amine. With excess ammonia, HCl is taken up as NH₄Cl.", "2": "Ethanenitrile is made by dehydrating an amide, for example with P₄O₁₀. It is not formed directly here."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6130' AND answer = 3;
UPDATE questions SET why = 'The ethanoate ion from sodium ethanoate acts as a nucleophile and replaces Cl in ethanoyl chloride. This joins two acyl groups through an oxygen: CH₃COCl + CH₃COONa → (CH₃CO)₂O + NaCl. The product is ethanoic anhydride.', wrong = '{"0": "Acidified dichromate oxidises ethanal to ethanoic acid. It does not join two acid molecules into an anhydride.", "1": "Ethanoic acid and NaOH undergo neutralisation, giving sodium ethanoate and water, not the anhydride.", "3": "Ethanol with ethanoic acid and a little concentrated H₂SO₄ is esterification, giving ethyl ethanoate."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6131' AND answer = 2;
UPDATE questions SET why = 'Boiling with dilute acid hydrolyses the amide: the C–N bond breaks and –NH₂ is replaced by –OH. In acid the ammonia released is protonated to NH₄⁺: CH₃CONH₂ + H₂O + HCl → CH₃COOH + NH₄Cl. The products are ethanoic acid and ammonium chloride.', wrong = '{"0": "Turning an amide into a nitrile removes water and needs a dehydrating agent such as P₄O₁₀, not dilute acid.", "2": "Acyl chlorides are far more reactive than amides, so they cannot form by hydrolysis in water.", "3": "Making ethylamine from an amide needs reduction, for example with LiAlH₄. Hydrolysis does not remove the C=O oxygen."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6132' AND answer = 1;
UPDATE questions SET why = 'A conjugated protein has a non-protein part, called a prosthetic group, joined to the protein chains. In haemoglobin the prosthetic group is haem, which contains iron and binds oxygen. So haemoglobin is a conjugated protein.', wrong = '{"0": "Derived proteins are breakdown products of natural proteins, such as proteoses and peptones. Haemoglobin is a complete natural protein.", "1": "A simple protein gives only amino acids on hydrolysis. Haemoglobin also contains the haem group, so it is not simple.", "3": "Haemoglobin is a soluble, compact globular protein. Fibrous proteins, such as collagen, form long insoluble fibres."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6133' AND answer = 2;
UPDATE questions SET why = 'Proteins are grouped into simple proteins (only amino acids on hydrolysis), conjugated proteins (protein plus a prosthetic group) and derived proteins. Derived proteins are formed when natural proteins are partly hydrolysed or denatured. Examples are proteoses, peptones and peptides.', wrong = '{"1": "Protein classes are based on composition and origin from other proteins, not on whether a plant made them.", "2": "Giving only amino acids on complete hydrolysis describes simple proteins, such as albumin.", "3": "A protein with a metal ion as a prosthetic group is a conjugated protein (a metalloprotein)."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6134' AND answer = 0;
UPDATE questions SET why = 'A simple protein such as albumin is made only of α-amino acids joined by peptide bonds. Complete hydrolysis breaks every peptide bond. So the only products are α-amino acids.', wrong = '{"0": "Glucose in the products would mean a carbohydrate group was attached, as in a glycoprotein, which is a conjugated protein.", "1": "A haem group comes from a conjugated protein such as haemoglobin, not from a simple protein.", "2": "Fatty acids and glycerol are the products of hydrolysing fats (lipids), not proteins."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-6135' AND answer = 3;
UPDATE questions SET why = 'The equation is 2H₂ + O₂ → 2H₂O. Moles: H₂ = 10.0 ÷ 2 = 5.0 mol and O₂ = 64.0 ÷ 32 = 2.0 mol. 2.0 mol O₂ needs only 4.0 mol H₂, so O₂ is limiting and 5.0 − 4.0 = 1.0 mol H₂ is left, which is 2.0 g. The water formed is 4.0 mol, or 72 g.', wrong = '{"0": "Oxygen is the limiting reactant and is completely used up, so none of it is left over.", "2": "1.0 g of hydrogen is only 0.5 mol of H₂. The excess is 1.0 mol, which has a mass of 2.0 g.", "3": "The reactants are present as 5.0 : 2.0 mol, not the 2 : 1 ratio the equation needs, so one must be in excess."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7001' AND answer = 1;
UPDATE questions SET why = 'Only 80% of the limestone is CaCO₃: 0.80 × 25.0 = 20.0 g = 0.200 mol. CaCO₃ → CaO + CO₂ gives 0.200 mol CaO, so the theoretical yield is 0.200 × 56 = 11.2 g. Percentage yield = (9.52 ÷ 11.2) × 100 = 85%.', wrong = '{"0": "47.6% comes from 9.52 ÷ 20.0, dividing the mass of CaO by the mass of CaCO₃. Their molar masses differ, so masses cannot be compared directly.", "1": "68% comes from treating all 25.0 g as pure CaCO₃ (theoretical 14.0 g) and ignoring the 80% purity.", "2": "80% is the purity of the limestone, given in the question. It is not the percentage yield."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7002' AND answer = 3;
UPDATE questions SET why = 'The balanced equation is C₃H₈ + 5O₂ → 3CO₂ + 4H₂O. Propane (M = 44) = 11.0 ÷ 44 = 0.25 mol, so O₂ needed = 5 × 0.25 = 1.25 mol. At STP this is 1.25 × 22.4 = 28.0 dm³.', wrong = '{"0": "5.6 dm³ = 0.25 × 22.4 is the volume of the propane itself, not of the oxygen it uses.", "1": "16.8 dm³ = 0.75 × 22.4 is the volume of CO₂ formed (3 × 0.25 mol), not the oxygen used.", "2": "22.4 dm³ is 1.0 mol, which matches the 4 × 0.25 = 1.0 mol of water formed, not the 1.25 mol of oxygen."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7003' AND answer = 3;
UPDATE questions SET why = 'Molar mass of CO₂ = 12 + 2 × 16 = 44 g mol⁻¹, so 4.4 g = 0.10 mol of molecules. Each CO₂ molecule contains 3 atoms, giving 0.30 mol of atoms. Number of atoms = 0.30 × 6.02 × 10²³ = 1.81 × 10²³.', wrong = '{"0": "6.02 × 10²² is 0.10 mol, the number of CO₂ molecules. Each molecule has three atoms.", "1": "1.20 × 10²³ is 0.20 mol, which counts only the two oxygen atoms per molecule and leaves out carbon.", "3": "7.95 × 10²⁴ = 4.4 × 3 × 6.02 × 10²³ treats 4.4 g as 4.4 mol instead of dividing by the molar mass."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7004' AND answer = 2;
UPDATE questions SET why = 'Each formula unit splits into five ions: Al₂(SO₄)₃ → 2Al³⁺ + 3SO₄²⁻. So 0.20 mol gives 5 × 0.20 = 1.0 mol of ions. One mole is 6.02 × 10²³ particles, so 6.02 × 10²³ ions are present.', wrong = '{"0": "1.20 × 10²³ is 0.20 mol, the number of formula units dissolved, not the ions they form.", "1": "2.41 × 10²³ is 0.40 mol, which counts only the Al³⁺ ions (2 × 0.20).", "2": "3.61 × 10²³ is 0.60 mol, which counts only the sulphate ions (3 × 0.20)."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7005' AND answer = 3;
UPDATE questions SET why = 'Work backwards through the steps using mole ratios. In step two NH₃ : NO = 4 : 4, so 2 mol NO needs 2 mol NH₃. In step one H₂ : NH₃ = 3 : 2, so 2 mol NH₃ needs 3 mol H₂.', wrong = '{"0": "1.5 mol is half the correct amount. It would make only 1 mol NH₃ and 1 mol NO.", "1": "2 mol assumes one H₂ per NO. But each NH₃ needs 1.5 H₂, so 2 mol NH₃ needs 3 mol H₂.", "3": "6 mol is double the amount. It would give 4 mol NH₃ and 4 mol NO."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7006' AND answer = 2;
UPDATE questions SET why = 'Moles: Al = 5.4 ÷ 27 = 0.20 mol and Cl₂ = 21.3 ÷ 71 = 0.30 mol. The ratio 0.20 : 0.30 is exactly the 2 : 3 in the equation, so both reactants are used up. 0.20 mol AlCl₃ forms, which is 0.20 × 133.5 = 26.7 g.', wrong = '{"0": "13.4 g is 0.10 mol AlCl₃, half the true amount. The reactants are in exact proportion, so neither is limiting.", "2": "The mass is right, but 0.30 mol Cl₂ is exactly what 0.20 mol Al needs, so no chlorine is left over.", "3": "40.1 g is 0.30 mol AlCl₃, as if Cl₂ and AlCl₃ were in a 1 : 1 ratio. The equation gives 3 : 2."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7007' AND answer = 1;
UPDATE questions SET why = 'Mass of C = 0.44 × 12/44 = 0.12 g (0.010 mol). Mass of H = 0.18 × 2/18 = 0.020 g (0.020 mol). Mass of O = 0.30 − 0.12 − 0.020 = 0.16 g (0.010 mol). The ratio C : H : O = 1 : 2 : 1 gives the empirical formula CH₂O (30), and 60 ÷ 30 = 2, so the molecular formula is C₂H₄O₂.', wrong = '{"1": "C₂H₆O has a molar mass of 46, not 60, and its C : H : O ratio of 2 : 6 : 1 does not match the analysis.", "2": "CH₂O is the empirical formula. Its mass is 30, so it must be doubled to reach 60.", "3": "C₃H₈O does have a molar mass of 60, but its ratio 3 : 8 : 1 does not match the 1 : 2 : 1 found."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7008' AND answer = 0;
UPDATE questions SET why = 'Actual ester = 22.0 ÷ 88 = 0.25 mol. At 50% yield, this is half of the theoretical amount, so the reaction must be set up for 0.50 mol of ester. With a 1 : 1 ratio this needs 0.50 mol of acid = 0.50 × 60 = 30 g.', wrong = '{"0": "15 g = 0.25 × 60 is the acid needed at 100% yield. It ignores that only half the acid becomes ester.", "2": "44 g = 0.50 × 88 is the theoretical mass of ester, not the mass of ethanoic acid.", "3": "60 g is 1.0 mol of acid. It applies the 50% yield twice."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7009' AND answer = 1;
UPDATE questions SET why = 'Each sample is 0.10 mol of molecules: 0.20/2, 1.6/16, 2.24/22.4 and 3.2/32. So the number of atoms depends on atoms per molecule. CH₄ has 5, giving 0.50 mol of atoms, more than NH₃ (0.40), O₂ (0.20) or H₂ (0.20).', wrong = '{"0": "0.20 g of H₂ is 0.10 mol, and each molecule has 2 atoms, giving only 0.20 mol of atoms.", "2": "2.24 dm³ of NH₃ at STP is 0.10 mol, with 4 atoms each, giving 0.40 mol of atoms. That is fewer than CH₄.", "3": "3.2 g of O₂ is 0.10 mol, with 2 atoms each, giving only 0.20 mol of atoms."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7010' AND answer = 1;
UPDATE questions SET why = 'Moles: Zn = 6.5 ÷ 65 = 0.10 mol and HCl = 0.100 dm³ × 1.0 mol dm⁻³ = 0.10 mol. 0.10 mol Zn would need 0.20 mol HCl, so HCl is limiting. H₂ = 0.10 ÷ 2 = 0.050 mol, which is 0.050 × 22.4 = 1.12 dm³. Half the zinc, 3.25 g, is left over.', wrong = '{"0": "0.56 dm³ is 0.025 mol of H₂. It halves the moles a second time.", "2": "2.24 dm³ is 0.10 mol of H₂, which assumes zinc is limiting. There is not enough acid for all the zinc.", "3": "4.48 dm³ is 0.20 mol of H₂, double the amount even zinc could give."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7011' AND answer = 1;
UPDATE questions SET why = '% N = (mass of N in one formula unit ÷ molar mass) × 100. Urea: 28/60 = 46.7%. Ammonium nitrate: 28/80 = 35.0%. Ammonium chloride: 14/53.5 = 26.2%. Ammonium sulphate: 28/132 = 21.2%. Urea has the highest percentage.', wrong = '{"1": "Ammonium sulphate has 28/132 = 21.2% N, the lowest of the four, because the heavy SO₄ group adds a lot of mass.", "2": "Ammonium nitrate has two N atoms in 80 g mol⁻¹, giving 35.0%. That is high, but less than urea''s 46.7%.", "3": "Ammonium chloride has 14/53.5 = 26.2% N, well below urea."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7012' AND answer = 0;
UPDATE questions SET why = 'For gases at the same temperature and pressure, volume ratios equal mole ratios (Avogadro''s law). CₓHᵧ + (x + y/4)O₂ → xCO₂ + (y/2)H₂O. CO₂: 30 ÷ 10 = 3, so x = 3. O₂: 50 ÷ 10 = 5 = 3 + y/4, so y = 8. The hydrocarbon is C₃H₈.', wrong = '{"0": "C₃H₄ needs 3 + 4/4 = 4 volumes of O₂, which is 40 cm³, not 50 cm³.", "1": "C₂H₆ has two carbons, so it gives only 20 cm³ of CO₂, not 30 cm³.", "3": "C₃H₆ needs 3 + 6/4 = 4.5 volumes of O₂, which is 45 cm³, not 50 cm³."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7013' AND answer = 2;
UPDATE questions SET why = 'Moles: Ag⁺ = 0.050 dm³ × 0.20 = 0.010 mol and Cl⁻ = 0.050 dm³ × 0.10 = 0.0050 mol. They react 1 : 1 (Ag⁺ + Cl⁻ → AgCl), so Cl⁻ is limiting. AgCl formed = 0.0050 mol × 143.5 = 0.72 g.', wrong = '{"0": "0.36 g is 0.0025 mol, half of the limiting amount of chloride.", "2": "1.08 g is 0.0075 mol, the average of the two amounts. Only the limiting amount, 0.0050 mol, can react.", "3": "1.44 g is 0.010 mol, which assumes all the silver precipitates. There is only enough chloride for half of it."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7014' AND answer = 1;
UPDATE questions SET why = 'Mass of the drop = volume × density = 0.050 cm³ × 1.0 g cm⁻³ = 0.050 g. Moles = 0.050 ÷ 18 = 2.8 × 10⁻³ mol. Molecules = 2.8 × 10⁻³ × 6.02 × 10²³ = 1.7 × 10²¹.', wrong = '{"0": "2.8 × 10⁻³ is the number of moles. It still has to be multiplied by Avogadro''s number.", "2": "3.0 × 10²² = 0.050 × 6.02 × 10²³ treats 0.050 g as 0.050 mol, skipping division by 18.", "3": "5.4 × 10²³ = 0.050 × 18 × 6.02 × 10²³ multiplies by the molar mass instead of dividing by it."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7015' AND answer = 1;
UPDATE questions SET why = 'The yields of successive steps multiply. Step one gives B = 0.50 × 0.80 = 0.40 mol. Step two gives C = 0.40 × 0.75 = 0.30 mol. The overall yield is 0.80 × 0.75 = 60%.', wrong = '{"1": "0.375 mol = 0.50 × 0.75 applies only the second step''s yield and forgets the 80% of step one.", "2": "0.39 mol uses the average yield of 77.5%. Successive yields multiply, they are not averaged.", "3": "0.40 mol is the amount of B after the first step. The second step loses another 25%."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7016' AND answer = 0;
UPDATE questions SET why = 'For n = 3, l can be 0 (3s), 1 (3p) or 2 (3d), and m runs from −l to +l. m = −1 exists only when l = 1 or l = 2, giving one 3p orbital and one 3d orbital. Each orbital holds 2 electrons, so 2 × 2 = 4 electrons.', wrong = '{"0": "2 electrons counts only one orbital. Both the 3p and the 3d subshells have an orbital with m = −1.", "2": "6 electrons counts all three 3p orbitals. Only one of them has m = −1.", "3": "8 electrons counts orbitals with m = +1 as well, which is four orbitals instead of two."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7017' AND answer = 1;
UPDATE questions SET why = 'The azimuthal quantum number l can only take values from 0 to n − 1. For n = 2, l can be 0 or 1 only (2s and 2p). l = 2 would mean a 2d subshell, which does not exist, so this set is not allowed.', wrong = '{"0": "n = 2, l = 1, m = 0, s = −½ is allowed. It describes an electron in a 2p orbital.", "1": "n = 4, l = 0, m = 0, s = +½ is allowed. It describes an electron in the 4s orbital.", "2": "n = 3, l = 2, m = −2, s = +½ is allowed. For l = 2, m can be −2 to +2, so this is a 3d electron."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7018' AND answer = 3;
UPDATE questions SET why = 'Cr is [Ar]3d⁵4s¹: one electron moves from 4s to give a half-filled 3d subshell, which is extra stable. That leaves 5 unpaired 3d electrons plus 1 unpaired 4s electron, 6 in all. Mn²⁺ and Fe³⁺ are both [Ar]3d⁵ with 5 unpaired, and Co is [Ar]3d⁷4s² with 3 unpaired.', wrong = '{"0": "Co is [Ar]3d⁷4s². Seven d electrons in five orbitals leave only 3 unpaired electrons.", "1": "Mn²⁺ is [Ar]3d⁵, with 5 unpaired electrons. Chromium''s extra unpaired 4s electron gives it one more.", "3": "Fe³⁺ is [Ar]3d⁵, with 5 unpaired electrons, one fewer than the Cr atom."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7019' AND answer = 2;
UPDATE questions SET why = 'Ionisation means moving the electron to n = ∞, where its energy is zero. In the n = 2 state, E₂ = −13.6 ÷ 2² = −13.6 ÷ 4 = −3.4 eV. So the energy needed is 0 − (−3.4) = 3.4 eV.', wrong = '{"0": "1.51 eV is the size of E₃ = 13.6 ÷ 9, the energy to ionise from n = 3, not from n = 2.", "2": "10.2 eV is the energy for the jump from n = 1 to n = 2, not for removing the electron from n = 2.", "3": "13.6 eV is the ionisation energy from the ground state, n = 1. An electron in n = 2 is already 10.2 eV higher."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7020' AND answer = 1;
UPDATE questions SET why = 'Each spectral line comes from a drop between two different levels. With levels n = 1 to 4, the possible drops are 4→3, 4→2, 4→1, 3→2, 3→1 and 2→1. The general formula is n(n − 1)/2 = 4 × 3 ÷ 2 = 6 lines.', wrong = '{"0": "3 counts only the single-step drops (4→3, 3→2, 2→1) and misses the larger jumps such as 4→1.", "1": "4 is the number of energy levels involved, not the number of transitions between them.", "3": "10 = 5 × 4 ÷ 2 is the number of lines for electrons starting at n = 5, not n = 4."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7021' AND answer = 2;
UPDATE questions SET why = 'By the (n + l) rule, the subshell with the lower n + l fills first. Here 4s = 4 + 0 = 4, 3d = 3 + 2 = 5, 4p = 4 + 1 = 5 and 5s = 5 + 0 = 5. When sums are equal, the lower n fills first, so the order is 4s < 3d < 4p < 5s.', wrong = '{"1": "3d and 4p both have n + l = 5, so the one with lower n, 3d, fills before 4p.", "2": "4s has n + l = 4, lower than 3d''s 5, so 4s fills before 3d.", "3": "4p and 5s both have n + l = 5, so 4p (n = 4) fills before 5s (n = 5)."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7022' AND answer = 0;
UPDATE questions SET why = 'Photon energy equals the gap between the two levels, ΔE = 13.6 (1/n₁² − 1/n₂²) eV. For 2→1: 13.6 × (1 − ¼) = 10.2 eV. Every drop that ends at n = 2 gives less: ∞→2 is 3.4 eV, 6→2 is 3.0 eV and 3→2 is 1.9 eV. The levels are furthest apart near the nucleus, so the 2→1 jump releases the most energy.', wrong = '{"0": "3→2 gives 13.6 × (¼ − 1/9) = 1.9 eV. This is the red Balmer line, the lowest energy of the four.", "1": "6→2 gives 13.6 × (¼ − 1/36) = 3.0 eV, much less than 10.2 eV.", "2": "∞→2 gives only 3.4 eV. Even the largest drop into n = 2 releases less energy than 2→1."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7023' AND answer = 3;
UPDATE questions SET why = 'Sulphur (Z = 16) has the configuration 1s² 2s² 2p⁶ 3s² 3p⁴. The p electrons are those in the 2p and 3p subshells, while the rest are in s subshells. So the number of p electrons is 6 + 4 = 10.', wrong = '{"0": "4 counts only the 3p electrons and leaves out the full 2p subshell.", "1": "6 counts only the 2p electrons and leaves out the four 3p electrons.", "3": "16 is the total number of electrons in sulphur, including the s electrons."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7024' AND answer = 2;
UPDATE questions SET why = 'Copper is [Ar]3d¹⁰4s¹, because a completely filled 3d subshell is extra stable. When a transition metal forms a positive ion, the 4s electrons are lost before the 3d electrons. So Cu⁺ loses its 4s electron and becomes [Ar]3d¹⁰.', wrong = '{"1": "This removes an electron from 3d and keeps the 4s electron. In ions, 4s electrons are lost first.", "2": "[Ar]3d¹⁰4s¹ has 29 electrons. It is the neutral copper atom, not the Cu⁺ ion.", "3": "[Ar]3d⁸4s² has 28 electrons arranged wrongly. It fits neither Cu⁺ nor the copper atom."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7025' AND answer = 0;
UPDATE questions SET why = 'Positive rays are positive ions formed from the gas in the discharge tube, so their e/m depends on the gas used. For the same charge, a lighter ion has a larger e/m. Hydrogen gives H⁺, the lightest positive ion, so its e/m is the largest. This particle was identified as the proton.', wrong = '{"1": "Ne⁺ has a mass of about 20 units for a charge of +1, so its e/m is about one-twentieth that of H⁺.", "2": "He⁺ is about four times heavier than H⁺ for the same charge, so its e/m is about a quarter as large.", "3": "O⁺ has a mass of about 16 units, so its e/m is much smaller than that of H⁺."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7026' AND answer = 0;
UPDATE questions SET why = 'All four ions have 10 electrons (isoelectronic). Their sizes are set by the number of protons pulling on the same electron cloud: O has 8, F 9, Na 11 and Mg 12. More protons pull the electrons in tighter, so O²⁻ > F⁻ > Na⁺ > Mg²⁺.', wrong = '{"0": "In this set the cations are smaller than the anions, because they have more protons for the same 10 electrons.", "1": "O²⁻ (8 protons) is larger than F⁻ (9 protons), and Na⁺ is larger than Mg²⁺. Both pairs are reversed.", "2": "This is the reverse order. Mg²⁺, with 12 protons, is the smallest ion, not the largest."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7027' AND answer = 3;
UPDATE questions SET why = 'Ionisation energy generally rises across Period 3 but drops twice. Al < Mg because Al''s electron comes from a 3p orbital, which is higher in energy and shielded by the 3s² pair. S < P because S loses an electron from a doubly filled 3p orbital, where the paired electrons repel each other.', wrong = '{"1": "Both comparisons are reversed. Mg is higher than Al, and P is higher than S.", "2": "Mg > Al is right, but S is lower than P because of repulsion between its paired 3p electrons.", "3": "P > S is right, but Al is lower than Mg because its electron is removed from the higher-energy 3p subshell."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7028' AND answer = 0;
UPDATE questions SET why = 'A very large jump in ionisation energy shows that an electron is being removed from a new, inner shell. Here the jump comes between the third and fourth values (2745 → 11 577 kJ mol⁻¹). So the atom has three outer electrons and is in Group 13. These are the values for aluminium.', wrong = '{"0": "A Group 1 element has one outer electron, so its big jump would come right after the first ionisation energy.", "1": "A Group 14 element has four outer electrons, so its big jump would come after the fourth value.", "3": "A Group 2 element has two outer electrons, so its big jump would come after the second value."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7029' AND answer = 2;
UPDATE questions SET why = 'The added electron enters fluorine''s small 2p subshell, which is already crowded with electrons. The strong repulsion between them partly cancels the nuclear attraction. In the larger chlorine atom the electrons are more spread out, so the extra electron is repelled less and more energy is released overall.', wrong = '{"0": "Fluorine is 2s²2p⁵, one electron short of a full shell, so it readily accepts an electron.", "1": "Chlorine''s added electron goes into its 3p subshell (3p⁵ → 3p⁶), not into a 3d orbital.", "2": "Chlorine''s extra protons are largely offset by extra shielding and greater distance. Repulsion in the small F atom is the key factor."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7030' AND answer = 3;
UPDATE questions SET why = 'NaCl is ionic. It simply dissolves into hydrated Na⁺ and Cl⁻ ions and does not react with water, so the solution is neutral (pH 7). Across Period 3 the chlorides become more covalent and react with water: MgCl₂ gives a slightly acidic solution, AlCl₃ an acidic one, and SiCl₄ is fully hydrolysed.', wrong = '{"1": "The small, highly charged Al³⁺ ion pulls on its water molecules so strongly that they release H⁺, making the solution acidic.", "2": "Mg²⁺ is small and doubly charged. It polarises water slightly, giving a weakly acidic solution.", "3": "SiCl₄ reacts vigorously with water: SiCl₄ + 2H₂O → SiO₂ + 4HCl, giving a strongly acidic solution."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7031' AND answer = 0;
UPDATE questions SET why = 'Silicon has a giant covalent structure, like diamond, in which every atom is joined to four others by strong Si–Si bonds. Melting means breaking a huge number of these bonds, so Si melts at about 1410 °C. Al is metallic (660 °C), and P₄ and S₈ are simple molecules held by weak forces.', wrong = '{"0": "Aluminium has strong metallic bonding, but it melts at only about 660 °C, far below silicon.", "1": "S₈ melts at about 115 °C, because only weak forces between the molecules are overcome. Molecule size does not make it the highest.", "3": "The P–P covalent bonds stay intact on melting. Only the weak forces between P₄ molecules are overcome."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7032' AND answer = 2;
UPDATE questions SET why = '[Ne]3s²3p³ is phosphorus, with three unpaired electrons in a half-filled 3p subshell. The next element, sulphur, loses an electron from a doubly filled 3p orbital, where pair repulsion helps remove it. So P''s first ionisation energy (about 1012 kJ mol⁻¹) is higher than S''s (about 1000 kJ mol⁻¹).', wrong = '{"0": "Atomic radius decreases across a period as nuclear charge rises, so phosphorus is smaller than aluminium.", "1": "Phosphorus is a non-metal. Its oxides, P₄O₆ and P₄O₁₀, are acidic, not basic.", "2": "Phosphorus is a non-metal and does not conduct electricity."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7033' AND answer = 3;
UPDATE questions SET why = 'Every Group 1 ion has a charge of +1, but Li⁺ is by far the smallest. The same charge packed into a small ion gives the highest charge density. So Li⁺ attracts the polar water molecules most strongly, and the most energy is released when it is hydrated.', wrong = '{"0": "Lithium has the lowest nuclear charge in the group (3 protons), so this cannot be the reason.", "2": "Hydration is an attraction between the ion and the water dipoles (ion–dipole). No covalent bonds are formed.", "3": "Li⁺ has only two electrons, the fewest of the Group 1 ions."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7034' AND answer = 1;
UPDATE questions SET why = 'At STP one mole of any gas occupies 22.4 dm³. So molar mass = density × molar volume = 1.25 g dm⁻³ × 22.4 dm³ mol⁻¹ = 28 g mol⁻¹. This matches N₂ (2 × 14 = 28). CO would also fit, but it is not offered.', wrong = '{"1": "O₂ has M = 32, so its density at STP would be 32 ÷ 22.4 = 1.43 g dm⁻³.", "2": "NH₃ has M = 17, so its density at STP would be 17 ÷ 22.4 = 0.76 g dm⁻³.", "3": "CO₂ has M = 44, so its density at STP would be 44 ÷ 22.4 = 1.96 g dm⁻³."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7035' AND answer = 0;
UPDATE questions SET why = 'Use the general gas equation P₁V₁/T₁ = P₂V₂/T₂, with temperatures in kelvin: 27 °C = 300 K and 127 °C = 400 K. V₂ = V₁ × (P₁/P₂) × (T₂/T₁) = 300 × (1.0/2.0) × (400/300) = 200 cm³.', wrong = '{"0": "150 cm³ = 300 × ½ applies only the pressure change and ignores the rise in temperature.", "2": "706 cm³ uses Celsius temperatures (127/27). Gas law calculations need kelvin.", "3": "800 cm³ multiplies by 2 instead of ½. Doubling the pressure halves the volume, it does not double it."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7036' AND answer = 1;
UPDATE questions SET why = 'From the ideal gas equation, n = PV/RT, with T = 27 + 273 = 300 K. n = (1.0 × 0.492) ÷ (0.0821 × 300) = 0.492 ÷ 24.6 = 0.020 mol. Molar mass = mass ÷ moles = 0.64 ÷ 0.020 = 32 g mol⁻¹.', wrong = '{"0": "2.9 g mol⁻¹ comes from using T = 27 instead of 300 K. Temperature must be in kelvin.", "2": "64 g mol⁻¹ would mean only 0.010 mol of gas, half the 0.020 mol actually present.", "3": "3.2 × 10³ g mol⁻¹ comes from using R = 8.314 J K⁻¹ mol⁻¹, which does not match volume in dm³ and pressure in atm."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7037' AND answer = 1;
UPDATE questions SET why = 'Boyle''s law states that PV = k at constant temperature, so P = k × (1/V). This has the form y = mx, with slope k. So a graph of P against 1/V is a straight line through the origin.', wrong = '{"0": "V against °C (Charles''s law, at constant pressure) is a straight line, but it meets the axis at −273 °C, not at the origin.", "1": "P against V gives a curve (a hyperbola), because P falls as V rises but never reaches zero.", "3": "PV is constant, so PV against P is a horizontal line. It does not pass through the origin."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7038' AND answer = 2;
UPDATE questions SET why = 'Partial pressure = mole fraction × total pressure (Dalton''s law). Moles: H₂ = 4.0 ÷ 2 = 2.0 mol and O₂ = 32 ÷ 32 = 1.0 mol, so the mole fraction of O₂ is 1.0 ÷ 3.0 = ⅓. p(O₂) = ⅓ × 3.0 atm = 1.0 atm.', wrong = '{"0": "0.33 is the mole fraction of oxygen. It must be multiplied by the total pressure of 3.0 atm.", "2": "1.5 atm splits the pressure equally between the gases, as if they had equal moles. There is twice as much H₂.", "3": "2.0 atm is the partial pressure of hydrogen, which makes up two-thirds of the moles."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7039' AND answer = 1;
UPDATE questions SET why = 'Real gases deviate from ideal behaviour mainly because of attractions between molecules. NH₃ is polar and forms hydrogen bonds, so its molecules attract each other strongly and it is easily liquefied. It therefore deviates most from PV = nRT.', wrong = '{"0": "H₂ molecules are small and non-polar, with very weak forces between them, so H₂ is close to ideal.", "1": "Helium atoms are tiny and have only very weak forces between them. Helium is the most nearly ideal gas.", "2": "N₂ is non-polar, with only weak London forces, so it deviates far less than NH₃."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7040' AND answer = 3;
UPDATE questions SET why = 'By Charles''s law, volume is proportional to temperature in kelvin at constant pressure. 0 °C = 273 K, so doubling the volume needs 2 × 273 = 546 K. Converting back, 546 − 273 = 273 °C.', wrong = '{"0": "546 is the required temperature in kelvin. Expressed in Celsius it is 273 °C, not 546 °C.", "1": "273 K is the same as 0 °C, the starting temperature, so the volume would not change.", "3": "136.5 °C is only 409.5 K, which is 1.5 times 273 K. The volume would grow by half, not double."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7041' AND answer = 2;
UPDATE questions SET why = 'When the tap opens, each gas spreads into the total volume of 5.0 dm³. By Boyle''s law: p(N₂) = 3.0 × 2.0 ÷ 5.0 = 1.2 atm and p(O₂) = 2.0 × 3.0 ÷ 5.0 = 1.2 atm. By Dalton''s law the total pressure is 1.2 + 1.2 = 2.4 atm.', wrong = '{"0": "1.2 atm is the partial pressure of just one gas. Both gases contribute to the total.", "2": "2.5 atm is the simple average of 3.0 and 2.0. The bulbs have different volumes, so the pressures must be weighted.", "3": "5.0 atm adds the original pressures. Each gas expands into a larger volume, so its pressure falls."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7042' AND answer = 1;
UPDATE questions SET why = 'At the same temperature all gases have the same average kinetic energy, ½mu². So speed is inversely proportional to the square root of molar mass, u ∝ 1/√M. u(H₂)/u(O₂) = √(32/2) = √16 = 4, so H₂ moves 4 times faster.', wrong = '{"1": "16 is the ratio of the molar masses. Speed depends on the square root of this ratio, which is 4.", "2": "The lighter molecule moves faster, not slower, when the kinetic energies are equal.", "3": "The two gases have the same average kinetic energy, not the same speed. Lighter H₂ must move faster."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7043' AND answer = 0;
UPDATE questions SET why = 'A higher vapour pressure at the same temperature means molecules escape the liquid more easily, so the forces between them are weaker. A liquid boils when its vapour pressure equals the outside pressure. X reaches that point at a lower temperature, so X has weaker forces and a lower boiling point than Y.', wrong = '{"0": "Stronger intermolecular forces would hold molecules in the liquid and lower the vapour pressure. X''s higher value shows weaker forces.", "1": "A higher vapour pressure means more molecules escape per second, so X evaporates faster, not slower.", "2": "At its boiling point, every liquid has a vapour pressure equal to the external pressure, so these values are equal."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7044' AND answer = 3;
UPDATE questions SET why = 'Boiling point depends on how many hydrogen bonds each molecule forms, not only on how strong each one is. HF has three lone pairs but only one H atom, so on average each molecule forms just one hydrogen bond, giving zig-zag chains. Water has two H atoms and two lone pairs, so it forms about two per molecule in a 3-D network that needs more energy to break.', wrong = '{"0": "The molar mass of HF (20) is actually slightly higher than that of water (18), so mass cannot explain it.", "1": "HF is strongly polar, because fluorine is far more electronegative than hydrogen.", "3": "A single F–H···F hydrogen bond is actually stronger than an O–H···O bond. Water wins because it forms more of them."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7045' AND answer = 2;
UPDATE questions SET why = 'Just above 0 °C, liquid water still contains ice-like clusters with an open, hydrogen-bonded structure and empty spaces. On warming, these clusters break down and the molecules pack more closely. Up to 4 °C this shrinking outweighs normal thermal expansion, so the volume decreases and density is greatest at 4 °C.', wrong = '{"0": "Most liquids expand on heating, but water is an exception between 0 °C and 4 °C, where it contracts.", "1": "Water molecules do not change size. The volume falls because the way they pack together changes.", "2": "The hydrogen-bonded clusters break up steadily as water warms, so the structure does change below 4 °C."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7046' AND answer = 3;
UPDATE questions SET why = 'In graphite each carbon is sp² hybridised and bonded to only three others in flat hexagonal layers. The fourth outer electron of each atom is delocalised over the layer and can move along it, so graphite conducts. In diamond each carbon is sp³ and uses all four electrons in fixed σ bonds, so no electrons are free.', wrong = '{"1": "Graphite contains no ions. Its carbon atoms are held by covalent bonds, and conduction is by delocalised electrons.", "2": "Four bonds per carbon is the structure of diamond. Using all four electrons in bonds leaves none free to conduct.", "3": "The layers in graphite are held by weak van der Waals forces, not ionic bonds. This is why the layers slide over each other."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7047' AND answer = 0;
UPDATE questions SET why = 'Molecular crystals, such as iodine, are made of separate molecules held together by weak intermolecular forces. Little energy is needed to separate them, so they are soft, melt or sublime easily, and have low melting points. They contain no ions or free electrons, so they do not conduct when solid or melted.', wrong = '{"0": "Covalent network crystals such as quartz are very hard and have very high melting points, because strong covalent bonds must be broken.", "1": "Ionic crystals such as NaCl are hard, melt at high temperatures and conduct electricity when molten, because their ions can then move.", "2": "Metallic crystals such as copper conduct electricity in the solid state, using their delocalised electrons."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7048' AND answer = 3;
UPDATE questions SET why = 'Lattice energy becomes larger when the ions carry higher charges and when they are smaller, so they sit closer together. MgO is made of small Mg²⁺ and O²⁻ ions with double charges. Its lattice energy, about −3800 kJ mol⁻¹, is roughly four times that of the singly charged salts.', wrong = '{"1": "NaF has small ions, but each carries only a single charge, so its lattice energy is only about −920 kJ mol⁻¹.", "2": "K⁺ and Br⁻ are the largest ions here and are singly charged, so KBr has the smallest lattice energy of the four.", "3": "NaCl has singly charged ions, and Cl⁻ is larger than F⁻, so its lattice energy is even smaller than that of NaF."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7049' AND answer = 0;
UPDATE questions SET why = 'At STP (273 K, 1 atm) 1.0 mol of gas occupies 22.4 dm³. 273 °C is 546 K, twice 273 K, which doubles the volume. The pressure of 2.0 atm halves it, so V = 22.4 × 2 × ½ = 22.4 dm³.', wrong = '{"0": "11.2 dm³ halves the volume for the doubled pressure but forgets to double it for the doubled kelvin temperature.", "2": "44.8 dm³ doubles the volume for temperature but forgets to halve it for the higher pressure.", "3": "89.6 dm³ doubles for temperature and also doubles for pressure. Higher pressure should halve the volume, not double it."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7050' AND answer = 1;
UPDATE questions SET why = 'Making 1.6 mol HI uses 0.8 mol each of H₂ and I₂, since the ratio is 1 : 1 : 2. At equilibrium [H₂] = 2.0 − 0.8 = 1.2 and [I₂] = 1.0 − 0.8 = 0.2 mol dm⁻³. Kc = [HI]²/([H₂][I₂]) = 1.6² ÷ (1.2 × 0.2) = 2.56 ÷ 0.24 = 10.7.', wrong = '{"0": "0.094 is 1 ÷ 10.7, from writing the expression upside down with reactants on top.", "1": "6.7 = 1.6 ÷ 0.24 uses [HI] instead of [HI]². The coefficient 2 must become a power of 2.", "3": "64 = 2.56 ÷ (0.2 × 0.2) wrongly takes [H₂] as 0.2, as if H₂ and I₂ had started in equal amounts."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7051' AND answer = 2;
UPDATE questions SET why = 'Kc = [SO₃]²/([SO₂]²[O₂]). The units are (mol dm⁻³)² on top and (mol dm⁻³)² × (mol dm⁻³) = (mol dm⁻³)³ underneath. This leaves (mol dm⁻³)⁻¹, which is written dm³ mol⁻¹.', wrong = '{"1": "mol dm⁻³ would be the unit if the product side had one more mole of gas than the reactant side. Here it has one fewer.", "2": "dm⁶ mol⁻² would need two fewer moles on the product side than the reactant side. Here the difference is one.", "3": "Kc has no units only when the total moles on each side are equal. Here there are 3 on the left and 2 on the right."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7052' AND answer = 0;
UPDATE questions SET why = 'The reaction quotient uses the same expression as Kc with the present concentrations: Qc = [NO₂]²/[N₂O₄] = 0.20² ÷ 0.20 = 0.040 ÷ 0.20 = 0.20 mol dm⁻³. Since Qc (0.20) is less than Kc (0.36), there is too little product. The forward reaction runs, dissociating more N₂O₄, until Qc reaches 0.36.', wrong = '{"0": "Qc is 0.20, which is smaller than Kc (0.36), not greater. So the reaction moves forward, not backward.", "1": "Equal concentrations do not mean anything special. The direction depends on comparing Qc with Kc.", "3": "The mixture is at equilibrium only when Qc equals Kc. Here 0.20 is not equal to 0.36."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7053' AND answer = 2;
UPDATE questions SET why = 'CaF₂ ⇌ Ca²⁺ + 2F⁻. If the solubility is s, then [Ca²⁺] = s and [F⁻] = 2s. Ksp = s × (2s)² = 4s³ = 4 × (2.0 × 10⁻⁴)³ = 4 × 8.0 × 10⁻¹² = 3.2 × 10⁻¹¹.', wrong = '{"0": "8.0 × 10⁻¹² is just s³. It misses the factor of 4 that comes from squaring 2s for the fluoride ions.", "2": "4.0 × 10⁻⁸ is s², the Ksp expression for a 1 : 1 salt such as AgCl. CaF₂ gives three ions.", "3": "1.6 × 10⁻⁷ is 4s², which leaves out one factor of s."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7054' AND answer = 1;
UPDATE questions SET why = 'NaCl supplies a common ion, Cl⁻, at about 0.10 mol dm⁻³. The dissolved AgCl adds only a tiny amount more. So s = [Ag⁺] = Ksp ÷ [Cl⁻] = 1.8 × 10⁻¹⁰ ÷ 0.10 = 1.8 × 10⁻⁹ mol dm⁻³, roughly 7000 times less than in pure water.', wrong = '{"0": "1.8 × 10⁻¹¹ comes from dividing Ksp by 10 instead of by 0.10.", "1": "1.8 × 10⁻¹⁰ is the value of Ksp itself, not the solubility.", "3": "1.3 × 10⁻⁵ is √Ksp, the solubility in pure water. The common Cl⁻ ion pushes the solubility much lower."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7055' AND answer = 2;
UPDATE questions SET why = 'Precipitation starts when [Ag⁺]²[CrO₄²⁻] reaches Ksp. So [Ag⁺] = √(Ksp ÷ [CrO₄²⁻]) = √(1.1 × 10⁻¹² ÷ 0.010) = √(1.1 × 10⁻¹⁰) = 1.0 × 10⁻⁵ mol dm⁻³. Any higher [Ag⁺] causes Ag₂CrO₄ to precipitate.', wrong = '{"0": "1.1 × 10⁻¹⁴ comes from multiplying Ksp by [CrO₄²⁻] instead of dividing.", "1": "1.1 × 10⁻¹⁰ is [Ag⁺]², not [Ag⁺]. The square root has been forgotten.", "2": "5.2 × 10⁻⁶ is half the correct value. Nothing in the calculation should be halved, since [Ag⁺] itself is asked for."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7056' AND answer = 3;
UPDATE questions SET why = 'The forward reaction is endothermic (ΔH = +58 kJ mol⁻¹). By Le Chatelier''s principle, raising the temperature shifts the equilibrium in the endothermic direction, towards NO₂. Higher temperature also gives more molecules the activation energy, so the rate increases too.', wrong = '{"0": "Removing NO₂ shifts the equilibrium to the right, but it lowers concentrations, so it does not speed up the reaction.", "1": "Higher pressure favours the side with fewer gas moles. Here that is N₂O₄ (1 mol against 2), so the yield of NO₂ falls.", "2": "A catalyst helps equilibrium be reached faster, but it speeds up both directions equally and does not change the yield."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7057' AND answer = 3;
UPDATE questions SET why = 'Adding argon at constant volume raises the total pressure, but the amount and volume of each reacting gas stay the same. So the partial pressures and concentrations of N₂, H₂ and NH₃ do not change. Qc still equals Kc, and the equilibrium does not shift.', wrong = '{"1": "Argon is a noble gas and does not take part in the reaction. It is not a catalyst.", "2": "Only the partial pressures of the reacting gases affect the position. The extra pressure from argon does not change them.", "3": "At constant volume argon does not dilute anything. The concentration of each reacting gas stays the same."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7058' AND answer = 0;
UPDATE questions SET why = 'The forward reaction is exothermic (ΔH = −92 kJ mol⁻¹). Raising the temperature favours the endothermic reverse reaction, so less NH₃ is present at equilibrium and Kc decreases. But all reactions speed up when heated, so equilibrium is reached faster. This is why industry uses a compromise temperature of about 400 to 450 °C.', wrong = '{"1": "Kc does change with temperature. A catalyst is the thing that never changes Kc.", "2": "For an exothermic reaction, Kc gets smaller, not larger, as the temperature rises.", "3": "Kc does decrease, but reaction rates always increase at higher temperature."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7059' AND answer = 0;
UPDATE questions SET why = 'Sulphuric acid is diprotic: when fully dissociated, each H₂SO₄ gives two H⁺ ions (H₂SO₄ → 2H⁺ + SO₄²⁻). So [H⁺] = 2 × 0.0010 = 0.0020 mol dm⁻³, and pH = −log(0.0020) = 2.7.', wrong = '{"0": "pH 2.0 would need [H⁺] = 0.010 mol dm⁻³, five times more than is present.", "2": "pH 3.0 comes from [H⁺] = 0.0010, counting only one H⁺ per H₂SO₄. Sulphuric acid is diprotic.", "3": "pH 3.3 comes from [H⁺] = 0.00050, which halves the acid concentration instead of doubling it."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7060' AND answer = 1;
UPDATE questions SET why = 'Moles: H⁺ = 0.050 × 0.20 = 0.010 mol and OH⁻ = 0.050 × 0.10 = 0.0050 mol. They neutralise 1 : 1, leaving 0.0050 mol H⁺ in a total volume of 100 cm³. [H⁺] = 0.0050 ÷ 0.100 = 0.050 mol dm⁻³, so pH = −log(0.050) = 1.3.', wrong = '{"0": "pH 0.7 = −log(0.20) is the pH of the original acid before any NaOH was added.", "1": "pH 1.0 comes from putting the 0.0050 mol excess in 50 cm³. After mixing, the volume is 100 cm³.", "3": "pH 7.0 would need exactly equal moles of acid and base. Here the acid is in excess."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7061' AND answer = 2;
UPDATE questions SET why = 'Ethanoic acid is weak and only slightly ionised, so [H⁺] = √(Ka × c). [H⁺] = √(1.8 × 10⁻⁵ × 0.10) = √(1.8 × 10⁻⁶) = 1.34 × 10⁻³ mol dm⁻³. pH = −log(1.34 × 10⁻³) = 2.87, about 2.9.', wrong = '{"0": "pH 1.0 treats the weak acid as fully ionised, with [H⁺] = 0.10. That is true only for a strong acid.", "2": "4.7 is the pKa of ethanoic acid. pH equals pKa only in a buffer with equal acid and salt.", "3": "5.7 = −log(Ka × c) leaves out the square root."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7062' AND answer = 1;
UPDATE questions SET why = 'NaOH turns 0.10 mol of the acid into 0.10 mol of sodium ethanoate, leaving 0.10 mol of acid. A weak acid mixed with its salt is a buffer. pH = pKa + log([salt]/[acid]) = 4.74 + log(0.10/0.10) = 4.74 + 0 = 4.74.', wrong = '{"0": "2.87 is roughly the pH of 0.10 mol dm⁻³ ethanoic acid alone, before any NaOH is added.", "2": "Only half the acid is neutralised, so the solution is not neutral. pH 7 is wrong.", "3": "9.26 = 14 − 4.74 is the pKb of the ethanoate ion. The mixture is an acidic buffer, so its pH is below 7."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7063' AND answer = 1;
UPDATE questions SET why = 'The added H⁺ reacts with ethanoate ions: CH₃COO⁻ + H⁺ → CH₃COOH. So acid becomes 0.10 + 0.020 = 0.12 mol and salt becomes 0.10 − 0.020 = 0.08 mol. pH = 4.74 + log(0.08/0.12) = 4.74 − 0.18 = 4.56. The pH drops only slightly, which is what a buffer does.', wrong = '{"0": "1.70 = −log(0.020) is the pH of the HCl in water with no buffer present.", "2": "4.74 would mean no change. Adding acid alters the salt-to-acid ratio, so the pH falls a little.", "3": "4.92 comes from using log(acid/salt) instead of log(salt/acid), which makes the pH go up instead of down."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7064' AND answer = 1;
UPDATE questions SET why = 'Water ionises as H₂O ⇌ H⁺ + OH⁻, and this is endothermic, so Kw rises with temperature. Each molecule that ionises gives one H⁺ and one OH⁻, so [H⁺] = [OH⁻] = √(5.5 × 10⁻¹⁴) = 2.3 × 10⁻⁷ mol dm⁻³, giving pH 6.6. Neutral means [H⁺] = [OH⁻], so the water is still neutral.', wrong = '{"0": "Kw increases because both [H⁺] and [OH⁻] rise by the same amount. The water does not become basic.", "1": "pH 7 means neutral only at 25 °C. At 50 °C the neutral pH is about 6.6.", "2": "Heating does not release H⁺ alone. Every ionisation gives one H⁺ and one OH⁻ together."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7065' AND answer = 3;
UPDATE questions SET why = 'The pH of a salt solution depends on how strongly its ions react with water (hydrolysis). CO₃²⁻ is the conjugate base of the very weak acid HCO₃⁻ (Ka about 5 × 10⁻¹¹), so it takes H⁺ from water strongly and makes many OH⁻ ions. Na₂CO₃ therefore gives the highest pH.', wrong = '{"1": "Ethanoate is the conjugate base of ethanoic acid (Ka 1.8 × 10⁻⁵), so it is only weakly basic, much weaker than carbonate.", "2": "NaCl is a salt of a strong acid and strong base. Neither ion hydrolyses, so its solution is neutral.", "3": "NH₄⁺ gives H⁺ to water when it hydrolyses, so NH₄Cl solution is acidic, with pH below 7."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7066' AND answer = 0;
UPDATE questions SET why = '40% of 2.0 mol is 0.80 mol of PCl₅ dissociated. In 1.0 dm³: [PCl₅] = 2.0 − 0.80 = 1.2 and [PCl₃] = [Cl₂] = 0.80 mol dm⁻³. Kc = [PCl₃][Cl₂]/[PCl₅] = (0.80 × 0.80) ÷ 1.2 = 0.64 ÷ 1.2 = 0.53 mol dm⁻³.', wrong = '{"0": "0.27 = (0.40 × 0.40) ÷ 0.60 uses a starting amount of 1.0 mol instead of 2.0 mol.", "2": "0.64 is just [PCl₃][Cl₂]. It has not been divided by [PCl₅] = 1.2.", "3": "1.9 = 1.2 ÷ 0.64 is the inverse expression, with PCl₅ on top."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7067' AND answer = 1;
UPDATE questions SET why = 'Two rules apply to equilibrium constants. Reversing an equation gives 1/K. Multiplying all coefficients by ½ raises K to the power ½, which is a square root. Doing both gives K′ = (1/K)^½ = 1/√K.', wrong = '{"0": "Equilibrium constants are always positive. Changing an equation inverts K or raises it to a power, never makes it negative.", "1": "√K accounts for halving the coefficients but not for reversing the reaction.", "2": "1/K accounts for reversing the reaction but not for halving the coefficients."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7068' AND answer = 3;
UPDATE questions SET why = 'Compare experiments where one concentration changes. From 1 to 2, [A] doubles with [B] fixed and the rate doubles (2.0 → 4.0 × 10⁻³), so the reaction is first order in A. From 1 to 3, [B] doubles and the rate quadruples (2.0 → 8.0 × 10⁻³), so it is second order in B. Rate = k[A][B]², third order overall.', wrong = '{"0": "k[A]²[B] swaps the orders. Doubling [A] only doubles the rate, so A is first order, not second.", "1": "Doubling [A] only doubles the rate, so the power of [A] is 1, not 2.", "3": "Doubling [B] makes the rate four times faster, so the power of [B] must be 2, not 1."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7069' AND answer = 2;
UPDATE questions SET why = 'For a third-order reaction, rate = k[conc]³, so k = rate ÷ [conc]³. Units: (mol dm⁻³ s⁻¹) ÷ (mol dm⁻³)³ = (mol dm⁻³)⁻² s⁻¹. This is dm⁶ mol⁻² s⁻¹.', wrong = '{"1": "mol dm⁻³ s⁻¹ is the unit of rate, and of k for a zero-order reaction.", "2": "s⁻¹ is the unit of k for a first-order reaction.", "3": "dm³ mol⁻¹ s⁻¹ is the unit of k for a second-order reaction."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7070' AND answer = 0;
UPDATE questions SET why = 'For a first-order reaction the half-life is constant, so the amount halves every 20 minutes. One hour (60 minutes) is 60 ÷ 20 = 3 half-lives. 80 g → 40 g → 20 g → 10 g.', wrong = '{"0": "5 g is left after four half-lives, which is 80 minutes, not one hour.", "2": "20 g is left after two half-lives, which is only 40 minutes.", "3": "26.7 g = 80 ÷ 3 treats the decay as dividing by the number of half-lives. Each half-life halves the amount."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7071' AND answer = 1;
UPDATE questions SET why = 'If 93.75% is used up, 6.25% remains, which is 1/16 of the start. Since 1/16 = (½)⁴, four half-lives are needed. For a first-order reaction each half-life is the same, so the time is 4 × 12 = 48 minutes.', wrong = '{"0": "22.5 minutes = (93.75 ÷ 50) × 12 treats the reaction as linear. Each half-life removes half of what is left, not a fixed amount.", "1": "36 minutes is 3 half-lives. By then 1/8 remains, so only 87.5% has reacted.", "3": "60 minutes is 5 half-lives. By then 1/32 remains, so about 96.9% has reacted."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7072' AND answer = 2;
UPDATE questions SET why = 'The slope of a concentration-time graph is the rate. A straight line has a constant slope, so the rate stays the same even as the reactant is used up. A rate that does not depend on concentration means the reaction is zero order (rate = k), as in some reactions on a saturated catalyst surface.', wrong = '{"0": "A straight line means the slope, and so the rate, is constant. A falling rate would give a curve that flattens out.", "1": "A second-order reaction gives a curve that flattens even more quickly than a first-order one, not a straight line.", "2": "A first-order reaction gives a curve with a constant half-life, not a straight line."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7073' AND answer = 3;
UPDATE questions SET why = 'Halving the volume doubles the concentration of every gas. The new rate = k(2[NO])²(2[O₂]) = 4 × 2 × k[NO]²[O₂]. So the rate becomes 8 times as great.', wrong = '{"0": "2 times allows only for the doubling of [O₂] and ignores the increase in [NO].", "1": "4 times allows only for [NO]² and ignores the doubling of [O₂].", "3": "16 = 2⁴ raises the factor 2 to the fourth power. The overall order is 3, so the factor is 2³ = 8."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7074' AND answer = 2;
UPDATE questions SET why = 'The rate doubles with each 10 °C rise, so after n steps the rate is 2ⁿ times as fast. 32 = 2⁵, so 5 steps are needed, a rise of 5 × 10 = 50 °C. The final temperature is 25 + 50 = 75 °C.', wrong = '{"0": "50 °C is the rise in temperature needed. It must be added to the starting 25 °C.", "1": "57 °C comes from adding 32 to 25. The factor 32 is not a temperature.", "3": "345 °C adds 32 × 10 °C, as if the rate rose by a fixed amount each step. It doubles each step instead."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7075' AND answer = 2;
UPDATE questions SET why = 'The slowest step controls the overall rate. Step 1 involves two NO₂ molecules, so rate = k[NO₂]². NO₃ is made in step 1 and used up in step 2, so it is an intermediate. CO reacts only in the fast step, so it does not appear in the rate equation.', wrong = '{"1": "CO is one of the starting reactants. An intermediate is formed in one step and used in a later one, which is NO₃ here.", "2": "Step 2 is the fast step. The rate equation comes from the slow step, not from the step that forms the products.", "3": "A rate equation cannot be written from the overall equation. It must come from the slow step or from experiment."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7076' AND answer = 0;
UPDATE questions SET why = 'The rates of change are in the same ratio as the coefficients. 2 mol of N₂O₅ give 4 mol of NO₂, so N₂O₅ is used up at half the rate NO₂ forms. Rate = 0.040 ÷ 2 = 0.020 mol dm⁻³ s⁻¹. O₂ forms at 0.040 ÷ 4 = 0.010 mol dm⁻³ s⁻¹.', wrong = '{"0": "0.010 mol dm⁻³ s⁻¹ is the rate at which O₂ is formed (coefficient 1), not the rate N₂O₅ is used.", "2": "0.040 mol dm⁻³ s⁻¹ ignores the 2 : 4 mole ratio between N₂O₅ and NO₂.", "3": "0.080 mol dm⁻³ s⁻¹ uses the ratio the wrong way round, multiplying by 2 instead of dividing."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7077' AND answer = 1;
UPDATE questions SET why = 'ΔH = Ea(forward) − Ea(reverse) = 80 − 120 = −40 kJ mol⁻¹. A catalyst does not change the energies of reactants or products, so ΔH stays −40. It lowers the peak, so both barriers drop by 80 − 50 = 30 kJ mol⁻¹, giving Ea(reverse) = 120 − 30 = 90 kJ mol⁻¹.', wrong = '{"0": "Ea(reverse) is right, but ΔH is set by the reactant and product energies, which a catalyst does not change. It stays −40.", "1": "A catalyst lowers the reverse barrier as well. It cannot rise from 120 to 150 kJ mol⁻¹.", "2": "A catalyst lowers both barriers by the same amount, and ΔH cannot change from −40 kJ mol⁻¹."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7078' AND answer = 3;
UPDATE questions SET why = 'Powdered marble has a far larger surface area than chips, so acid particles collide with it more often and CO₂ is given off faster. That makes the initial slope steeper. The acid is in excess and the mass of CaCO₃ is the same, so both experiments give the same final volume of CO₂.', wrong = '{"1": "The rate depends on the exposed surface area, not just on the mass. Powder exposes much more surface.", "2": "Chips expose less surface, so they react more slowly and give a less steep slope.", "3": "The final volume depends on the amount of CaCO₃. Equal masses give the same amount of CO₂."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7079' AND answer = 0;
UPDATE questions SET why = 'For a second-order reaction, t½ = 1/(k[A]₀). The half-life is inversely proportional to the starting concentration. So halving [A]₀ doubles the half-life, as described.', wrong = '{"0": "For a zero-order reaction, t½ = [A]₀/2k, so halving [A]₀ would halve the half-life.", "1": "For a third-order reaction, t½ depends on 1/[A]₀², so halving [A]₀ would make it four times longer.", "2": "For a first-order reaction, t½ = 0.693/k, which does not depend on the starting concentration at all."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7080' AND answer = 3;
UPDATE questions SET why = 'By Hess''s law, ΔHf = sum of ΔHc of reactants − ΔHc of the product. Reactants: 2(−394) + 3(−286) = −788 − 858 = −1646 kJ. So ΔHf = −1646 − (−1367) = −279 kJ mol⁻¹.', wrong = '{"0": "−3013 kJ mol⁻¹ = −1646 + (−1367) adds the ethanol term instead of subtracting it.", "1": "−1367 kJ mol⁻¹ is the enthalpy of combustion of ethanol, given in the question, not its enthalpy of formation.", "3": "+279 kJ mol⁻¹ has the sign reversed. It subtracts the reactants'' combustion values from the product''s."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7081' AND answer = 2;
UPDATE questions SET why = 'ΔH = energy of bonds broken − energy of bonds formed. Broken: ½(436) + ½(193) = 314.5 kJ. So −52 = 314.5 − E(H–Br), giving E(H–Br) = 314.5 + 52 = 366 kJ mol⁻¹.', wrong = '{"0": "263 kJ mol⁻¹ = 314.5 − 52 subtracts 52 instead of adding it, a sign error.", "1": "315 kJ mol⁻¹ is only the energy to break half a mole each of H–H and Br–Br. It leaves out ΔH.", "3": "681 kJ mol⁻¹ = 436 + 193 + 52 uses whole moles of H₂ and Br₂, but the equation has only half a mole of each."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7082' AND answer = 2;
UPDATE questions SET why = 'Only the bonds that change are counted. Broken: one C–H and one Cl–Cl, 413 + 243 = 656 kJ. Formed: one C–Cl and one H–Cl, 346 + 432 = 778 kJ. ΔH = 656 − 778 = −122 kJ mol⁻¹. The other three C–H bonds are unchanged.', wrong = '{"0": "−778 kJ mol⁻¹ counts only the energy released by bonds formed and forgets the energy needed to break bonds.", "1": "−365 kJ mol⁻¹ = 413 − 778 leaves out the Cl–Cl bond, which also has to be broken.", "3": "+122 kJ mol⁻¹ has the sign reversed. More energy is released forming bonds than is used breaking them, so ΔH is negative."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7083' AND answer = 2;
UPDATE questions SET why = 'Heat gained by water: q = mcΔT = 200 × 4.18 × 30.0 = 25 080 J = 25.08 kJ. Methanol burned = 1.60 ÷ 32 = 0.0500 mol. ΔHc = −25.08 ÷ 0.0500 = −502 kJ mol⁻¹. The data-book value, about −726 kJ mol⁻¹, is larger because heat is lost to the air and apparatus.', wrong = '{"0": "−1003 kJ mol⁻¹ divides by 0.025 mol, half the amount of methanol actually burned.", "2": "−251 kJ mol⁻¹ divides by 0.100 mol, double the amount of methanol actually burned.", "3": "−25.1 is the heat released in kJ by this sample. It has not been divided by the moles of methanol."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7084' AND answer = 1;
UPDATE questions SET why = 'HCl = 0.050 × 2.0 = 0.10 mol and NaOH = 0.050 × 1.0 = 0.050 mol. NaOH is limiting, so only 0.050 mol of water forms. Heat = 0.050 × 57 000 = 2850 J, and ΔT = q ÷ (mc) = 2850 ÷ (100 × 4.18) = 6.8 °C.', wrong = '{"0": "3.4 °C is half the correct rise. It uses only 0.025 mol of water formed.", "2": "10.2 °C uses 0.075 mol, the average of the acid and alkali amounts. Only the limiting 0.050 mol reacts.", "3": "13.6 °C uses 0.10 mol, the amount of HCl. The NaOH runs out first, so only 0.050 mol reacts."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7085' AND answer = 1;
UPDATE questions SET why = 'Only gases count in Δn. Products have 1 mol of gas (CO₂, since water is liquid) and reactants have 1 + 2 = 3, so Δn = −2. ΔnRT = −2 × 8.314 × 298 = −4955 J, about −5 kJ. So ΔH = ΔE − 5 kJ, meaning ΔH is about 5 kJ mol⁻¹ more negative than ΔE.', wrong = '{"1": "The total moles (3 and 3) are equal, but only gas moles count. Gas moles fall from 3 to 1.", "2": "Δn is negative, so ΔnRT is negative and ΔH is more negative than ΔE, not less.", "3": "2.5 kJ mol⁻¹ uses Δn = −1. Liquid water must not be counted as gas, so Δn = −2."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7086' AND answer = 0;
UPDATE questions SET why = 'By the first law, ΔE = q + w. In a rigid bomb calorimeter the volume cannot change, so no expansion work is done (w = −PΔV = 0). Then qᵥ = ΔE, and the heat released equals −ΔE. At constant pressure the heat would equal ΔH instead.', wrong = '{"0": "No such combination applies. At constant volume the heat change is simply ΔE.", "1": "Gases cannot do expansion work when the volume is fixed, so the work done is zero.", "2": "Heat equals ΔH only at constant pressure. At constant volume it equals ΔE."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7087' AND answer = 3;
UPDATE questions SET why = 'The enthalpy of formation is for 1 mol of a compound made from its elements in their standard states. The enthalpy of combustion is for 1 mol of a substance burned completely in oxygen. Burning 1 mol of graphite, carbon''s standard state, to give 1 mol of CO₂ fits both definitions.', wrong = '{"1": "This is the combustion of diamond, but diamond is not the standard state of carbon, so it is not the formation of CO₂.", "2": "CO is a compound, not an element, so this is not a formation reaction. It is only the combustion of CO.", "3": "This burns 2 mol of H₂ and forms 2 mol of water. Both definitions are for 1 mol, so ΔH must be halved."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7088' AND answer = 0;
UPDATE questions SET why = 'Hess''s law lets equations be added like algebra. Keep the Al equation (ΔH = −1676 kJ) and reverse the Fe equation (Fe₂O₃ → 2Fe + 3⁄2O₂, ΔH = +824 kJ). Adding them cancels the O₂: ΔH = −1676 + 824 = −852 kJ.', wrong = '{"0": "−2500 kJ adds both equations as written, without reversing the iron equation.", "2": "−426 kJ is half the correct value. The thermite equation uses 2 mol Al and 1 mol Fe₂O₃, matching the given equations.", "3": "+852 kJ has the wrong sign. It reverses the aluminium equation instead of the iron one."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7089' AND answer = 1;
UPDATE questions SET why = 'Dissolving ammonium nitrate is endothermic, so ΔH is positive. The system (the dissolving salt) takes in heat from its surroundings, the water and the beaker. Losing that heat makes the surroundings, and so the beaker, feel cold.', wrong = '{"0": "ΔH is positive, but an endothermic system absorbs heat. It does not release it to the surroundings.", "1": "A fall in temperature of the surroundings shows heat flowed into the system, so ΔH is positive, not negative.", "2": "The cooling comes from the dissolving process itself, which absorbs energy. It is not caused by evaporation."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7090' AND answer = 3;
UPDATE questions SET why = 'ΔH and ΔE are state functions: they depend only on the starting and final states, so they must be the same for both routes. Heat (q) and work (w) depend on the path taken and can differ. Only their sum, q + w = ΔE, is fixed.', wrong = '{"0": "Heat and work are path functions. They can have different values on different routes.", "1": "ΔH and ΔE must match, but q and w can differ between the two routes.", "2": "Heat depends on the route taken, so q need not be the same for both routes."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7091' AND answer = 3;
UPDATE questions SET why = 'With a strong acid such as HCl, neutralisation is just H⁺ + OH⁻ → H₂O, releasing about −57 kJ mol⁻¹. Ethanoic acid is weak and mostly un-ionised. Some of the heat released is used to complete its ionisation, which is slightly endothermic, so less heat comes out overall.', wrong = '{"1": "Ethanoic acid is a weak acid and HCl is a strong acid, not the other way round.", "2": "Both acids are monoprotic, so each forms 1 mol of water per mole of acid.", "3": "Both sodium ethanoate and sodium chloride stay dissolved. Solubility is not the cause."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7092' AND answer = 0;
UPDATE questions SET why = 'Mg has the more negative E°, so it is oxidised at the anode, and Ag⁺ is reduced at the cathode. E°cell = E°(cathode) − E°(anode) = +0.80 − (−2.37) = 3.17 V. Electrode potentials are not multiplied when the equation is multiplied by 2.', wrong = '{"0": "1.57 V comes from adding −2.37 and +0.80. The anode potential must be subtracted, not added.", "1": "2.37 V is just the size of the magnesium electrode potential. The silver half-cell also contributes.", "3": "3.97 V doubles the silver potential because of the 2Ag⁺. E° values do not depend on the number of electrons."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7093' AND answer = 2;
UPDATE questions SET why = 'A metal can reduce the ions of another metal only if that metal''s E° is more positive than its own, giving a positive E°cell. For Cu + Fe²⁺, Fe²⁺ would be reduced and Cu oxidised: E°cell = −0.44 − (+0.34) = −0.78 V. A negative value means this reaction does not occur.', wrong = '{"1": "Zn reduces Fe²⁺: E°cell = −0.44 − (−0.76) = +0.32 V, which is positive, so it is feasible.", "2": "Cu reduces Ag⁺: E°cell = +0.80 − (+0.34) = +0.46 V, which is positive, so it is feasible.", "3": "Fe reduces Cu²⁺: E°cell = +0.34 − (−0.44) = +0.78 V, which is positive, so it is feasible."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7094' AND answer = 0;
UPDATE questions SET why = 'In an ion, the oxidation numbers add up to the charge, with O = −2. For S₂O₃²⁻: 2x + 3(−2) = −2, so 2x = +4 and x = +2. The other species give different values for sulphur.', wrong = '{"0": "In H₂S: 2(+1) + x = 0, so sulphur is −2, its lowest oxidation state.", "1": "In SO₃²⁻: x + 3(−2) = −2, so sulphur is +4, not +2.", "2": "In S₄O₆²⁻: 4x + 6(−2) = −2, so 4x = +10 and the average is +2.5."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7095' AND answer = 3;
UPDATE questions SET why = 'Each Cr changes from +6 in Cr₂O₇²⁻ to +3 in Cr³⁺, gaining 3 electrons. Two Cr atoms gain 2 × 3 = 6 electrons. Each Fe²⁺ loses only one electron (Fe²⁺ → Fe³⁺), so 6 Fe²⁺ are needed per Cr₂O₇²⁻.', wrong = '{"0": "2 just matches the number of Cr atoms. The electrons must balance, and 2 Fe²⁺ give only 2 electrons.", "1": "3 counts the electrons gained by only one Cr atom. The dichromate ion has two.", "2": "5 is the ratio for MnO₄⁻, which gains 5 electrons. Dichromate gains 6."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7096' AND answer = 3;
UPDATE questions SET why = 'Moles of Fe²⁺ = 0.0250 × 0.10 = 2.5 × 10⁻³ mol. The equation needs 1 MnO₄⁻ for 5 Fe²⁺, so MnO₄⁻ = 2.5 × 10⁻³ ÷ 5 = 5.0 × 10⁻⁴ mol. Volume = 5.0 × 10⁻⁴ ÷ 0.020 = 0.025 dm³ = 25.0 cm³.', wrong = '{"0": "5.0 cm³ comes from dividing by 5 twice, giving only 1.0 × 10⁻⁴ mol of MnO₄⁻.", "1": "12.5 cm³ corresponds to a 1 : 10 ratio. The equation shows 1 MnO₄⁻ to 5 Fe²⁺.", "3": "125 cm³ uses a 1 : 1 ratio, taking 2.5 × 10⁻³ mol of MnO₄⁻. Each MnO₄⁻ oxidises five Fe²⁺."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7097' AND answer = 2;
UPDATE questions SET why = 'At the cathode Al³⁺ + 3e⁻ → Al, so each Al atom needs 3 electrons. Al = 0.90 ÷ 27 = 0.0333 mol, needing 3 × 0.0333 = 0.100 mol of electrons. Charge Q = 0.100 × 96 500 = 9650 C, and time t = Q ÷ I = 9650 ÷ 9.65 = 1000 s.', wrong = '{"0": "100 s passes only 965 C, which is 0.010 mol of electrons. That deposits just 0.090 g of Al, a tenth of the mass needed.", "1": "333 s forgets that each Al³⁺ needs three electrons. It uses 0.0333 mol of electrons instead of 0.100 mol.", "3": "3000 s multiplies by 3 twice, using 0.300 mol of electrons instead of 0.100 mol."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7098' AND answer = 2;
UPDATE questions SET why = 'Cathode: 4H⁺ + 4e⁻ → 2H₂. Anode: 2H₂O → O₂ + 4H⁺ + 4e⁻. The same 4 electrons make 2 molecules of H₂ but only 1 molecule of O₂. By Avogadro''s law volumes follow the same 2 : 1 ratio, so 30 cm³ of H₂ comes with 15 cm³ of O₂.', wrong = '{"1": "Equal volumes would need the same number of electrons per molecule. O₂ needs 4 electrons but H₂ only 2.", "2": "Sulphate ions are not discharged at the anode. Water is oxidised to oxygen instead.", "3": "60 cm³ reverses the ratio. The volume of oxygen is half that of hydrogen, not double."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7099' AND answer = 0;
UPDATE questions SET why = 'The SHE is defined at standard conditions: 1.0 mol dm⁻³ H⁺, H₂ gas at 1 atm (101 kPa) and 298 K. Its potential comes from the equilibrium 2H⁺ + 2e⁻ ⇌ H₂. Lowering [H⁺] to 0.10 mol dm⁻³ shifts this equilibrium, so the potential is no longer 0.00 V.', wrong = '{"1": "The potential depends on concentrations, pressure and temperature, not on the size of the platinum electrode.", "2": "What matters is the pressure of the hydrogen gas. Bubbling faster at the same pressure does not change it.", "3": "The SHE''s own potential is fixed by its conditions. Only the overall cell e.m.f. depends on the other half-cell."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7100' AND answer = 0;
UPDATE questions SET why = 'To oxidise Cl⁻ to Cl₂, an oxidising agent needs an E° more positive than +1.36 V. Of those listed, only acidified MnO₄⁻ (+1.51 V) qualifies. This is why KMnO₄ titrations are acidified with H₂SO₄ and not HCl, since HCl would be oxidised.', wrong = '{"0": "Acidified dichromate has E° = +1.33 V, slightly below +1.36 V, so under standard conditions it cannot oxidise Cl⁻.", "2": "Br₂ has E° = +1.07 V, well below +1.36 V. In fact Cl₂ oxidises Br⁻, not the other way round.", "3": "Acidified MnO₄⁻, at +1.51 V, has a high enough E° to oxidise Cl⁻."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7101' AND answer = 1;
UPDATE questions SET why = 'In disproportionation, the same element in one oxidation state is both oxidised and reduced. Here chlorine starts at 0 in Cl₂. Some becomes Cl⁻ (−1, reduced) and some becomes ClO₃⁻ (+5, oxidised).', wrong = '{"0": "Here Cl is reduced (+5 → −1) but a different element, oxygen, is oxidised (−2 → 0). That is not disproportionation.", "1": "Zinc is oxidised and copper is reduced. Two different elements are involved, so this is a displacement reaction.", "2": "Sulphur starts in two different states (−2 and +4) and ends at one (0). This is the reverse of disproportionation (comproportionation)."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7102' AND answer = 3;
UPDATE questions SET why = 'A reducing agent is oxidised itself. Only the Cl atoms that become Cl₂ (−1 → 0) are oxidised. 5Cl₂ contains 10 Cl atoms, so 10 of the 16 HCl act as reducing agents: 10/16 = 5/8. The other 6 Cl stay as Cl⁻ in 2KCl and 2MnCl₂.', wrong = '{"0": "Not all the HCl is oxidised. Six Cl atoms stay as Cl⁻ ions in KCl and MnCl₂.", "1": "Half would be 8 of 16. In fact 10 of the 16 Cl atoms end up in Cl₂.", "3": "3/8 (6 of 16) is the fraction that only supplies Cl⁻ ions to form salts. It is not oxidised."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7103' AND answer = 2;
UPDATE questions SET why = 'At the zinc anode, Zn → Zn²⁺ + 2e⁻ adds positive ions to the solution. To keep it electrically neutral, negative NO₃⁻ ions from the salt bridge move into the zinc half-cell. At the same time K⁺ ions move into the copper half-cell, where Cu²⁺ is being removed.', wrong = '{"1": "Removing Cu²⁺ leaves extra negative charge in the copper half-cell, so positive K⁺ ions move there, not NO₃⁻.", "2": "Electrons travel through the external wire, not the salt bridge. Anions move towards the anode compartment.", "3": "The ions must move to keep both solutions neutral. If they did not, charge would build up and the current would stop."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7104' AND answer = 0;
UPDATE questions SET why = 'NH₄⁺ has four bonding pairs and no lone pair around nitrogen. Four equal pairs repel each other equally and point to the corners of a regular tetrahedron, at exactly 109.5°. In the other species a lone pair, which repels more strongly, squeezes the bond angles below 109.5°.', wrong = '{"0": "H₃O⁺ has three bonding pairs and one lone pair, which pushes the bond angles down to about 107°.", "1": "NH₃ has one lone pair, which reduces the H–N–H angle to about 107°.", "2": "H₂O has two lone pairs, which reduce the H–O–H angle even further, to about 104.5°."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7105' AND answer = 3;
UPDATE questions SET why = 'A molecule with polar bonds is non-polar overall if its shape makes the bond dipoles cancel. CO₂ is linear, so its two C=O dipoles point in opposite directions. BCl₃ is trigonal planar with three equal B–Cl dipoles at 120°, which also cancel exactly.', wrong = '{"0": "H₂O is bent and NH₃ is pyramidal. Their bond dipoles do not cancel, so both molecules are polar.", "1": "CO₂ is non-polar, but SO₂ is bent because of a lone pair on sulphur, so it is polar.", "2": "CCl₄ is non-polar, but in CHCl₃ the C–H and C–Cl dipoles are unequal and do not cancel, so it is polar."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7106' AND answer = 3;
UPDATE questions SET why = 'The middle carbon forms two σ bonds, one to each CH₂ carbon, and two π bonds. It needs only two hybrid orbitals for its σ bonds, so it is sp hybridised and the C=C=C unit is linear (180°). Its two leftover p orbitals form the two π bonds. The end carbons are sp².', wrong = '{"0": "An sp³ carbon forms four σ bonds and no π bonds. The middle carbon here has two π bonds.", "2": "sp² describes the two end carbons, which each form three σ bonds and one π bond, not the middle one.", "3": "dsp² hybridisation uses d orbitals, which carbon does not have in its valence shell."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7107' AND answer = 1;
UPDATE questions SET why = 'Every bond has one σ bond. A double bond adds one π and a triple bond adds two π. σ bonds: three C–H, one in C=C, one C–C and one in C≡N, which is 6. π bonds: one in C=C and two in C≡N, which is 3.', wrong = '{"0": "7 σ and 2 π miscounts the bonds. There are only six bonds in total, each with one σ, and the C≡N has two π bonds.", "1": "6 σ is right, but a triple bond contains two π bonds, so the total π count is 3, not 2.", "3": "5 σ and 4 π gives the C≡N too many π bonds. A triple bond is one σ and two π."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7108' AND answer = 2;
UPDATE questions SET why = 'Ammonia has three bonding pairs and one lone pair around nitrogen, which gives a trigonal pyramidal shape. H₃O⁺ also has three bonding pairs and one lone pair around oxygen. So it has the same trigonal pyramidal shape.', wrong = '{"1": "CH₃⁺ has three bonding pairs and no lone pair around carbon, so it is trigonal planar, not pyramidal.", "2": "BF₃ has three bonding pairs and no lone pair on boron, so it is trigonal planar.", "3": "SO₃ has no lone pair on sulphur and three bonding regions, so it is trigonal planar."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7109' AND answer = 0;
UPDATE questions SET why = 'An ionic bond gains covalent character when the cation distorts (polarises) the anion''s electron cloud. A small cation polarises strongly, and a large anion is easily distorted. Li⁺ is the smallest cation here and I⁻ the largest anion, so LiI is the most covalent.', wrong = '{"0": "Na⁺ is larger than Li⁺, so it polarises less, and Cl⁻ is smaller than I⁻, so it is harder to distort.", "2": "Li⁺ polarises strongly, but F⁻ is small and hard to distort, so LiF stays mainly ionic.", "3": "Cs⁺ is large and polarises weakly, and F⁻ is hard to distort. CsF is one of the most ionic compounds."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7110' AND answer = 1;
UPDATE questions SET why = 'A double bond is one σ bond plus one π bond. The π bond forms by sideways overlap of p orbitals, which is less effective than the head-on overlap of a σ bond. So the π bond adds only about 614 − 348 = 266 kJ mol⁻¹, less than another σ bond would.', wrong = '{"0": "A double bond contains one σ and one π bond, not two σ bonds.", "1": "C=C (134 pm) is shorter than C–C (154 pm), not longer.", "3": "The carbons in a C=C bond are sp² hybridised. sp³ carbons form only single bonds."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7111' AND answer = 2;
UPDATE questions SET why = 'In the trans isomer the two C–Cl bond dipoles point in opposite directions and cancel, so the molecule is non-polar. In the cis isomer they lie on the same side and add up, giving a net dipole. The cis isomer therefore has dipole–dipole forces as well as London forces, so it boils higher.', wrong = '{"0": "Neither isomer can hydrogen bond, because neither has H attached to N, O or F.", "1": "Both isomers have the same formula, C₂H₂Cl₂, with two chlorine atoms each.", "2": "Isomers have the same molecular formula and so the same molar mass."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7112' AND answer = 3;
UPDATE questions SET why = 'In a coordinate bond, both shared electrons come from the same atom. In CH₄ each C–H bond is made from one electron of carbon and one of hydrogen, so there is no coordinate bond. NH₄⁺ and H₃O⁺ form when a lone pair is donated to H⁺, and in CO oxygen donates a pair to carbon.', wrong = '{"1": "In CO there is a triple bond, and one of its three pairs is donated by oxygen to carbon, a coordinate bond.", "2": "H₃O⁺ forms when H₂O donates a lone pair from oxygen to an H⁺ ion, making a coordinate bond.", "3": "NH₄⁺ forms when NH₃ donates its lone pair to H⁺. Once formed, all four N–H bonds are identical."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7113' AND answer = 0;
UPDATE questions SET why = 'In BF₃ boron has three bonding pairs, so it is sp² hybridised and trigonal planar, with one empty p orbital. When NH₃ donates its lone pair into that orbital, boron has four electron pairs. It becomes sp³ hybridised and tetrahedral.', wrong = '{"0": "After accepting the lone pair, boron has four electron pairs, so it must use four hybrid orbitals (sp³).", "1": "BF₃ starts as sp², not sp. An sp boron would be linear.", "2": "Boron goes from three electron pairs to four, so it changes from sp² to sp³, not the reverse."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7114' AND answer = 3;
UPDATE questions SET why = 'In 2-nitrophenol the –OH and –NO₂ groups are next to each other, so they hydrogen bond within the same molecule (intramolecular). This leaves little hydrogen bonding between molecules, so 2-nitrophenol is volatile and distils in steam. In 4-nitrophenol the groups are far apart and hydrogen bond between molecules, making it much less volatile.', wrong = '{"0": "The two compounds are isomers with the same formula, so they have the same molar mass.", "1": "2-Nitrophenol forms fewer intermolecular hydrogen bonds, not more. That is why it is more volatile.", "3": "Acid strength does not decide how easily a compound evaporates. Intermolecular forces do."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7115' AND answer = 2;
UPDATE questions SET why = 'A higher bond order means a shorter bond. CH₃OH has a C–O single bond (about 143 pm). In CO₃²⁻ resonance spreads one double bond over three bonds, giving each a bond order of 1⅓ (about 129 pm). CO₂ has two C=O double bonds (about 116 pm). So CH₃OH > CO₃²⁻ > CO₂.', wrong = '{"0": "This is the reverse order. The C=O double bonds in CO₂ are the shortest, not the longest.", "2": "CO₂ has full double bonds, which are shorter than carbonate''s bonds of order 1⅓.", "3": "The carbonate bonds (order 1⅓) are shorter than the C–O single bond in methanol, not longer."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7116' AND answer = 1;
UPDATE questions SET why = 'A small cation with a high charge density, such as Mg²⁺, pulls on the electron cloud of the large CO₃²⁻ ion. This polarisation weakens a C–O bond, so CO₂ is released at a lower temperature. Down the group the cations get larger, polarise less, and the carbonates need more heat to decompose.', wrong = '{"1": "The metals actually become more reactive down Group 2. That does not explain the stability of their carbonates.", "2": "Larger cations have a lower charge density, so they attract and distort the carbonate ion less, not more.", "3": "Lattice energies become less exothermic down the group as the ions get larger, not more."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7117' AND answer = 0;
UPDATE questions SET why = 'Group 2 hydroxides and sulphates show opposite trends. Hydroxides become more soluble down the group: Mg(OH)₂ is sparingly soluble but Ba(OH)₂ is fairly soluble. Sulphates become less soluble: MgSO₄ dissolves well but BaSO₄ is almost insoluble, which is why it is safe for barium meals.', wrong = '{"0": "The sulphates do become less soluble, but the hydroxides become more soluble down the group.", "1": "Both trends are reversed. Mg(OH)₂ is less soluble than Ba(OH)₂, and MgSO₄ is more soluble than BaSO₄.", "2": "The hydroxide part is right, but sulphate solubility falls down the group, so BaSO₄ is less soluble than MgSO₄."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7118' AND answer = 3;
UPDATE questions SET why = 'The equation is Ca + 2H₂O → Ca(OH)₂ + H₂, so 1 mol Ca gives 1 mol H₂. Ca = 0.40 ÷ 40 = 0.010 mol, giving 0.010 mol H₂. At STP, 1 mol of gas is 22 400 cm³, so the volume is 0.010 × 22 400 = 224 cm³.', wrong = '{"0": "22.4 cm³ is 0.0010 mol, ten times too little. It may come from treating 22.4 dm³ as 2240 cm³.", "1": "112 cm³ is 0.0050 mol, which assumes 2 mol Ca give 1 mol H₂. The ratio is 1 : 1.", "3": "448 cm³ is 0.020 mol, which assumes each Ca gives 2 mol H₂. The two waters give one H₂ between them."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7119' AND answer = 2;
UPDATE questions SET why = 'Be²⁺ is very small, so its charge density is close to that of Al³⁺. This diagonal relationship makes beryllium behave like aluminium. Like Al₂O₃, BeO and Be(OH)₂ are amphoteric, dissolving in both acids and alkalis.', wrong = '{"1": "Be(OH)₂ is amphoteric, not a strong base. Strongly basic hydroxides appear lower in Group 2, such as Ba(OH)₂.", "2": "Beryllium does not react with water or even steam. Vigorous reaction with cold water is typical of Ca, Sr and Ba.", "3": "BeCl₂ is covalent, like AlCl₃, with a low melting point. It is not a high-melting ionic solid."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7120' AND answer = 0;
UPDATE questions SET why = 'Group 2 nitrates break down completely on strong heating, giving the oxide, brown NO₂ gas and oxygen: 2Mg(NO₃)₂ → 2MgO + 4NO₂ + O₂. Sodium and potassium nitrates only lose oxygen to form nitrites, for example 2NaNO₃ → 2NaNO₂ + O₂, and give no brown gas.', wrong = '{"0": "KNO₃ decomposes only to potassium nitrite and colourless oxygen, so no brown fumes appear.", "2": "NaNO₃ decomposes only to sodium nitrite and colourless oxygen, so no brown fumes appear.", "3": "Magnesium nitrate does give brown NO₂ fumes on heating, so \"none of these\" is not correct."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7121' AND answer = 1;
UPDATE questions SET why = 'The equation is MgCO₃ → MgO + CO₂. MgCO₃ (M = 84) = 8.4 ÷ 84 = 0.10 mol, giving 0.10 mol of MgO (M = 40), which is 4.0 g. The other 4.4 g leaves as CO₂ gas.', wrong = '{"0": "2.0 g is 0.05 mol of MgO, half the true amount. MgCO₃ and MgO are in a 1 : 1 ratio.", "2": "4.4 g is the mass of CO₂ given off (0.10 × 44), not the solid left behind.", "3": "5.6 g uses the molar mass of CaO (56) instead of MgO (40)."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7122' AND answer = 1;
UPDATE questions SET why = 'I⁻ is the strongest reducing agent among the halide ions, so chlorine oxidises it first: Cl₂ + 2I⁻ → 2Cl⁻ + I₂. Any Br₂ that forms would also oxidise I⁻ straight away. Iodine dissolves in hexane with a violet colour, so violet appears first. Orange bromine appears only after the iodide is used up.', wrong = '{"0": "Bromide is oxidised only after the iodide is gone. Any Br₂ formed earlier would itself oxidise I⁻.", "1": "Chlorine is a stronger oxidising agent than both bromine and iodine, so it does react.", "2": "Chlorine reacts with the halide ions instead of simply dissolving in the hexane, so its pale colour is not seen."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7123' AND answer = 3;
UPDATE questions SET why = 'NaI and concentrated H₂SO₄ do form some HI at first. But I⁻ is a strong reducing agent, so it reduces the sulphuric acid to SO₂, S and even H₂S, and is itself oxidised to iodine. So pure HI cannot be collected. Phosphoric acid, which is not an oxidising agent, is used instead.', wrong = '{"1": "HI is the strongest acid of the hydrogen halides, so weakness is not the problem.", "2": "NaI does react with the acid. The trouble is that the HI formed is then oxidised to iodine.", "3": "HI is the least stable hydrogen halide, with the weakest H–X bond. It does not stay behind because of stability."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7124' AND answer = 0;
UPDATE questions SET why = 'For an acid to release H⁺, its H–X bond must break. Down the group the halogen atom gets larger, so the H–X bond becomes longer and weaker (about 562 kJ mol⁻¹ for HF, 299 kJ mol⁻¹ for HI). HI therefore ionises most easily and is the strongest acid, even though HF has the most polar bond.', wrong = '{"0": "Halide ions get larger, not smaller, from F⁻ to I⁻.", "1": "Bond polarity decreases from HF to HI, because electronegativity falls. Polarity alone would predict the opposite order.", "3": "Electronegativity decreases from F to I, not increases."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7125' AND answer = 2;
UPDATE questions SET why = 'Electrons lost per atom equal the rise in oxidation number. Nitrogen is −3 in NH₃ and goes through +2 in NO and +4 in NO₂ to +5 in HNO₃. The overall change is +5 − (−3) = 8, so 8 electrons are lost per nitrogen atom.', wrong = '{"0": "2 is the oxidation number of N in NO, an intermediate step. It is not the overall change.", "1": "3 is only the size of nitrogen''s oxidation number in NH₃, ignoring the sign and the final value.", "2": "5 is only the final oxidation number of N in HNO₃. The starting value of −3 must also be counted."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7126' AND answer = 3;
UPDATE questions SET why = 'Each S atom ends up in one H₂SO₄ molecule, so 1 mol S gives 1 mol H₂SO₄. 32 kg of S is 1000 mol, which in theory gives 1000 mol × 98 g mol⁻¹ = 98 kg of H₂SO₄. At 96% yield, the mass is 0.96 × 98 = 94 kg.', wrong = '{"0": "31 kg = 0.96 × 32 applies the yield to the mass of sulphur instead of to the mass of acid.", "1": "47 kg is half of 94 kg. Each S atom gives one H₂SO₄, so nothing should be halved.", "3": "98 kg is the theoretical yield at 100%. The process gives only 96% of this."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7127' AND answer = 2;
UPDATE questions SET why = 'Moles of sucrose = 34.2 ÷ 342 = 0.10 mol. Each molecule contains 12 carbon atoms, so 0.10 mol gives 12 × 0.10 = 1.2 mol of carbon. Mass of carbon = 1.2 × 12 = 14.4 g.', wrong = '{"0": "7.2 g is 0.60 mol of carbon, half the true amount.", "1": "12.0 g is 1 mol of carbon. 0.10 mol of sucrose actually gives 1.2 mol.", "3": "28.8 g is 2.4 mol of carbon, double the true amount."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7128' AND answer = 2;
UPDATE questions SET why = 'Silicon is larger than carbon and has empty 3d orbitals of fairly low energy. A water molecule can attack Si and donate a lone pair into one of them, which starts the hydrolysis to SiO₂ and HCl. Carbon is small, crowded by four Cl atoms, and has no d orbitals in its valence shell, so water cannot attack CCl₄.', wrong = '{"1": "CCl₄ is a covalent molecule, not an ionic compound.", "2": "Carbon (2.5) is more electronegative than silicon (about 1.9), not the other way round.", "3": "The Si–Cl bond is actually more polar than C–Cl, which also helps water attack the silicon."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7129' AND answer = 0;
UPDATE questions SET why = 'The inert pair effect means that down Group 14 the ns² electrons are less often used, so +2 becomes more stable than +4. For lead, +2 is the stable state, so Pb(IV) in PbO₂ readily gains electrons and is a strong oxidising agent. For carbon, +4 is the stable state, so C(II) in CO readily loses electrons and acts as a reducing agent.', wrong = '{"0": "Carbon is most stable in the +4 state, as in CO₂ and CH₄. The +2 state is the less stable one for carbon.", "2": "This does not describe the trend. Tin forms both +4 and +2 compounds, and tin(II) acts as a reducing agent.", "3": "CO₂ is stable because carbon prefers +4, and PbO is stable because lead prefers +2. Neither is a strong oxidant or reductant."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7130' AND answer = 1;
UPDATE questions SET why = 'Moles of Al = 2.7 ÷ 27 = 0.10 mol. The equation shows 2 mol Al giving 3 mol H₂, so H₂ = 0.10 × 3/2 = 0.15 mol. At STP this is 0.15 × 22.4 = 3.36 dm³. Reacting with an alkali shows that aluminium is amphoteric.', wrong = '{"0": "1.12 dm³ is 0.050 mol, which assumes 2 mol Al give only 1 mol H₂.", "1": "2.24 dm³ is 0.10 mol, which assumes a 1 : 1 ratio of Al to H₂ instead of 2 : 3.", "3": "6.72 dm³ is 0.30 mol, double the correct amount."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7131' AND answer = 2;
UPDATE questions SET why = 'A base drives ammonia out of an ammonium salt: NH₄Cl + NaOH → NaCl + NH₃ + H₂O. Moles of NH₄Cl = 5.35 ÷ 53.5 = 0.10 mol, which gives 0.10 mol NH₃. At STP the volume is 0.10 × 22.4 = 2.24 dm³.', wrong = '{"0": "1.12 dm³ is 0.050 mol, half the ammonia. The ratio of NH₄Cl to NH₃ is 1 : 1.", "2": "4.48 dm³ is 0.20 mol, double the ammonia that 0.10 mol of NH₄Cl can give.", "3": "22.4 dm³ is the volume of a whole mole of gas. Only 0.10 mol is formed here."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7132' AND answer = 1;
UPDATE questions SET why = 'Transition metal ions are coloured because an electron moves between split d orbitals, absorbing visible light (a d–d transition). This needs a partly filled d subshell. Sc³⁺ is 3d⁰ (no d electrons) and Zn²⁺ is 3d¹⁰ (full), so neither can do this and both are colourless.', wrong = '{"1": "Cu⁺ (3d¹⁰) is colourless, but Fe³⁺ (3d⁵) has a partly filled d subshell and is yellow-brown in solution.", "2": "Sc³⁺ is colourless, but Ti³⁺ (3d¹) has one d electron that can be excited, so it is purple.", "3": "Zn²⁺ is colourless, but Cu²⁺ (3d⁹) has a partly filled d subshell and is blue."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7133' AND answer = 0;
UPDATE questions SET why = 'In [Fe(CN)₆]³⁻, each cyanide ligand is CN⁻ (−1) and the ion has a −3 charge. So x + 6(−1) = −3, giving x = +3. The other compounds give different values for the metal.', wrong = '{"0": "In K₄[Fe(CN)₆] the complex ion is [Fe(CN)₆]⁴⁻: x − 6 = −4, so Fe is +2.", "1": "In K₂Cr₂O₇: 2(+1) + 2x + 7(−2) = 0, so 2x = +12 and Cr is +6.", "2": "In [Cu(NH₃)₄]SO₄, NH₃ is neutral and SO₄ is −2, so the complex ion is [Cu(NH₃)₄]²⁺ and Cu is +2."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7134' AND answer = 3;
UPDATE questions SET why = 'The coordination number is the number of bonds from ligands to the central metal, not the number of ligands. Each ethanedioate ion is bidentate, binding through two oxygen atoms. Three of them make 3 × 2 = 6 bonds, so the coordination number is 6 and the complex is octahedral.', wrong = '{"0": "3 is the number of ligands. Each one forms two bonds, so the bond count is 6.", "1": "4 does not match any count here. It is a common coordination number, but each of the three ligands gives two bonds.", "3": "12 would mean each ligand formed four bonds. Ethanedioate forms only two."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7135' AND answer = 2;
UPDATE questions SET why = 'In the complex, the water ligands split the five 3d orbitals of Cu²⁺ into two groups with different energies. Cu²⁺ is 3d⁹, so an electron can jump from a lower to a higher d orbital by absorbing visible light, mainly red-orange. The light that is not absorbed reaches the eye and looks blue.', wrong = '{"0": "Water itself is colourless. The light is absorbed by the copper complex, not by free water molecules.", "1": "Cu²⁺ ([Ar]3d⁹) has no 4s electrons. The colour comes from its 3d electrons.", "2": "The colour comes from light being absorbed and the rest transmitted, not from light being emitted."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7136' AND answer = 3;
UPDATE questions SET why = 'Iron is [Ar]3d⁶4s². Fe²⁺ loses the two 4s electrons to become 3d⁶. Losing one more electron gives Fe³⁺, which is 3d⁵, with one electron in each of the five d orbitals. A half-filled d subshell is especially stable, so Fe²⁺ tends to be oxidised to Fe³⁺.', wrong = '{"0": "A completely filled 3d subshell would be 3d¹⁰. Fe³⁺ has only five d electrons.", "2": "Fe³⁺ has a charge of +3, which is larger than the +2 charge of Fe²⁺.", "3": "Fe³⁺ has lost both of its 4s electrons and one 3d electron, so it is [Ar]3d⁵, not 4s²3d³."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7137' AND answer = 1;
UPDATE questions SET why = 'Transition metals act as catalysts partly because they change easily between oxidation states. V₂O₅ oxidises SO₂ and is reduced: SO₂ + V₂O₅ → SO₃ + V₂O₄ (V: +5 → +4). Oxygen then reoxidises it: 2V₂O₄ + O₂ → 2V₂O₅ (V: +4 → +5). The catalyst is regenerated at the end.', wrong = '{"1": "A catalyst is not used up permanently. V₂O₅ is regenerated after each cycle.", "2": "Vanadium in V₂O₅ is +5, which is 3d⁰. Its catalytic action comes from variable oxidation states, not a full d subshell.", "3": "A catalyst speeds up the forward and reverse reactions equally, so it does not shift the position of equilibrium."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7138' AND answer = 0;
UPDATE questions SET why = 'Cl⁻ ions are larger than water molecules, so only four can fit around the Co²⁺ ion. The coordination number falls from 6 in [Co(H₂O)₆]²⁺ to 4 in [CoCl₄]²⁻, and the shape changes from octahedral to tetrahedral. Cobalt stays +2 (x − 4 = −2).', wrong = '{"0": "Cobalt is +2 in both ions. In [CoCl₄]²⁻, x + 4(−1) = −2 gives x = +2.", "2": "The coordination number falls from 6 to 4, not rises.", "3": "The change is the other way: octahedral (6 ligands) to tetrahedral (4 ligands)."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7139' AND answer = 1;
UPDATE questions SET why = 'Count the electrons left after ionisation; transition metal ions lose 4s electrons first. V²⁺ has 23 − 2 = 21 electrons, which is [Ar]3d³. Cr³⁺ has 24 − 3 = 21 electrons, also [Ar]3d³. So both ions have the same 3d³ configuration.', wrong = '{"0": "Ti³⁺ (22 − 3 = 19 electrons) is 3d¹, but Sc³⁺ (21 − 3 = 18) is 3d⁰.", "1": "Fe²⁺ (26 − 2 = 24 electrons) is 3d⁶, but Co²⁺ (27 − 2 = 25) is 3d⁷.", "2": "Cu⁺ (29 − 1 = 28 electrons) is 3d¹⁰, but Ni²⁺ (28 − 2 = 26) is 3d⁸."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7140' AND answer = 3;
UPDATE questions SET why = 'The –OH group can sit on a straight four-carbon chain or a branched one. Straight chain: butan-1-ol and butan-2-ol. Branched chain: 2-methylpropan-1-ol and 2-methylpropan-2-ol. That makes 4 alcohols. C₄H₁₀O also has three ethers, so 7 isomers in all.', wrong = '{"0": "2 counts only the straight-chain alcohols and misses the two branched ones.", "1": "3 is the number of ether isomers of C₄H₁₀O, not the alcohols.", "3": "7 counts the three ethers as well as the four alcohols."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7141' AND answer = 2;
UPDATE questions SET why = 'List the carbon skeletons from longest chain to most branched. Six carbons: hexane. Five-carbon chain: 2-methylpentane and 3-methylpentane. Four-carbon chain: 2,2-dimethylbutane and 2,3-dimethylbutane. That is 5 structural isomers.', wrong = '{"0": "3 is the number of structural isomers of pentane, C₅H₁₂, not hexane.", "1": "4 misses one of the isomers, usually one of the two dimethylbutanes or one of the methylpentanes.", "3": "There is no sixth distinct skeleton. Names such as 1-methylpentane just describe hexane again."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7142' AND answer = 2;
UPDATE questions SET why = 'A molecule shows optical isomerism if it has a chiral carbon, one bonded to four different groups. In butan-2-ol, CH₃CH(OH)CH₂CH₃, carbon 2 carries H, OH, CH₃ and C₂H₅, all different. So it exists as a pair of non-superimposable mirror images (enantiomers).', wrong = '{"1": "In 2-methylpropan-2-ol the C–OH carbon carries three identical CH₃ groups, so it is not chiral.", "2": "In propan-2-ol the C–OH carbon carries two identical CH₃ groups, so it is not chiral.", "3": "In butan-1-ol no carbon has four different groups. The C–OH carbon carries two H atoms."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7143' AND answer = 0;
UPDATE questions SET why = 'Cis-trans isomerism needs restricted rotation about C=C and two different groups on each carbon of the double bond. In pent-2-ene, CH₃CH=CHCH₂CH₃, C2 carries H and CH₃, and C3 carries H and C₂H₅. So cis and trans forms exist.', wrong = '{"0": "In but-1-ene, CH₂=CHCH₂CH₃, C1 carries two H atoms, so there is only one arrangement.", "1": "In 1,1-dichloroethene one carbon carries two Cl atoms and the other two H atoms, so no cis-trans forms exist.", "2": "In 2-methylpropene, C2 carries two CH₃ groups and C1 two H atoms, so no cis-trans forms exist."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7144' AND answer = 3;
UPDATE questions SET why = 'Isomers must have the same molecular formula. Propanal, CH₃CH₂CHO, is C₃H₆O, but propan-1-ol, CH₃CH₂CH₂OH, is C₃H₈O. They differ by two hydrogens, so they are not isomers.', wrong = '{"0": "Propanal and propanone are both C₃H₆O. They are functional group isomers (aldehyde and ketone).", "2": "Ethanol and methoxymethane are both C₂H₆O. They are functional group isomers (alcohol and ether).", "3": "Butane and 2-methylpropane are both C₄H₁₀. They are chain isomers."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7145' AND answer = 1;
UPDATE questions SET why = 'Cyclohexene''s ring is made only of carbon atoms, so it is homocyclic. It is a non-aromatic ring compound, so it is alicyclic. It contains a C=C double bond, so it is unsaturated.', wrong = '{"1": "The ring contains only carbon, so it is not heterocyclic, and its C=C bond makes it unsaturated.", "2": "Cyclohexene has one C=C bond, not a delocalised benzene-type ring, so it is not aromatic.", "3": "Cyclohexene is a closed ring of six carbons, not an open chain."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7146' AND answer = 0;
UPDATE questions SET why = '4-Chloropent-2-ene is CH₃CH=CH–CHCl–CH₃. Each carbon of the C=C carries two different groups, so it shows geometric (cis-trans) isomerism. C4 carries H, Cl, CH₃ and CH=CHCH₃, four different groups, so it is chiral and also shows optical isomerism.', wrong = '{"0": "Pent-2-ene shows cis-trans isomerism but has no carbon with four different groups, so it is not optically active.", "1": "2-Chloropropene, CH₂=CClCH₃, has two H atoms on C1, so no cis-trans forms, and it has no chiral carbon.", "2": "2-Chlorobutane has a chiral carbon, but it has no C=C bond, so it cannot show geometric isomerism."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7147' AND answer = 3;
UPDATE questions SET why = 'C₅H₈ fits CₙH₂ₙ₋₂, which has four hydrogens fewer than the alkane C₅H₁₂. That means two units of unsaturation: two π bonds, or one ring plus one π bond. Pent-1-yne (a triple bond), penta-1,3-diene (two double bonds) and cyclopentene (a ring and a double bond) all have this formula.', wrong = '{"0": "Alkynes fit C₅H₈, but so do cycloalkenes such as cyclopentene and dienes such as penta-1,3-diene.", "2": "Dienes fit C₅H₈, but so do alkynes such as pent-1-yne and cycloalkenes such as cyclopentene.", "3": "Cycloalkenes fit C₅H₈, but so do alkynes and dienes."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7148' AND answer = 1;
UPDATE questions SET why = 'Propane, CH₃CH₂CH₃, has six primary H atoms on its two CH₃ groups and two secondary H atoms on the CH₂ group. Replacing a primary H gives 1-chloropropane and a secondary H gives 2-chloropropane. If every H were equally likely, the ratio would be 6 : 2 = 3 : 1. In practice more 2-chloropropane forms, because the secondary radical is more stable.', wrong = '{"1": "1 : 3 reverses the ratio. There are more primary hydrogens (6) than secondary ones (2).", "2": "2 : 1 counts the two end carbons against the middle carbon, not the hydrogens on them.", "3": "1 : 1 counts the two kinds of carbon position, not the number of hydrogen atoms at each."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7149' AND answer = 0;
UPDATE questions SET why = '2-Methylbutane is (CH₃)₂CHCH₂CH₃. It has four different kinds of hydrogen: on the two equivalent CH₃ groups at C1, on C2, on C3 and on C4. Replacing each kind gives a different product: 1-chloro-2-methylbutane, 2-chloro-2-methylbutane, 2-chloro-3-methylbutane and 1-chloro-3-methylbutane. So there are 4 products.', wrong = '{"0": "2 counts too few. Besides the end CH₃ and the tertiary C–H, there are also the CH₂ hydrogens and the other CH₃.", "1": "3 misses one set of equivalent hydrogens. There are four distinct types in this molecule.", "3": "5 treats the two CH₃ groups on C2 as different. They are equivalent and give the same product."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7150' AND answer = 2;
UPDATE questions SET why = 'UV light splits Cl₂ into Cl• radicals, and Cl• takes an H from CH₄ to form methyl radicals, CH₃•. Two methyl radicals can join in a termination step: CH₃• + •CH₃ → C₂H₆. Finding ethane shows that methyl radicals were present, which supports the free radical chain mechanism.', wrong = '{"0": "UV light causes homolytic fission, giving two Cl• radicals, not Cl⁺ and Cl⁻ ions.", "1": "In the initiation step Cl₂ splits into radicals. Methane molecules do not join together directly.", "2": "Methane is saturated and has no π bond, so it cannot undergo addition. This is a substitution reaction."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7151' AND answer = 3;
UPDATE questions SET why = 'In the first step the π electrons of the C=C attack H⁺. If H goes to the end carbon (C1), the positive charge sits on C2, giving CH₃CH⁺CH₃, a secondary carbocation. It is stabilised by two alkyl groups, so it forms in preference to a primary one. Br⁻ then bonds to C2, giving 2-bromopropane (Markovnikov''s rule).', wrong = '{"1": "Without peroxides, HBr adds by an ionic mechanism through a carbocation, not by free radicals.", "2": "A secondary carbocation is more stable than a primary one, because more alkyl groups push electrons towards the positive carbon.", "3": "The electrophile H⁺ adds first. Br⁻ attacks only after the carbocation has formed."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7152' AND answer = 0;
UPDATE questions SET why = 'Hot, concentrated acidified KMnO₄ breaks the C=C bond completely. The (CH₃)₂C= end becomes propanone, CH₃COCH₃, a ketone that resists further oxidation. The =CHCH₃ end first gives ethanal, which is oxidised further to ethanoic acid, CH₃COOH.', wrong = '{"0": "The diol forms with cold, dilute KMnO₄, which only adds two OH groups. Hot concentrated KMnO₄ breaks the C=C bond.", "2": "Ethanal does form at first, but under these strong conditions it is oxidised further to ethanoic acid.", "3": "The double bond lies between C2 and C3, so the fragments have three and two carbons, not three and one."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7153' AND answer = 1;
UPDATE questions SET why = 'Concentrated H₂SO₄ removes the OH and an H from a neighbouring carbon (dehydration). Butan-2-ol can lose H from C1 or C3. Losing it from C3 gives but-2-ene, the more substituted and more stable alkene, so it is the main product (Saytzeff rule). But-1-ene forms only in smaller amounts.', wrong = '{"0": "But-1-ene does form, but as the minor product, because it is less substituted and less stable.", "1": "Ethers form at lower temperatures with excess alcohol. Under strong heating with acid, the alkene is the main product.", "3": "Dehydration removes water and creates a double bond. It does not add hydrogen, so butane is not formed."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7154' AND answer = 2;
UPDATE questions SET why = 'Water adds across the triple bond by Markovnikov''s rule, so the OH goes onto the middle carbon. This gives the enol CH₃C(OH)=CH₂. An enol is unstable and rearranges at once (tautomerises) into the ketone CH₃COCH₃, propanone.', wrong = '{"0": "The enol rearranges to a ketone, not a saturated alcohol. Propan-2-ol would need extra hydrogen.", "1": "Hydration adds water to the triple bond. It does not simply turn the alkyne into an alkene.", "2": "Propanal would need the OH on the end carbon, which is anti-Markovnikov addition."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7155' AND answer = 3;
UPDATE questions SET why = 'Lindlar''s catalyst is palladium poisoned with lead salts, so it adds only one mole of H₂ and stops at the alkene. Both H atoms add from the catalyst surface to the same side of the triple bond (syn addition). But-2-yne therefore gives cis-but-2-ene.', wrong = '{"1": "The triple bond is between C2 and C3, so after hydrogenation the double bond stays there. But-1-ene cannot form.", "2": "Trans-but-2-ene is made by reducing the alkyne with sodium in liquid ammonia, not on a metal catalyst.", "3": "Lindlar''s catalyst is deliberately weakened, so it does not reduce the alkene further to butane."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7156' AND answer = 0;
UPDATE questions SET why = 'Only a hydrogen on a triply bonded carbon (≡C–H) is acidic enough to be replaced by silver. But-1-yne is a terminal alkyne: CH₃CH₂C≡CH + [Ag(NH₃)₂]⁺ → CH₃CH₂C≡CAg, a white precipitate. The sp carbon holds the C–H electrons tightly, which makes this H acidic.', wrong = '{"0": "But-1-ene has hydrogens on sp² carbons, which are not acidic enough to react with silver ions.", "2": "Butane has only sp³ C–H bonds, which are the least acidic of all. It does not react.", "3": "But-2-yne has its triple bond in the middle, so no hydrogen is attached to a triply bonded carbon."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7157' AND answer = 1;
UPDATE questions SET why = 'Sulphuric acid is the stronger acid, so it protonates nitric acid. The protonated HNO₃ loses water to form the nitronium ion: HNO₃ + 2H₂SO₄ → NO₂⁺ + H₃O⁺ + 2HSO₄⁻. NO₂⁺ is a strong electrophile that attacks the benzene ring.', wrong = '{"1": "The nitro group stays on the ring as the product, nitrobenzene. H₂SO₄ does not remove it.", "2": "Benzene is not oxidised to phenol during nitration. The ring is substituted directly.", "3": "H₂SO₄ is not the electrophile. Its job is to produce NO₂⁺, which attacks the ring."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7158' AND answer = 0;
UPDATE questions SET why = 'The –NO₂ group pulls electrons out of the ring, deactivating it. The ortho and para positions lose the most electron density, so the electrophile attacks the meta (3-) position, where the intermediate is least destabilised. The main product is 1-bromo-3-nitrobenzene.', wrong = '{"0": "The 4- (para) position is disfavoured, because –NO₂ is a meta director.", "1": "The nitro group is not replaced. Bromine substitutes a ring hydrogen.", "3": "The 2- (ortho) position is disfavoured, because –NO₂ is a meta director."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7159' AND answer = 2;
UPDATE questions SET why = 'Nitration is attack by the electrophile NO₂⁺, so a ring with more electron density reacts faster. The methyl group releases electrons into the ring and activates it. Methylbenzene is therefore nitrated faster than benzene, while Cl and especially –NO₂ withdraw electrons and slow the reaction.', wrong = '{"0": "The nitro group withdraws electrons strongly, so nitrobenzene is nitrated much more slowly than benzene.", "2": "Chlorine directs to the ortho and para positions, but it withdraws electrons overall, so it slightly deactivates the ring.", "3": "Benzene has no activating group, so it reacts more slowly than methylbenzene."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7160' AND answer = 1;
UPDATE questions SET why = 'Hot alkaline KMnO₄ oxidises any alkyl side chain that has a hydrogen on the carbon joined to the ring (a benzylic hydrogen). The whole side chain is cut down to –COOH. Ethylbenzene loses one carbon as CO₂ and gives benzoic acid, C₆H₅COOH, after acidification.', wrong = '{"0": "The benzene ring itself is very stable and is not oxidised by KMnO₄. It has no side chain to oxidise.", "1": "Cyclohexane has no benzene ring, so it cannot give benzoic acid.", "2": "In tert-butylbenzene the carbon attached to the ring carries no hydrogen, so the side chain resists oxidation."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7161' AND answer = 3;
UPDATE questions SET why = 'In bright UV light, Cl• radicals form and substitute on the CH₃ side chain, as they do in alkanes, giving (chloromethyl)benzene, C₆H₅CH₂Cl. In the dark with FeCl₃ as catalyst, an electrophile (Cl⁺) substitutes on the ring. The methyl group directs it to the 2- and 4-positions.', wrong = '{"0": "Methyl is an ortho/para director, so ring substitution gives the 2- and 4-isomers, not 3-. UV light attacks the side chain.", "1": "The two sets of conditions are swapped. UV light gives side-chain substitution and FeCl₃ gives ring substitution.", "3": "With a CH₃ side chain present, UV light mainly causes radical substitution on the CH₃. FeCl₃ gives ring substitution."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7162' AND answer = 2;
UPDATE questions SET why = 'In bright sunlight benzene adds three molecules of chlorine: C₆H₆ + 3Cl₂ → C₆H₆Cl₆. The molar mass of C₆H₆Cl₆ is 72 + 6 + 213 = 291 g mol⁻¹. Benzene = 7.8 ÷ 78 = 0.10 mol, which gives 0.10 × 291 = 29.1 g of product.', wrong = '{"0": "11.3 g is 0.10 mol of chlorobenzene (M = 112.5), the substitution product, not the addition product.", "1": "14.7 g is 0.10 mol of a dichlorobenzene (M = 147), not the hexachloro addition product.", "2": "21.3 g is the mass of chlorine used (0.30 mol Cl₂ × 71), not the mass of the product."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7163' AND answer = 3;
UPDATE questions SET why = 'The –NO₂ group pulls so much electron density out of its ring that the weak electrophiles in Friedel-Crafts reactions cannot attack it. So nitrobenzene does not undergo alkylation or acylation itself. It can dissolve the reagents while the reaction happens on the other, more reactive compound.', wrong = '{"1": "Nitrobenzene is far less reactive than benzene, because –NO₂ strongly withdraws electrons.", "2": "The Lewis acid catalyst in Friedel-Crafts reactions is AlCl₃ (or FeCl₃), not nitrobenzene.", "3": "The –NO₂ group is a meta director, not an ortho/para director."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7164' AND answer = 0;
UPDATE questions SET why = 'In SN2, the nucleophile attacks the carbon from the side opposite the Br, in one step. Alkyl groups on that carbon get in the way (steric hindrance). So the rate falls as alkyl groups are added: CH₃Br (no alkyl groups) > primary > secondary > tertiary.', wrong = '{"0": "CH₃Br has no alkyl groups around the carbon, so it is the least hindered and reacts fastest, not second.", "2": "Steric hindrance differs greatly between methyl and tertiary halides, so the rates are very different.", "3": "This is roughly the order for SN1, which depends on carbocation stability, not the SN2 order."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7165' AND answer = 1;
UPDATE questions SET why = 'SN2 happens in one step: OH⁻ attacks from the back as Br⁻ leaves from the front. The other three groups flip over, like an umbrella turning inside out in the wind. This gives a single enantiomer of butan-2-ol with the inverted configuration.', wrong = '{"0": "Attack from the back side flips the arrangement of groups, so the configuration is inverted, not kept.", "1": "A racemic mixture forms in SN1, where a flat carbocation can be attacked from either side.", "3": "Aqueous OH⁻ under SN2 conditions mainly gives substitution. Elimination to but-2-ene needs ethanolic KOH and heat."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7166' AND answer = 2;
UPDATE questions SET why = 'In SN1 the C–Br bond breaks first, giving a carbocation. The positive carbon is sp² hybridised and flat. Water can attack either face with almost equal chance, so both enantiomers form in nearly equal amounts, giving a racemic mixture.', wrong = '{"0": "Tertiary halides do undergo substitution by SN1 in water. Elimination competes, but it is not the only path.", "1": "Once the flat carbocation forms, the original arrangement is lost, so a single retained enantiomer is not obtained.", "2": "Inversion to a single enantiomer is typical of SN2, not SN1."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7167' AND answer = 3;
UPDATE questions SET why = 'SN1 is fastest when the carbocation formed is stable and the C–X bond breaks easily in the slow step. 2-Bromo-2-methylpropane is tertiary, giving the most stable carbocation. Its C–Br bond (290 kJ mol⁻¹) is also weaker than C–Cl (346 kJ mol⁻¹), so it ionises faster.', wrong = '{"1": "A methyl carbocation is very unstable, so bromomethane reacts by SN2, not SN1.", "2": "1-Bromobutane is primary. Its carbocation is very unstable, so it reacts by SN2 instead.", "3": "2-Chloro-2-methylpropane is also tertiary, but its stronger C–Cl bond ionises more slowly than C–Br."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7168' AND answer = 0;
UPDATE questions SET why = 'The rate of hydrolysis is controlled mainly by C–X bond strength: C–Cl 346, C–Br 290 and C–I 228 kJ mol⁻¹. The C–I bond is the weakest, so it breaks fastest and releases I⁻ first. I⁻ meets Ag⁺ and forms a yellow precipitate of AgI.', wrong = '{"0": "C–I is the least polar of the three bonds, because iodine is the least electronegative halogen. Polarity is not the deciding factor.", "2": "Iodine is the least electronegative of these halogens, not the most.", "3": "AgI is the least soluble silver halide, not the most. The precipitate appears first because C–I breaks fastest."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7169' AND answer = 1;
UPDATE questions SET why = 'In SN1 the slow step is the C–Br bond breaking to form a carbocation, and OH⁻ is not involved in it. So rate = k[RX], and [OH⁻] has no effect. Halving [RX] halves the rate, and doubling [OH⁻] changes nothing.', wrong = '{"0": "Quartering would need two factors of ½. Only the halide concentration affects the rate here.", "1": "Doubling would follow if only OH⁻ mattered. In SN1, OH⁻ is not in the rate equation.", "2": "No change would be true for SN2 (rate = k[RX][OH⁻]), where ½ × 2 = 1. This is SN1."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7170' AND answer = 3;
UPDATE questions SET why = 'Hot ethanolic KOH acts as a strong base. OH⁻ removes an H from a carbon next to the C–Br carbon as Br⁻ leaves, in a single step (E2). Removing H from C3 gives but-2-ene, the more substituted and more stable alkene, as the main product.', wrong = '{"1": "A secondary halide with a strong base in ethanol reacts mainly by E2 elimination, not by SN1 through a carbocation.", "2": "Butan-2-ol forms by substitution, favoured by aqueous OH⁻. Ethanolic KOH and heat favour elimination.", "3": "But-1-ene forms only as the minor product, because it is less substituted and less stable."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7171' AND answer = 0;
UPDATE questions SET why = 'CN⁻ is a nucleophile and replaces Br: CH₃CH₂Br + CN⁻ → CH₃CH₂CN + Br⁻. This adds one carbon, giving propanenitrile. Boiling with dilute acid hydrolyses –CN to –COOH, so the final product is propanoic acid, CH₃CH₂COOH.', wrong = '{"0": "Ethanoic acid has only two carbons. The cyanide group adds a third carbon to the chain.", "2": "An amine forms when a nitrile is reduced, and it would be propylamine. Here the nitrile is hydrolysed.", "3": "Ethanol would form by substitution with OH⁻. Here the nucleophile is CN⁻."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7172' AND answer = 1;
UPDATE questions SET why = 'Acidified dichromate oxidises an alcohol only if the carbon carrying the OH also carries a hydrogen. 2-Methylpropan-2-ol, (CH₃)₃COH, is tertiary, so that carbon has no H. It is not oxidised, so orange Cr₂O₇²⁻ is not reduced to green Cr³⁺.', wrong = '{"0": "Butan-2-ol is a secondary alcohol. It is oxidised to butanone, and the dichromate turns green.", "1": "2-Methylpropan-1-ol is a primary alcohol, so it is oxidised and the dichromate turns green.", "3": "Butan-1-ol is a primary alcohol. It is oxidised to an aldehyde and then an acid, turning the dichromate green."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7173' AND answer = 2;
UPDATE questions SET why = 'An acid is stronger when the ion left after losing H⁺ is more stable. In phenoxide the negative charge spreads into the benzene ring, and an –NO₂ group at the 4-position spreads it even further. In ethoxide the ethyl group pushes electrons onto the oxygen, making it less stable, so ethanol is slightly weaker than water. Order: 4-nitrophenol > phenol > water > ethanol.', wrong = '{"0": "Phenols are much stronger acids than water, because the phenoxide ion is stabilised by the ring.", "1": "The electron-withdrawing –NO₂ group makes 4-nitrophenol stronger than phenol, not weaker.", "2": "This is the exact reverse order. Ethanol is the weakest acid of the four."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7174' AND answer = 3;
UPDATE questions SET why = 'The –OH group activates the benzene ring so strongly that bromine water substitutes at all three ortho and para positions with no catalyst. The white precipitate is 2,4,6-tribromophenol (M = 94 + 3 × 79 = 331). Phenol = 9.4 ÷ 94 = 0.10 mol, giving 0.10 × 331 = 33.1 g.', wrong = '{"0": "17.3 g is 0.10 mol of a monobromophenol (M = 173). With bromine water, three Br atoms are substituted, not one.", "1": "25.2 g is 0.10 mol of a dibromophenol (M = 252). The ring is activated enough for a third substitution.", "3": "48.0 g is the mass of bromine used, 0.30 mol Br₂ × 160, not the mass of precipitate."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7175' AND answer = 2;
UPDATE questions SET why = 'Both ethanol and phenol have an O–H bond that reacts with sodium metal, giving hydrogen gas and sodium ethoxide or sodium phenoxide. The other reagents need features that only phenol has. Phenol is acidic enough to react with NaOH, gives a violet colour with FeCl₃, and has an activated ring that decolourises bromine water.', wrong = '{"0": "Only phenol reacts with bromine water, because its ring is activated by –OH. Ethanol has no benzene ring.", "2": "Ethanol is too weak an acid to react with aqueous NaOH. Only phenol forms a salt with it.", "3": "The violet colour with neutral FeCl₃ is a test for phenols. Ethanol does not give it."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7176' AND answer = 1;
UPDATE questions SET why = 'In esterification the acid loses its whole –OH group, while the alcohol loses only the H of its O–H. The alcohol''s oxygen therefore stays in the product and joins the two halves of the ester: CH₃CO–¹⁸O–C₂H₅. The water formed contains the acid''s oxygen, so it is unlabelled.', wrong = '{"1": "The oxygen in the water comes from the –OH of the acid, not from the alcohol.", "2": "Concentrated H₂SO₄ is only a catalyst. It does not take the labelled oxygen.", "3": "The labelled oxygen atom goes entirely into the ester. It is not shared between ester and water."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7177' AND answer = 0;
UPDATE questions SET why = 'Which product forms depends on temperature and on which reagent is in excess. At about 140 °C with excess ethanol, one ethanol molecule attacks another protonated one, and water is lost between two molecules, giving ethoxyethane. At about 170 °C with excess acid, water is lost from within one molecule, giving ethene.', wrong = '{"0": "UV light plays no part in this reaction, and a temperature of 170 °C favours ethene, not the ether.", "2": "At room temperature with only a trace of acid, ethanol is not dehydrated at all.", "3": "About 170 °C with excess acid are the conditions that give mainly ethene."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7178' AND answer = 1;
UPDATE questions SET why = 'The iodoform test is positive for alcohols with a CH₃CH(OH)– group. These are first oxidised by iodine to CH₃CO– compounds, which then form yellow CHI₃. Ethanol, CH₃CH₂OH, has this group (with H as the other substituent), so it gives the yellow precipitate.', wrong = '{"1": "Methanol, CH₃OH, has no CH₃ group next to the C–OH carbon, so it gives no precipitate.", "2": "2-Methylpropan-2-ol is tertiary. Its C–OH carbon has no H, so it cannot be oxidised to a CH₃CO– compound.", "3": "In propan-1-ol, CH₃CH₂CH₂OH, the C–OH carbon carries an ethyl group, not a methyl group."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7179' AND answer = 0;
UPDATE questions SET why = 'Both compounds are C₄H₁₀O and have similar London forces. Butan-1-ol has an H attached to oxygen, so its molecules form hydrogen bonds with each other, which need much more energy to overcome. Ethoxyethane has no O–H, so its molecules cannot hydrogen bond to each other, and it boils far lower.', wrong = '{"0": "Both compounds are covalent molecules. Neither contains ions.", "1": "As isomers of similar size, they have similar London forces. These do not explain the 82 °C difference.", "3": "The alcohol is the more polar of the two, and it also forms hydrogen bonds."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7180' AND answer = 2;
UPDATE questions SET why = 'NaCN supplies CN⁻ ions, which are good nucleophiles. CN⁻ attacks the electron-poor carbonyl carbon, forming an alkoxide ion. This takes H⁺ from HCN, regenerating CN⁻. The product is (CH₃)₂C(OH)CN, 2-hydroxy-2-methylpropanenitrile.', wrong = '{"0": "2-Hydroxypropanenitrile would come from ethanal, not propanone. Also CN⁻ attacks the carbonyl carbon, not the oxygen.", "1": "The oxygen is not replaced. It stays in the product as an –OH group.", "2": "The product is right, but the first step is attack by CN⁻ on carbon. HCN is too weakly acidic to start by protonating the oxygen."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7181' AND answer = 3;
UPDATE questions SET why = '2,4-DNPH gives an orange precipitate with any compound containing a C=O group, so the compound is an aldehyde or a ketone. Tollens'' reagent is reduced only by aldehydes. Since there is no silver mirror, the compound is a ketone, and the only C₃H₆O ketone is propanone, CH₃COCH₃.', wrong = '{"1": "Methoxyethene, CH₂=CHOCH₃, is an ether with no C=O group, so it would not react with 2,4-DNPH.", "2": "Propanal has a C=O group but is an aldehyde, so it would give a silver mirror with Tollens'' reagent.", "3": "Prop-2-en-1-ol is an alcohol with a C=C bond. It has no C=O, so it gives no precipitate with 2,4-DNPH."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7182' AND answer = 0;
UPDATE questions SET why = 'NaBH₄ supplies hydride ions (H⁻), which add to the carbonyl carbon. The C=O group is flat, so H⁻ can attack from either face with equal chance. Butanone gives butan-2-ol, CH₃CH(OH)CH₂CH₃, which is chiral, so the two enantiomers form in equal amounts: a racemic mixture.', wrong = '{"0": "Reducing a ketone gives a secondary alcohol. Butan-1-ol is primary and would come from butanal.", "1": "The flat carbonyl group is attacked equally from both sides, so both enantiomers form, not just one.", "2": "NaBH₄ is a reducing agent. Butanoic acid would need oxidation, not reduction."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7183' AND answer = 3;
UPDATE questions SET why = 'Fehling''s solution contains a blue complex of Cu²⁺ in alkali. An aldehyde reduces Cu²⁺ to Cu⁺ and is itself oxidised to a carboxylate. The Cu⁺ precipitates as red-brown copper(I) oxide, Cu₂O.', wrong = '{"0": "Copper is reduced only to the +1 state here, not all the way to copper metal.", "2": "Silver metal (a silver mirror) comes from Tollens'' reagent, not Fehling''s solution.", "3": "Copper(II) oxide is black and still contains Cu²⁺. The aldehyde reduces copper to +1."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7184' AND answer = 1;
UPDATE questions SET why = 'The iodoform test needs a CH₃CO– group, a methyl group joined directly to the C=O carbon. Propanal is CH₃CH₂CHO. Its C=O carbon is attached to an ethyl group and an H, not a methyl group, so it gives no yellow precipitate.', wrong = '{"0": "Butanone, CH₃COCH₂CH₃, has a CH₃CO– group, so it gives the yellow precipitate.", "1": "Propanone, CH₃COCH₃, has a CH₃CO– group, so it gives the yellow precipitate.", "3": "Ethanal, CH₃CHO, has a CH₃CO– group, so it is the one aldehyde that gives a positive test."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7185' AND answer = 2;
UPDATE questions SET why = 'An acid is stronger when its carboxylate ion is more stable. Electron-withdrawing Cl atoms pull charge away from the –COO⁻ group and spread it out, so more Cl atoms give a stronger acid. Electron-releasing alkyl groups do the opposite. So Cl₃CCOOH > ClCH₂COOH > CH₃COOH > CH₃CH₂COOH.', wrong = '{"0": "Three Cl atoms withdraw more electron density than one, so trichloroethanoic acid is stronger than chloroethanoic acid.", "1": "Chloro-substituted acids are stronger than ethanoic acid, not weaker.", "3": "This is the exact reverse order. Propanoic acid is the weakest of the four."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7186' AND answer = 2;
UPDATE questions SET why = 'A carboxylic acid is strong enough to release CO₂ from sodium hydrogencarbonate: CH₃COOH + NaHCO₃ → CH₃COONa + H₂O + CO₂. The ratio is 1 : 1. Acid = 6.0 ÷ 60 = 0.10 mol, so 0.10 mol CO₂ forms, which is 0.10 × 22.4 = 2.24 dm³.', wrong = '{"0": "1.12 dm³ assumes 2 mol of acid per mole of CO₂, which is the ratio with Na₂CO₃, not NaHCO₃.", "2": "4.48 dm³ is 0.20 mol, double the CO₂ that 0.10 mol of acid can give.", "3": "22.4 dm³ is the volume of a whole mole of gas. Only 0.10 mol forms here."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7187' AND answer = 1;
UPDATE questions SET why = 'In ethyl propanoate, CH₃CH₂COOC₂H₅, the acid part is propanoate (three carbons) and the alcohol part is ethyl. Boiling with NaOH breaks the ester link and gives the sodium salt of the acid and the free alcohol. The products are sodium propanoate and ethanol, and the reaction goes to completion.', wrong = '{"0": "In aqueous alkali the acid is present as its sodium salt and the alcohol is released free, not the other way round.", "1": "This mixes up the two parts of the name. \"Ethyl\" is the alcohol part and \"propanoate\" is the acid part.", "2": "The ester is made from propanoic acid and ethanol, so it cannot give ethanoic acid and propan-1-ol."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7188' AND answer = 3;
UPDATE questions SET why = 'The Cl atom pulls electrons away from the carbonyl carbon, making it very electron-poor, and Cl⁻ is an excellent leaving group. So CH₃COCl + C₂H₅OH → CH₃COOC₂H₅ + HCl happens quickly at room temperature and does not reverse. Making the ester from ethanoic acid is slow and stops at an equilibrium.', wrong = '{"1": "Ethanoyl chloride reacts violently with water, so dry ethanol must be used.", "2": "It is the ethanoic acid route that forms an equilibrium mixture. The acyl chloride reaction goes to completion.", "3": "No catalyst is needed with ethanoyl chloride. Concentrated H₂SO₄ is used for the acid route."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7189' AND answer = 0;
UPDATE questions SET why = 'Let x mol of ester form, which also forms x mol of water and leaves (1 − x) mol each of acid and alcohol. Kc = x² ÷ (1 − x)² = 4.0. Taking the square root, x ÷ (1 − x) = 2, so x = 2 − 2x and x = 2/3 = 0.67 mol. The volume cancels because the moles are equal on each side.', wrong = '{"0": "0.33 mol is the amount of acid (or alcohol) left over at equilibrium, 1 − 0.67, not the ester formed.", "1": "0.50 mol would give Kc = (0.5)² ÷ (0.5)² = 1, not 4.0.", "3": "0.80 mol would give Kc = (0.8)² ÷ (0.2)² = 16, not 4.0."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7190' AND answer = 2;
UPDATE questions SET why = 'A silver mirror with Tollens'' reagent shows that X is an aldehyde. Oxidation turns –CHO into –COOH without changing the carbon skeleton. Since the acid formed is 2-methylpropanoic acid, (CH₃)₂CHCOOH, X must be 2-methylpropanal, (CH₃)₂CHCHO.', wrong = '{"0": "Butanal is an aldehyde and gives a silver mirror, but its straight chain oxidises to butanoic acid, not the branched acid.", "2": "Butanone is a ketone, so it does not give a silver mirror with Tollens'' reagent.", "3": "But-3-en-2-ol is an alcohol, not an aldehyde, so it does not reduce Tollens'' reagent."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7191' AND answer = 1;
UPDATE questions SET why = 'The acid protonates the carbonyl oxygen: C=O + H⁺ ⇌ C=OH⁺. The positive charge is shared onto the carbonyl carbon, making it much more electron-deficient. Even weak nucleophiles, such as water or alcohols, can then attack that carbon.', wrong = '{"1": "H⁺ is an electrophile, not a nucleophile. The nucleophile attacks the carbonyl carbon, not the oxygen.", "2": "The acid adds H⁺ to the oxygen. It does not remove a hydrogen from the carbonyl carbon.", "3": "The acid is a catalyst for addition. It does not oxidise the aldehyde to a carboxylic acid."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7192' AND answer = 0;
UPDATE questions SET why = 'A peptide has a free –NH₂ end and a free –COOH end, so the order of the units matters. Gly-Ala-Ser and Ser-Ala-Gly are different molecules. Three different units used once each can be arranged in 3 × 2 × 1 = 6 orders, so 6 tripeptides are possible.', wrong = '{"0": "3 treats some different orders as the same. Reversing a sequence gives a new peptide, so there are 6.", "2": "9 = 3 × 3 has no sound basis here. With each unit used exactly once, there are only 3 × 2 × 1 = 6 orders.", "3": "27 = 3³ allows any amino acid in each position, with repeats. Each unit must be used exactly once."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7193' AND answer = 1;
UPDATE questions SET why = 'Each peptide bond forms by condensation, releasing one water molecule. A straight chain of n amino acids has n − 1 peptide bonds between them. For 50 amino acids, 50 − 1 = 49 bonds form, so 49 water molecules are released.', wrong = '{"0": "25 treats each water molecule as joining two pairs of units. Every single peptide bond releases its own water molecule.", "2": "50 counts one bond per amino acid, but a straight chain has one fewer link than units.", "3": "51 adds one instead of subtracting one. A chain of 50 units has 49 links."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7194' AND answer = 1;
UPDATE questions SET why = 'Secondary structure is the regular folding of the backbone into an α-helix or a β-pleated sheet. It is held by hydrogen bonds between the C=O group of one peptide link and the N–H group of another. Tertiary structure depends mainly on interactions between side chains, such as disulphide bridges.', wrong = '{"0": "Quaternary structure is the way several separate polypeptide chains fit together, as in haemoglobin.", "1": "Tertiary structure is the overall 3-D folding, held mainly by interactions between the R groups (side chains).", "2": "Primary structure is the sequence of amino acids, held by covalent peptide bonds, not hydrogen bonds."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7195' AND answer = 3;
UPDATE questions SET why = 'Heating breaks the weak forces that hold a protein''s shape, such as hydrogen bonds and other side-chain interactions, so it unfolds (denatures). The covalent peptide bonds are much stronger and are not broken at 80 °C. So the amino acid sequence, the primary structure, stays the same.', wrong = '{"0": "Tertiary structure depends on side-chain interactions, which heat disrupts, so the 3-D folding is lost.", "1": "Secondary structure is held by hydrogen bonds, which are broken on heating, so helices and sheets unwind.", "3": "The shape of the active or binding site depends on folding, so it is lost when the protein unfolds."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7196' AND answer = 2;
UPDATE questions SET why = 'Each enzyme molecule can convert only a certain number of substrate molecules per second. At high substrate concentration every active site is occupied (the enzyme is saturated). Extra substrate has to wait for a free site, so the rate levels off at its maximum, Vmax.', wrong = '{"1": "The enzyme still provides the same lower-energy pathway, so the activation energy has not risen.", "2": "More substrate is being added, so it has not run out. The limit is the number of active sites.", "3": "The substrate does not denature the enzyme. Denaturing is caused by heat or extreme pH."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7197' AND answer = 0;
UPDATE questions SET why = 'In water, glycine exists mainly as the zwitterion H₃N⁺CH₂COO⁻. In strong acid at pH 1, the –COO⁻ group takes up an H⁺ and becomes –COOH. Both groups are then protonated, giving H₃N⁺CH₂COOH, which has an overall positive charge.', wrong = '{"0": "The zwitterion H₃N⁺CH₂COO⁻ is the main form near the isoelectric point, about pH 6, not in strong acid.", "1": "H₂NCH₂COO⁻, with a net negative charge, is the main form in strongly alkaline solution.", "2": "The uncharged form H₂NCH₂COOH is never the main species in water, because the groups transfer H⁺ to give the zwitterion."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7198' AND answer = 3;
UPDATE questions SET why = 'Each –COOH group of hexanedioic acid reacts with an –NH₂ group of hexane-1,6-diamine. They form an amide link, –CONH–, and a molecule of water is eliminated each time. So nylon-6,6 is a condensation polymer (a polyamide). Its repeat unit has 6 + 6 = 12 carbons, which is where the name 6,6 comes from.', wrong = '{"0": "Neither monomer has a C=C bond. Nylon-6,6 forms by condensation, not by addition.", "1": "The repeat unit has 12 carbons: six from the diacid and six from the diamine.", "3": "The links in nylon are amide (–CONH–) groups, not ester (–COO–) groups."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7199' AND answer = 2;
UPDATE questions SET why = 'A polyester forms from a diol and a dicarboxylic acid. Each –OH and –COOH pair joins into an ester link, releasing water, and having two groups on each monomer lets the chain keep growing. Ethane-1,2-diol and benzene-1,4-dicarboxylic acid form PET (Terylene).', wrong = '{"1": "Ethene has no –OH or –COOH group, so it cannot form an ester link with the diol.", "2": "A diamine and a diacid form amide links, giving a polyamide (nylon-6,6), not a polyester.", "3": "Ethene and chloroethene are alkenes. They join by addition polymerisation, with no ester links."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-7200' AND answer = 0;
UPDATE questions SET why = 'Noble gas atoms have full outer shells, so they form no bonds and are non-polar. The only attraction between them is the London dispersion force. It arises when a moving electron cloud creates a temporary dipole, which induces a dipole in a neighbouring atom.', wrong = '{"0": "Noble gases have full outer shells, so they do not share electrons to form covalent bonds.", "1": "Noble gas atoms do not lose or gain electrons, so there are no ions to attract each other.", "2": "Hydrogen bonds need H attached to N, O or F. Noble gas atoms contain no hydrogen."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9001' AND answer = 3;
UPDATE questions SET why = 'Dry silver oxide joins two ethyl groups through an oxygen atom, while the chlorine is removed as AgCl: 2C₂H₅Cl + Ag₂O → C₂H₅–O–C₂H₅ + 2AgCl. The product is diethyl ether (ethoxyethane). With moist Ag₂O, which acts like AgOH, ethanol would form instead.', wrong = '{"0": "Dimethyl ether contains two methyl groups, so it would need a methyl halide such as CH₃Cl, not ethyl chloride.", "2": "Silver oxide here acts as a source of oxygen to link two alkyl groups. It does not oxidise the ethyl group to an acid.", "3": "No oxidation to an aldehyde takes place. The C–Cl bond is simply replaced by a C–O–C link."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9002' AND answer = 1;
UPDATE questions SET why = 'The –OH group activates the benzene ring of phenol so strongly that bromine water substitutes at the 2, 4 and 6 positions without a catalyst. The orange bromine colour disappears and a white precipitate of 2,4,6-tribromophenol forms.', wrong = '{"0": "2,4,6-Tribromophenol is a white solid, not red.", "2": "No blue product forms in this reaction. The precipitate is white.", "3": "Orange is the colour of bromine water before the reaction. It is decolourised as the bromine is used up."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9003' AND answer = 1;
UPDATE questions SET why = 'Each hydrogen spectral series is named after the orbit the electron falls to. Lyman ends at n = 1, Balmer at n = 2, Paschen at n = 3, Brackett at n = 4 and Pfund at n = 5. So the Pfund series comes from electrons falling to the 5th orbit.', wrong = '{"0": "Electrons falling to n = 2 produce the Balmer series, which lies in the visible region.", "1": "Electrons falling to n = 3 produce the Paschen series, in the infrared.", "2": "Electrons falling to n = 4 produce the Brackett series, also in the infrared."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9004' AND answer = 3;
UPDATE questions SET why = 'A hydrogen atom has one electron, 1s¹. The hydride ion H⁻ has gained one extra electron, so it has two. Both go into the 1s orbital with opposite spins, giving 1s², the same configuration as helium.', wrong = '{"0": "1s⁰ means no electrons, which describes H⁺, a bare proton.", "1": "1s¹ is the neutral hydrogen atom with its single electron.", "3": "1s²2s¹ has three electrons, like lithium. H⁻ has only two."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9005' AND answer = 2;
UPDATE questions SET why = 'The alkyl group of a Grignard reagent, RMgX, attacks the carbon of carbon dioxide. This gives RCOOMgX, and acid hydrolysis turns it into the carboxylic acid RCOOH. The method adds one carbon to the chain.', wrong = '{"0": "Carbonates are not used to make acids from Grignard reagents. Dry CO₂ (often as dry ice) is the standard reagent.", "2": "Grignard reagents add to aldehydes to give alcohols: secondary alcohols, or primary alcohols with methanal. They do not give acids.", "3": "Carbon monoxide is not the reagent for making carboxylic acids from Grignard reagents. CO₂ is."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9006' AND answer = 1;
UPDATE questions SET why = 'The principal quantum number n = 4 gives the fourth shell. The azimuthal quantum number l = 0 means an s subshell (l = 1 is p, 2 is d, 3 is f). So the electron is in the 4s subshell, and m = 0 and s = −½ fit this.', wrong = '{"1": "A p subshell has l = 1. Here l = 0, so it is an s subshell.", "2": "5s would need n = 5. This electron has n = 4.", "3": "5p would need n = 5 and l = 1. This electron has n = 4 and l = 0."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9007' AND answer = 0;
UPDATE questions SET why = 'A real gas behaves most ideally when attractions between molecules are negligible and the molecules'' own volume is tiny compared with the container. High temperature gives molecules enough energy to overcome attractions, and low pressure keeps them far apart. Of these, 1000 °C and 1 atm is the highest temperature with the lowest pressure.', wrong = '{"0": "100 °C is a lower temperature and 10 atm a higher pressure than 1000 °C and 1 atm, so the gas is less ideal.", "1": "The temperature is equally high, but 20 atm is a higher pressure than 1 atm, so the molecules are crowded closer.", "3": "A low temperature with a very high pressure gives the largest deviation from ideal behaviour."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9008' AND answer = 2;
UPDATE questions SET why = 'In a crystalline solid the particles are arranged in a regular pattern that repeats in all three directions (a crystal lattice). This long-range order gives crystals a definite geometric shape and a sharp melting point.', wrong = '{"0": "A random arrangement with no repeating pattern describes an amorphous solid, such as glass.", "2": "Softening gradually over a range of temperatures is typical of amorphous solids. Crystalline solids melt sharply.", "3": "Crystalline solids have a definite shape and a sharp melting point, so this describes the opposite."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9009' AND answer = 1;
UPDATE questions SET why = 'CaCO₃ → CaO + CO₂ has a 1 : 1 mole ratio. 25 g of CaCO₃ is 25 ÷ 100 = 0.25 mol, which can give 0.25 × 56 = 14 g of CaO in theory. Percentage yield = (12 ÷ 14) × 100 ≈ 86%.', wrong = '{"0": "50% is roughly 12 ÷ 25 = 48%, which compares the mass of CaO with the mass of CaCO₃. Their molar masses differ.", "1": "A 60% yield would mean only 0.60 × 14 = 8.4 g of CaO, not 12 g.", "3": "A 90% yield would mean 0.90 × 14 = 12.6 g of CaO, more than the 12 g obtained."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9010' AND answer = 2;
UPDATE questions SET why = 'Percentage yield compares what was actually obtained with the maximum possible amount. Percentage yield = (actual yield ÷ theoretical yield) × 100 = (20 ÷ 25) × 100 = 0.80 × 100 = 80%.', wrong = '{"0": "A 60% yield would mean only 0.60 × 25 = 15 g was obtained, not 20 g.", "1": "A 70% yield would mean 0.70 × 25 = 17.5 g was obtained, not 20 g.", "3": "An 85% yield would mean 0.85 × 25 = 21.25 g was obtained, more than the 20 g actually made."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9011' AND answer = 2;
UPDATE questions SET why = 'From the ideal gas equation, V = nRT/P. Doubling n multiplies V by 2, doubling T multiplies it by 2, and halving P also multiplies it by 2. The new volume is 2 × 2 × 2 = 8 times the old volume.', wrong = '{"0": "Double counts only one of the three changes.", "1": "Four times counts only two of the three changes. Halving the pressure also doubles the volume.", "2": "Six times adds the factors (2 + 2 + 2). The factors multiply, giving 2 × 2 × 2 = 8."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9012' AND answer = 3;
UPDATE questions SET why = 'E1 means unimolecular elimination. The slow, rate-determining step is the C–X bond breaking to form a carbocation, and only the alkyl halide is involved. The base removes H⁺ only afterwards, in a fast step. So rate = k[R–X].', wrong = '{"1": "The base acts only after the slow step, so its concentration does not affect the E1 rate.", "2": "No nucleophile appears in the slow step of E1, so the rate does not depend on one.", "3": "A rate depending on both the base and the alkyl halide describes E2, which is bimolecular."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9013' AND answer = 0;
UPDATE questions SET why = 'Substitute doubled concentrations into the rate equation. New rate = k(2[A])(2[B])² = 2 × 4 × k[A][B]². So the rate becomes 8 times the original.', wrong = '{"0": "Increasing concentrations of reactants that appear in the rate equation can only raise the rate, not lower it.", "1": "Doubling the rate counts only the [A] term and ignores the doubling of [B].", "2": "Four times counts only the [B]² term and ignores the doubling of [A]."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9014' AND answer = 3;
UPDATE questions SET why = 'A Grignard reagent adds its alkyl group to the carbonyl carbon of methanal, HCHO, giving RCH₂OMgX. Acid hydrolysis then gives RCH₂OH. The –OH carbon is bonded to only one alkyl group, so this is a primary alcohol. Other aldehydes give secondary alcohols and ketones give tertiary ones.', wrong = '{"0": "Phenols have –OH on a benzene ring. They are not made by adding Grignard reagents to methanal.", "2": "Carboxylic acids come from Grignard reagents reacting with CO₂, not with methanal.", "3": "Grignard reagents add to carbonyl compounds to give alcohols after hydrolysis, not ketones."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9015' AND answer = 1;
UPDATE questions SET why = 'In the modern quantum model an electron''s exact path cannot be known. An orbital is the region of space around the nucleus where the probability of finding the electron is highest. This replaced Bohr''s idea of a fixed circular orbit.', wrong = '{"0": "An orbit is Bohr''s fixed circular path of an electron. It is not a region of probability.", "2": "Degenerate describes orbitals that have the same energy, such as the three 2p orbitals. It says nothing about probability.", "3": "A node is a region where the probability of finding the electron is zero, the opposite of what is asked."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9016' AND answer = 1;
UPDATE questions SET why = 'Hydration adds water across the triple bond, giving an enol that rearranges to a carbonyl compound. Markovnikov addition puts the oxygen on an inner carbon, so most alkynes give ketones. Ethyne has only two carbons, both CH, so it gives the aldehyde ethanal (acetaldehyde), not a ketone.', wrong = '{"1": "Propyne gives propanone, CH₃COCH₃, which is a ketone.", "2": "Butyne (either isomer) gives butanone, CH₃COCH₂CH₃, which is a ketone.", "3": "Pentyne gives a pentanone, such as pentan-2-one, which is a ketone."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9017' AND answer = 0;
UPDATE questions SET why = 'In benzene each carbon is sp² hybridised and has one p orbital at right angles to the ring. These six p orbitals overlap all round the ring, so the six π electrons are delocalised over all six carbons. This delocalisation (resonance) lowers the molecule''s energy and makes it unusually stable.', wrong = '{"0": "Benzene has a σ framework plus delocalised π bonding. It is not a molecule with only single bonds.", "2": "Benzene''s carbons are sp² hybridised and planar, not sp³.", "3": "Isolated double bonds would make benzene react like an alkene, adding bromine easily. It does not."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9018' AND answer = 1;
UPDATE questions SET why = 'Lattice energy is larger when ions carry higher charges and are smaller. Across Period 3 the metal ion changes from Na⁺ to Mg²⁺ to Al³⁺, so its charge rises and its radius shrinks. The attraction to the chloride ions grows, so the lattice energy increases.', wrong = '{"1": "A higher cation charge and a smaller cation radius both increase lattice energy, not decrease it.", "2": "The cation''s charge and size both change across the period, so the lattice energy cannot stay the same.", "3": "The change follows a clear pattern set by cation charge and size, so it is not random."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9019' AND answer = 0;
UPDATE questions SET why = 'Acidified potassium dichromate (K₂Cr₂O₇ with H₂SO₄) is an oxidising agent. It oxidises a primary alcohol first to an aldehyde and then, when heated under reflux, to a carboxylic acid. The orange dichromate turns green as Cr³⁺ forms.', wrong = '{"0": "CH₃COOH with P₂O₅ is a dehydrating mixture, used to make an anhydride. It is not an oxidising agent.", "1": "Ammonia is a base and a nucleophile. It does not oxidise alcohols.", "2": "Methanol is itself an alcohol. It has no ability to oxidise another alcohol."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9020' AND answer = 3;
UPDATE questions SET why = 'In transition metals both the d and s electrons take part in metallic bonding. This gives strong bonds between the atoms, so most transition metals are hard, strong and have high melting points. Mercury, a liquid at room temperature, is the main exception.', wrong = '{"0": "Transition metals have strong metallic bonding, so they are strong and have high melting points, not weak and low-melting.", "2": "Most transition metals are hard, not soft, because of their strong metallic bonding.", "3": "Most transition metals are hard, strong and high-melting, the opposite of this."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9021' AND answer = 1;
UPDATE questions SET why = 'Methyl ketones contain the CH₃CO– group. Warming with iodine and NaOH turns this group into a yellow precipitate of iodoform (CHI₃). Ketones without a CH₃ next to the C=O give no precipitate, so the iodoform test separates the two.', wrong = '{"0": "Tollens'' test (silver mirror) distinguishes aldehydes from ketones. No ketone gives a silver mirror.", "1": "Silver nitrate is used to test for halide ions, not to tell ketones apart.", "3": "The Lucas test uses ZnCl₂ and HCl to classify alcohols as primary, secondary or tertiary."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9022' AND answer = 2;
UPDATE questions SET why = 'Moles = number of molecules ÷ Avogadro''s number = 9.03 × 10²³ ÷ 6.02 × 10²³ = 1.5 mol. At STP one mole of any ideal gas occupies 22.4 dm³. So the volume is 1.5 × 22.4 = 33.6 dm³.', wrong = '{"0": "11.2 dm³ is the volume of 0.5 mol of gas, which is only 3.01 × 10²³ molecules.", "1": "22.4 dm³ is the volume of 1 mol of gas, which is 6.02 × 10²³ molecules.", "3": "44.8 dm³ is the volume of 2 mol of gas, which is 1.204 × 10²⁴ molecules."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9023' AND answer = 2;
UPDATE questions SET why = 'The power of [A] in the rate equation is 0, so the reaction is zero order in A and [A] has no effect: doubling it multiplies the rate by 2⁰ = 1. The power of [B] is 1, so doubling [B] doubles the rate. Overall the rate doubles.', wrong = '{"0": "[A] has no effect, but [B] appears to the first power, so doubling it does change the rate.", "2": "The rate depends on [B] to the first power only, so doubling [B] gives 2 times the rate, not 3.", "3": "Raising [B] cannot lower the rate, because [B] appears with a positive power."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9024' AND answer = 1;
UPDATE questions SET why = 'Ammonium nitrate is made of NH₄⁺ and NO₃⁻ ions, so each nitrogen is worked out separately. In NH₄⁺: N + 4(+1) = +1, so N = −3. In NO₃⁻: N + 3(−2) = −1, so N = +5.', wrong = '{"0": "+4 and −4 do not fit either ion. With H = +1 and O = −2, the values must be −3 in NH₄⁺ and +5 in NO₃⁻.", "2": "−4 and +6 do not fit. In NH₄⁺, −4 + 4 = 0, not +1, and in NO₃⁻, +6 − 6 = 0, not −1.", "3": "+5 is right for NO₃⁻, but in NH₄⁺, N = +1 − 4 = −3, not −4."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9025' AND answer = 1;
UPDATE questions SET why = 'A subshell with azimuthal quantum number l contains 2l + 1 orbitals, because m runs from −l to +l. Each orbital holds a maximum of 2 electrons. So the subshell holds 2(2l + 1) electrons: 2 for s, 6 for p, 10 for d and 14 for f.', wrong = '{"0": "l + 1 would give a p subshell (l = 1) only 2 electrons, but it holds 6.", "1": "2l + 1 is the number of orbitals in the subshell. Each orbital holds two electrons, so this must be doubled.", "3": "2l + 2 would give a p subshell only 4 electrons, but it holds 6."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9026' AND answer = 2;
UPDATE questions SET why = 'By definition, the anode is the electrode where oxidation (loss of electrons) happens, and the cathode is where reduction happens. In a galvanic cell, such as the Daniell cell, zinc is oxidised at the anode: Zn → Zn²⁺ + 2e⁻.', wrong = '{"0": "Reduction, the gain of electrons, takes place at the cathode, not oxidation.", "2": "The salt bridge only lets ions move to keep the solutions neutral. No electron transfer happens there.", "3": "Oxidation and reduction happen on the electrode surfaces. The electrolyte only carries ions."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9027' AND answer = 1;
UPDATE questions SET why = 'The oxidation numbers in a neutral molecule add up to zero, with H = +1 and O = −2. For HClO₃: (+1) + Cl + 3(−2) = 0. So Cl − 5 = 0, and Cl = +5.', wrong = '{"0": "−1 is the oxidation number of chlorine in HCl or in chloride ions, not in HClO₃.", "1": "Chlorine is bonded to oxygen, which is more electronegative, so chlorine''s oxidation number is positive, not −5.", "2": "+1 is the oxidation number of chlorine in HClO, which has only one oxygen."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9028' AND answer = 3;
UPDATE questions SET why = 'Mass = number of moles × molar mass. For CaCO₃ the molar mass is 40 + 12 + 3 × 16 = 100 g mol⁻¹. So 0.5 mol has a mass of 0.5 × 100 = 50 g.', wrong = '{"1": "55 g would be 55 ÷ 100 = 0.55 mol of CaCO₃, slightly more than the 0.5 mol given.", "2": "45 g would be 45 ÷ 100 = 0.45 mol of CaCO₃, slightly less than the 0.5 mol given.", "3": "60 g would be 60 ÷ 100 = 0.6 mol of CaCO₃, more than the 0.5 mol given."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9029' AND answer = 0;
UPDATE questions SET why = 'Dissolving happens only at the surface of a solid, where water molecules can reach the particles. Crushing the crystals breaks them into many smaller pieces, which exposes much more surface for the same mass. More particles leave the surface each second, so the crushed sample dissolves faster.', wrong = '{"0": "Crushing does not change the density of copper sulphate. Density is a property of the substance.", "2": "Crushing does not lower the density. The crystals are the same substance, only smaller.", "3": "Crushing increases the surface area, not decreases it."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9030' AND answer = 1;
UPDATE questions SET why = '2-Butene is CH₃CH=CHCH₃. Rotation about the C=C bond is restricted, and each carbon of the double bond carries two different groups, H and CH₃. So the two CH₃ groups can be on the same side (cis) or opposite sides (trans), which is geometric isomerism.', wrong = '{"0": "Tautomerism is a rapid shift of an H atom between two structures, such as keto and enol forms. 2-Butene does not do this.", "2": "Functional group isomers have different functional groups. Cis and trans 2-butene have the same C=C group.", "3": "Metamerism occurs in ethers, ketones and amines with different alkyl groups around the functional group, not in alkenes like this."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9031' AND answer = 1;
UPDATE questions SET why = 'Nylon-6,6 is made from hexane-1,6-diamine (hexamethylenediamine) and hexanedioic acid (adipic acid). Each monomer has 6 carbon atoms. The two sixes in the name "6,6" record this.', wrong = '{"1": "The diamine has only 2 amino groups, one at each end of the chain.", "2": "The diamine has only 2 nitrogen atoms, and adipic acid has none.", "3": "Adipic acid has only 2 –COOH groups, one at each end."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9032' AND answer = 0;
UPDATE questions SET why = 'An ionic solid conducts electricity only when molten or dissolved, because only then can its ions move. A molecular solid contains neither ions nor free electrons, so it does not conduct in any state. So X is ionic and Y is molecular.', wrong = '{"0": "This swaps the two. The solid that conducts when molten (X) must contain ions.", "2": "Y does not conduct even when melted, so it cannot be ionic.", "3": "X conducts when molten, so it must contain ions and cannot be molecular."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9033' AND answer = 1;
UPDATE questions SET why = 'AgBr ⇌ Ag⁺ + Br⁻, so in a saturated solution [Ag⁺] = [Br⁻] = s, the solubility. Ksp = [Ag⁺][Br⁻] = s² = (7.1 × 10⁻⁷)² = 50.41 × 10⁻¹⁴ = 5.04 × 10⁻¹³.', wrong = '{"1": "A positive power of ten is impossible. Squaring a number as small as 7.1 × 10⁻⁷ gives a very small Ksp.", "2": "7.1 × 10⁻⁷ is the solubility itself. For a 1 : 1 salt Ksp is the square of the solubility.", "3": "1.42 × 10⁻¹³ multiplies 7.1 by 2 instead of squaring it, while still squaring the power of ten."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9034' AND answer = 0;
UPDATE questions SET why = '"Aqueous" means made with water. In an aqueous solution water is the solvent, the substance present in larger amount that does the dissolving. Methanol is the solute.', wrong = '{"0": "HCl is not mentioned as part of this solution, so it cannot be the solvent.", "2": "Methanol is the substance being dissolved, so it is the solute, not the solvent.", "3": "NaOH is not mentioned as part of this solution, so it cannot be the solvent."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9035' AND answer = 1;
UPDATE questions SET why = 'An amorphous solid has no regular long-range arrangement of particles. Glass is the classic example: it has no definite crystal shape and softens gradually over a range of temperatures instead of melting sharply.', wrong = '{"0": "Diamond is a covalent network crystal, with every carbon in a regular tetrahedral lattice.", "2": "Sodium chloride is an ionic crystal with a regular cubic lattice and a sharp melting point.", "3": "Potassium bromide is an ionic crystal, like NaCl, with a regular lattice."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9036' AND answer = 1;
UPDATE questions SET why = 'HCl adds once across the triple bond of ethyne: HC≡CH + HCl → CH₂=CHCl. The product, vinyl chloride (chloroethene), still has a C=C bond, so it can undergo addition polymerisation to form PVC.', wrong = '{"0": "Adding HCl to ethene gives chloroethane, CH₃CH₂Cl, which has no C=C bond left to polymerise.", "2": "Vinyl alcohol is an unstable enol that rearranges to ethanal. It is not used to make vinyl chloride.", "3": "Methane has no multiple bond, so HCl cannot add to it. Chlorinating methane gives chloromethanes."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9037' AND answer = 1;
UPDATE questions SET why = 'Thionyl chloride replaces the –OH of a carboxylic acid with –Cl: CH₃COOH + SOCl₂ → CH₃COCl + SO₂ + HCl. The by-products are gases and escape easily, leaving acetyl chloride. PCl₃ and PCl₅ can also be used.', wrong = '{"1": "Chlorine gas substitutes a hydrogen on the CH₃ group (the α-carbon), giving chloroacetic acid, not acetyl chloride.", "2": "Sodium chloride does not replace the –OH group of acetic acid, so no acetyl chloride forms.", "3": "Phosphorus trioxide contains no chlorine, so it cannot make an acid chloride. PCl₃ (phosphorus trichloride) would work."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9038' AND answer = 0;
UPDATE questions SET why = 'NaBH₄ reduces both aldehyde and ketone groups to alcohols. In CH₃CH₂CH₂COCHO, the aldehyde at C1 becomes –CH₂OH (primary) and the ketone at C2 becomes –CH(OH)– (secondary). The product is CH₃CH₂CH₂CH(OH)CH₂OH, pentane-1,2-diol.', wrong = '{"0": "CH₃CH(OH)CH₂CH₂OH has only four carbons. Reduction does not shorten the five-carbon chain.", "1": "Pentan-1-ol has lost the C2 oxygen entirely. NaBH₄ turns C=O into C–OH but cannot remove the oxygen.", "2": "Pentane-2,4-diol puts the OH groups on C2 and C4. The carbonyl groups were on C1 and C2."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9039' AND answer = 3;
UPDATE questions SET why = 'By Avogadro''s law, at constant temperature and pressure the volume is proportional to the number of moles. The moles rise from 0.5 to 0.5 + 1.0 = 1.5 mol, which is 3 times as many. So the volume becomes 2.0 × 3 = 6.0 L.', wrong = '{"0": "3.0 L adds 1 L to the volume instead of scaling it with the moles.", "1": "4.0 L would match a total of 1.0 mol, but the total is 1.5 mol.", "3": "8.0 L would match a total of 2.0 mol, more than the 1.5 mol present."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9040' AND answer = 2;
UPDATE questions SET why = 'The usual value of R is 0.0821 dm³ atm K⁻¹ mol⁻¹. One atmosphere equals 760 torr, so to express pressure in torr the value is multiplied by 760. R = 0.0821 × 760 = 62.4 dm³ torr K⁻¹ mol⁻¹.', wrong = '{"0": "0.0821 is the value of R when pressure is in atmospheres (dm³ atm K⁻¹ mol⁻¹), not torr.", "1": "1.987 is the value of R in cal K⁻¹ mol⁻¹, an energy unit.", "2": "8.314 is the value of R in J K⁻¹ mol⁻¹, the SI unit."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9041' AND answer = 3;
UPDATE questions SET why = 'Iron is [Ar]3d⁶4s². When it forms Fe²⁺ it loses the two 4s electrons first, leaving [Ar]3d⁶. Six electrons in five d orbitals: by Hund''s rule five go in singly, and the sixth pairs up with one. That leaves 4 unpaired electrons.', wrong = '{"0": "Five d orbitals can hold at most 5 unpaired electrons, so 6 electrons cannot all be unpaired.", "2": "3 unpaired electrons fits a d³ or d⁷ ion, such as Cr³⁺ or Co²⁺, not d⁶.", "3": "2 unpaired electrons fits a d² or d⁸ ion, such as Ni²⁺, not d⁶."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9042' AND answer = 1;
UPDATE questions SET why = 'Z = 27 is cobalt, [Ar]3d⁷4s². The last electrons added go into the 3d subshell. An element whose last electron enters a d subshell belongs to the d-block (the transition elements).', wrong = '{"0": "s-block elements add their last electron to an s subshell, as in Groups 1 and 2. Cobalt''s last electrons go into 3d.", "1": "p-block elements add their last electron to a p subshell, as in Groups 13 to 18.", "3": "f-block elements fill 4f or 5f subshells. These are the lanthanides and actinides, far beyond Z = 27."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9043' AND answer = 2;
UPDATE questions SET why = 'In a complete cycle the system returns to its starting state, so its internal energy is unchanged: ΔE = 0. By the first law, ΔE = q + w, so the net heat absorbed must be balanced by work. Net heat in = 1200 − 700 = 500 J, so the system does 500 J of net work on the surroundings.', wrong = '{"0": "Internal energy is a state function. After a full cycle the system is back where it started, so ΔE = 0.", "1": "ΔE over a full cycle is zero, so the internal energy cannot fall either.", "3": "The system took in a net 500 J of heat, so it must give out 500 J as work. The surroundings do not do work on it."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9044' AND answer = 2;
UPDATE questions SET why = 'P³⁻ and Cl⁻ both have 18 electrons. P³⁻ has only 15 protons pulling on them while Cl⁻ has 17, so the electron cloud of P³⁻ is held less tightly and spreads out further. Na⁺ has lost its whole outer shell and is very small, so P³⁻ is the largest of these ions.', wrong = '{"0": "Na⁺ has lost its outer shell and has only two shells left, so it is a small ion.", "1": "Silicon does not form a simple stable ion in ordinary compounds. It bonds covalently instead.", "3": "Cl⁻ has the same 18 electrons as P³⁻ but 2 more protons, so it is pulled in tighter and is smaller."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9045' AND answer = 2;
